#include <pigpio.h>
#include <stdio.h>
#include <time.h>
#include <unistd.h>

#define GPIO_PIN 4
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Open SPI device
    int spi = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpioTerminate();
        return 1;
    }

    // Open file for logging
    FILE *file = fopen("flame_data.csv", "w");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for logging\n");
        spiClose(spi);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        // Read GPIO pin
        int flameDetected = gpioRead(GPIO_PIN);
        if (flameDetected < 0) {
            fprintf(stderr, "Failed to read GPIO pin\n");
            fclose(file);
            spiClose(spi);
            gpioTerminate();
            return 1;
        }

        // Read ADC
        unsigned char spiData[3] = {0x01, 0x80, 0x00};
        char adcData[3] = {0, 0, 0};
        int result = spiXfer(spi, spiData, adcData, sizeof(spiData));
        if (result < 0) {
            fprintf(stderr, "Failed to read ADC\n");
            fclose(file);
            spiClose(spi);
            gpioTerminate();
            return 1;
        }

        // Calculate temperature
        int adcValue = (adcData[1] << 8) | adcData[2];
        double temperature = 10.0 + 40.0 * adcValue / 1023.0;

        // Log data
        fprintf(file, "%s,%d,%.2f\n", timestamp, flameDetected, temperature);
        fflush(file);

        // Sleep for a second
        sleep(1);
    }

    // Cleanup
    fclose(file);
    spiClose(spi);
    gpioTerminate();

    return 0;
}

