#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>

#define FLAME_SENSOR_GPIO 4
#define BUZZER_GPIO 27
#define ADC_ADDRESS 0x48
#define ADC_CHANNEL 0

volatile sig_atomic_t running = 1;
FILE *log_file;

void alarm_callback(int gpio, int level, uint32_t tick)
{
    if (level == 0) // falling edge
    {
        time_t now = time(NULL);
        fprintf(log_file, "Flame detected at %s", ctime(&now));
        gpioWrite(BUZZER_GPIO, 1);
        time_sleep(2);
        gpioWrite(BUZZER_GPIO, 0);
    }
}

int main(void)
{
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    if ((log_file = fopen("fire_log.txt", "w")) == NULL)
    {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) < 0)
    {
        fprintf(stderr, "Failed to set flame sensor GPIO mode\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) < 0)
    {
        fprintf(stderr, "Failed to set buzzer GPIO mode\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (gpioSetISRFunc(FLAME_SENSOR_GPIO, FALLING_EDGE, 50, alarm_callback) < 0)
    {
        fprintf(stderr, "Failed to set ISR function\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    while (running)
    {
        time_sleep(0.1);
    }

    fclose(log_file);
    gpioSetISRFunc(FLAME_SENSOR_GPIO, FALLING_EDGE, 0, NULL);
    gpioTerminate();
    return 0;
}

void signal_handler(int signum)
{
    running = 0;
}

