#include <stdio.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <linux/spi/spidev.h>

#define SPI_DEV "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip4"
#define GPIO_LINE 18
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define ADC_VREF 3.3
#define ADC_RES 10
#define SENSOR_SENSITIVITY 100.0
#define CURRENT_THRESHOLD 5.0

int spi_fd;
struct gpiod_chip *chip;
struct gpiod_line *line;

void cleanup(int signum) {
    gpiod_line_set_value(line, 0);
    close(spi_fd);
    gpiod_chip_close(chip);
    exit(0);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        return 1;
    }

    if (gpiod_line_request_output(line, "cooling_fan", 0) < 0) {
        perror("Failed to request GPIO line as output");
        return 1;
    }

    FILE *log_file = fopen("current_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    while (1) {
        uint8_t tx[3] = {0x01, 0x80, 0x00};
        uint8_t rx[3] = {0};

        if (write(spi_fd, tx, 3) < 0) {
            perror("Failed to write to SPI device");
            return 1;
        }

        if (read(spi_fd, rx, 3) < 0) {
            perror("Failed to read from SPI device");
            return 1;
        }

        uint16_t adc_value = ((rx[1] & 0x03) << 8) | rx[2];
        double voltage = adc_value * (ADC_VREF / ((1 << ADC_RES) - 1));
        double current = voltage / SENSOR_SENSITIVITY;

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, 20, "%Y-%m-%dT%H:%M:%S", timeinfo);

        fprintf(log_file, "%s,%f\n", timestamp, current);
        fflush(log_file);

        if (current > CURRENT_THRESHOLD) {
            gpiod_line_set_value(line, 1);
        } else {
            gpiod_line_set_value(line, 0);
        }

        sleep(1);
    }

    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(spi_fd);

    return 0;
}

