#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>

#define MLX91204_ADDR 0x48
#define BUFFER_SIZE 100
#define THRESHOLD 50.0

volatile sig_atomic_t stop;

void alarmHandler(int signum) {
    stop = 1;
}

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up alarm for graceful shutdown
    signal(SIGINT, alarmHandler);

    // Set up LED GPIO
    gpioSetMode(17, PI_OUTPUT);

    // Set up I2C
    int i2cHandle = i2cOpen(1, MLX91204_ADDR, 0);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Set up circular buffer
    float buffer[BUFFER_SIZE] = {0};
    int bufferIndex = 0;

    while (!stop) {
        // Read from sensor
        char data[2] = {0};
        if (i2cReadDevice(i2cHandle, data, 2) < 0) {
            fprintf(stderr, "Failed to read from sensor\n");
            return 1;
        }

        // Convert to current
        float current = (data[0] * 256 + data[1]) * 0.00375;

        // Add to buffer
        buffer[bufferIndex++] = current;
        if (bufferIndex == BUFFER_SIZE) {
            bufferIndex = 0;
        }

        // Calculate average current
        float average = 0;
        for (int i = 0; i < BUFFER_SIZE; i++) {
            average += buffer[i];
        }
        average /= BUFFER_SIZE;

        // Check if average current exceeds threshold
        if (average > THRESHOLD) {
            gpioWrite(17, 1);
        } else {
            gpioWrite(17, 0);
        }

        // Sleep for 100ms
        usleep(100000);
    }

    // Clean up
    i2cClose(i2cHandle);
    gpioTerminate();

    return 0;
}

