#define GPIO_DEV "/dev/gpiochip0"
#define GPIO_LINE 8
#define SPI_SPEED 1000000
#define SPI_DELAY 0
#define SPI_BITS 8
#define ADC_CHANNELS 2

int spi_fd;
struct gpiod_chip *chip;
