    gpiod_line_release(line);
    close(spi_fd);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    FILE *file;
    char buffer[50];
    struct spi_ioc_transfer spi[ADC_CHANNELS];
    unsigned char data[ADC_CHANNELS][3];
    int i, j, ret;

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return 1;
    }

    chip = gpiod_chip_open(GPIO_DEV);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Error getting GPIO line");
        return 1;
    }

    ret = gpiod_line_request_output(line, "mcp3008-cs", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line");
        return 1;
    }

    for (i = 0; i < ADC_CHANNELS; i++) {
        data[i][0] = 0x06 | ((i & 0x07) >> 2);
        data[i][1] = ((i & 0x03) << 6);
        data[i][2] = 0x00;
    }

    for (i = 0; i < ADC_CHANNELS; i++) {
        spi[i].tx_buf = (unsigned long)data[i];
        spi[i].rx_buf = (unsigned long)data[i];
        spi[i].len = 3;
        spi[i].delay_us = SPI_DELAY;
        spi[i].speed_hz = SPI_SPEED;
        spi[i].bits_per_word = SPI_BITS;
    }

    file = fopen("moisture_log.csv", "w");
    if (!file) {
        perror("Error opening file");
        return 1;
    }

    fprintf(file, "Timestamp,Moisture1,Moisture2\n");

    while (1) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        gpiod_line_set_value(line, 0);
        for (i = 0; i < ADC_CHANNELS; i++) {
            ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), spi + i);
            if (ret < 0) {
                perror("Error reading from SPI device");
                return 1;
            }
        }
        gpiod_line_set_value(line, 1);

        fprintf(file, "%s,", timestamp);
        for (i = 0; i < ADC_CHANNELS; i++) {
            int moisture = ((data[i][1] & 0x03) << 8) | data[i][2];
            fprintf(file, "%d,", (int)((moisture / 1023.0) * 100));
        }
        fprintf(file, "\n");
        fflush(file);

        sleep(5);
    }

    fclose(file);
    cleanup(0);

    return 0;
}

