#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_MOTOR_SHUTDOWN "gpiochip0"
#define GPIO_MOTOR_SHUTDOWN_LINE 17
#define ADC_VREF 3.3
#define ADC_RESOLUTION 1024
#define SENSITIVITY 0.1
#define OFFSET 0.05
#define OVERCURRENT_THRESHOLD 10.0

int spi_fd;
struct gpiod_chip *chip;
struct gpiod_line *motor_shutdown_line;

void cleanup(void) {
    close(spi_fd);
    gpiod_line_release(motor_shutdown_line);
    gpiod_chip_close(chip);
}

void signal_handler(int signum) {
    cleanup();
    exit(0);
}

int main(void) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_MOTOR_SHUTDOWN);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    motor_shutdown_line = gpiod_chip_get_line(chip, GPIO_MOTOR_SHUTDOWN_LINE);
    if (!motor_shutdown_line) {
        perror("Failed to get GPIO line");
        return 1;
    }

    int ret = gpiod_line_request_output(motor_shutdown_line, "motor_shutdown", 1);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        return 1;
    }

    FILE *log_file = fopen("current_log.csv", "a+");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    struct spi_ioc_rd_wr rdwr;
    struct spi_message m;
    spi_ioc_rd_wr_init(&rdwr);

    unsigned char tx_buf[3] = {1, 0, 0};
    unsigned char rx_buf[3] = {0, 0, 0};

    spi_message_init(&m);
    spi_message_add_tx(&m, tx_buf, 3);
    spi_message_add_rx(&m, rx_buf, 3);

    ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &m);
    if (ret < 0) {
        perror("Failed to read from SPI device");
        return 1;
    }

    unsigned int adc_value = (rx_buf[1] << 8) | rx_buf[2];
    double voltage = ADC_VREF * adc_value / ADC_RESOLUTION;
    double current = (voltage - OFFSET) / SENSITIVITY;

    if (current > OVERCURRENT_THRESHOLD) {
        gpiod_line_set_value(motor_shutdown_line, 0);
        time_t now = time(NULL);
        fprintf(log_file, "%ld,%f\n", now, current);
        sleep(1);
        gpiod_line_set_value(motor_shutdown_line, 1);
    } else {
        time_t now = time(NULL);
        fprintf(log_file, "%ld,%f\n", now, current);
    }

    fclose(log_file);
    cleanup();

    return 0;
}

