#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define ADC_CHANNEL 0
#define ADC_VREF 3.3
#define ADC_STEPS 1024
#define CURRENT_SENSITIVITY 66e-3
#define ZERO_CURRENT_MIDPOINT ADC_VREF / 2
#define OVERCURRENT_THRESHOLD 10.0
#define OVERCURRENT_GPIO 27
#define SAMPLE_RATE_MS 100

FILE *log_file;

void signal_handler(int signum) {
    fclose(log_file);
    gpioWrite(OVERCURRENT_GPIO, PI_LOW);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int spi_handle = spiOpen(0, 1000000, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        return 1;
    }

    log_file = fopen("current_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    gpioSetMode(OVERCURRENT_GPIO, PI_OUTPUT);

    while (1) {
        char tx_buffer[3] = {0x01, (char)(ADC_CHANNEL << 6), 0x00};
        char rx_buffer[3] = {0, 0, 0};

        int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
        if (result < 0) {
            fprintf(stderr, "SPI transfer error\n");
            return 1;
        }

        int adc_value = ((rx_buffer[1] & 0x03) << 8) | rx_buffer[2];
        if (adc_value < 0 || adc_value > 1023) {
            fprintf(stderr, "Invalid ADC value\n");
            return 1;
        }

        double voltage = adc_value * ADC_VREF / ADC_STEPS;
        double current = (voltage - ZERO_CURRENT_MIDPOINT) / CURRENT_SENSITIVITY;

        time_t now = time(NULL);
        fprintf(log_file, "%ld, %f\n", now, current);
        fflush(log_file);

        if (current > OVERCURRENT_THRESHOLD) {
            gpioWrite(OVERCURRENT_GPIO, PI_HIGH);
            fprintf(log_file, "%ld, OVERCURRENT\n", now);
            fflush(log_file);
            break;
        }

        gpioDelay(1000000000 / SAMPLE_RATE_MS);
    }

    fclose(log_file);
    gpioWrite(OVERCURRENT_GPIO, PI_LOW);
    gpioTerminate();

    return 0;
}

