#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <fcntl.h>
#include <linux/spi/spidev.h>
#include <sys/ioctl.h>

#define SPI_DEV "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip4"
#define GPIO_LINE 8
#define TMP36_CHANNEL 0
#define VREF 3.3
#define MAX_TEMP 125
#define MIN_TEMP -40

struct gpiod_chip *chip;
struct gpiod_line *line;
int spi_fd;

void cleanup(int signum) {
    gpiod_line_release(line);
    close(spi_fd);
    exit(0);
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        return 1;
    }

    int ret = gpiod_line_request_output(line, "tmp36-mcp3208", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        return 1;
    }

    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    uint8_t mode = 0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Failed to set SPI mode");
        return 1;
    }

    FILE *log_file = fopen("temperature_log.csv", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    while (1) {
        gpiod_line_set_value(line, 0);
        usleep(1);
        gpiod_line_set_value(line, 1);

        uint8_t tx[3] = {1, (TMP36_CHANNEL << 4) | 0x07, 0};
        uint8_t rx[3] = {0, 0, 0};

        struct spi_ioc_transfer tr = {
            .tx_buf = (unsigned long)tx,
            .rx_buf = (unsigned long)rx,
            .len = 3,
            .delay_usecs = 0,
            .speed_hz = 1000000,
            .bits_per_word = 8,
        };

        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
            perror("Failed to transfer SPI message");
            return 1;
        }

        uint16_t adc_value = (rx[1] << 8) | rx[2];
        double voltage = adc_value * VREF / 4095.0;
        double temp_celsius = (voltage - 0.5) / 0.01;

        if (temp_celsius < MIN_TEMP || temp_celsius > MAX_TEMP) {
            printf("Temperature out of range: %.2f C\n", temp_celsius);
            continue;
        }

        time_t now = time(NULL);
        fprintf(log_file, "%ld,%.2f\n", now, temp_celsius);
        fflush(log_file);

        usleep(1000000);
    }

    return 0;
}

