#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define SAMPLE_RATE 44100
#define CHANNELS 2
#define GAIN 1

volatile sig_atomic_t stop;

void sigint_handler(int signum) {
    stop = 1;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        printf("Usage: %s <gain>\n", argv[0]);
        return 1;
    }

    int gain = atoi(argv[1]);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    int handle = spiOpen(0, SAMPLE_RATE, 3);
    if (handle < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (!stop) {
        unsigned char buffer[CHANNELS * 2];
        int result = spiXfer(handle, buffer, sizeof(buffer));
        if (result < 0) {
            fprintf(stderr, "Failed to read from SPI device\n");
            return 1;
        }

        for (int i = 0; i < CHANNELS; i++) {
            int sample = (buffer[i * 2] << 8) | buffer[i * 2 + 1];
            sample = (sample - 0x8000) * gain / 0x7FFF;
            printf("%d,", sample);
        }
        printf("\n");
    }

    spiClose(handle);
    gpioTerminate();

    return 0;
}

