#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>

#define SPI_DEV "/dev/spidev0.0"
#define GPIO_BUZZER 18
#define ADC_CHANNEL 0
#define ADC_SPEED 1000000
#define ADC_MODE 0
#define ADC_BITS 10
#define TEMP_FILE "ambient_temp.txt"
#define LOG_FILE "flame_log.txt"
#define FLAME_THRESHOLD 1.0

struct gpiod_chip *chip;
struct gpiod_line *buzzer;
int spi_fd;

void handle_sigint(int sig) {
    gpiod_line_set_value(buzzer, 0);
    gpiod_chip_close(chip);
    close(spi_fd);
    printf("\nExiting...\n");
    exit(0);
}

double read_temp() {
    FILE *file = fopen(TEMP_FILE, "r");
    if (file == NULL) return 25.0;
    double temp;
    if (fscanf(file, "%lf", &temp) != 1) {
        fclose(file);
        return 25.0;
    }
    fclose(file);
    return temp;
}

int main() {
    signal(SIGINT, handle_sigint);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    buzzer = gpiod_chip_get_line(chip, GPIO_BUZZER);
    if (buzzer == NULL) {
        perror("Failed to get GPIO line");
        return 1;
    }

    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    int ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &ADC_MODE);
    if (ret == -1) {
        perror("Failed to set SPI mode");
        return 1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &ADC_SPEED);
    if (ret == -1) {
        perror("Failed to set SPI speed");
        return 1;
    }

    while (1) {
        struct timespec ts = {0, 500000000};
        nanosleep(&ts, NULL);

        uint8_t tx[3] = {1, (8 + ADC_CHANNEL) << 4, 0};
        uint8_t rx[3] = {0, 0, 0};

        struct spi_ioc_transfer tr = {
            .tx_buf = (unsigned long)tx,
            .rx_buf = (unsigned long)rx,
            .len = 3,
            .delay_usecs = 0,
            .speed_hz = ADC_SPEED,
            .bits_per_word = 8,
        };

        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
        if (ret < 1) {
            perror("Failed to transfer SPI message");
            continue;
        }

        uint16_t adc_value = (rx[1] & 0x03) << 8 | rx[2];
        double temp = read_temp();
        double voltage = adc_value * (3.3 / (1 << ADC_BITS));
        double compensated_voltage = voltage + (temp - 25.0) * 0.001;
        int flame_detected = compensated_voltage > FLAME_THRESHOLD;

        FILE *log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Failed to open log file");
            return 1;
        }

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char time_str[20];
        strftime(time_str, 20, "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s,%d,%.3f,%.3f,%.2f,%d\n", time_str, adc_value, voltage, compensated_voltage, temp, flame_detected);
        fclose(log_file);

        gpiod_line_set_value(buzzer, flame_detected);
    }

    return 0;
}

