    int spiHandle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spiHandle < 0) {
        fprintf(stderr, "Failed to open SPI channel: %s\n", pigpio_error(spiHandle));
        return 1;
