#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define MAX_RETRIES 5

int spiHandle;
int adcChannel;
int minRaw, maxRaw;
int moistureThreshold;
int logFrequency;
char *recipientEmail;
char *msmtpConfigFile;

void sendEmail(char *message) {
    FILE *msmtp = popen("echo \"From: Plant Monitor\nTo: $recipientEmail\nSubject: Soil Moisture Alert\n\n$message\" | msmtp --config=$msmtpConfigFile $recipientEmail", "r");
    if (msmtp == NULL) {
        perror("Failed to send email");
        return;
    }
    int status = pclose(msmtp);
    if (status == -1) {
        perror("Failed to send email");
    } else if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "msmtp exited with status %d\n", WEXITSTATUS(status));
    }
}

void readSensor() {
    for (int i = 0; i < MAX_RETRIES; i++) {
        int adcValue = gpioSPIDataRW(spiHandle, (char[]){adcChannel, 0, 0}, 3);
        if (adcValue < 0) {
            perror("Failed to read from ADC");
            continue;
        }
        int moisturePercent = (adcValue - minRaw) * 100 / (maxRaw - minRaw);
        if (moisturePercent < moistureThreshold) {
            char message[100];
            sprintf(message, "The soil moisture is below the threshold at %d%%.", moisturePercent);
            sendEmail(message);
        }
        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%F %T", timeinfo);
        FILE *file = fopen("plant_data.txt", "a");
        if (file == NULL) {
            perror("Failed to open file");
            return;
        }
        fprintf(file, "%s, %d\n", timestamp, moisturePercent);
        fclose(file);
        return;
    }
}

void signalHandler(int signum) {
    gpioSPIEnd(spiHandle);
    gpioTerminate();
    exit(signum);
}

int main(int argc, char *argv[]) {
    if (argc != 8) {
        fprintf(stderr, "Usage: %s <SPI channel> <ADC channel> <min raw> <max raw> <moisture threshold> <log frequency> <recipient email> <msmtp config file>\n", argv[0]);
        return 1;
    }
    spiHandle = atoi(argv[1]);
    adcChannel = atoi(argv[2]);
    minRaw = atoi(argv[3]);
    maxRaw = atoi(argv[4]);
    moistureThreshold = atoi(argv[5]);
    logFrequency = atoi(argv[6]);
    recipientEmail = argv[7];
    msmtpConfigFile = argv[8];
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);
    if (gpioSPIBegin(spiHandle) < 0) {
        fprintf(stderr, "Failed to initialize SPI\n");
        return 1;
    }
    while (1) {
        readSensor();
        sleep(logFrequency);
    }
    return 0;
}

