#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <signal.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define ADC_CHANNEL 0
#define ADC_RESOLUTION 1024
#define DRY_CALIBRATION 700
#define WET_CALIBRATION 300

int spi_fd;

void cleanup(int signum) {
    close(spi_fd);
    exit(0);
}

int main() {
    struct spi_ioc_transfer spi_transfer;
    unsigned char spi_data[3] = {1, (ADC_CHANNEL << 6) | 0x80, 0};
    int raw_adc;
    float moisture_percentage;

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        return 1;
    }

    spi_transfer.tx_buf = (unsigned long)spi_data;
    spi_transfer.rx_buf = (unsigned long)spi_data;
    spi_transfer.len = 3;
    spi_transfer.delay_usecs = 0;
    spi_transfer.speed_hz = SPI_SPEED;
    spi_transfer.bits_per_word = 8;

    while (1) {
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_transfer) < 0) {
            perror("Failed to read from SPI device");
            return 1;
        }

        raw_adc = (spi_data[1] << 8) | spi_data[2];
        moisture_percentage = (raw_adc - DRY_CALIBRATION) / (WET_CALIBRATION - DRY_CALIBRATION) * 100;

        if (moisture_percentage < 0)
            moisture_percentage = 0;
        else if (moisture_percentage > 100)
            moisture_percentage = 100;

        printf("Raw ADC: %d, Moisture: %.2f%%\n", raw_adc, moisture_percentage);
        sleep(5);
    }

    return 0;
}

