#define ADC_CHANNEL 0
#define PRESSURE_MIN 0.5
#define PRESSURE_MAX 4.5
#define PRESSURE_RANGE 150.0

volatile sig_atomic_t stop;

void signal_handler(int signum) {
    stop = 1;
}

double read_pressure_sensor() {
    unsigned int raw_adc = gpio_spi_read(ADC_CHANNEL);
    if (raw_adc < 0) {
        perror("Failed to read from ADC");
        exit(1);
    }

    double voltage = (raw_adc * ADC_VREF) / ((1 << ADC_BITS) - 1);
    double pressure = (voltage - PRESSURE_MIN) * PRESSURE_RANGE / (PRESSURE_MAX - PRESSURE_MIN);

    return pressure;
}

