#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>

#define VREF 3.3
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_CHANNELS 3

FILE *csv_file;

void sigint_handler(int sig) {
    fclose(csv_file);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    csv_file = fopen("analog_log.csv", "w");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open CSV file\n");
        return 1;
    }

    fprintf(csv_file, "Timestamp,Channel,Voltage\n");

    int spiHandle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spiHandle < 0) {
        fprintf(stderr, "Failed to open SPI handle\n");
        return 1;
    }

    while (1) {
        for (int channel = 0; channel < ADC_CHANNELS; channel++) {
            char tx_buf[3] = {0x01, (char)(channel << 6), 0x00};
            char rx_buf[3] = {0, 0, 0};

            int result = spiXfer(spiHandle, tx_buf, rx_buf, 3);
            if (result < 0) {
                fprintf(stderr, "SPI transfer failed\n");
                continue;
            }

            int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
            double voltage = adc_value * (VREF / 1023.0);

            time_t now = time(NULL);
            struct tm *timeinfo = localtime(&now);
            char timestamp[20];
            strftime(timestamp, 20, "%FT%TZ", timeinfo);

            fprintf(csv_file, "%s,%d,%f\n", timestamp, channel, voltage);
            fflush(csv_file);

            gpioDelay(1000000); // delay for 1 second
        }
    }

    return 0;
}

