#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>

#define I2C_ADDR 0x48
#define GPIO_RELAY 17
#define GPIO_DOOR 27
#define SAMPLE_COUNT 10
#define SAMPLE_INTERVAL 50 // in ms
#define TRIGGER_THRESHOLD 0.8
#define POLL_INTERVAL 200 // in ms

int i2c_fd;
struct gpiod_chip *chip;
struct gpiod_line *relay, *door;

void cleanup(int signum) {
    gpiod_line_set_value(relay, 0);
    gpiod_line_release(relay);
    gpiod_line_release(door);
    close(i2c_fd);
    exit(0);
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    relay = gpiod_chip_get_line(chip, GPIO_RELAY);
    if (!relay) {
        perror("Failed to get GPIO line");
        return 1;
    }

    door = gpiod_chip_get_line(chip, GPIO_DOOR);
    if (!door) {
        perror("Failed to get GPIO line");
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return 1;
    }

    // Calibration
    int samples[SAMPLE_COUNT];
    for (int i = 0; i < SAMPLE_COUNT; i++) {
        usleep(SAMPLE_INTERVAL * 1000);
        // Read from ADC and store in samples[i]
    }

    int threshold = average(samples) * TRIGGER_THRESHOLD;

    while (1) {
        usleep(POLL_INTERVAL * 1000);

        // Read from ADC
        int distance;
        // Check for errors and handle them

        if (distance < threshold) {
            // Trigger door release
            gpiod_line_set_value(relay, 1);
            usleep(3000 * 1000);
            gpiod_line_set_value(relay, 0);

            // Check if door is open
            int door_state = gpiod_line_get_value(door);
            if (door_state == 0) {
                FILE *log = fopen("/var/log/door_events.log", "a");
                if (log) {
                    time_t now = time(NULL);
                    fprintf(log, "%ld: Door opened\n", now);
                    fclose(log);
                }
            }
        }
    }

    return 0;
}

