#include <pigpio.h>
#include <ADS1115.h>
#include <syslog.h>
#include <signal.h>
#include <stdbool.h>

#define HALL_EFFECT_SENSOR_PIN ADS1115_CHANNEL_0
#define ADC_ADDRESS 0x48
#define MOTOR_CONTROL_PIN 27
#define BUFFER_SIZE 10
#define THRESHOLD 500.0

ADS1115 ads1115;
float buffer[BUFFER_SIZE];
int bufferIndex = 0;
bool motorOn = false;

void handleSigint(int sig) {
    gpioWrite(MOTOR_CONTROL_PIN, 0);
    gpioTerminate();
    closelog();
    exit(0);
}

float readHallEffectSensor() {
    int16_t rawValue = ads1115.readADC(HALL_EFFECT_SENSOR_PIN);
    if (rawValue < 0) {
        syslog(LOG_ERR, "Failed to read from ADC: %d", rawValue);
        return -1.0;
    }

    float voltage = ads1115.computeVoltage(rawValue);
    if (voltage < 0 || voltage > 3.3) {
        syslog(LOG_ERR, "Invalid voltage reading: %f", voltage);
        return -1.0;
    }

    return voltage;
}

float calculateGauss(float voltage) {
    return (voltage - 2.5) / 0.0014;
}

void updateMotorControl(float gauss) {
    if (gauss > THRESHOLD) {
        if (!motorOn) {
            gpioWrite(MOTOR_CONTROL_PIN, 1);
            syslog(LOG_INFO, "Motor shutdown signal sent");
            motorOn = true;
        }
    } else {
        if (motorOn) {
            gpioWrite(MOTOR_CONTROL_PIN, 0);
            syslog(LOG_INFO, "Motor shutdown signal released");
            motorOn = false;
        }
    }
}

int main() {
    signal(SIGINT, handleSigint);
    signal(SIGTERM, handleSigint);

    openlog("HallEffectSensor", LOG_PID, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO");
        return 1;
    }

    if (ads1115.begin(ADC_ADDRESS) < 0) {
        syslog(LOG_ERR, "Failed to initialize ADC");
        return 1;
    }

    gpioSetMode(MOTOR_CONTROL_PIN, PI_OUTPUT);

    while (true) {
        float voltage = readHallEffectSensor();
        if (voltage < 0) continue;

        float gauss = calculateGauss(voltage);
        buffer[bufferIndex++] = gauss;
        if (bufferIndex == BUFFER_SIZE) bufferIndex = 0;

        float rollingAverage = 0.0;
        for (int i = 0; i < BUFFER_SIZE; i++) {
            rollingAverage += buffer[i];
        }
        rollingAverage /= BUFFER_SIZE;

        updateMotorControl(rollingAverage);

        syslog(LOG_INFO, "Voltage: %f, Gauss: %f, Rolling average: %f", voltage, gauss, rollingAverage);

        sleep(1);
    }

    return 0;
}

