    if (rawValue < 0) {
        syslog(LOG_ERR, "Failed to read from ADC: %d", rawValue);
        return -1.0;
    }

    float voltage = ads1115.computeVoltage(rawValue);
    if (voltage < 0 || voltage > 3.3) {
        syslog(LOG_ERR, "Invalid voltage reading: %f", voltage);
        return -1.0;
    }

    return voltage;
}

float calculateGauss(float voltage) {
    return (voltage - 2.5) / 0.0014;
}

void updateMotorControl(float gauss) {
    if (gauss > THRESHOLD) {
        if (!motorOn) {
            gpioWrite(MOTOR_CONTROL_PIN, 1);
            syslog(LOG_INFO, "Motor shutdown signal sent");
            motorOn = true;
        }
    } else {
        if (motorOn) {
            gpioWrite(MOTOR_CONTROL_PIN, 0);
            syslog(LOG_INFO, "Motor shutdown signal released");
            motorOn = false;
        }
    }
}

int main() {
    signal(SIGINT, handleSigint);
    signal(SIGTERM, handleSigint);

    openlog("HallEffectSensor", LOG_PID, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO");
        return 1;
    }

    if (ads1115.begin(ADC_ADDRESS) < 0) {
        syslog(LOG_ERR, "Failed to initialize ADC");
        return 1;
    }

    gpioSetMode(MOTOR_CONTROL_PIN, PI_OUTPUT);

    while (true) {
        float voltage = readHallEffectSensor();
        if (voltage < 0) continue;

        float gauss = calculateGauss(voltage);
        buffer[bufferIndex++] = gauss;
        if (bufferIndex == BUFFER_SIZE) bufferIndex = 0;

        float rollingAverage = 0.0;
        for (int i = 0; i < BUFFER_SIZE; i++) {
            rollingAverage += buffer[i];
        }
        rollingAverage /= BUFFER_SIZE;

        updateMotorControl(rollingAverage);

        syslog(LOG_INFO, "Voltage: %f, Gauss: %f, Rolling average: %f", voltage, gauss, rollingAverage);

        sleep(1);
    }

    return 0;
}
```

This program continuously reads from the ADS1115 ADC, converts the raw voltage to Gauss, and stores the last 10 readings in a circular buffer. It then calculates the rolling average of the buffer and compares it to a threshold. If the rolling average exceeds the threshold, it sets GPIO27 HIGH to signal motor shutdown. If the rolling average falls below the threshold, it resets GPIO27 to LOW.

The program also logs all readings, threshold events, and errors via syslog. If the program receives a SIGINT or SIGTERM signal, it will reset GPIO27 to LOW, terminate pigpio, and close syslog.

Please note that you need to install the pigpio and ADS1115 libraries in your Raspberry Pi before running this program. You can install them using the following commands:

```bash
sudo apt-get update
sudo apt-get install pigpio
git clone https://github.com/adafruit/Adafruit_Python_ADS1x15.git
cd Adafruit_Python_ADS1x15
sudo python setup.py install
```

Also, please replace the `ADS1115.h` with the correct path to the ADS1115 library header file in your system.

