#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define ADC_CHANNEL 0
#define ADC_VREF 3.3
#define ADC_RESOLUTION 1024

#define RAIN_LEVELS 10

volatile sig_atomic_t stop;

void sigint_handler(int signum) {
    stop = 1;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    int spiHandle = spiOpen(0, 1000000, 0);
    if (spiHandle < 0) {
        fprintf(stderr, "Failed to open SPI bus\n");
        return 1;
    }

    while (!stop) {
        unsigned char data[3] = {1, (8 + ADC_CHANNEL) << 4, 0};
        unsigned char result[3] = {0, 0, 0};

        if (spiXfer(spiHandle, data, result, 3) < 0) {
            fprintf(stderr, "Failed to transfer SPI data\n");
            continue;
        }

        unsigned int adcValue = ((result[1] & 0x03) << 8) | result[2];
        float rainfallIntensity = (float)adcValue / ADC_RESOLUTION * RAIN_LEVELS;

        time_t now = time(NULL);
        printf("%s: ADC=%d, Intensity=%.2f\n", ctime(&now), adcValue, rainfallIntensity);

        sleep(1);
    }

    spiClose(spiHandle);
    gpioTerminate();

    return 0;
}

