    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    int spiHandle = spiOpen(0, SPI_SPEED, 0);
    if (spiHandle < 0) {
        fprintf(stderr, "Failed to open SPI: %d\n", spiHandle);
        return 1;
    }

    if (gpioSetMode(PWM_CHANNEL, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_CHANNEL);
        return 1;
    }

    if (gpioSetPWMfrequency(PWM_CHANNEL, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (!stop) {
        char buf[3] = {1, (char)(8 + ADC_CHANNEL << 4), 0};
        if (spiXfer(spiHandle, buf, 3) < 0) {
            fprintf(stderr, "Failed to transfer SPI data\n");
            return 1;
        }

        int adcValue = ((buf[1] & 3) << 8) | buf[2];
        int dutyCycle = (adcValue * PWM_FREQ) / 1023;

        gpioPWM(PWM_CHANNEL, dutyCycle);

        printf("ADC Value: %d, Duty Cycle: %d\n", adcValue, dutyCycle);

        gpioDelay(1000000); // delay for 1 second
    }

    spiClose(spiHandle);
    gpioTerminate();

    return 0;
}

