#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <ADS1115.h>

#define ADC_ADDRESS 0x48
#define ADC_GAIN PGA_4_096V
#define SENSOR_PIN ADS1115_CHANNEL_0
#define LED_PIN 17
#define SLEEP_TIME 100 // in ms
#define THRESHOLD 100.0 // in Gauss

ADS1115 ads1115;

void sigint_handler(int sig) {
    gpioTerminate();
    exit(0);
}

double read_sensor() {
    int16_t raw = ADS1115_readADC_SingleEnded(ads1115, SENSOR_PIN);
    if (raw < 0) {
        fprintf(stderr, "Failed to read from ADC: %s\n", strerror(errno));
        exit(1);
    }
    return ADS1115_computeVolts(ads1115, raw);
}

void blink_led() {
    gpioWrite(LED_PIN, 1);
    time_sleep(0.005); // 50 ms on
    gpioWrite(LED_PIN, 0);
    time_sleep(0.005); // 50 ms off
}

int main(int argc, char *argv[]) {
    double threshold = THRESHOLD;
    if (argc > 1) {
        threshold = atof(argv[1]);
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    ads1115 = ADS1115_init(ADC_ADDRESS, ADC_GAIN);
    if (ads1115 < 0) {
        fprintf(stderr, "Failed to initialize ADS1115: %s\n", strerror(errno));
        return 1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);

    while (1) {
        double value = read_sensor();
        printf("Magnetic field strength: %.2f Gauss\n", value);

        if (value > threshold) {
            for (int i = 0; i < 20; i++) {
                blink_led();
                time_sleep(0.005); // 50 ms off
            }
        }

        time_sleep(SLEEP_TIME / 1000.0); // sleep for SLEEP_TIME ms
    }

    return 0;
}

