#include <pigpio.h>
#include <mqtt/client.h>
#include <syslog.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>

#define RELAY_PIN 17
#define ADC_CHANNEL 0
#define ADC_SPI_CLOCK 1000000
#define ADC_SPI_DEVICE "/dev/spidev0.0"
#define MQTT_BROKER "mqtt://your_broker"
#define MQTT_CLIENT_ID "soil_moisture_sensor"
#define SOIL_MOISTURE_TOPIC "soil_moisture"
#define PUMP_CONTROL_TOPIC "pump_control"

mqtt::client client(MQTT_BROKER, MQTT_CLIENT_ID);

void on_pump_control(const std::string& topic, const std::string& message) {
    if (message == "pump_on") {
        gpioWrite(RELAY_PIN, 1);
    } else if (message == "pump_off") {
        gpioWrite(RELAY_PIN, 0);
    }
}

void read_and_publish_moisture() {
    // Read from ADC
    int adc_value = spiRead(ADC_SPI_DEVICE, ADC_CHANNEL, ADC_SPI_CLOCK);
    if (adc_value < 0) {
        syslog(LOG_ERR, "Failed to read from ADC: %s", strerror(errno));
        return;
    }

    // Convert ADC value to moisture percentage
    int moisture_percentage = adc_value_to_percentage(adc_value);

    // Publish moisture reading
    client.publish(SOIL_MOISTURE_TOPIC, std::to_string(moisture_percentage));
}

void handle_sigint(int sig) {
    // Clean up resources
    gpioWrite(RELAY_PIN, 0);
    spiClose(ADC_SPI_DEVICE);
    client.disconnect();
    gpioTerminate();
    closelog();
    exit(0);
}

int main() {
    // Initialize syslog
    openlog("soil_moisture_sensor", LOG_PID, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio: %s", strerror(errno));
        return 1;
    }

    // Set up relay pin as output
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Open SPI device
    int spi_handle = spiOpen(ADC_SPI_DEVICE, ADC_SPI_CLOCK, 0);
    if (spi_handle < 0) {
        syslog(LOG_ERR, "Failed to open SPI device: %s", strerror(errno));
        return 1;
    }

    // Initialize MQTT client
    try {
        client.connect();
        client.subscribe(PUMP_CONTROL_TOPIC, on_pump_control);
    } catch (const mqtt::exception& e) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", e.what());
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    // Main loop
    while (1) {
        read_and_publish_moisture();
        sleep(60);
    }

    return 0;
}

