    signal(SIGTERM, sig_handler);

    int spiHandle = spiOpen(SPI_CHANNEL, 1000000, 0);
    if (spiHandle < 0) {
        fprintf(stderr, "Failed to open SPI channel: %d\n", spiHandle);
        return 1;
    }

    FILE *file = fopen("sensor_data.csv", "w");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file\n");
        return 1;
    }

    while (1) {
        for (int channel = 0; channel < 3; channel++) {
            char data[3] = {1, (char)(8 + channel), 0};
            char result[3] = {0};

            int status = spiXfer(spiHandle, data, result, sizeof(data));
            if (status < 0) {
                fprintf(stderr, "Failed to transfer SPI data: %d\n", status);
                return 1;
