#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <unistd.h>

#define ADC_CHANNEL 0
#define GPIO_MOTOR1 17
#define GPIO_MOTOR2 27
#define PWM_FREQ 100
#define ADC_THRESHOLD 500
#define ADC_MAX_VALUE 1023
#define SAMPLE_INTERVAL_MS 10

int adc_fd;

void sig_handler(int signum) {
    gpioWrite(GPIO_MOTOR1, 0);
    gpioWrite(GPIO_MOTOR2, 0);
    gpioTerminate();
    close(adc_fd);
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    if ((adc_fd = spiOpen(0, 0, 1000000)) < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        return 1;
    }

    gpioSetMode(GPIO_MOTOR1, PI_OUTPUT);
    gpioSetMode(GPIO_MOTOR2, PI_OUTPUT);

    gpioSetPWMfrequency(GPIO_MOTOR1, PWM_FREQ);
    gpioSetPWMfrequency(GPIO_MOTOR2, PWM_FREQ);

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        unsigned char data[3] = {1, (char)(8 + ADC_CHANNEL) << 4, 0};
        char result[3] = {0, 0, 0};

        if (spiXfer(adc_fd, data, result, sizeof(data)) < 0) {
            fprintf(stderr, "Failed to read from ADC\n");
            continue;
        }

        int adc_value = (result[1] & 0x03) << 8 | result[2];

        if (adc_value > ADC_THRESHOLD) {
            int pwm_duty = (adc_value * 100) / ADC_MAX_VALUE;
            gpioPWM(GPIO_MOTOR1, pwm_duty);
            gpioPWM(GPIO_MOTOR2, pwm_duty);

            FILE *log_file = fopen("vibration_log.txt", "a");
            if (log_file != NULL) {
                time_t now = time(NULL);
                fprintf(log_file, "%s: ADC value = %d, PWM duty = %d\n", ctime(&now), adc_value, pwm_duty);
                fclose(log_file);
            }
        } else {
            gpioWrite(GPIO_MOTOR1, 0);
            gpioWrite(GPIO_MOTOR2, 0);
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    return 0;
}

