#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define GPIO_PUMP 17
#define THRESHOLD 30

int spiHandle;

void sigint_handler(int sig) {
    gpioWrite(GPIO_PUMP, 0);
    gpioTerminate();
    spiClose(spiHandle);
    exit(0);
}

int read_adc() {
    unsigned char data[3] = {1, (char)(ADC_CHANNEL<<6), 0};
    unsigned char result[3] = {0, 0, 0};

    for(int i=0; i<3; i++) {
        spiXfer(spiHandle, data, result, 3);
        if(result[1]&0x80) {
            continue;
        } else {
            break;
        }
    }

    return ((result[1]&0x3F)<<8)|result[2];
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    if(gpioInitialise()<0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    spiHandle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if(spiHandle<0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        return 1;
    }

    if(gpioSetMode(GPIO_PUMP, PI_OUTPUT)<0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        return 1;
    }

    while(1) {
        int adc_value = read_adc();
        int moisture = (100.0 * adc_value) / 1023.0;

        printf("%ld, Moisture: %d%%\n", time(NULL), moisture);

        if(moisture < THRESHOLD) {
            gpioWrite(GPIO_PUMP, 1);
        } else {
            gpioWrite(GPIO_PUMP, 0);
        }

        time_sleep(60);
    }

    return 0;
}

