#include <pigpio.h>
#include <stdio.h>
#include <signal.h>
#include <time.h>

#define ADC_CHANNELS 3
#define ADC_SPI_CHANNEL 0
#define ADC_SPI_SPEED 1000000
#define ADC_SPI_MODE 0
#define ADC_SPI_CS 0

#define GPIO_PWM 17
#define PWM_FREQ 100
#define PWM_RANGE 100

#define LOG_FILE "irrigation.log"

FILE *logFile;

void signalHandler(int signum) {
    gpioWrite(GPIO_PWM, 0);
    spiClose(ADC_SPI_CHANNEL);
    fclose(logFile);
    gpioTerminate();
    exit(signum);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    int adcSpi = spiOpen(ADC_SPI_CHANNEL, ADC_SPI_SPEED, ADC_SPI_MODE);
    if (adcSpi < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        return 1;
    }

    logFile = fopen(LOG_FILE, "w");
    if (logFile == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    gpioSetMode(GPIO_PWM, PI_OUTPUT);
    gpioPWMfrequency(GPIO_PWM, PWM_FREQ);

    while (1) {
        int adcValues[ADC_CHANNELS];
        int average = 0;
        int i;
        for (i = 0; i < ADC_CHANNELS; i++) {
            char tx[3] = {1, (8 + ADC_SPI_CS) << 4, 0};
            char rx[3];
            spiXfer(adcSpi, tx, rx, sizeof(tx));
            adcValues[i] = (rx[1] << 8) | rx[2];
            average += adcValues[i];
        }
        average /= ADC_CHANNELS;

        int valvePosition = PWM_RANGE - (average * PWM_RANGE / 1023);
        gpioPWMwrite(GPIO_PWM, valvePosition);

        time_t now = time(NULL);
        fprintf(logFile, "%s: ADC values: %d, %d, %d. Average: %d. Valve position: %d%%\n",
                ctime(&now), adcValues[0], adcValues[1], adcValues[2], average, valvePosition);
        fflush(logFile);

        sleep(5);
    }

    return 0;
}

