                    retries++;
                    sleep(1 << retries);
                }
            }
        }
        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read ADC value\n");
        }
    }

    fclose(file);
    gpioSPIEnd(SPI_CHANNEL);
    gpioTerminate();

    return 0;
}

