#define ADC_MAX_RETRIES 3

volatile sig_atomic_t running = 1;

void interrupt_handler(int signum) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int spi_fd;
    unsigned char tx[3] = {0x01, 0x00, 0x00};
    unsigned char rx[3];
    int adc_value;
    double ppm;
    char buffer[50];
    FILE *log_file;

    signal(SIGINT, interrupt_handler);
    signal(SIGTERM, interrupt_handler);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        return 1;
    }

    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    log_file = fopen("alcohol_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    tx[1] = (ADC_CHANNEL << 4) | ADC_SINGLE_ENDED;

    while (running) {
        int retries;
        for (retries = 0; retries < ADC_MAX_RETRIES; retries++) {
            if (gpiod_line_set_value(line, 1) < 0) {
                perror("Failed to set GPIO line value");
                return 1;
            }

            if (write(spi_fd, tx, 3) != 3) {
                perror("Failed to write to SPI device");
                return 1;
            }

            if (read(spi_fd, rx, 3) != 3) {
                perror("Failed to read from SPI device");
                return 1;
            }

            if (gpiod_line_set_value(line, 0) < 0) {
                perror("Failed to clear GPIO line value");
                return 1;
            }

            adc_value = ((rx[1] & 0x03) << 8) | rx[2];
            if (adc_value > 0 && adc_value < 1023)
                break;

            usleep(100000);
        }

        if (retries == ADC_MAX_RETRIES) {
            fprintf(log_file, "%s: Sensor error\n",
                    buffer, 49, "%Y-%m-%dT%H:%M:%SZ");
            continue;
        }

        ppm = (adc_value * 0.5) - 10.0;

        strftime(buffer, 49, "%Y-%m-%dT%H:%M:%SZ", gmtime(NULL));
        if (ppm > 50.0)
            fprintf(log_file, "%s: Alcohol detected! Limit exceeded.\n", buffer);
        else if (ppm < 20.0)
            fprintf(log_file, "%s: Sobriety confirmed.\n", buffer);
        else
            fprintf(log_file, "%s: Alcohol level within acceptable range.\n", buffer);

        sleep(1);
    }

    fclose(log_file);
    close(spi_fd);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

