#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>

#define MOTOR1_ENABLE 18
#define MOTOR1_DIRECTION 23
#define MOTOR2_ENABLE 24
#define MOTOR2_DIRECTION 25
#define ADC_CHANNEL_1 0
#define ADC_CHANNEL_2 1
#define ADC_SPI_CHANNEL 0
#define ADC_SPI_SPEED 1000000
#define ADC_SPI_MODE 0
#define ADC_SPI_MOSI 10
#define ADC_SPI_MISO 9
#define ADC_SPI_SCLK 11
#define ADC_SPI_CE0 8
#define MIN_SPEED 50
#define MAX_SPEED 255

void cleanup(void);
void handle_signal(int signum);

int main(void)
{
    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Set up GPIO
    gpioSetMode(MOTOR1_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR1_DIRECTION, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR2_DIRECTION, PI_OUTPUT);

    // Set up ADC SPI
    int adc_spi = spiOpen(ADC_SPI_CHANNEL, ADC_SPI_SPEED, ADC_SPI_MODE);
    if (adc_spi < 0)
    {
        fprintf(stderr, "Failed to open ADC SPI channel\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1)
    {
        // Read from ADC
        unsigned char adc_data[3] = {1, (char)(ADC_CHANNEL_1 << 6), 0};
        spiXfer(adc_spi, adc_data, 3);
        int potentiometer_1 = (adc_data[1] << 8) | adc_data[2];

        adc_data[1] = (char)(ADC_CHANNEL_2 << 6);
        spiXfer(adc_spi, adc_data, 3);
        int potentiometer_2 = (adc_data[1] << 8) | adc_data[2];

        // Map potentiometer values to speed factors
        int speed_factor_1 = log(potentiometer_1 + 1) / log(1024);
        int speed_factor_2 = log(potentiometer_2 + 1) / log(1024);

        // Control motors
        int speed_1 = MIN_SPEED + (MAX_SPEED - MIN_SPEED) * speed_factor_1;
        int speed_2 = MIN_SPEED + (MAX_SPEED - MIN_SPEED) * speed_factor_2;

        gpioPWM(MOTOR1_ENABLE, speed_1);
        gpioWrite(MOTOR1_DIRECTION, 1); // 1 for forward, 0 for backward

        gpioPWM(MOTOR2_ENABLE, speed_2);
        gpioWrite(MOTOR2_DIRECTION, 0); // 1 for forward, 0 for backward

        // Wait for 2 seconds
        sleep(2);

        // Decelerate
        for (int i = speed_1; i >= MIN_SPEED; i--)
        {
            gpioPWM(MOTOR1_ENABLE, i);
            gpioPWM(MOTOR2_ENABLE, i);
            sleep(1);
        }

        // Wait for 5 seconds
        sleep(5);
    }

    return 0;
}

void cleanup(void)
{
    // Clean up resources
    spiClose(ADC_SPI_CHANNEL);
    gpioTerminate();
}

void handle_signal(int signum)
{
    // Handle signals
    cleanup();
    exit(0);
}

