#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define ADC_CHANNEL 0
#define ADC_SPI_SPEED 1000000
#define ADC_BITS 10
#define ADC_VOLTS 3.3
#define ADC_MAX ((1 << ADC_BITS) - 1)

#define MIC_SAMPLES 5000
#define MIC_THRESHOLD 0.1

#define LED_GPIO 17

static volatile sig_atomic_t signal_received = 0;

void signal_handler(int sig) {
    signal_received = 1;
}

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open SPI
    int spi = spiOpen(0, ADC_SPI_SPEED, 0);
    if (spi < 0) {
        fprintf(stderr, "Failed to open SPI: %d\n", spi);
        return 1;
    }

    // Set up GPIO
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Calibrate ambient noise
    int sum = 0;
    for (int i = 0; i < MIC_SAMPLES && !signal_received; i++) {
        unsigned char buf[3] = {1, (char)(ADC_CHANNEL << 6), 0};
        gpioSPIXfer(spi, buf, 3);
        sum += (buf[1] & 0x03) << 8 | buf[2];
        gpioDelay(1000);
    }
    float ambient = (float)sum / MIC_SAMPLES;
    float threshold = ambient * (1 + MIC_THRESHOLD);

    // Main loop
    while (!signal_received) {
        unsigned char buf[3] = {1, (char)(ADC_CHANNEL << 6), 0};
        gpioSPIXfer(spi, buf, 3);
        int level = (buf[1] & 0x03) << 8 | buf[2];

        if (level > threshold) {
            gpioWrite(LED_GPIO, 1);
            gpioDelay(100000); // 10 ms debounce
        } else {
            gpioWrite(LED_GPIO, 0);
        }

        gpioDelay(1000);
    }

    // Cleanup
    gpioWrite(LED_GPIO, 0);
    spiClose(spi);
    gpioTerminate();

    return 0;
}

