        unsigned char buf[3] = {1, (char)(ADC_CHANNEL << 6), 0};
        gpioSPIXfer(spi, buf, 3);
        sum += (buf[1] & 0x03) << 8 | buf[2];
        gpioDelay(1000);
    }
    float ambient = (float)sum / MIC_SAMPLES;
    float threshold = ambient * (1 + MIC_THRESHOLD);

    // Main loop
    while (!signal_received) {
        unsigned char buf[3] = {1, (char)(ADC_CHANNEL << 6), 0};
        gpioSPIXfer(spi, buf, 3);
        int level = (buf[1] & 0x03) << 8 | buf[2];

        if (level > threshold) {
            gpioWrite(LED_GPIO, 1);
            gpioDelay(100000); // 10 ms debounce
        } else {
            gpioWrite(LED_GPIO, 0);
        }

        gpioDelay(1000);
    }

    // Cleanup
    gpioWrite(LED_GPIO, 0);
    spiClose(spi);
    gpioTerminate();

    return 0;
}
```

This program continuously samples the microphone and checks if the sound level exceeds the threshold. If it does, it turns on the LED. If not, it turns off the LED. The program also handles SIGINT and cleans up the GPIO and SPI resources.

Please note that this is a simple example and does not include error handling for all possible SPI and GPIO errors. You may need to add more error checking code to handle these cases in a production environment.

