#include <stdio.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>

#define SPI_DEV "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 8
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED 1000000
#define ADC_CHANNEL 0
#define SAMPLE_RATE 1000

struct gpiod_chip *chip;
struct gpiod_line *line;
int spi_fd;
FILE *log_file;

void cleanup(int signum) {
    gpiod_line_release(line);
    close(spi_fd);
    fclose(log_file);
    exit(0);
}

int main() {
    struct timespec sample_period;
    sample_period.tv_sec = 0;
    sample_period.tv_nsec = 1000 * 1000; // 1 ms

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        return 1;
    }

    int ret = gpiod_line_request_output(line, "ADC_CS", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line as output");
        return 1;
    }

    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    ret = ioctl(spi_fd, SPI_MODE, SPI_MODE);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        return 1;
    }

    ret = ioctl(spi_fd, SPI_BITS_PER_WORD, SPI_BITS_PER_WORD);
    if (ret < 0) {
        perror("Failed to set SPI bits per word");
        return 1;
    }

    ret = ioctl(spi_fd, SPI_MAX_SPEED, SPI_MAX_SPEED);
    if (ret < 0) {
        perror("Failed to set SPI max speed");
        return 1;
    }

    log_file = fopen("audio_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    uint8_t tx_buf[3] = {0x01, (0x08 | ADC_CHANNEL) << 4, 0x00};
    uint8_t rx_buf[3] = {0};

    while (1) {
        gpiod_line_set_value(line, 0);

        struct spi_ioc_transfer tr = {
            .tx_buf = (unsigned long)tx_buf,
            .rx_buf = (unsigned long)rx_buf,
            .len = 3,
            .delay_usecs = 0,
            .speed_hz = SPI_MAX_SPEED,
            .bits_per_word = SPI_BITS_PER_WORD,
        };

        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
        if (ret < 0) {
            perror("Failed to transfer SPI message");
            return 1;
        }

        gpiod_line_set_value(line, 1);

        uint32_t raw_adc_value = (rx_buf[1] << 8) | rx_buf[2];

        struct timespec timestamp;
        clock_gettime(CLOCK_MONOTONIC_RAW, &timestamp);

        fprintf(log_file, "%ld|%u\n", timestamp.tv_nsec, raw_adc_value);
        fflush(log_file);

        nanosleep(&sample_period, NULL);
    }

    return 0;
}

