#include <pigpio.h>
#include <stdio.h>
#include <signal.h>
#include <unistd.h>

#define ADXL335_X_CHANNEL 0
#define ADXL335_Y_CHANNEL 1
#define ADXL335_Z_CHANNEL 2
#define MCP3008_CS_PIN 8
#define MCP3008_MOSI_PIN 10
#define MCP3008_MISO_PIN 9
#define MCP3008_SCLK_PIN 11

#define ADXL335_SENSITIVITY 300.0 // mV/g
#define ADXL335_BIAS 1.5 // V
#define ADC_REF_VOLTAGE 3.3 // V
#define ADC_RESOLUTION 1024.0 // 10-bit

int adc_handle;

void sig_handler(int signum) {
    gpioSPI(adc_handle, 0);
    gpioTerminate();
    exit(0);
}

double read_adxl335_channel(int channel) {
    unsigned char adc_command = 0x01;
    adc_command |= (channel & 0x07) << 4;

    gpioSPI(adc_handle, 1);
    unsigned char adc_response[3] = {0, 0, 0};
    gpioSPI(adc_handle, 3);
    gpioSPI(adc_handle, adc_command);
    gpioSPI(adc_handle, 3);
    gpioSPI(adc_handle, adc_response);
    gpioSPI(adc_handle, 0);

    unsigned int adc_value = (adc_response[1] << 8) | adc_response[2];
    double adc_voltage = (adc_value * ADC_REF_VOLTAGE) / ADC_RESOLUTION;
    double adxl335_voltage = adc_voltage - ADXL335_BIAS;
    double acceleration = adxl335_voltage * 1000.0 / ADXL335_SENSITIVITY; // g

    return acceleration;
}

int main() {
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    adc_handle = spiOpen(0, 8000000, 0); // Open SPI0 with 8MHz clock, CS0
    if (adc_handle < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpioTerminate();
        return 1;
    }

    while (1) {
        double x_acceleration = read_adxl335_channel(ADXL335_X_CHANNEL);
        double y_acceleration = read_adxl335_channel(ADXL335_Y_CHANNEL);
        double z_acceleration = read_adxl335_channel(ADXL335_Z_CHANNEL);

        printf("X: %.2f g, Y: %.2f g, Z: %.2f g\n", x_acceleration, y_acceleration, z_acceleration);

        usleep(100000); // 100ms delay
    }

    return 0;
}

