#define ADC_CHANNEL 0
#define ADC_SPI_SPEED 500000
#define ADC_SPI_DEVICE "/dev/spidev0.0"
#define GPIO_PUMP 17
#define WATER_LEVEL_THRESHOLD 30

void handle_signal(int signum) {
    gpioWrite(GPIO_PUMP, PI_OFF);
    gpioTerminate();
    exit(0);
}

int main() {
    FILE *log_file;
    time_t now;
    struct tm *timeinfo;
    char buffer[80];
    int value;
    double moisture_level;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    gpioSetMode(GPIO_PUMP, PI_OUTPUT);
    gpioWrite(GPIO_PUMP, PI_OFF);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    log_file = fopen("watering.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    while (1) {
        time(&now);
        timeinfo = localtime(&now);
        strftime(buffer, sizeof(buffer), "%d-%m-%Y %H:%M:%S", timeinfo);
        fprintf(log_file, "%s - Program start\n", buffer);

        value = spiRead(ADC_SPI_DEVICE, ADC_CHANNEL, ADC_SPI_SPEED, &value);
        if (value < 0) {
            fprintf(log_file, "%s - Failed to read from ADC: %s\n", buffer, strerror(value));
            continue;
        }

        moisture_level = (double)value / 1023 * 100;
        fprintf(log_file, "%s - Moisture level: %.2f%%\n", buffer, moisture_level);

        if (moisture_level < WATER_LEVEL_THRESHOLD) {
            gpioWrite(GPIO_PUMP, PI_ON);
            fprintf(log_file, "%s - Pump turned ON\n", buffer);
        } else {
            gpioWrite(GPIO_PUMP, PI_OFF);
            fprintf(log_file, "%s - Pump turned OFF\n", buffer);
        }

        fflush(log_file);
        sleep(60);
    }

    fclose(log_file);
    gpioTerminate();
    return 0;
}

