#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>

#define SPI_DEV "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000
#define CHANNELS 3

int fd;
FILE *file;

void close_spi_and_file(int signum) {
    close(fd);
    fclose(file);
    exit(0);
}

int main() {
    struct spi_ioc_transfer spi;
    unsigned char data[3];
    int channel, value;
    char filename[] = "sensor_data.csv";

    fd = open(SPI_DEV, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &SPI_MODE) == -1) {
        perror("Failed to set SPI mode");
        return 1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) == -1) {
        perror("Failed to set SPI bits per word");
        return 1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) == -1) {
        perror("Failed to set SPI speed");
        return 1;
    }

    file = fopen(filename, "w");
    if (file == NULL) {
        perror("Failed to open CSV file");
        return 1;
    }

    signal(SIGINT, close_spi_and_file);

    while (1) {
        for (channel = 0; channel < CHANNELS; channel++) {
            data[0] = 0x01;
            data[1] = 0x80 | (channel << 4);
            data[2] = 0x00;

            spi.tx_buf = (unsigned long)data;
            spi.rx_buf = (unsigned long)data;
            spi.len = 3;
            spi.delay_usecs = 0;
            spi.speed_hz = SPI_SPEED;
            spi.bits_per_word = SPI_BITS_PER_WORD;

            if (ioctl(fd, SPI_IOC_MESSAGE(1), &spi) == -1) {
                perror("Failed to send SPI message");
                return 1;
            }

            value = ((data[1] & 0x03) << 8) | data[2];
            fprintf(file, "%d,%d\n", channel, value);
            fflush(file);
        }

        sleep(1);
    }

    return 0;
}

