#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <signal.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <cjson/cJSON.h>

#define LED_GPIO 17
#define MQTT_BROKER "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "rpi_led_control"
#define MQTT_TOPIC "home/led_control"

bool led_state = false;
struct mosquitto *mqtt_client = NULL;

void on_connect(struct mosquitto *client, void *userdata, int result) {
    if (result != 0) {
        fprintf(stderr, "[%ld] Error connecting to MQTT broker: %s\n", time(NULL), mosquitto_strerror(result));
    } else {
        mosquitto_subscribe(client, NULL, MQTT_TOPIC, 0);
    }
}

void on_message(struct mosquitto *client, void *userdata, const struct mosquitto_message *message) {
    cJSON *json = cJSON_Parse((char *)message->payload);
    if (json == NULL) {
        fprintf(stderr, "[%ld] Error parsing JSON: %s\n", time(NULL), cJSON_GetErrorPtr());
        return;
    }

    cJSON *led_state_json = cJSON_GetObjectItemCaseSensitive(json, "led_state");
    if (cJSON_IsBool(led_state_json)) {
        led_state = led_state_json->boolValue;
        gpioWrite(LED_GPIO, led_state);
    } else {
        fprintf(stderr, "[%ld] Invalid JSON: led_state must be a boolean\n", time(NULL));
    }

    cJSON_Delete(json);
}

void on_disconnect(struct mosquitto *client, void *userdata, int result) {
    fprintf(stderr, "[%ld] Disconnected from MQTT broker\n", time(NULL));
}

void on_signal(int signal) {
    if (mqtt_client != NULL) {
        mosquitto_disconnect(mqtt_client);
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    mosquitto_lib_cleanup();
    exit(0);
}

int main() {
    signal(SIGINT, on_signal);
    signal(SIGTERM, on_signal);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "[%ld] Error initializing GPIO\n", time(NULL));
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    mqtt_client = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (mqtt_client == NULL) {
        fprintf(stderr, "[%ld] Error creating MQTT client\n", time(NULL));
        return 1;
    }

    mosquitto_connect_callback_set(mqtt_client, on_connect);
    mosquitto_message_callback_set(mqtt_client, on_message);
    mosquitto_disconnect_callback_set(mqtt_client, on_disconnect);

    if (mosquitto_connect(mqtt_client, MQTT_BROKER, MQTT_PORT, 0) != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "[%ld] Error connecting to MQTT broker\n", time(NULL));
        return 1;
    }

    mosquitto_loop_start(mqtt_client);

    while (true) {
        sleep(1);
    }

    return 0;
}

