    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Failed to open chip");
        exit(1);
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    led_line = gpiod_chip_get_line(chip, LED_PIN);

    if (!sensor_line || !led_line) {
        perror("Failed to get line");
        gpiod_chip_close(chip);
        exit(1);
    }

    if (gpiod_line_request_input(sensor_line, "ky-038-sensor") < 0) {
        perror("Failed to request input for sensor");
        gpiod_line_release(sensor_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        exit(1);
    }

    if (gpiod_line_request_output(led_line, "alarm-led", 0) < 0) {
        perror("Failed to request output for LED");
        gpiod_line_release(sensor_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        exit(1);
    }

