#include <gpiod.h>

volatile sig_atomic_t stop;

void intHandler(int signum) {
    stop = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_event event;
    FILE *log_file;
    char buffer[256];
    time_t t;

    signal(SIGINT, intHandler);
    signal(SIGTERM, intHandler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip == NULL) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    line = gpiod_chip_get_line(chip, 17);
    if (line == NULL) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_falling_edge_events(line, "vibration-monitor") < 0) {
        perror("Failed to request falling-edge events");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    log_file = fopen("/var/log/vibration_shutdown.log", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    while (!stop) {
        if (gpiod_line_event_wait(line, 1000) < 0) {
            perror("Failed to wait for event");
            break;
        }

        if (gpiod_line_event_read(line, &event) < 0) {
            perror("Failed to read event");
            break;
        }

        t = time(NULL);
        sprintf(buffer, "Vibration detected at %s", ctime(&t));
        printf("%s", buffer);
        fprintf(log_file, "%s", buffer);
        fflush(log_file);

        system("sudo shutdown -h now");
    }

    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

