#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_REF_VOLTAGE 3.3
#define LM35_SENSITIVITY 10.0
#define BUFFER_SIZE 120
#define FILE_NAME "temp_log.dat"

float buffer[BUFFER_SIZE];
int buffer_index = 0;
FILE *file;

void signal_handler(int signum) {
    if (file) fclose(file);
    gpioTerminate();
    exit(0);
}

float read_temperature() {
    unsigned char tx[3] = {0x01, 0x80, 0x00};
    unsigned char rx[3] = {0, 0, 0};

    if (gpioSPITransfer(SPI_CHANNEL, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1.0;
    }

    int raw_adc = (rx[1] << 8) | rx[2];
    float voltage = (raw_adc * ADC_REF_VOLTAGE) / 1023.0;
    float temperature = voltage * LM35_SENSITIVITY;

    return temperature;
}

void write_buffer_to_file() {
    if (fseek(file, 0, SEEK_SET) != 0) {
        fprintf(stderr, "Failed to seek in file\n");
        return;
    }

    if (fwrite(buffer, sizeof(float), BUFFER_SIZE, file) != BUFFER_SIZE) {
        fprintf(stderr, "Failed to write to file\n");
    }
}

int main() {
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to set SIGINT handler\n");
        return 1;
    }

    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to set SIGTERM handler\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSPIBegin(SPI_CHANNEL, SPI_SPEED) < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        return 1;
    }

    file = fopen(FILE_NAME, "wb+");
    if (!file) {
        fprintf(stderr, "Failed to open file\n");
        return 1;
    }

    while (1) {
        float temperature = read_temperature();
        if (temperature >= 0.0) {
            buffer[buffer_index++] = temperature;
            if (buffer_index == BUFFER_SIZE) {
                buffer_index = 0;
                write_buffer_to_file();
            }
            printf("Temperature: %.2f °C\n", temperature);
        }
        sleep(5);
    }

    return 0;
}

