#include <pigpio.h>
#include <stdio.h>
#include <time.h>
#include <signal.h>

#define ADC_CHANNEL 0
#define TMP36_VOLTS_PER_DEGREE 0.01
#define DAC_VOLTS_PER_DEGREE 0.083333333333333333333333333333333
#define DAC_OFFSET 0.0
#define DAC_REF_VOLTAGE 3.3

int spiHandle;
int i2cHandle;
FILE *logFile;

void sigint_handler(int sig) {
    gpioSPIClose(spiHandle);
    gpioI2CClose(i2cHandle);
    fclose(logFile);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    spiHandle = gpioSPIOpen(0, 500000, 3);
    if (spiHandle < 0) {
        fprintf(stderr, "Failed to open SPI bus\n");
        return 1;
    }

    i2cHandle = gpioI2COpen(1, 0x62, 0);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    logFile = fopen("temperature_log.txt", "w");
    if (logFile == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    while (1) {
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        unsigned char spiData[3] = {1, (char)(ADC_CHANNEL << 6), 0};
        unsigned char adcReading[3];
        gpioSPIDataRW(spiHandle, spiData, 3);
        gpioSPIDataRW(spiHandle, adcReading, 3);

        int rawADC = ((adcReading[1] & 0x03) << 8) | adcReading[2];
        float voltage = rawADC * 3.3 / 1023.0;
        float temperature = voltage / TMP36_VOLTS_PER_DEGREE;

        float dacVoltage = (temperature * DAC_VOLTS_PER_DEGREE) + DAC_OFFSET;
        dacVoltage = dacVoltage > DAC_REF_VOLTAGE ? DAC_REF_VOLTAGE : dacVoltage;
        dacVoltage = dacVoltage < 0 ? 0 : dacVoltage;

        unsigned char dacCommand = (unsigned char)((dacVoltage / DAC_REF_VOLTAGE) * 256.0);
        gpioI2CWriteByte(i2cHandle, dacCommand);

        fprintf(logFile, "%s, %d, %.2f, %.2f\n", timestamp, rawADC, temperature, dacVoltage);
        fflush(logFile);

        printf("%s, %d, %.2f, %.2f\n", timestamp, rawADC, temperature, dacVoltage);

        gpioDelay(500000000); // 0.5 seconds
    }

    return 0;
}

