#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_CHANNELS 3

FILE *file;

void signal_handler(int signum) {
    fclose(file);
    spiClose(SPI_CHANNEL);
    gpioTerminate();
    printf("\nGoodbye!\n");
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    int spiHandle = spiOpen(SPI_CHANNEL, SPI_SPEED);
    if (spiHandle < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        return 1;
    }

    file = fopen("soil_data.txt", "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (1) {
        for (int i = 0; i < ADC_CHANNELS; i++) {
            unsigned char data[3] = {1, 0x80 | (i << 6), 0};
            char result[3] = {0, 0, 0};

            int status = spiXfer(spiHandle, data, result, 3);
            if (status < 0) {
                fprintf(stderr, "Failed to read from ADC\n");
                continue;
            }

            int adc_value = (result[1] & 0x03) << 8 | result[2];
            if (adc_value < 0 || adc_value > 1023) {
                fprintf(stderr, "Invalid ADC value\n");
                continue;
            }

            double moisture = (1.0 - (adc_value / 1023.0)) * 100.0;

            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char time_str[20];
            strftime(time_str, 20, "%Y-%m-%d %H:%M:%S", tm_info);

            fprintf(file, "%s Sensor %d: %.2f%% moisture\n", time_str, i, moisture);
            fflush(file);
        }

        gpioDelay(10000000); // 10 seconds delay
    }

    return 0;
}

