#include <pigpio.h>
#include <stdio.h>
#include <time.h>
#include <signal.h>

#define ADC_CHANNEL 0
#define THRESHOLD 500
#define LED_PIN 16
#define SPI_CHANNEL 0
#define SPI_CLOCK 1000000
#define DEBOUNCE_DELAY 10000

void sigint_handler(int sig) {
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    int spiHandle = spiOpen(SPI_CHANNEL, SPI_CLOCK, 0);
    if (spiHandle < 0) {
        fprintf(stderr, "Failed to open SPI channel: %d\n", spiHandle);
        return 1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        return 1;
    }

    while (1) {
        char buffer[3] = {1, (char)(8 + ADC_CHANNEL << 4), 0};
        char result[3] = {0, 0, 0};

        int spiResult = spiXfer(spiHandle, buffer, result, 3);
        if (spiResult < 0) {
            fprintf(stderr, "Failed to transfer SPI data: %d\n", spiResult);
            return 1;
        }

        int adcValue = (result[1] & 0x03) << 8 | result[2];
        if (adcValue > THRESHOLD) {
            gpioWrite(LED_PIN, 1);

            time_t now = time(NULL);
            struct tm *timeinfo = localtime(&now);
            char timestamp[20];
            strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);

            FILE *logFile = fopen("sound_events.log", "a");
            if (logFile == NULL) {
                fprintf(stderr, "Failed to open log file\n");
                return 1;
            }

            fprintf(logFile, "%s\n", timestamp);
            fclose(logFile);

            gpioDelay(500000);
            gpioWrite(LED_PIN, 0);
        }

        gpioDelay(DEBOUNCE_DELAY);
    }

    return 0;
}

