#define GPIO_PATH "/sys/class/gpio/gpio17/"
#define GPIO_EXPORT_PATH "/sys/class/gpio/export"
#define GPIO_UNEXPORT_PATH "/sys/class/gpio/unexport"
#define GPIO_VALUE "value"
#define MAX_RETRY 10

int gpio_fd;

void cleanup(int signum) {
    int i;
    for (i = 0; i < MAX_RETRY; i++) {
        gpio_fd = open(GPIO_PATH GPIO_VALUE, O_WRONLY);
        if (gpio_fd < 0) {
            perror("Failed to open GPIO value for writing");
            sleep(1);
        } else {
            write(gpio_fd, "0", 1);
            close(gpio_fd);
            break;
        }
    }
    if (i == MAX_RETRY) {
        perror("Failed to unexport GPIO after max retries");
    }
    unlink(GPIO_EXPORT_PATH);
    exit(0);
}

int main() {
    int i;
    char buffer[100];
    double voltage, distance;
    FILE *log_file;
    time_t now;
    struct tm *timeinfo;

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    unlink(GPIO_EXPORT_PATH);
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    for (i = 0; i < MAX_RETRY; i++) {
        gpio_fd = open(GPIO_PATH GPIO_VALUE, O_RDONLY);
        if (gpio_fd < 0) {
            perror("Failed to open GPIO value for reading");
            sleep(1);
        } else {
            break;
        }
    }
    if (i == MAX_RETRY) {
        perror("Failed to export GPIO after max retries");
        return 1;
    }

    while (1) {
        lseek(gpio_fd, 0, SEEK_SET);
        read(gpio_fd, buffer, 1);
        close(gpio_fd);

        voltage = atof(buffer) * 3.3;
        distance = 26.0 / voltage - 6.0;

        now = time(NULL);
        timeinfo = localtime(&now);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
        fprintf(log_file, "%s, %.2f mm\n", buffer, distance);
        fflush(log_file);

        if (distance < 200.0) {
            printf("Feeder Activated\n");
        } else {
            printf("Feeder Idle\n");
        }

        sleep(1);
    }

    fclose(log_file);
    return 0;
}

