#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define GPIO_PUMP 17
#define GPIO_CHIP "gpiochip0"
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0

struct gpiod_chip *chip;
struct gpiod_line *pump;
int fd;

void cleanup(int signum) {
    gpiod_line_set_value(pump, 0);
    close(fd);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    signal(SIGINT, cleanup);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    pump = gpiod_chip_get_line(chip, GPIO_PUMP);
    if (!pump) {
        perror("Failed to get GPIO line");
        return 1;
    }

    int ret = gpiod_line_request_output(pump, "soil_moisture_pump", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line as output");
        return 1;
    }

    fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    uint8_t mode = ADC_CHANNEL;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Failed to set SPI mode");
        return 1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Failed to set SPI speed");
        return 1;
    }

    FILE *log = fopen("soil_moisture.log", "w");
    if (!log) {
        perror("Failed to open log file");
        return 1;
    }

    while (1) {
        uint8_t tx[3] = {1, (8 + ADC_CHANNEL) << 4, 0};
        uint8_t rx[3];

        struct spi_ioc_transfer tr = {
            .tx_buf = (unsigned long)tx,
            .rx_buf = (unsigned long)rx,
            .len = 3,
            .delay_usecs = 0,
            .speed_hz = SPI_SPEED,
            .bits_per_word = 8,
        };

        if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
            perror("Failed to read from SPI device");
            return 1;
        }

        int adc_value = (rx[1] & 0x03) << 8 | rx[2];
        double moisture_percentage = (adc_value - 800) / (300.0 - 800) * 100;
        int pump_status = moisture_percentage < 30;

        gpiod_line_set_value(pump, pump_status);

        time_t now = time(NULL);
        fprintf(log, "%s, %.2f%%, %s\n", ctime(&now), moisture_percentage, pump_status ? "ON" : "OFF");
        fflush(log);

        sleep(60);
    }

    return 0;
}

