        perror("Failed to get GPIO line");
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    uint8_t mode = 0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        return 1;
    }

    FILE *log_file = fopen("magnetic_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    while (1) {
        gpiod_line_set_value(line, 0);

        uint8_t tx_data[3] = {1, (ADC_CHANNEL << 4) | 0x07, 0};
        uint8_t rx_data[3] = {0, 0, 0};

        struct spi_ioc_transfer tr = {
            .tx_buf = (unsigned long)tx_data,
            .rx_buf = (unsigned long)rx_data,
            .len = 3,
            .delay_usecs = 0,
            .speed_hz = 1000000,
            .bits_per_word = 8,
        };

        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
            perror("Failed to transfer SPI data");
            return 1;
        }

        gpiod_line_set_value(line, 1);

        uint16_t adc_value = (rx_data[1] << 8) | rx_data[2];
        double vout_mv = adc_value * 3300.0 / 1023.0;
        double B_mt = (vout_mv - 1650.0) / 100.0;

        time_t now = time(NULL);
        fprintf(log_file, "%ld,%.2f\n", now, B_mt);
        fflush(log_file);

        sleep(SAMPLE_RATE / 1000);
    }

    return 0;
}
