#define SENSOR_VOLTAGE_OFFSET ADC_VOLTAGE_REF / 2
#define SENSOR_SENSITIVITY_mV_PER_mT (SENSOR_VOLTAGE_REF * ADC_VOLTAGE_REF) / (5 * ADC_RESOLUTION)
#define THRESHOLD_mT 10.0
#define GPIO_LED 21

void sigint_handler(int sig) {
    gpioTerminate();
    fprintf(stderr, "Exiting...\n");
    exit(0);
}

