        double field_mT = (adcVoltage - SENSOR_VOLTAGE_OFFSET) * 1000 / SENSOR_SENSITIVITY_mV_PER_mT;

        time_t now = time(NULL);
        fprintf(logFile, "%ld, %f\n", now, field_mT);
