#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0

#define START_BIT 0x01
#define SINGLE_ENDED_BIT 0x80

void sigint_handler(int sig) {
    gpioSPI(SPI_CHANNEL, 0, 0);
    gpioTerminate();
    exit(0);
}

int main() {
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        perror("Unable to catch SIGINT");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Unable to initialize pigpio library\n");
        return 1;
    }

    int spiHandle = gpioSPI(SPI_CHANNEL, SPI_SPEED, 1);
    if (spiHandle < 0) {
        fprintf(stderr, "Unable to open SPI channel: %s\n", gpioErrorText(spiHandle));
        return 1;
    }

    while (1) {
        char tx_buf[3] = {START_BIT, SINGLE_ENDED_BIT | ADC_CHANNEL, 0};
        char rx_buf[3] = {0, 0, 0};

        int result = gpioSPIXfer(spiHandle, tx_buf, rx_buf, 3);
        if (result < 0) {
            fprintf(stderr, "SPI transfer failed: %s\n", gpioErrorText(result));
            continue;
        }

        int adc_value = (rx_buf[1] & 0x03) << 8 | rx_buf[2];

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        FILE *file = fopen("moisture_log.txt", "a");
        if (file == NULL) {
            perror("Unable to open log file");
            continue;
        }

        if (adc_value < 0) {
            fprintf(file, "%s: ADC read failed\n", timestamp);
        } else {
            fprintf(file, "%s: %d\n", timestamp, adc_value);
        }

        fclose(file);

        sleep(60);
    }

    return 0;
}

