#include <pigpio.h>
#include <unistd.h>
#include <stdio.h>
#include <time.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0

#define MLX91211_CHANNEL 0

#define VREF 5.0

volatile sig_atomic_t stop;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    int spi = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi < 0) {
        fprintf(stderr, "Failed to open SPI\n");
        gpioTerminate();
        return 1;
    }

    FILE *file = fopen("current_log.txt", "w");
    if (file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi);
        gpioTerminate();
        return 1;
    }

    while (!stop) {
        char tx[3] = {0x01, 0x80 | (MLX91211_CHANNEL << 4), 0x00};
        char rx[3];

        if (spiXfer(spi, tx, rx, 3) < 0) {
            fprintf(stderr, "SPI transfer error\n");
            sleep(1);
            continue;
        }

        int raw = ((rx[1] & 0x03) << 8) | rx[2];
        double voltage = raw * (VREF / 1023.0);
        double current = (voltage - 2.5) * (50.0 / 2.5);

        if (voltage < 0 || voltage > 5) {
            fprintf(stderr, "Warning: voltage out of range\n");
            sleep(1);
            continue;
        }

        time_t t = time(NULL);
        struct tm *tm = localtime(&t);
        fprintf(file, "%04d-%02d-%02d %02d:%02d:%02d %.2f A\n",
                tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
                tm->tm_hour, tm->tm_min, tm->tm_sec, current);
        fflush(file);

        gpioDelay(100000);
    }

    fclose(file);
    spiClose(spi);
    gpioTerminate();

    return 0;
}

