#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define SAMPLE_COUNT 5
#define SAMPLE_DELAY 2000 // in microseconds

struct gpiod_chip *chip;
struct gpiod_line *sensor1, *sensor2;

void cleanup(int signum) {
    gpiod_line_release(sensor1);
    gpiod_line_release(sensor2);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    signal(SIGINT, cleanup);

    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    sensor1 = gpiod_chip_get_line(chip, SENSOR1_GPIO);
    sensor2 = gpiod_chip_get_line(chip, SENSOR2_GPIO);

    if (!sensor1 || !sensor2) {
        perror("Failed to get lines");
        return 1;
    }

    if (gpiod_line_request_input(sensor1, "sensor1") || gpiod_line_request_input(sensor2, "sensor2")) {
        perror("Failed to request lines as input");
        return 1;
    }

    while (1) {
        int s1_state = 0, s2_state = 0;

        for (int i = 0; i < SAMPLE_COUNT; i++) {
            usleep(SAMPLE_DELAY);
            s1_state += gpiod_line_get_value(sensor1);
            s2_state += gpiod_line_get_value(sensor2);
        }

        printf("Sensor 1: %s\n", s1_state < SAMPLE_COUNT / 2 ? "No object" : "Object present");
        printf("Sensor 2: %s\n", s2_state < SAMPLE_COUNT / 2 ? "No object" : "Object present");

        if (s1_state < SAMPLE_COUNT / 2 && s2_state < SAMPLE_COUNT / 2) {
            printf("ALERT: Both sensors detect object\n");
        }

        sleep(1);
    }

    return 0;
}

