#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define READ_DELAY 60
#define MIN_ADC 300
#define MAX_ADC 800
#define LOG_FILE "soil_moisture_log.csv"

volatile sig_atomic_t termination_flag = 0;

int read_mcp3008(int channel) {
    unsigned char tx_buf[3] = {0x01, 0x80 | (channel << 4), 0x00};
    unsigned char rx_buf[3] = {0x00, 0x00, 0x00};

    if (gpio_spi_xfer(SPI_CHANNEL, tx_buf, rx_buf, sizeof(tx_buf)) < 0) {
        printf("SPI transfer failed\n");
        sleep(1); // retry after a delay
        return -1;
    }

    return ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
}

double calculate_moisture_level(int adc_value) {
    return 100.0 - ((adc_value - MIN_ADC) / (double)(MAX_ADC - MIN_ADC)) * 100.0;
}

