#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_DELAY 200
#define POLL_DELAY 50
#define IMAGE_PATH "/home/pi/security_cam/%Y-%m-%dT%H:%M:%S.jpg"

volatile sig_atomic_t stop;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    openlog("security_cam", LOG_PID, LOG_USER);
    syslog(LOG_INFO, "Starting up");

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int last_state = gpioRead(GPIO_PIN);
    time_t last_change = time(NULL);

    while (!stop) {
        int current_state = gpioRead(GPIO_PIN);

        if (current_state != last_state) {
            last_change = time(NULL);
            last_state = current_state;
        } else if (current_state && (time(NULL) - last_change >= DEBOUNCE_DELAY)) {
            time_t now = time(NULL);
            struct tm *timeinfo = localtime(&now);
            char filename[256];
            strftime(filename, sizeof(filename), IMAGE_PATH, timeinfo);

            if (access(filename, F_OK) != -1) {
                syslog(LOG_ERR, "File %s already exists", filename);
                continue;
            }

            pid_t pid = fork();

            if (pid == 0) {
                execl("/usr/bin/libcamera-still", "libcamera-still", "-o", filename, "-r", "1280x720", "-n", "-q", NULL);
                syslog(LOG_ERR, "Failed to execute libcamera-still: %s", strerror(errno));
                exit(1);
            } else if (pid < 0) {
                syslog(LOG_ERR, "Failed to fork: %s", strerror(errno));
                continue;
            }

            int status;
            waitpid(pid, &status, 0);

            if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
                syslog(LOG_INFO, "Capture successful: %s", filename);
            } else {
                syslog(LOG_ERR, "Capture failed: %s", filename);
            }
        }

        gpioDelay(10000000); // Delay for 10ms
    }

    gpioTerminate();
    closelog();

    syslog(LOG_INFO, "Shutting down");

    return 0;
}

