#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <signal.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_FORMAT V4L2_PIX_FMT_GREY
#define NUM_BUFFERS 1

int fd;
struct v4l2_buffer buf;
void *mem_start;

void cleanup(int signum) {
    printf("Cleaning up...\n");
    v4l2_ioctl(fd, VIDIOC_STREAMOFF, NULL);
    v4l2_ioctl(fd, VIDIOC_RELEASEBUF, &buf);
    munmap(mem_start, buf.length);
    close(fd);
    exit(0);
}

int main(int argc, char *argv[]) {
    const char *device_name = argc > 1 ? argv[1] : DEVICE_NAME;
    fd = v4l2_open(device_name, O_RDWR | O_NONBLOCK);
    if (fd < 0) {
        perror("Failed to open device");
        return 1;
    }

    struct v4l2_capability cap;
    v4l2_ioctl(fd, VIDIOC_QUERYCAP, &cap);
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        return 1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = IMAGE_FORMAT;
    v4l2_ioctl(fd, VIDIOC_S_FMT, &fmt);

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    v4l2_ioctl(fd, VIDIOC_REQBUFS, &req);

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    v4l2_ioctl(fd, VIDIOC_QUERYBUF, &buf);
    mem_start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

    v4l2_ioctl(fd, VIDIOC_STREAMON, &buf.type);

    int frame_count = 0;
    while (1) {
        fd_set fds;
        FD_ZERO(&fds);
        FD_SET(fd, &fds);
        int ret = select(fd + 1, &fds, NULL, NULL, NULL);
        if (ret < 0) {
            perror("Select error");
            break;
        }
        if (ret == 0) {
            printf("Timeout\n");
            continue;
        }
        v4l2_ioctl(fd, VIDIOC_DQBUF, &buf);
        char filename[32];
        sprintf(filename, "image_%04d.pgm", frame_count++);
        FILE *file = fopen(filename, "wb");
        fwrite(mem_start, 1, buf.bytesused, file);
        fclose(file);
        v4l2_ioctl(fd, VIDIOC_QBUF, &buf);
    }

    cleanup(0);
    return 0;
}

