#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_PAN 4
#define GPIO_TILT 5
#define GPIO_TILT_UP 6
#define GPIO_TILT_DOWN 7
#define GPIO_PAN_LEFT 8
#define GPIO_PAN_RIGHT 9

#define PWM_PERIOD 20000 // 20 ms
#define PWM_MIN 500 // 1 ms
#define PWM_MAX 1000 // 2 ms
#define PWM_RANGE (PWM_MAX - PWM_MIN)

struct gpiod_chip *chip;
struct gpiod_line *pan, *tilt, *tilt_up, *tilt_down, *pan_left, *pan_right;
int pan_pos = 75, tilt_pos = 75;

void cleanup(int signum) {
    gpiod_line_release(pan);
    gpiod_line_release(tilt);
    gpiod_line_release(tilt_up);
    gpiod_line_release(tilt_down);
    gpiod_line_release(pan_left);
    gpiod_line_release(pan_right);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    signal(SIGINT, cleanup);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Open chip failed");
        return 1;
    }

    pan = gpiod_chip_get_line(chip, GPIO_PAN);
    tilt = gpiod_chip_get_line(chip, GPIO_TILT);
    tilt_up = gpiod_chip_get_line(chip, GPIO_TILT_UP);
    tilt_down = gpiod_chip_get_line(chip, GPIO_TILT_DOWN);
    pan_left = gpiod_chip_get_line(chip, GPIO_PAN_LEFT);
    pan_right = gpiod_chip_get_line(chip, GPIO_PAN_RIGHT);

    if (!pan || !tilt || !tilt_up || !tilt_down || !pan_left || !pan_right) {
        perror("Request line failed");
        return 1;
    }

    while (1) {
        int tilt_up_val = gpiod_line_get_value(tilt_up);
        int tilt_down_val = gpiod_line_get_value(tilt_down);
        int pan_left_val = gpiod_line_get_value(pan_left);
        int pan_right_val = gpiod_line_get_value(pan_right);

        if (tilt_up_val == 0 && tilt_pos < 125) tilt_pos += 5;
        if (tilt_down_val == 0 && tilt_pos > 25) tilt_pos -= 5;
        if (pan_left_val == 0 && pan_pos > 25) pan_pos -= 5;
        if (pan_right_val == 0 && pan_pos < 125) pan_pos += 5;

        gpiod_line_set_value(tilt, tilt_pos * PWM_RANGE / 100 + PWM_MIN);
        gpiod_line_set_value(pan, pan_pos * PWM_RANGE / 100 + PWM_MIN);

        usleep(50000); // 50 ms
    }

    return 0;
}

