#include <pigpio.h>
#include <signal.h>

#define PAN_SERVO 4
#define TILT_SERVO 5
#define UP_BUTTON 6
#define DOWN_BUTTON 7
#define LEFT_BUTTON 8
#define RIGHT_BUTTON 9

#define SERVO_MIN 1000
#define SERVO_MAX 2000
#define SERVO_CENTER 1500

volatile int running = 1;

void sigint_handler(int sig) {
    running = 0;
}

void update_servo(int servo, int button, int direction) {
    static int position = SERVO_CENTER;
    if (gpioRead(button) == 0) {
        position += direction * 10;
        if (position < SERVO_MIN) position = SERVO_MIN;
        if (position > SERVO_MAX) position = SERVO_MAX;
        gpioServo(servo, position);
    } else {
        gpioServo(servo, SERVO_CENTER);
        position = SERVO_CENTER;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        printf("Failed to initialize pigpio library\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    gpioSetMode(PAN_SERVO, PI_OUTPUT);
    gpioSetMode(TILT_SERVO, PI_OUTPUT);
    gpioSetMode(UP_BUTTON, PI_INPUT);
    gpioSetMode(DOWN_BUTTON, PI_INPUT);
    gpioSetMode(LEFT_BUTTON, PI_INPUT);
    gpioSetMode(RIGHT_BUTTON, PI_INPUT);

    gpioSetPullUpDown(UP_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(DOWN_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(LEFT_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(RIGHT_BUTTON, PI_PUD_UP);

    printf("Pan servo on GPIO %d, tilt servo on GPIO %d\n", PAN_SERVO, TILT_SERVO);
    printf("UP button on GPIO %d, DOWN button on GPIO %d\n", UP_BUTTON, DOWN_BUTTON);
    printf("LEFT button on GPIO %d, RIGHT button on GPIO %d\n", LEFT_BUTTON, RIGHT_BUTTON);
    printf("Center position: %d microseconds\n", SERVO_CENTER);

    while (running) {
        update_servo(PAN_SERVO, LEFT_BUTTON, -1);
        update_servo(PAN_SERVO, RIGHT_BUTTON, 1);
        update_servo(TILT_SERVO, UP_BUTTON, -1);
        update_servo(TILT_SERVO, DOWN_BUTTON, 1);
        gpioDelay(250000);  // 50 ms delay
    }

    gpioServo(PAN_SERVO, 0);
    gpioServo(TILT_SERVO, 0);
    gpioTerminate();
    return 0;
}

