#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_LINE 17
#define GPIO_CHIP "gpiochip0"
#define IMAGE_PATH "/home/pi/images/"
#define LOG_FILE "/home/pi/motion_capture.log"

struct gpiod_chip *chip;
struct gpiod_line *line;
FILE *log_file;

void signal_handler(int signum) {
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(log_file);
    exit(0);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        return 1;
    }

    int request_flags = GPIOD_LINE_REQUEST_FLAG_BIAS_DISABLE | GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW | GPIOD_LINE_REQUEST_FLAG_EVENT_FALLING_EDGE;
    int ret = gpiod_line_request_both_edges_debounced(line, "motion_sensor", request_flags);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    while (1) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", localtime(&ts.tv_sec));

        char filename[50];
        sprintf(filename, "%simages/%s_mmm.jpg", IMAGE_PATH, timestamp);

        char command[100];
        sprintf(command, "libcamera-still -o %s --width 640 --height 480 -q 85 --timeout 2000 --nopreview", filename);

        int ret = system(command);
        if (ret != 0) {
            time_t now = time(NULL);
            fprintf(log_file, "%ld: Failed to capture image: %s\n", now, strerror(errno));
        } else {
            time_t now = time(NULL);
            fprintf(log_file, "%ld: Captured image: %s\n", now, filename);
        }

        sleep(1);
    }

    return 0;
}

