#define MAX_PULSE_WIDTH 2500
#define INCREMENT 5
#define MIN_ANGLE 0
#define MAX_ANGLE 180

void handle_sigint(int sig);
void set_angle(int gpio, int angle);

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    signal(SIGINT, handle_sigint);

    set_angle(PAN_GPIO, 90);
    set_angle(TILT_GPIO, 90);

    char input;
    while (1) {
        scanf("%c", &input);
        switch (input) {
            case 'w':
                set_angle(PAN_GPIO, gpioGetServoPulsewidth(PAN_GPIO) - INCREMENT);
                break;
            case 's':
                set_angle(PAN_GPIO, gpioGetServoPulsewidth(PAN_GPIO) + INCREMENT);
                break;
            case 'a':
                set_angle(TILT_GPIO, gpioGetServoPulsewidth(TILT_GPIO) - INCREMENT);
                break;
            case 'd':
                set_angle(TILT_GPIO, gpioGetServoPulsewidth(TILT_GPIO) + INCREMENT);
                break;
            case 'q':
                set_angle(PAN_GPIO, 90);
                set_angle(TILT_GPIO, 90);
                break;
            default:
