#include <pigpio.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <signal.h>
#include <stdio.h>

#define GPIO_PIN 17
#define I2C_BUS 1
#define I2C_ADDR 0x27
#define PULSES_PER_LITER 450.0

volatile sig_atomic_t stop;

void handle_signal(int signum) {
    stop = 1;
}

int main() {
    // Initialize GPIO and I2C
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }
    int i2c = wiringPiI2CSetup(I2C_ADDR);
    if (i2c < 0) {
        fprintf(stderr, "Failed to initialize I2C\n");
        return 1;
    }

    // Set up GPIO pin as input with pull-up
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    double pulses = 0.0;
    double volume = 0.0;
    double rate = 0.0;

    stop = 0;
    while (!stop) {
        // Wait for a pulse
        while (gpioRead(GPIO_PIN) && !stop) {
            gpioDelay(1);
        }
        if (stop) break;

        // Count the pulse
        pulses++;

        // Calculate flow rate in liters per minute
        rate = pulses / PULSES_PER_LITER;

        // Update volume
        volume += rate / 60.0;

        // Log the current flow rate and total volume
        printf("Flow rate: %.2f L/min, Total volume: %.2f L\n", rate, volume);

        // Update LCD screen
        int result = wiringPiI2CWrite(i2c, (int)(volume * 100));
        if (result < 0) {
            fprintf(stderr, "Failed to write to I2C\n");
            return 1;
        }

        // Wait for 1 second
        delay(1000);
    }

    // Release resources
    gpioTerminate();
    return 0;
}

