#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define ROWS 8
#define COLS 8

#define ROW_PINS {17, 18, 27, 22, 23, 24, 25, 4}
#define COL_PINS {5, 6, 12, 13, 19, 16, 26, 20}

#define SCAN_DELAY 800

int row_pins[ROWS] = ROW_PINS;
int col_pins[COLS] = COL_PINS;

struct gpiod_chip *chip;
struct gpiod_line *row_lines[ROWS];
struct gpiod_line *col_lines[COLS];

void cleanup(int signum) {
    for (int i = 0; i < ROWS; i++) {
        gpiod_line_release(row_lines[i]);
    }
    for (int i = 0; i < COLS; i++) {
        gpiod_line_release(col_lines[i]);
    }
    gpiod_chip_close(chip);
    exit(0);
}

int main(int argc, char *argv[]) {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    for (int i = 0; i < ROWS; i++) {
        row_lines[i] = gpiod_chip_get_line(chip, row_pins[i]);
        if (!row_lines[i]) {
            fprintf(stderr, "Failed to get line %d\n", row_pins[i]);
            return 1;
        }
        gpiod_line_request_output(row_lines[i], "wave", 0);
    }

    for (int i = 0; i < COLS; i++) {
        col_lines[i] = gpiod_chip_get_line(chip, col_pins[i]);
        if (!col_lines[i]) {
            fprintf(stderr, "Failed to get line %d\n", col_pins[i]);
            return 1;
        }
        gpiod_line_request_output(col_lines[i], "wave", 0);
    }

    signal(SIGINT, cleanup);

    while (1) {
        for (int i = 0; i < ROWS; i++) {
            gpiod_line_set_value(row_lines[i], 1);
            usleep(SCAN_DELAY);
            gpiod_line_set_value(row_lines[i], 0);
        }
        for (int i = COLS - 1; i >= 0; i--) {
            gpiod_line_set_value(col_lines[i], 1);
            usleep(SCAN_DELAY);
            gpiod_line_set_value(col_lines[i], 0);
        }
    }

    return 0;
}

