#define REG_ADDR 0x0D

void sigint_handler(int sig) {
    printf("Exiting...\n");
    gpioTerminate();
    exit(0);
}

int main() {
    FILE *file;
    int handle;
    uint16_t distance;
    char timestamp[20];

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    if ((handle = i2cOpen(I2C_BUS, I2C_ADDR, 0)) < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        return 1;
    }

    if ((file = fopen("depth_log.csv", "a")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    while (1) {
        if (i2cWriteByte(handle, REG_ADDR) < 0) {
            fprintf(stderr, "Failed to write to I2C handle\n");
            return 1;
        }

        if (i2cReadWord(handle, &distance) < 0) {
            fprintf(stderr, "Failed to read from I2C handle\n");
            return 1;
        }

        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d,%H:%M:%S", &tm);

        fprintf(file, "%s,%d\n", timestamp, distance);
        fflush(file);

        gpioDelay(100000);  // Delay for 100ms
    }

    fclose(file);
    i2cClose(handle);
    gpioTerminate();

