        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    log_file = fopen("biometric_data.log", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    gpioSetI2COptions(I2C_HANDLE, 100000, 1);

    char part_id = gpioI2CReadByteData(I2C_HANDLE, I2C_ADDR, PART_ID_REG);
