#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_GPIO 17
#define ECHO_GPIO 27
#define TIMEOUT_MS 30
#define POLL_INTERVAL_SEC 60

struct gpiod_chip *chip;
struct gpiod_line *trigger_line, *echo_line;
struct timespec last_poll_time;
FILE *log_file;

void cleanup(int signum) {
    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);
    fclose(log_file);
    exit(0);
}

int main() {
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip == NULL) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_GPIO);
    echo_line = gpiod_chip_get_line(chip, ECHO_GPIO);

    if (gpiod_line_request_output(trigger_line, "hcsr04", 0) < 0) {
        perror("Failed to request trigger line");
        return 1;
    }

    if (gpiod_line_request_input(echo_line, "hcsr04") < 0) {
        perror("Failed to request echo line");
        return 1;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    clock_gettime(CLOCK_MONOTONIC, &last_poll_time);

    while (1) {
        struct timespec now, diff;
        long long elapsed_ns;
        int ret;

        gpiod_line_set_value(trigger_line, 1);
        usleep(10);
        gpiod_line_set_value(trigger_line, 0);

        ret = gpiod_line_event_wait(echo_line, TIMEOUT_MS * 1000);
        if (ret < 0) {
            perror("Failed to wait for echo event");
            continue;
        }

        clock_gettime(CLOCK_MONOTONIC, &now);
        timespec_sub(&now, &last_poll_time, &diff);
        elapsed_ns = diff.tv_sec * 1000000000LL + diff.tv_nsec;

        if (elapsed_ns < POLL_INTERVAL_SEC * 1000000000LL) {
            continue;
        }

        clock_gettime(CLOCK_MONOTONIC, &last_poll_time);

        ret = gpiod_line_event_read(echo_line, NULL, NULL, TIMEOUT_MS * 1000);
        if (ret < 0) {
            perror("Failed to read echo event");
            continue;
        }

        clock_gettime(CLOCK_MONOTONIC, &now);
        timespec_sub(&now, &last_poll_time, &diff);
        elapsed_ns = diff.tv_sec * 1000000000LL + diff.tv_nsec;

        double distance = (elapsed_ns / 1000000.0) * 34300.0 / 2.0;

        if (distance < 2.0 || distance > 400.0) {
            fprintf(log_file, "[%s] Invalid distance: %.2f cm\n",
                    current_time_iso8601(), distance);
            fflush(log_file);
            continue;
        }

        fprintf(log_file, "[%s] Distance: %.2f cm\n",
                current_time_iso8601(), distance);
        fflush(log_file);

        if (distance < 15.0) {
            fprintf(log_file, "[%s] Time to water the plant!\n",
                    current_time_iso8601());
            fflush(log_file);
        }
    }

    return 0;
}

