#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <signal.h>
#include <time.h>

#define I2C_DEV "/dev/i2c-1"
#define I2C_ADDR 0x5A
#define PART_ID_EXPECTED 0x73
#define COMMAND_REG 0x47
#define MEAS_RATE0_REG 0x08
#define PS_DATA0_REG 0x24
#define PS_DATA1_REG 0x25

volatile sig_atomic_t running = 1;

void sig_handler(int signum) {
    running = 0;
}

int main() {
    int i2c_fd;
    FILE *csv_file;
    uint8_t part_id;
    struct timespec ts;
    char timestamp[20];

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    if ((i2c_fd = open(I2C_DEV, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire bus access or talk to slave");
        return 1;
    }

    if (read(i2c_fd, &part_id, 1) != 1 || part_id != PART_ID_EXPECTED) {
        fprintf(stderr, "Failed to read part ID or ID mismatch\n");
        return 1;
    }

    if ((csv_file = fopen("heartrate.csv", "w")) == NULL) {
        perror("Failed to open CSV file");
        return 1;
    }

    if (write(i2c_fd, &MEAS_RATE0_REG, 1) != 1 || write(i2c_fd, "\xFF", 1) != 1) {
        perror("Failed to write to MEAS_RATE0 register");
        return 1;
    }

    if (write(i2c_fd, &COMMAND_REG, 1) != 1 || write(i2c_fd, "\x01", 1) != 1) {
        perror("Failed to write to COMMAND register");
        return 1;
    }

    while (running) {
        uint16_t ps_data;
        uint8_t ps_data_buf[2];

        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", gmtime(&ts.tv_sec));

        if (write(i2c_fd, &PS_DATA0_REG, 1) != 1 || read(i2c_fd, ps_data_buf, 2) != 2) {
            fprintf(stderr, "Failed to read PS_DATA registers\n");
            continue;
        }

        ps_data = (ps_data_buf[1] << 8) | ps_data_buf[0];

        fprintf(csv_file, "%s,%d\n", timestamp, ps_data);
        fflush(csv_file);

        usleep(100000);
    }

    fclose(csv_file);
    close(i2c_fd);

    return 0;
}

