#include <pigpio.h>
#include <stdio.h>
#include <time.h>
#include <signal.h>

#define I2C_HANDLE 1
#define I2C_ADDR 0x29
#define GPIO_PIN 17
#define SYSRANGE_START_REG 0x00
#define RESULT_INTERRUPT_STATUS_REG 0x13
#define RESULT_RANGE_STATUS_REG 0x14
#define SYSTEM_INTERRUPT_CLEAR_REG 0x0B

void sigint_handler(int sig) {
    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
    i2cClose(I2C_HANDLE);
    fclose(stdout);
    exit(0);
}

int main() {
    signal(SIGINT, sigint_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (i2cOpen(1, I2C_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        return 1;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set GPIO pull-up\n");
        return 1;
    }

    if (gpioSetAlertFunc(GPIO_PIN, PI_FALLING_EDGE, sigint_handler) < 0) {
        fprintf(stderr, "Failed to set GPIO alert function\n");
        return 1;
    }

    FILE *log_file = fopen("distance_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    while (1) {
        if (i2cWriteByte(I2C_HANDLE, SYSRANGE_START_REG, 0x01) < 0) {
            fprintf(stderr, "Failed to start distance measurement\n");
            return 1;
        }

        int interrupt_status;
        do {
            interrupt_status = i2cReadByteData(I2C_HANDLE, RESULT_INTERRUPT_STATUS_REG);
            if (interrupt_status < 0) {
                fprintf(stderr, "Failed to read interrupt status\n");
                return 1;
            }
        } while ((interrupt_status & 0x01) == 0);

        char result_block[14];
        if (i2cReadI2CBlockData(I2C_HANDLE, RESULT_RANGE_STATUS_REG, result_block, 14) < 0) {
            fprintf(stderr, "Failed to read result block\n");
            return 1;
        }

        int distance = (result_block[10] << 8) | result_block[11];
        time_t timestamp = time(NULL);
        fprintf(log_file, "%ld,%d\n", timestamp, distance);

        if (i2cWriteByte(I2C_HANDLE, SYSTEM_INTERRUPT_CLEAR_REG, 0x01) < 0) {
            fprintf(stderr, "Failed to clear interrupt\n");
            return 1;
        }
    }

    return 0;
}

