int i2c_handle;

void sigint_handler(int sig) {
    fclose(log_file);
    gpio_i2c_close(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    i2c_handle = gpio_i2c_open(1, SENSOR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        return 1;
    }

    log_file = fopen("biometric_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        int retries = 0;
        uint16_t proximity_data, ambient_data;

        while (retries < MAX_RETRIES) {
            int result = gpio_i2c_read_word_data(i2c_handle, PROXIMITY_REG, &proximity_data);
            if (result >= 0) break;
            retries++;
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read proximity data\n");
            return 1;
        }

        retries = 0;
        while (retries < MAX_RETRIES) {
            int result = gpio_i2c_read_word_data(i2c_handle, AMBIENT_REG, &ambient_data);
            if (result >= 0) break;
            retries++;
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read ambient data\n");
            return 1;
        }

        time_t now = time(NULL);
        fprintf(log_file, "%ld, Proximity: %u, Ambient: %u\n", now, proximity_data, ambient_data);
        fflush(log_file);

        gpioSleep(PI_TIME_RELATIVE, 0, 500000);
    }

    return 0;
}

