#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <unistd.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>

#define I2C_DEV "/dev/i2c-1"
#define I2C_ADDR 0x50
#define SAMPLE_COUNT 10
#define RANGE 1000

int fd;

void handle_sigint(int sig) {
    printf("\nClosing I2C file descriptor and exiting...\n");
    close(fd);
    exit(0);
}

int main() {
    signal(SIGINT, handle_sigint);

    if ((fd = open(I2C_DEV, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire bus access or talk to slave");
        return 1;
    }

    while (1) {
        uint16_t distances[SAMPLE_COUNT];
        uint32_t sum = 0;

        for (int i = 0; i < SAMPLE_COUNT; i++) {
            uint8_t command[4] = {0x50, 0x0A, 0x00, 0x01};

            if (write(fd, command, 4) != 4) {
                perror("Failed to write to I2C device");
                return 1;
            }

            usleep(10000);  // Wait for at least 10 ms

            uint8_t response[15];

            if (read(fd, response, 15) != 15 || response[0] != 0x50) {
                perror("Failed to read from I2C device or invalid response");
                return 1;
            }

            uint16_t distance = (response[11] << 8) | response[12];
            distances[i] = distance;
            sum += distance;
        }

        uint32_t average = sum / SAMPLE_COUNT;

        if (average < RANGE) {
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

            FILE *log_file = fopen("intrusion_log.txt", "a");
            if (log_file == NULL) {
                perror("Failed to open log file");
                return 1;
            }

            fprintf(log_file, "%s: Intrusion detected at %d mm\n", timestamp, average);
            fclose(log_file);
        }

        usleep(100000);  // Wait for 100 ms
    }

    return 0;
}

