#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <unistd.h>
#include <stdint.h>
#include <signal.h>

#define I2C_DEV "/dev/i2c-1"
#define I2C_ADDR 0x4C
#define REG_ADDR 0x00
#define COUNT_TO_MM 0.125

int fd;

void sig_handler(int signum) {
    close(fd);
    exit(0);
}

int main() {
    if ((fd = open(I2C_DEV, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire bus access or talk to slave");
        return 1;
    }

    uint8_t reg = REG_ADDR;
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write to the i2c bus");
        return 1;
    }

    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        perror("Failed to read from the i2c bus");
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        uint16_t raw_distance = (buf[0] << 8) | buf[1];
        double distance_mm = raw_distance * COUNT_TO_MM;
        printf("Distance: %.2f mm\n", distance_mm);

        struct timespec ts = {
            .tv_sec = 0,
            .tv_nsec = 500 * 1000 * 1000, // 500 ms
        };
        nanosleep(&ts, NULL);

        if (read(fd, buf, 2) != 2) {
            perror("Failed to read from the i2c bus");
            continue;
        }
    }

    return 0;
}

