#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIG 17
#define ECHO 18
#define MAX_DISTANCE 3800 // Maximum distance in microseconds (3800 = 38ms)

volatile sig_atomic_t stop;

void alarmHandler(int signum) {
    stop = 1;
}

int main(int argc, char *argv[]) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    signal(SIGINT, alarmHandler);
    signal(SIGTERM, alarmHandler);

    gpioSetMode(TRIG, PI_OUTPUT);
    gpioSetMode(ECHO, PI_INPUT);

    while (!stop) {
        gpioWrite(TRIG, 1);
        gpioDelay(10); // 10 microsecond trigger pulse
        gpioWrite(TRIG, 0);

        unsigned int start = gpioTick();
        while (gpioRead(ECHO) == 0 && !stop) {
            if (gpioTick() - start > MAX_DISTANCE) {
                fprintf(stderr, "Echo rising-edge timeout\n");
                break;
            }
        }

        if (stop) break;

        unsigned int echo_start = gpioTick();
        while (gpioRead(ECHO) == 1 && !stop) {
            if (gpioTick() - echo_start > MAX_DISTANCE) {
                fprintf(stderr, "Echo falling-edge timeout\n");
                break;
            }
        }

        if (stop) break;

        unsigned int pulse_us = gpioTick() - echo_start;
        if (pulse_us <= 0 || pulse_us > MAX_DISTANCE) {
            fprintf(stderr, "Invalid pulse duration\n");
            continue;
        }

        double distance_cm = (pulse_us * 0.0343) / 2;
        printf("%lu: %.2f cm\n", gpioTick(), distance_cm);

        gpioDelay(1); // Wait for 1 microsecond
    }

    gpioTerminate();
    return 0;
}

