#include <pigpio.h>
#include <time.h>
#include <stdio.h>
#include <signal.h>
#include <unistd.h>

#define I2C_HANDLE 1
#define I2C_ADDR 0x69
#define DIST_REG_HIGH 0x31
#define DIST_REG_LOW 0x32
#define GPIO_PIN 17

void sig_handler(int signum) {
    gpioTerminate();
    i2cClose(I2C_HANDLE);
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (signal(SIGINT, sig_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to set SIGINT handler\n");
        return 1;
    }

    if (signal(SIGTERM, sig_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to set SIGTERM handler\n");
        return 1;
    }

    int i2c_handle = i2cOpen(1, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        return 1;
    }

    FILE *log_file = fopen("distance_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    while (1) {
        char high_byte, low_byte;
        int dist;

        if (i2cReadI2CBlockData(i2c_handle, DIST_REG_HIGH, &high_byte, 1) < 0) {
            fprintf(stderr, "Failed to read high byte\n");
            return 1;
        }

        if (i2cReadI2CBlockData(i2c_handle, DIST_REG_LOW, &low_byte, 1) < 0) {
            fprintf(stderr, "Failed to read low byte\n");
            return 1;
        }

        dist = (high_byte << 8) | low_byte;

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

        fprintf(log_file, "%s,%d\n", timestamp, dist);
        fflush(log_file);

        if (dist < 1000) {
            gpioWrite(GPIO_PIN, 1);
        } else {
            gpioWrite(GPIO_PIN, 0);
        }

        sleep(0.1);
    }

    return 0;
}

