#include <pigpio.h>

#define I2C_HANDLE 1
#define ADDRESS 0x29
#define MODE_START_REG 0x007
#define SYSRANGE__START_REG 0x000
#define RESULT__INTERRUPT_STATUS_REG 0x013
#define SYSTEM__INTERRUPT_CLEAR_REG 0x014
#define RESULT__RANGE_STATUS_REG 0x078
#define MODEL_ID_REG 0x010F
#define SYSTEM_RESET_REG 0x0000

#define MODEL_ID 0xEA
#define SYSTEM_RESET 0x00
#define SYSTEM_MODE_START 0x01

#define TIMEOUT 100
#define INTERVAL 100

FILE *file;

void sig_handler(int signum) {
    fclose(file);
    gpio_i2c_close(I2C_HANDLE);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    int i2c_handle = gpio_i2c_open(I2C_HANDLE, ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C handle: %d\n", i2c_handle);
        return 1;
    }

    unsigned char model_id[2];
    gpio_i2c_read_device(i2c_handle, MODEL_ID_REG, model_id, 2);
    if (model_id[0] != MODEL_ID) {
        fprintf(stderr, "Invalid model ID: 0x%02X\n", model_id[0]);
        return 1;
    }

    gpio_i2c_write_byte(i2c_handle, SYSTEM_RESET_REG, SYSTEM_RESET);
    gpio_i2c_write_byte(i2c_handle, MODE_START_REG, SYSTEM_MODE_START);

    file = fopen("distance_log.csv", "w");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file\n");
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        unsigned char sysrange_start;
        do {
            gpio_i2c_read_byte(i2c_handle, SYSRANGE__START_REG, &sysrange_start);
            gpioDelay(TIMEOUT);
        } while ((sysrange_start & 0x01) != 0);

        unsigned char result_interrupt_status;
        gpio_i2c_read_byte(i2c_handle, RESULT__INTERRUPT_STATUS_REG, &result_interrupt_status);
        if ((result_interrupt_status & 0x01) != 0) {
            unsigned char result_range_status[2];
            gpio_i2c_read_device(i2c_handle, RESULT__RANGE_STATUS_REG, result_range_status, 2);
            unsigned int distance = (result_range_status[1] << 8) | result_range_status[0];

            time_t now = time(NULL);
            fprintf(file, "%ld,%d\n", now, distance);
            fflush(file);

            gpio_i2c_write_byte(i2c_handle, SYSTEM__INTERRUPT_CLEAR_REG, 0x01);

            if (distance < 300) {
                printf("STOP\n");
            } else if (distance < 600) {
                printf("APPROACH\n");
            } else if (distance < 1200) {
                printf("SLOW\n");
            } else {
                printf("CLEAR\n");
            }
        }

        gpioDelay(INTERVAL * 1000);
    }

    return 0;
}

