#include <pigpio.h>
#include <stdio.h>
#include <unistd.h>
#include <signal.h>

#define I2C_BUS 1
#define I2C_ADDR 0x45
#define LED_PIN 18
#define MIN_DIST 50
#define MAX_DIST 500
#define MIN_FREQ 10
#define MAX_FREQ 1

int i2cHandle;

void sigint_handler(int sig) {
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    i2cClose(i2cHandle);
    exit(0);
}

double readDistance() {
    char buf[2];
    int retry = 3;
    while (retry--) {
        if (i2cReadI2CBlockData(i2cHandle, I2C_ADDR, 0, buf, 2) >= 0) {
            return (buf[0] << 8) | buf[1];
        }
        sleep(0.01);
    }
    return -1;
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    i2cHandle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);

    while (1) {
        double dist = readDistance();
        if (dist < 0) {
            fprintf(stderr, "Failed to read distance\n");
            return 1;
        }

        double freq = (dist - MIN_DIST) / (MAX_DIST - MIN_DIST) * (MAX_FREQ - MIN_FREQ) + MIN_FREQ;
