FILE *logFile;

void signalHandler(int signum) {
    fclose(logFile);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    if ((logFile = fopen("proximity_log.txt", "w")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(SENSOR1, PI_INPUT);
    gpioSetMode(SENSOR2, PI_INPUT);

    int sensor1State = HIGH;
    int sensor2State = HIGH;
    int sensor1PrevState = HIGH;
    int sensor2PrevState = HIGH;
    time_t timestamp;

    while (1) {
        time_t startTime = time(NULL);

        sensor1PrevState = sensor1State;
        sensor1State = gpioRead(SENSOR1);
        sensor2PrevState = sensor2State;
        sensor2State = gpioRead(SENSOR2);

        if (sensor1State != sensor1PrevState) {
            timestamp = time(NULL);
            fprintf(logFile, "%s, Sensor 1, %s\n", ctime(&timestamp), sensor1State == LOW ? "DETECTED" : "CLEARED");
            fflush(logFile);
        }

        if (sensor2State != sensor2PrevState) {
            timestamp = time(NULL);
            fprintf(logFile, "%s, Sensor 2, %s\n", ctime(&timestamp), sensor2State == LOW ? "DETECTED" : "CLEARED");
            fflush(logFile);
        }

        time_t endTime = time(NULL);
        if (endTime - startTime < DEBOUNCE_TIME / 10) {
            usleep((DEBOUNCE_TIME / 10 - (endTime - startTime)) * 1000);
        }
    }

    return 0;
}

