#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define I2C_DEV "/dev/i2c-1"
#define I2C_ADDR 0x49
#define MEAS_TRIGGER 0x04
#define MEAS_STATUS 0x06
#define DIST_HIGH 0x08
#define DIST_LOW 0x09

int fd;

void cleanup(int signum) {
    close(fd);
    exit(0);
}

int i2c_read(int reg) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Failed to write to I2C: %s\n", strerror(errno));
        return -1;
    }

    char data[2];
    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "Failed to read from I2C: %s\n", strerror(errno));
        return -1;
    }

    return (data[0] << 8) | data[1];
}

void i2c_write(int reg, int val) {
    char data[2] = {reg, val};
    if (write(fd, data, 2) != 2) {
        fprintf(stderr, "Failed to write to I2C: %s\n", strerror(errno));
    }
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    if ((fd = open(I2C_DEV, O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire bus access or talk to slave: %s\n", strerror(errno));
        return 1;
    }

    FILE *log_file = fopen("distance_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    while (1) {
        i2c_write(MEAS_TRIGGER, 0x01);

        int status;
        do {
            usleep(50000);  // 50 ms
            status = i2c_read(MEAS_STATUS);
        } while ((status & 0x01) == 0);

        int distance = i2c_read(DIST_HIGH);
        if (distance >= 0) {
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char timestamp[20];
            strftime(timestamp, 20, "%Y-%m-%dT%H:%M:%S", tm_info);
            fprintf(log_file, "%s,%d\n", timestamp, distance);
            fflush(log_file);
        }

        usleep(500000);  // 500 ms
    }

    fclose(log_file);
    return 0;
}

