    }

    while (!stop) {
        int retry_count = 0;
        int result;
        do {
            result = i2cReadByteData(i2c, 0x00);
            if (result >= 0) {
                break;
            }
            else {
                usleep(RETRY_DELAY);
            }
        } while (++retry_count < RETRY_COUNT);

        if (result < 0) {
            fprintf(stderr, "Failed to read from sensor\n");
            break;
        }

