#define RESET_REG 0x7FFF
#define RANGING_REG 0x0009
#define INTERRUPT_REG 0x0046
#define DISTANCE_HIGH_REG 0x0096
#define DISTANCE_LOW_REG 0x0097

void sig_handler(int signum) {
    gpio_i2c_close(I2C_BUS);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    int i2c_handle = gpio_i2c_open(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    char reset_val = 0;
    if (gpio_i2c_write_byte_data(i2c_handle, RESET_REG, reset_val) < 0) {
        fprintf(stderr, "Failed to write to reset register\n");
        return 1;
    }

    gpioSleep(GPIO_SLEEP_WUF);

    if (gpio_i2c_write_byte_data(i2c_handle, RANGING_REG, reset_val) < 0) {
        fprintf(stderr, "Failed to start ranging\n");
        return 1;
    }

    while (1) {
        gpioSleep(GPIO_SLEEP_MICROSECONDS, 500000);

        char interrupt_status;
        if (gpio_i2c_read_byte_data(i2c_handle, INTERRUPT_REG, &interrupt_status) < 0) {
            fprintf(stderr, "Failed to read interrupt status\n");
            continue;
        }

        if (interrupt_status & 0x01) {
            char distance_high, distance_low;
            if (gpio_i2c_read_byte_data(i2c_handle, DISTANCE_HIGH_REG, &distance_high) < 0 ||
                gpio_i2c_read_byte_data(i2c_handle, DISTANCE_LOW_REG, &distance_low) < 0) {
                fprintf(stderr, "Failed to read distance\n");
                continue;
            }

            time_t now = time(NULL);
            struct tm *timeinfo = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            printf("%s.%06ld, Distance: %d mm\n", timestamp, now % 1000000, (distance_high << 8) | distance_low);
        }
    }

    return 0;
}

