#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <stdio.h>

#define TRIG 23
#define ECHO 24
#define SERVO 17
#define SPEED_OF_SOUND 34300 // in cm/ms
#define MAX_DISTANCE 400 // in cm
#define MIN_DISTANCE 2 // in cm

void sigint_handler(int sig) {
    gpioWrite(SERVO, 0);
    gpioTerminate();
    exit(0);
}

int measure_distance() {
    gpioWrite(TRIG, 1);
    gpioDelay(10); // 10 microsecond delay
    gpioWrite(TRIG, 0);

    int start_tick = gpioTick();
    int end_tick = 0;

    while (gpioRead(ECHO) == 0) {
        if (gpioTick() - start_tick > 500000) {
            return -1; // timeout
        }
    }

    while (gpioRead(ECHO) == 1) {
        end_tick = gpioTick();
    }

    int travel_time = end_tick - start_tick;
    int distance = (travel_time / 1000) * SPEED_OF_SOUND / 2; // divide by 2 because it's the round trip

    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return -1; // invalid distance
    }

    return distance;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    gpioSetMode(TRIG, PI_OUTPUT);
    gpioSetMode(ECHO, PI_INPUT);
    gpioSetMode(SERVO, PI_OUTPUT);

    FILE *log_file = fopen("sensor_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    while (1) {
        int distance = measure_distance();

        if (distance >= 0) {
            int angle = (distance - MIN_DISTANCE) * 180 / (MAX_DISTANCE - MIN_DISTANCE);
            gpioServo(SERVO, angle);

            time_t now = time(NULL);
            fprintf(log_file, "%ld,%d\n", now, distance);
            fflush(log_file);
        }

        gpioDelay(200000); // 200 ms delay
    }

    return 0;
}

