#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <mqueue.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define REG_SOFT_RESET 0x00
#define REG_MODEL_ID 0x010F
#define REG_TIMING_BUDGET 0x0084
#define REG_START_RANGING 0x0080
#define REG_DATA_READY 0x0089
#define REG_DISTANCE 0x0096
#define GPIO_BUZZER 23

int main(void)
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Open I2C bus
    int i2c = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c < 0)
    {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Check sensor model ID
    unsigned char model_id[2];
    if (i2cReadI2CBlockData(i2c, REG_MODEL_ID, model_id, 2) != 2)
    {
        fprintf(stderr, "Failed to read sensor model ID\n");
        return 1;
    }
    if (model_id[0] != 0xEA)
    {
        fprintf(stderr, "Invalid sensor model ID\n");
        return 1;
    }

    // Perform software reset
    if (i2cWriteByteData(i2c, REG_SOFT_RESET, 0x01) < 0)
    {
        fprintf(stderr, "Failed to perform software reset\n");
        return 1;
    }

    // Configure timing budget
    if (i2cWriteByteData(i2c, REG_TIMING_BUDGET, 0xFF) < 0)
    {
        fprintf(stderr, "Failed to configure timing budget\n");
        return 1;
    }

    // Start ranging
    if (i2cWriteByteData(i2c, REG_START_RANGING, 0x01) < 0)
    {
        fprintf(stderr, "Failed to start ranging\n");
        return 1;
    }

    // Initialize GPIO for buzzer
    gpioSetMode(GPIO_BUZZER, PI_OUTPUT);

    // Main loop
    while (1)
    {
        // Check data-ready bit
        unsigned char data_ready;
        if (i2cReadByteData(i2c, REG_DATA_READY) & 0x01)
        {
            // Read distance
            unsigned char distance[2];
            if (i2cReadI2CBlockData(i2c, REG_DISTANCE, distance, 2) != 2)
            {
                fprintf(stderr, "Failed to read distance\n");
                return 1;
            }

            // Convert distance to millimeters
            unsigned int distance_mm = (distance[0] << 8) | distance[1];

            // Activate buzzer if distance is below 100mm
            if (distance_mm < 100)
            {
                gpioWrite(GPIO_BUZZER, 1);
            }
            else
            {
                gpioWrite(GPIO_BUZZER, 0);
            }

            // Log distance reading
            // ...
        }

        // Sleep for 50ms
        usleep(50000);
    }

    // Cleanup
    gpioTerminate();
    i2cClose(i2c);

    return 0;
}

