#define SHUTDOWN_GPIO 23
#define INTERRUPT_GPIO 24
#define SERVO_GPIO 18
#define MIN_DIST 50
#define MAX_DIST 60

FILE *log_file;

void sig_handler(int signum) {
    fclose(log_file);
    gpioTerminate();
    exit(0);
}

void check_error(int result, const char *message) {
    if (result < 0) {
        fprintf(stderr, "Error: %s, code %d\n", message, result);
        exit(1);
    }
}

int main() {
    // Initialize GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    // Open log file
    log_file = fopen("parking_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Set up GPIOs
    gpioSetMode(SHUTDOWN_GPIO, PI_OUTPUT);
    gpioSetMode(INTERRUPT_GPIO, PI_INPUT);
    gpioSetMode(SERVO_GPIO, PI_OUTPUT);

    // Initialize VL53L1X
    int tof = i2cOpen(1, TOF_ADDR, 0);
    if (tof < 0) {
        fprintf(stderr, "Failed to open VL53L1X\n");
        return 1;
    }

    // Verify sensor model ID
    char model_id[3];
    check_error(i2cReadDevice(tof, model_id, 3), "Failed to read model ID");
    if (model_id[0] != 0xEA || model_id[1] != 0xE9) {
        fprintf(stderr, "Invalid sensor model ID\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Read distance
        char dist_msb, dist_lsb;
        check_error(i2cReadDevice(tof, &dist_msb, 1), "Failed to read distance MSB");
        check_error(i2cReadDevice(tof, &dist_lsb, 1), "Failed to read distance LSB");
        int distance = (dist_msb << 8) | dist_lsb;

        // Log distance and timestamp
        time_t now = time(NULL);
        fprintf(log_file, "%s: Distance = %d cm\n", ctime(&now), distance);
        fflush(log_file);

        // Open gate if distance is less than 50 cm, close if greater than 60 cm
        if (distance < MIN_DIST) {
            gpioWrite(SERVO_GPIO, 1); // Open gate
        } else if (distance > MAX_DIST) {
            gpioWrite(SERVO_GPIO, 0); // Close gate
        }

        // Sleep for a while
        time_sleep(0.1);
    }

    return 0;
}

