#include <pigpio.h>
#include <time.h>
#include <stdio.h>
#include <unistd.h>
#include <signal.h>

#define I2C_HANDLE 1
#define I2C_ADDR 0x29
#define DISTANCE_REG 0x16
#define SOFT_RESET_REG 0x00
#define TIMING_BUDGET_REG 0x01
#define GO_REG 0x00

#define GPIO_GATE_OPEN 18
#define GPIO_GATE_CLOSE 19

#define TIMEOUT 500000

int i2cHandle;
FILE *logFile;

void sigint_handler(int sig) {
    fclose(logFile);
    gpioTerminate();
    exit(0);
}

void writeRegister(uint8_t reg, uint16_t data) {
    uint8_t buffer[3] = {reg, (data >> 8) & 0xFF, data & 0xFF};
    if (i2cWriteI2CBlockData(i2cHandle, I2C_ADDR, buffer, 3) < 0) {
        time_t now = time(NULL);
        fprintf(logFile, "%s: Error writing to register 0x%02X: %s\n", ctime(&now), reg, strerror(errno));
    }
}

uint16_t readRegister(uint8_t reg) {
    uint8_t buffer[2] = {0, 0};
    if (i2cReadI2CBlockData(i2cHandle, I2C_ADDR, reg, buffer, 2) < 0) {
        time_t now = time(NULL);
        fprintf(logFile, "%s: Error reading from register 0x%02X: %s\n", ctime(&now), reg, strerror(errno));
        return 0;
    }
    return (buffer[0] << 8) | buffer[1];
}

void handleSensorData(uint16_t data) {
    if (data < 200) {
        gpioWrite(GPIO_GATE_OPEN, 1);
        gpioWrite(GPIO_GATE_CLOSE, 0);
        time_t now = time(NULL);
        fprintf(logFile, "%s: Gate opened\n", ctime(&now));
    } else {
        gpioWrite(GPIO_GATE_OPEN, 0);
        gpioWrite(GPIO_GATE_CLOSE, 1);
        time_t now = time(NULL);
        fprintf(logFile, "%s: Gate closed\n", ctime(&now));
    }
}

int main() {
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        perror("Unable to catch SIGINT");
        return 1;
    }
    if (signal(SIGTERM, sigint_handler) == SIG_ERR) {
        perror("Unable to catch SIGTERM");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    i2cHandle = i2cOpen(1, I2C_ADDR, 0);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return 1;
    }

    logFile = fopen("gate_events.log", "w");
    if (logFile == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    gpioSetMode(GPIO_GATE_OPEN, PI_OUTPUT);
    gpioSetMode(GPIO_GATE_CLOSE, PI_OUTPUT);

    writeRegister(SOFT_RESET_REG, 0x01);
    time_sleep(0.1);
    writeRegister(TIMING_BUDGET_REG, 0x0020);
    writeRegister(GO_REG, 0x01);

    while (1) {
        handleSensorData(readRegister(DISTANCE_REG));
        time_sleep(0.5);
    }

    return 0;
