#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>

#define I2C_HANDLE 1
#define GPIO_TRIGGER 24
#define GPIO_MOTOR_FORWARD 17
#define GPIO_MOTOR_BACKWARD 18
#define VL53L1X_ADDR 0x29
#define VL53L1X_MEASUREMENT_REG 0x0089
#define VL53L1X_DISTANCE_REG_MSB 0x0096
#define VL53L1X_DISTANCE_REG_LSB 0x0097

void sigint_handler(int sig) {
    gpioWrite(GPIO_MOTOR_FORWARD, 0);
    gpioWrite(GPIO_MOTOR_BACKWARD, 0);
    gpioTerminate();
    exit(0);
}

void i2c_retry(int handle, int addr, char* data, int len) {
    int retry_count = 5;
    while (retry_count--) {
        if (i2cWriteDevice(handle, data, len) >= 0)
            return;
        sleep(1 << retry_count);
    }
    fprintf(stderr, "Failed to write to I2C device\n");
    exit(1);
}

void on_gpio_interrupt(int gpio, int level, uint32_t tick) {
    char data[2];
    int distance;

    i2c_retry(I2C_HANDLE, VL53L1X_ADDR, "\x00\x00", 2);
    sleep(1);
    i2c_retry(I2C_HANDLE, VL53L1X_ADDR, "\x01\x00", 2);

    while (1) {
        i2c_retry(I2C_HANDLE, VL53L1X_ADDR, (char*)&VL53L1X_MEASUREMENT_REG, 1);
        i2c_retry(I2C_HANDLE, VL53L1X_ADDR, data, 1);
        if (data[0] & 0x01)
            break;
        sleep(1);
    }

    i2c_retry(I2C_HANDLE, VL53L1X_ADDR, (char*)&VL53L1X_DISTANCE_REG_MSB, 1);
    i2c_retry(I2C_HANDLE, VL53L1X_ADDR, data, 2);
    distance = (data[0] << 8) | data[1];

    printf("Distance: %d mm\n", distance);

    if (distance < 100) {
        gpioWrite(GPIO_MOTOR_FORWARD, 1);
        gpioWrite(GPIO_MOTOR_BACKWARD, 0);
    } else if (distance > 300) {
        gpioWrite(GPIO_MOTOR_FORWARD, 0);
        gpioWrite(GPIO_MOTOR_BACKWARD, 1);
    } else {
        gpioWrite(GPIO_MOTOR_FORWARD, 0);
        gpioWrite(GPIO_MOTOR_BACKWARD, 0);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    gpioSetMode(GPIO_TRIGGER, PI_INPUT);
    gpioSetMode(GPIO_MOTOR_FORWARD, PI_OUTPUT);
    gpioSetMode(GPIO_MOTOR_BACKWARD, PI_OUTPUT);

    gpioSetISRFunc(GPIO_TRIGGER, RISING_EDGE, 0, on_gpio_interrupt);

    while (1)
        sleep(1);

    return 0;
}

