#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_GPIO 17
#define ECHO_GPIO 18
#define GPIO_CHIP "gpiochip0"
#define SPEED_OF_SOUND 343.0
#define MAX_DISTANCE 400.0
#define MIN_DISTANCE 2.0
#define TRIGGER_PULSE_US 10
#define TRIGGER_HOLD_US 5
#define ECHO_TIMEOUT_MS 30

volatile sig_atomic_t stop;
struct gpiod_chip *chip;
struct gpiod_line *trigger_line, *echo_line;

void intHandler(int dummy) {
    stop = 1;
    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);
    fclose(log_file);
    exit(0);
}

int main() {
    struct timespec ts = {0, 1000000000};
    FILE *log_file = fopen("distance_log.txt", "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (chip == NULL) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_GPIO);
    echo_line = gpiod_chip_get_line(chip, ECHO_GPIO);
    if (trigger_line == NULL || echo_line == NULL) {
        perror("Failed to get GPIO lines");
        return 1;
    }

    if (gpiod_line_request_output(trigger_line, "trigger", 0) < 0) {
        perror("Failed to request trigger line as output");
        return 1;
    }

    if (gpiod_line_request_input(echo_line, "echo") < 0) {
        perror("Failed to request echo line as input");
        return 1;
    }

    signal(SIGINT, intHandler);

    while (!stop) {
        gpiod_line_set_value(trigger_line, 0);
        nanosleep(&ts, NULL);
        gpiod_line_set_value(trigger_line, 1);
        nanosleep(&ts, NULL);
        gpiod_line_set_value(trigger_line, 0);

        int ret = gpiod_line_event_wait(echo_line, 1, NULL, NULL, ECHO_TIMEOUT_MS * 1000000);
        if (ret < 0) {
            perror("Failed to wait for echo line event");
            return 1;
        }

        if (ret == 0) {
            fprintf(log_file, "%s: Timeout\n", get_current_time());
            continue;
        }

        struct gpiod_line_event event;
        ret = gpiod_line_event_read(echo_line, &event);
        if (ret < 0) {
            perror("Failed to read echo line event");
            return 1;
        }

        double distance = (event.timestamp.tv_nsec / 1000.0 - TRIGGER_HOLD_US - TRIGGER_PULSE_US) * SPEED_OF_SOUND / 2.0;
        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            fprintf(log_file, "%s: Out of range: %.2f cm\n", get_current_time(), distance);
        } else {
            fprintf(log_file, "%s: %.2f cm\n", get_current_time(), distance);
        }

        fflush(log_file);
        nanosleep(&ts, NULL);
    }

    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);
    fclose(log_file);
    return 0;
}

