#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <syslog.h>
#include <signal.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define GPIO_TRIGGER 27

void sigint_handler(int sig) {
    closeserial(i2c);
    gpioTerminate();
    exit(0);
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialise GPIO");
        return 1;
    }

    gpioSetMode(GPIO_TRIGGER, PI_OUTPUT);
    gpioWrite(GPIO_TRIGGER, 1);

    int i2c = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c < 0) {
        syslog(LOG_ERR, "Failed to open I2C device");
        return 1;
    }

    while (1) {
        char buffer[3];
        buffer[0] = 0x14;
        i2cWriteByte(i2c, 0x18);
        i2cWriteByte(i2c, 0x00);
        i2cWriteByte(i2c, 0x01);

        gpioDelay(100000);

        i2cReadI2CBlock(i2c, 0x14, buffer, 2);
        i2cReadI2CBlock(i2c, 0x16, buffer+2, 1);

        int distance = (buffer[1] << 8) | buffer[0];
        int status = buffer[2];

        if (distance > 0 && status == 0) {
            syslog(LOG_INFO, "Timestamp: %ld, Distance: %d mm, Status: %d", time(NULL), distance, status);
        } else {
            syslog(LOG_ERR, "Failed to read distance and status");
        }

        gpioDelay(1000000);
    }

    return 0;
}

