#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_HANDLE 1
#define SENSOR_ADDR 0x29
#define GPIO_PIN 24
#define LOG_FILE "gate_log.txt"

void sigint_handler(int sig);
void write_log(char *message);

int main() {
    // Initialise pigpio and I2C
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_HANDLE, SENSOR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        return 1;
    }

    // Initialise sensor
    unsigned char sensor_id[2];
    if (i2cReadDevice(i2c_handle, 0x010F, sensor_id, 2) != 2) {
        fprintf(stderr, "Failed to read sensor ID\n");
        return 1;
    }

    if (sensor_id[0] != 0xEA) {
        fprintf(stderr, "Invalid sensor ID: 0x%02X\n", sensor_id[0]);
        return 1;
    }

    if (i2cWriteByte(i2c_handle, 0x0021, 0x00) < 0) {
        fprintf(stderr, "Failed to set ranging mode\n");
        return 1;
    }

    if (i2cWriteByte(i2c_handle, 0x0015, 0x01) < 0) {
        fprintf(stderr, "Failed to start ranging\n");
        return 1;
    }

    // Initialise GPIO
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, PI_LOW);

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Main loop
    while (1) {
        unsigned char distance_data[2];
        if (i2cReadDevice(i2c_handle, 0x0089, distance_data, 2) != 2) {
            fprintf(stderr, "Failed to read distance\n");
            return 1;
        }

        int distance = (distance_data[0] << 8) | distance_data[1];
        printf("Distance: %d cm\n", distance);

        if (distance < 200) {
            gpioWrite(GPIO_PIN, PI_HIGH);
            write_log("Gate opened");
        } else {
            gpioWrite(GPIO_PIN, PI_LOW);
            write_log("Gate closed");
        }

        time_sleep(0.1);
    }

    return 0;
}

void sigint_handler(int sig) {
    // Close I2C handle and terminate pigpio
    i2cClose(I2C_HANDLE);
    gpioTerminate();

    // Close log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fclose(log_file);
    }

    exit(0);
}

void write_log(char *message) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fclose(log_file);
    }
}

