#include <pigpio.h>
#include <stdio.h>
#include <signal.h>
#include <math.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

volatile sig_atomic_t stop;

void alertCallback(int gpio, int level, uint32_t tick);

int main() {
    FILE *file;
    int startTick, elapsed;
    double distance, avgDistance = 0.0, angle;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    if (gpioSetAlertFunc(ECHO_PIN, alertCallback) < 0) {
        fprintf(stderr, "Failed to register alert callback\n");
        return 1;
    }

    if ((file = fopen("distance_log.csv", "w")) == NULL) {
        fprintf(stderr, "Failed to open CSV file\n");
        return 1;
    }

    fprintf(file, "Timestamp,Distance (cm),Servo Angle (deg)\n");
    fflush(file);

    signal(SIGINT, [](int sig) {
        stop = 1;
        gpioServo(SERVO_PIN, 90);
        fclose(file);
        gpioTerminate();
    });

    while (!stop) {
        gpioWrite(TRIG_PIN, 1);
        gpioDelay(10);
        gpioWrite(TRIG_PIN, 0);

        if (gpioRead(ECHO_PIN) == 0) {
            fprintf(file, "%ld,-1.0,90\n", time(NULL));
            fflush(file);
            continue;
        }

        startTick = gpioTick();
        while (gpioRead(ECHO_PIN) == 1) {
            if ((gpioTick() - startTick) > 320000) {
                fprintf(file, "%ld,-1.0,90\n", time(NULL));
                fflush(file);
                goto next_iteration;
            }
        }

        elapsed = gpioTickDiff(startTick, gpioTick());
        distance = elapsed / 58.0; // Speed of sound = 34300 cm/s, divide by 2 (round trip) and convert to cm

        avgDistance = (avgDistance * 4.0 + distance) / 5.0;

        angle = log(avgDistance) * 18.0 / 3.14159265358979323846; // Logarithmic mapping
        angle = fmax(fmin(angle, 180.0), 0.0); // Clamp to 0-180 degrees

        gpioServo(SERVO_PIN, (int)angle);

        fprintf(file, "%ld,%.2f,%.0f\n", time(NULL), avgDistance, angle);
        fflush(file);

    next_iteration:
        gpioDelay(10000000); // 10 ms delay
    }

    return 0;
}

void alertCallback(int gpio, int level, uint32_t tick) {
    gpioWrite(ECHO_PIN, 0);
}

