    signal(SIGINT, sigint_handler);

    handle_error(gpioInitialise());
    handle_error(VL53L1X_Init(&dev, I2C_BUS, I2C_ADDR));
    handle_error(VL53L1X_SetDistanceMode(&dev, 1)); // Set distance mode to Short
    handle_error(VL53L1X_SetTimingBudgetInMs(&dev, 10)); // Set timing budget to 10 ms
    handle_error(VL53L1X_StartRanging(&dev));

    while (1) {
        uint16_t distance;
        handle_error(VL53L1X_GetDistance(&dev, &distance));

        buffer[buffer_index++] = distance;
        if (buffer_index == BUFFER_SIZE) buffer_index = 0;

        if (distance < 200) {
            gpioWrite(GPIO_PIN, 1);
        } else {
            gpioWrite(GPIO_PIN, 0);
        }

        usleep(READ_INTERVAL);
    }

    return 0;
}

