#include <stdio.h>
#include <math.h>

#define TRIG 23
#define ECHO 24
#define SPEAKER 18

double map_distance_to_frequency(double distance) {
    if (distance < 2.0 || distance > 200.0) {
        return -1.0;
    }
    return 200.0 * exp(distance / 50.0);
}

void sigint_handler(int signum) {
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    if (gpioSetMode(TRIG, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set trigger GPIO mode\n");
        return 1;
    }

    if (gpioSetMode(ECHO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set echo GPIO mode\n");
        return 1;
    }

    if (gpioSetMode(SPEAKER, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set speaker GPIO mode\n");
        return 1;
    }

    while (1) {
        gpioTrigger(TRIG, 10, 1); // Send 10 us trigger pulse
        double start = gpioTick();
        while (gpioRead(ECHO) == 0) {
            if (gpioTick() - start > 200000) { // Timeout after 200 ms
                break;
            }
        }
        double distance = (gpioTick() - start) / 1000000.0 * 340.0 / 2.0; // Calculate distance in cm
        double frequency = map_distance_to_frequency(distance);
        if (frequency > 0.0) {
            gpioHardwarePWM(SPEAKER, frequency, 500000, 1000000); // Generate tone with PWM
        }
    }

    return 0;
}

