#include <pigpio.h>
#include <stdio.h>
#include <signal.h>

#define TRIG 23
#define ECHO 24
#define BUZZER 18

#define MIN_DIST 5
#define MAX_DIST 50
#define MIN_FREQ 200
#define MAX_FREQ 2000

volatile sig_atomic_t stop;

void alarmHandler(int signum) {
    stop = 1;
}

double getDistance() {
    gpioSetMode(TRIG, PI_OUTPUT);
    gpioSetMode(ECHO, PI_INPUT);

    gpioWrite(TRIG, PI_OFF);
    gpioDelay(10);

    gpioWrite(TRIG, PI_ON);
    gpioDelay(10);
    gpioWrite(TRIG, PI_OFF);

    while(gpioRead(ECHO) == PI_OFF) {
        if(stop) return -1;
    }

    gpioSetWatchdog(ECHO, 100000000);
    gpioRead(ECHO);
    unsigned int startTick = gpioTick();

    while(gpioRead(ECHO) == PI_ON) {
        if(stop) return -1;
    }

    unsigned int endTick = gpioTick();
    gpioSetWatchdog(ECHO, 0);

    double diff = endTick - startTick;
    double distance = (diff / 1000000.0) * 34000.0 / 2.0;

    if(distance < MIN_DIST || distance > MAX_DIST) {
        return -1;
    }

    return distance;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, alarmHandler);

    while(1) {
        double distance = getDistance();

        if(distance < 0) {
            fprintf(stderr, "Failed to read distance\n");
            continue;
        }

        unsigned int freq = MIN_FREQ + (MAX_FREQ - MIN_FREQ) * (MAX_DIST - distance) / (MAX_DIST - MIN_DIST);

        if(freq < MIN_FREQ) freq = MIN_FREQ;
        if(freq > MAX_FREQ) freq = MAX_FREQ;

        printf("Distance: %.2f cm, Frequency: %d Hz\n", distance, freq);

        gpioHardwarePWM(BUZZER, freq, 500000);

        gpioDelay(10000000);

        if(stop) {
            gpioHardwarePWM(BUZZER, 0, 0);
            break;
        }
    }

    gpioTerminate();

    return 0;
}

