        gpioWrite(TRIG, 1);
        gpioDelay(pigpio_micros(TRIG_PULSE_WIDTH));
        gpioWrite(TRIG, 0);

        unsigned int start_tick = gpioTick();
        unsigned int echo_width = gpioRead(ECHO);

        if (echo_width == PI_TIMEOUT) {
            fprintf(stderr, "Timeout occurred\n");
            continue;
        }

        float distance = (float)echo_width * SPEED_OF_SOUND / 2.0 / 10000.0;

