#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>

#define I2C_DEV "/dev/i2c-1"
#define SENSOR_ADDR 0x60
#define REG_ALS_VISIBLE_LOW 0x22
#define REG_ALS_VISIBLE_HIGH 0x23

int fd;
FILE *log_file;

void cleanup(int signum) {
    fclose(log_file);
    close(fd);
    exit(0);
}

int main() {
    uint16_t als_visible;
    char timestamp[20];

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    if ((fd = open(I2C_DEV, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to acquire bus access or talk to slave");
        return 1;
    }

    if ((log_file = fopen("proximity_log.csv", "w")) == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    fprintf(log_file, "timestamp,als_visible\n");

    while (1) {
        uint8_t low, high;

        if (write(fd, &REG_ALS_VISIBLE_LOW, 1) != 1) {
            perror("Failed to write to the i2c bus");
            return 1;
        }

        if (read(fd, &low, 1) != 1) {
            perror("Failed to read from the i2c bus");
            return 1;
        }

        if (write(fd, &REG_ALS_VISIBLE_HIGH, 1) != 1) {
            perror("Failed to write to the i2c bus");
            return 1;
        }

        if (read(fd, &high, 1) != 1) {
            perror("Failed to read from the i2c bus");
            return 1;
        }

        als_visible = (high << 8) | low;

        time_t t = time(NULL);
        struct tm *tm = localtime(&t);
        strftime(timestamp, sizeof(timestamp), "%FT%T%z", tm);

        fprintf(log_file, "%s,%d\n", timestamp, als_visible);
        fflush(log_file);

        sleep(5);
    }

    return 0;
}

