    fclose(logFile);
    close(fd);
    exit(0);
}

void handle_sigterm(int sig) {
    fclose(logFile);
    close(fd);
    exit(0);
}

int main() {
    if (wiringPiSetup() == -1) {
        printf("Failed to setup wiringPi: %s\n", strerror(errno));
        return 1;
    }

    fd = wiringPiI2CSetup(I2C_ADDR);
    if (fd == -1) {
        printf("Failed to open I2C device: %s\n", strerror(errno));
        return 1;
    }

    logFile = fopen("biometric_log.txt", "w");
    if (logFile == NULL) {
        printf("Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    int partId = wiringPiI2CReadReg8(fd, PART_ID_REG);
    if (partId == -1) {
        printf("Failed to read part ID: %s\n", strerror(errno));
        return 1;
    }

    if (partId != 0x48) {
        printf("Sensor not found, part ID: 0x%02X\n", partId);
        return 1;
    }

    if (wiringPiI2CWriteReg8(fd, MEAS_RATE_REG, 0x07) == -1) {
        printf("Failed to write to measurement rate register: %s\n", strerror(errno));
        return 1;
    }

    while (1) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", tm_info);

        int rawAmbientLight = wiringPiI2CReadReg16(fd, AMBIENT_LIGHT_REG);
        if (rawAmbientLight == -1) {
            printf("Failed to read ambient light: %s\n", strerror(errno));
            return 1;
        }

        float lux = rawAmbientLight * 0.1;

        int rawProximity = wiringPiI2CReadReg16(fd, PROXIMITY_REG);
        if (rawProximity == -1) {
            printf("Failed to read proximity: %s\n", strerror(errno));
            return 1;
        }

        fprintf(logFile, "%s,%.2f,%d\n", timestamp, lux, rawProximity);
        printf("%s,%.2f,%d\n", timestamp, lux, rawProximity);

        fflush(logFile);
        sleep(0.1);
    }

    return 0;
}

