#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>

#define I2C_ADDR 0x60
#define REG_HARDWARE_KEY 0x07
#define REG_MEAS_RATE 0x06
#define REG_PS_ADC_COUNTER 0x21
#define REG_PS_ADC_GAIN 0x0D
#define REG_PS_LED 0x0C
#define REG_COMMAND 0x00
#define REG_PS1_DATA 0x16

#define MAX_RETRIES 3

FILE *log_file;
int i2c_handle;

void handle_sigint(int sig) {
    fclose(log_file);
    gpioTerminate();
    exit(0);
}

void handle_sigterm(int sig) {
    fclose(log_file);
    gpioTerminate();
    exit(0);
}

void write_to_sensor(int reg, char value) {
    for(int i = 0; i < MAX_RETRIES; i++) {
        if(gpioWriteI2C(i2c_handle, reg, value) >= 0)
            return;
        time_t t = time(NULL);
        fprintf(log_file, "%s: Failed to write to register 0x%02X, retrying...\n", ctime(&t), reg);
    }
    exit(1);
}

unsigned int read_from_sensor(int reg) {
    char data[2];
    for(int i = 0; i < MAX_RETRIES; i++) {
        if(gpioReadI2C(i2c_handle, reg, data, 2) >= 0)
            return (data[0] << 8) | data[1];
        time_t t = time(NULL);
        fprintf(log_file, "%s: Failed to read from register 0x%02X, retrying...\n", ctime(&t), reg);
    }
    exit(1);
}

int main() {
    if(gpioInitialise() < 0)
        return 1;

    i2c_handle = i2cOpen(1, I2C_ADDR, 0);
    if(i2c_handle < 0)
        return 1;

    log_file = fopen("proximity_log.txt", "w");
    if(log_file == NULL)
        return 1;

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    write_to_sensor(REG_HARDWARE_KEY, 0x03);
    write_to_sensor(REG_MEAS_RATE, 0x02);
    write_to_sensor(REG_PS_ADC_COUNTER, 0x0B);
    write_to_sensor(REG_PS_ADC_GAIN, 0x07);
    write_to_sensor(REG_PS_LED, 0x03);
    write_to_sensor(REG_COMMAND, 0x03);

    while(1) {
        unsigned int proximity = read_from_sensor(REG_PS1_DATA);
        time_t t = time(NULL);
        fprintf(log_file, "%s: Proximity: %u\n", ctime(&t), proximity);
        fflush(log_file);
        time_sleep(1);
    }

    return 0;
}

