#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIG_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27

volatile unsigned long startTime = 0, endTime = 0;

void alertCallback(int gpio, int level, uint32_t tick) {
    if (level == 0) { // Rising edge
        startTime = tick;
    } else { // Falling edge
        endTime = tick;
    }
}

void errorHandler(int signum) {
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio library\n");
        return 1;
    }

    signal(SIGINT, errorHandler);

    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set trigger pin mode\n");
        return 1;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set echo pin mode\n");
        return 1;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set buzzer pin mode\n");
        return 1;
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, alertCallback) < 0) {
        fprintf(stderr, "Failed to set alert function\n");
        return 1;
    }

    while (1) {
        gpioWrite(TRIG_PIN, 1);
        gpioDelay(10); // 10 us
        gpioWrite(TRIG_PIN, 0);

        if (startTime != 0 && endTime != 0) {
            double distance = (endTime - startTime) * 0.0343 / 2;
            printf("Distance: %.2f cm\n", distance);

            if (distance < 20.0) {
                gpioWrite(BUZZER_PIN, 1);
            } else {
                gpioWrite(BUZZER_PIN, 0);
            }

            startTime = 0;
            endTime = 0;
        }

        gpioDelay(1000000); // 1 second
    }

    return 0;
}

