#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_HANDLE 1
#define VL53L1X_ADDR 0x29
#define SERVO_GPIO 18
#define TIMING_BUDGET 100
#define DISTANCE_REG 0x10F
#define MODEL_ID_REG 0x010F
#define MODEL_ID 0xEA
#define HYSTERESIS 50
#define OPEN_PULSE 1000
#define CLOSE_PULSE 2000

int i2cHandle;
FILE *logFile;

void sigint_handler(int sig) {
    fclose(logFile);
    gpioWrite(SERVO_GPIO, 0);
    gpioTerminate();
    i2cClose(i2cHandle);
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    i2cHandle = i2cOpen(I2C_HANDLE, VL53L1X_ADDR, 0);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        return 1;
    }

    logFile = fopen("gate_log.txt", "w");
    if (logFile == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    char modelId;
    i2cReadByteData(i2cHandle, MODEL_ID_REG, &modelId);
    if (modelId != MODEL_ID) {
        fprintf(stderr, "Invalid model ID\n");
        return 1;
    }

    gpioSetMode(SERVO_GPIO, PI_OUTPUT);
    gpioHardwarePWM(SERVO_GPIO, 50, CLOSE_PULSE * 1000, 1000000);

    i2cWriteByteData(i2cHandle, 0x0204, TIMING_BUDGET);
    i2cWriteByteData(i2cHandle, 0x0010, 0x01);

    while (1) {
        char distance[2];
        i2cReadDevice(i2cHandle, distance, 2);
        int distance_mm = (distance[0] << 8) | distance[1];

        if (distance_mm < 200) {
            gpioHardwarePWM(SERVO_GPIO, 50, OPEN_PULSE * 1000, 1000000);
            time_t now = time(NULL);
            fprintf(logFile, "%s: Gate opened\n", ctime(&now));
        } else if (distance_mm > 250) {
            gpioHardwarePWM(SERVO_GPIO, 50, CLOSE_PULSE * 1000, 1000000);
            time_t now = time(NULL);
            fprintf(logFile, "%s: Gate closed\n", ctime(&now));
        }

        time_sleep(0.1);
    }

    return 0;
}

