#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define TEMP_REG 0x01
#define HUMID_REG 0x02
#define CONFIG_REG 0x03
#define CONFIG_VAL 0x00

volatile sig_atomic_t stop;

void sigint_handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    int handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    char buf[2];
    buf[0] = CONFIG_REG;
    buf[1] = CONFIG_VAL;
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Failed to write to CONFIG register\n");
        return 1;
    }

    gpioDelay(10000);  // Wait 10 ms

    while (!stop) {
        if (i2cWriteDevice(handle, &TEMP_REG, 1) != 1) {
            fprintf(stderr, "Failed to write to TEMP register\n");
            return 1;
        }

        gpioDelay(10000);  // Wait 10 ms

        if (i2cReadDevice(handle, buf, 2) != 2) {
            fprintf(stderr, "Failed to read from TEMP register\n");
            return 1;
        }

        float temp = (175.72 * (buf[0] * 256 + buf[1])) / 65536.0 - 46.85;

        if (i2cWriteDevice(handle, &HUMID_REG, 1) != 1) {
            fprintf(stderr, "Failed to write to HUMID register\n");
            return 1;
        }

        if (i2cReadDevice(handle, buf, 2) != 2) {
            fprintf(stderr, "Failed to read from HUMID register\n");
            return 1;
        }

        float humid = (125.0 * (buf[0] * 256 + buf[1])) / 65536.0 - 6.0;

        printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp, humid);

        gpioDelay(2000000);  // Wait 2 seconds
    }

    i2cClose(handle);
    gpioTerminate();

    return 0;
}

