#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define SMPLRT_DIV 0x19
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG 0x1B
#define WHO_AM_I 0x75
#define TEMP_OUT_H 0x41
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43

void sigint_handler(int sig) {
    gpioTerminate();
    exit(0);
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    int handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    char who_am_i;
    if (i2cReadByteData(handle, WHO_AM_I) != MPU6050_ADDR) {
        fprintf(stderr, "MPU6050 not found\n");
        return 1;
    }

    i2cWriteByteData(handle, PWR_MGMT_1, 0); // Reset and wake up the device
    sleep(1); // Wait for the device to stabilize
    i2cWriteByteData(handle, PWR_MGMT_1, 0); // Clear the sleep bit
    i2cWriteByteData(handle, SMPLRT_DIV, 7); // Set the sample-rate divider
    i2cWriteByteData(handle, ACCEL_CONFIG, 0); // Set the accelerometer range to ±2 g
    i2cWriteByteData(handle, GYRO_CONFIG, 0); // Set the gyroscope range to ±250 deg/s

    while (1) {
        char data[14];
        if (i2cReadI2CBlockData(handle, ACCEL_XOUT_H, data, 14) < 0) {
            fprintf(stderr, "Failed to read from MPU6050\n");
            return 1;
        }

        int16_t accel_x = (data[0] << 8) | data[1];
        int16_t accel_y = (data[2] << 8) | data[3];
        int16_t accel_z = (data[4] << 8) | data[5];
        int16_t temp = (data[6] << 8) | data[7];
        int16_t gyro_x = (data[8] << 8) | data[9];
        int16_t gyro_y = (data[10] << 8) | data[11];
        int16_t gyro_z = (data[12] << 8) | data[13];

        printf("Accel X: %d, Accel Y: %d, Accel Z: %d, Temp: %d, Gyro X: %d, Gyro Y: %d, Gyro Z: %d\n",
               accel_x, accel_y, accel_z, temp, gyro_x, gyro_y, gyro_z);

        sleep(0.1); // Sleep for 100 ms
    }

    i2cClose(handle);
    gpioTerminate();

    return 0;
}

