#define CRC_POLY 0x31
#define CRC_INIT 0xFF

void sig_handler(int signum) {
    gpioTerminate();
    exit(0);
}

uint8_t crc8(uint8_t *data, uint8_t len) {
    uint8_t crc = CRC_INIT;
    for (uint8_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    int handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    while (1) {
        int result = i2cWriteByte(handle, CMD_MEASURE_HIGH_REP);
        if (result < 0) {
            fprintf(stderr, "Failed to write to I2C bus\n");
            i2cClose(handle);
            return 1;
        }

        usleep(10000); // Wait for 10 ms

        uint8_t data[6];
        result = i2cReadDevice(handle, data, 6);
        if (result != 6) {
            fprintf(stderr, "Failed to read from I2C bus\n");
            i2cClose(handle);
            return 1;
        }

        if (crc8(data, 2) != data[2] || crc8(data + 3, 2) != data[5]) {
            fprintf(stderr, "CRC check failed\n");
            continue;
        }

        float temp = -45 + 175 * ((data[0] << 8) | data[1]) / 65535.0;
        float humidity = -6 + 125 * ((data[3] << 8) | data[4]) / 65535.0;
        if (temp < 0) temp = 0;
        if (temp > 100) temp = 100;
        if (humidity < 0) humidity = 0;
        if (humidity > 100) humidity = 100;

        printf("Temperature: %.2f%%\nHumidity: %.2f%%\n", temp, humidity);

        sleep(5);
    }

    return 0;
}

