#include <stdio.h>
#include <stdlib.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define I2C_DEV "/dev/i2c-1"
#define I2C_ADDR 0x5A

int fd;
FILE *log_file;

void handle_sigint(int sig) {
    fclose(log_file);
    close(fd);
    exit(0);
}

int main() {
    signal(SIGINT, handle_sigint);

    if ((fd = open(I2C_DEV, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire bus access or talk to slave");
        return 1;
    }

    if ((log_file = fopen("temperature_log.csv", "w")) == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    while (1) {
        char buf[2];
        buf[0] = 0x06;
        if (write(fd, buf, 1) != 1) {
            perror("Failed to write to the i2c bus");
            return 1;
        }
        sleep(1);
        if (read(fd, buf, 2) != 2) {
            perror("Failed to read from the i2c bus");
            return 1;
        }
        float ambient_temp = (buf[0] * 256 + buf[1]) * 0.02 - 273.15;

        buf[0] = 0x07;
        if (write(fd, buf, 1) != 1) {
            perror("Failed to write to the i2c bus");
            return 1;
        }
        sleep(1);
        if (read(fd, buf, 2) != 2) {
            perror("Failed to read from the i2c bus");
            return 1;
        }
        float object_temp = (buf[0] * 256 + buf[1]) * 0.02 - 273.15;

        time_t now = time(NULL);
        fprintf(log_file, "%ld,%f,%f\n", now, ambient_temp, object_temp);
        fflush(log_file);

        sleep(5);
    }

    return 0;
}

