    if (error_log == NULL) {
        printf("Failed to open error log file\n");
        exit(1);
    }
    time_t now = time(NULL);
    fprintf(error_log, "Caught signal %d at %s", signum, ctime(&now));
    fclose(error_log);
    gpioTerminate();
    exit(0);
}

