        printf("Failed to initialize pigpio library\n");
        return 1;
    }

    signal(SIGINT, error_handler);

    int handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (handle < 0) {
        printf("Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen("enclosure_temp_log.txt", "w");
    if (log_file == NULL) {
        printf("Failed to open log file\n");
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    while (1) {
        char cmd[2] = {0x24, 0x00};
        i2cWriteDevice(handle, cmd, 2);
        time_t now = time(NULL);
        char buf[3] = {0};
        if (i2cReadDevice(handle, buf, 3) != 3) {
            fprintf(stderr, "Failed to read from STS30-DIS at %s", ctime(&now));
            continue;
        }
        float temp = (buf[0] << 8) | buf[1];
        temp *= 0.00381;
        temp += 45.0;
        fprintf(log_file, "%s Temperature: %.2fC\n", ctime(&now), temp);
        fflush(log_file);
        time_t next_sample = time(NULL) + 5;
        while (time(NULL) < next_sample) {
            gpioDelay(1000000);
        }
    }

    fclose(log_file);
    i2cClose(handle);
    gpioTerminate();
    return 0;
}

