        struct tm tm = *localtime(&t);
        fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Temperature: %.2f, Humidity: %.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, temp, humidity);
        fflush(log_file);

        sleep(5);
    }

    fclose(log_file);
    return 0;
