#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28
#define TRIGGER_CMD 0x2196
#define RETRY_ATTEMPTS 3
#define RETRY_DELAY_INIT 1000

volatile sig_atomic_t stop;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    FILE *log_file;
    char log_line[100];
    int i2c;
    char data[6];
    int retry_delay = RETRY_DELAY_INIT;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_file = fopen("airflow.log", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    i2c = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    while (!stop) {
        for (int attempt = 0; attempt < RETRY_ATTEMPTS; attempt++) {
            if (i2cWriteDevice(i2c, &TRIGGER_CMD, 2) >= 0) {
                break;
            }
            usleep(retry_delay);
            retry_delay *= 2;
        }
        retry_delay = RETRY_DELAY_INIT;

        for (int attempt = 0; attempt < RETRY_ATTEMPTS; attempt++) {
            if (i2cReadDevice(i2c, data, 6) == 6) {
                break;
            }
            usleep(retry_delay);
            retry_delay *= 2;
        }
        retry_delay = RETRY_DELAY_INIT;

        time_t now = time(NULL);
        double pressure_pa = (data[0] * 256 + data[1]) / 60.0;
        double temperature_c = (data[3] * 256 + data[4]) / 200.0;

        sprintf(log_line, "%ld,%f,%f\n", now, pressure_pa, temperature_c);
        fputs(log_line, log_file);
        fflush(log_file);

        usleep(100000);
    }

    i2cClose(i2c);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

