#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

#define SENSOR_ADDR 0x40
#define TEMP_CMD 0xF3
#define HUMID_CMD 0xF5

FILE *file;

void sigint_handler(int sig) {
    fclose(file);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", gpioErrorText(gpioGetLastError()));
        return 1;
    }

    int handle = i2cOpen(1, SENSOR_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", gpioErrorText(gpioGetLastError()));
        return 1;
    }

    file = fopen("sensor_data.txt", "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file: %s\n", strerror(errno));
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        char buf[2];
        buf[0] = TEMP_CMD;
        if (i2cWriteI2CBlock(handle, SENSOR_ADDR, buf, 1) < 0) {
            fprintf(stderr, "Failed to write to I2C bus: %s\n", gpioErrorText(gpioGetLastError()));
            return 1;
        }

        usleep(25000); // wait for measurement to be ready

        if (i2cReadI2CBlock(handle, SENSOR_ADDR, buf, 2) < 0) {
            fprintf(stderr, "Failed to read from I2C bus: %s\n", gpioErrorText(gpioGetLastError()));
            return 1;
        }

        float temp = (175.72 * ((buf[0] << 8) | buf[1]) / 65536.0) - 46.85;

        buf[0] = HUMID_CMD;
        if (i2cWriteI2CBlock(handle, SENSOR_ADDR, buf, 1) < 0) {
            fprintf(stderr, "Failed to write to I2C bus: %s\n", gpioErrorText(gpioGetLastError()));
            return 1;
        }

        usleep(25000); // wait for measurement to be ready

        if (i2cReadI2CBlock(handle, SENSOR_ADDR, buf, 2) < 0) {
            fprintf(stderr, "Failed to read from I2C bus: %s\n", gpioErrorText(gpioGetLastError()));
            return 1;
        }

        float humid = (125.0 * ((buf[0] << 8) | buf[1]) / 65536.0) - 6.0;
        if (humid < 0) humid = 0;
        if (humid > 100) humid = 100;

        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        timestamp[strlen(timestamp) - 1] = '\0'; // remove newline

        printf("%s: Temperature = %.2f°C, Humidity = %.2f%%\n", timestamp, temp, humid);
        fprintf(file, "%s: Temperature = %.2f°C, Humidity = %.2f%%\n", timestamp, temp, humid);
        fflush(file);

        sleep(5);
    }

    return 0;
}

