#include <stdio.h>
#include <stdlib.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x25
#define COMMAND 0x362F

int fd;
FILE *file;

void cleanup(int signum) {
    fclose(file);
    close(fd);
    exit(0);
}

int main() {
    unsigned char buffer[9];
    int result;

    fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    result = ioctl(fd, I2C_SLAVE, I2C_ADDRESS);
    if (result < 0) {
        perror("Failed to acquire bus access or talk to slave");
        return 1;
    }

    file = fopen("airflow_data.txt", "w");
    if (file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    fprintf(file, "Timestamp,Pressure (Pa),Temperature (°C)\n");

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        buffer[0] = COMMAND;
        result = write(fd, buffer, 1);
        if (result != 1) {
            perror("Failed to write to the i2c bus");
            return 1;
        }

        usleep(45000); // wait for 45 ms

        result = read(fd, buffer, 9);
        if (result != 9) {
            perror("Failed to read from the i2c bus");
            return 1;
        }

        // validate CRCs here...

        unsigned long pressure = (buffer[0] << 16) | (buffer[1] << 8) | buffer[2];
        pressure /= buffer[6]; // scale factor

        float temperature = ((buffer[3] << 8) | buffer[4]) / 200.0 - 45;

        time_t now = time(NULL);
        fprintf(file, "%ld,%lu,%.2f\n", now, pressure, temperature);
        fflush(file);

        usleep(100000); // wait for 100 ms
    }

    return 0;
}

