#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>

#define STS30_ADDR 0x4A
#define STS30_CMD_SINGLE_SHOT 0x2C06
#define STS30_CMD_READ_DATA 0x2400

void sigint_handler(int sig) {
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio library\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    int handle = i2cOpen(1, STS30_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    while (1) {
        char buf[3];
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, 20, "%Y-%m-%dT%H:%M:%S", tm_info);

        if (i2cWriteByte(handle, STS30_CMD_SINGLE_SHOT) < 0) {
            fprintf(stderr, "[%s] Failed to write to I2C bus\n", timestamp);
            continue;
        }

        gpioDelay(15000);  // Wait at least 15 ms for conversion

        if (i2cReadI2CBlockData(handle, STS30_CMD_READ_DATA, buf, 3) < 0) {
            fprintf(stderr, "[%s] Failed to read from I2C bus\n", timestamp);
            continue;
        }

        // Calculate CRC-8 checksum
        char crc = buf[0] ^ buf[1];
        for (int i = 0; i < 8; i++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }

        if (crc != buf[2]) {
            fprintf(stderr, "[%s] CRC mismatch\n", timestamp);
            continue;
        }

        // Convert raw value to degrees Celsius
        unsigned short raw = (buf[0] << 8) | buf[1];
        float temp = -45 + 175 * (raw / 65535.0);

        // Log temperature reading
        FILE *log_file = fopen("enclosure_temp_log.txt", "a");
        if (log_file != NULL) {
            fprintf(log_file, "[%s] %.2f\n", timestamp, temp);
            fclose(log_file);
        }
    }

    i2cClose(handle);
    gpioTerminate();
    return 0;
}

