#include <sys/ioctl.h>
#include <signal.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SDA_PIN 2
#define SCL_PIN 3
#define SENSOR_ADDR 0x25
#define COMMAND 0x362F

int fd;
FILE *file;

void cleanup(int signum) {
    fclose(file);
    close(fd);
    exit(0);
}

int main() {
    if ((fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        exit(1);
    }

    if (ioctl(fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to acquire bus access or talk to slave");
        exit(1);
    }

    if ((file = fopen("airflow_data.txt", "w")) == NULL) {
        perror("Failed to open file");
        exit(1);
    }

    signal(SIGINT, cleanup);

    while (1) {
        if (write(fd, &COMMAND, 2) != 2) {
            perror("Failed to write to the i2c bus");
            continue;
        }

        delay(1);

        unsigned char buffer[6];
        if (read(fd, buffer, 6) != 6) {
            perror("Failed to read from the i2c bus");
            continue;
        }

        int pressure = (buffer[0] << 8) | buffer[1];
        int temperature = (buffer[3] << 8) | buffer[4];

        pressure = pressure * 240;
        temperature = temperature * 200 - 4500;

        time_t now = time(NULL);
        fprintf(file, "%ld,%d,%d\n", now, pressure, temperature);
        fflush(file);

        delay(1000);
    }

    return 0;
}

