    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    int handle = i2cOpen(I2C_HANDLE, SENSOR_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        return 1;
