#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <stdio.h>

#define SENSOR_PIN 4
#define TIMEOUT_MS 50
#define SAMPLE_INTERVAL_MS 5000
#define MAX_FAILURES 3

volatile sig_atomic_t stop;
int failure_count = 0;
FILE *log_file;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_file = fopen("temperature_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    gpioSetMode(SENSOR_PIN, PI_INPUT);

    while (!stop) {
        unsigned int start, end, total, high;
        double temperature;
        time_t now;
        char timestamp[20];

        gpioTrigger(SENSOR_PIN, TIMEOUT_MS, 1);
        start = gpioTick();

        while (gpioRead(SENSOR_PIN) == 1) {
            end = gpioTick();
            if (end - start > TIMEOUT_MS) {
                failure_count++;
                if (failure_count >= MAX_FAILURES) {
                    fprintf(log_file, "%s SENSOR MALFUNCTION\n", asctime(localtime(&now)));
                    failure_count = 0;
                }
                break;
            }
        }

        if (failure_count > 0) {
            failure_count--;
            continue;
        }

        high = end - start;
        total = gpioTick() - end;

        if (total == 0) {
            fprintf(stderr, "Division by zero\n");
            continue;
        }

        temperature = 4215 - (2143 * high / total);

        if (temperature < -40 || temperature > 150) {
            fprintf(stderr, "Temperature out of range\n");
            continue;
        }

        now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", gmtime(&now));
        fprintf(log_file, "%s %.2f\n", timestamp, temperature);

        time_t next_sample = time(NULL) + SAMPLE_INTERVAL_MS / 1000;
        while (time(NULL) < next_sample) {
            gpioDelay(SAMPLE_INTERVAL_MS);
        }
    }

    fclose(log_file);
    gpioTerminate();

    return 0;
}

