#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SHT35_ADDR 0x44
#define I2C_BUS 1
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF
#define MAX_RETRIES 3
#define DELAY_BETWEEN_RETRIES 1000000 // in microseconds
#define SINUSOIDAL_OFFSET_TEMP 2
#define SINUSOIDAL_OFFSET_HUMIDITY 5
#define LOG_FILENAME "environmental_data.txt"
#define LOG_INTERVAL 5 // in seconds

void sigintHandler(int sig) {
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

uint8_t calc_crc(uint8_t *data, size_t len) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (size_t j = 0; j < 8; j++) {
            if ((crc & 0x80) != 0) {
                crc = (uint8_t)((crc << 1) ^ CRC_POLYNOMIAL);
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return EXIT_FAILURE;
    }

    int i2c = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILENAME, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigintHandler);
    signal(SIGTERM, sigintHandler);

    time_t start_time = time(NULL);
    while (1) {
        uint8_t cmd[] = {0x24, 0x00};
        if (i2cWriteDevice(i2c, cmd, sizeof(cmd)) < 0) {
            fprintf(stderr, "Failed to write to I2C bus\n");
            return EXIT_FAILURE;
        }

        usleep(15000); // wait at least 15 ms

        uint8_t data[6];
        if (i2cReadDevice(i2c, data, sizeof(data)) < 0) {
            fprintf(stderr, "Failed to read from I2C bus\n");
            return EXIT_FAILURE;
        }

        uint8_t crc = calc_crc(data, 2);
        if (crc != data[2]) {
            fprintf(stderr, "CRC check failed\n");
            return EXIT_FAILURE;
        }

        crc = calc_crc(data + 3, 2);
        if (crc != data[5]) {
            fprintf(stderr, "CRC check failed\n");
            return EXIT_FAILURE;
        }

        float temp = -45.0 + 175.0 * data[0] / 65535.0;
        float humidity = 100.0 * data[2] / 65535.0;

        time_t now = time(NULL);
        temp += SINUSOIDAL_OFFSET_TEMP * (1 + sin(2 * M_PI * (now - start_time) / 3600));
        humidity += SINUSOIDAL_OFFSET_HUMIDITY * (1 + sin(2 * M_PI * (now - start_time) / 3600));

        fprintf(log_file, "%ld,%.2f,%.2f\n", now, temp, humidity);
        fflush(log_file);

        sleep(LOG_INTERVAL);
    }

    return EXIT_SUCCESS;
}

