#include <signal.h>
#include <pigpio.h>

#define I2C_HANDLE 1
#define I2C_ADDR 0x25
#define COMMAND 0x362F
#define CONVERSION_TIME 1000000 // 1 second
#define FILE_NAME "airflow.dat"

FILE *file;

void signal_handler(int signum) {
    fclose(file);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    int i2c = i2cOpen(I2C_HANDLE, I2C_ADDR);
    if (i2c < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    if ((file = fopen(FILE_NAME, "wb")) == NULL) {
        fprintf(stderr, "Failed to open file\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        char command[2] = {COMMAND >> 8, COMMAND & 0xFF};
        if (i2cWriteI2CBlockData(i2c, I2C_ADDR, command, 2) < 0) {
            fprintf(stderr, "Failed to write command\n");
            return 1;
        }

        gpioDelay(CONVERSION_TIME);

        char data[9];
        if (i2cReadI2CBlockData(i2c, I2C_ADDR, data, 9) < 0) {
            fprintf(stderr, "Failed to read data\n");
            return 1;
        }

        float pressure = ((data[0] << 8) | data[1]) / (float)data[3] - 1000.0;
        float temperature = ((data[4] << 8) | data[5]) / 200.0 - 45.0;

        if (fwrite(&pressure, sizeof(float), 1, file) != 1 ||
            fwrite(&temperature, sizeof(float), 1, file) != 1) {
            fprintf(stderr, "Failed to write to file\n");
            return 1;
        }

        fflush(file);

        gpioDelay(1000000); // 1 second
    }

    return 0;
}

