#define TEMP_REG 0x00
#define BUFFER_SIZE 10
#define GPIO_LED 17

volatile sig_atomic_t stop;

void handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

