        return 1;
    }

    i2cHandle = gpioI2COpen(I2C_BUS, SCD30_ADDR);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        gpioTerminate();
        return 1;
    }

    logFile = fopen("air_quality.log", "w");
    if (logFile == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioI2CClose(i2cHandle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigHandler);
    signal(SIGTERM, sigHandler);

    // Start continuous measurement with 2 second interval and no ambient pressure compensation
    uint8_t startCommand[] = {0x0010, 0x0000, 0x0202};
    gpioI2CWriteDevice(i2cHandle, startCommand, sizeof(startCommand));

    while (1) {
        // Poll the data-ready flag
        uint8_t readyCommand[] = {0x0202};
        gpioI2CWriteDevice(i2cHandle, readyCommand, sizeof(readyCommand));

        uint8_t readyStatus[3];
        gpioI2CReadDevice(i2cHandle, readyStatus, sizeof(readyStatus));

        if ((readyStatus[0] & 0x01) == 0) {
            fprintf(stderr, "Sensor not ready\n");
            continue;
        }

        // Read the measurement
        uint8_t readCommand[] = {0x0300};
        gpioI2CWriteDevice(i2cHandle, readCommand, sizeof(readCommand));

        uint8_t measurement[18];
