        // Verify the CRC here...

        // Extract the CO2, temperature, and humidity values
        uint32_t co2 = (measurement[0] << 24) | (measurement[1] << 16) | (measurement[2] << 8);
        int16_t temp = (measurement[3] << 8) | measurement[4];
        int16_t humidity = (measurement[6] << 8) | measurement[7];

        // Get the current time
        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%FT%TZ", timeinfo);

        // Log the values
        fprintf(logFile, "%s,%u,%d,%d\n", timestamp, co2, temp, humidity);
        fflush(logFile);

        // Control the ventilation system based on the CO2 reading...

        // Sleep for 2 seconds
        time_t next = time(NULL) + 2;
        while (time(NULL) < next);
    }

    return 0;
}

