#define SENSOR_CMD 0x362F
#define I2C_BUS 1

volatile sig_atomic_t stop;

void handler(int signum) {
    stop = 1;
}

int main(int argc, char *argv[]) {
    int handle, delay;
    unsigned char buffer[9], crc;
    unsigned int pressure, temperature, scale_factor;
    float pressure_pa;

    if (argc != 2) {
        printf("Usage: %s <delay in ms>\n", argv[0]);
        return 1;
    }

    delay = atoi(argv[1]);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, handler);
    signal(SIGTERM, handler);

    handle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByte(handle, SENSOR_CMD) < 0) {
        fprintf(stderr, "Failed to start sensor\n");
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    while (!stop) {
        if (i2cReadI2CBlockData(handle, buffer, 9) != 9) {
            fprintf(stderr, "Failed to read from sensor\n");
            break;
        }

        crc = crc8(buffer, 8);
        if (crc != buffer[8]) {
            fprintf(stderr, "CRC check failed\n");
            break;
        }

        pressure = (buffer[0] << 8) | buffer[1];
        temperature = (buffer[3] << 8) | buffer[4];
        scale_factor = (buffer[6] << 8) | buffer[7];

        pressure_pa = (float)pressure / scale_factor;

        printf("Pressure: %f Pa, Temperature: %u C, Scale Factor: %u\n", pressure_pa, temperature, scale_factor);

        usleep(delay * 1000);
    }

    i2cClose(handle);
    gpioTerminate();

    return 0;
}

