#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <signal.h>

#define I2C_DEV "/dev/i2c-1"
#define I2C_ADDR 0x40

int fd;

void handle_signal(int signum) {
    close(fd);
    exit(0);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if ((fd = open(I2C_DEV, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire bus access or talk to slave");
        return 1;
    }

    // Configure the Configuration Register to enable 14-bit resolution
    char config[] = {0x02, 0x00};
    if (write(fd, config, 2) != 2) {
        perror("Failed to write to the i2c bus");
        return 1;
    }

    while (1) {
        // Write the temperature register pointer
        char temp_reg = 0x00;
        if (write(fd, &temp_reg, 1) != 1) {
            perror("Failed to write to the i2c bus");
            return 1;
        }

        sleep(0.035);  // Wait for 20 ms

        // Read 4 bytes from the sensor
        char data[4];
        if (read(fd, data, 4) != 4) {
            perror("Failed to read from the i2c bus");
            return 1;
        }

        // Convert the raw values to temperature and humidity
        int temp_raw = (data[0] << 8) | data[1];
