        for (size_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    int handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    FILE *file = fopen("airflow_log.csv", "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file\n");
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    if (access("airflow_log.csv", F_OK) != 0) {
        fprintf(file, "Timestamp,Pressure\n");
    }

    while (!stop) {
        int result = i2cWriteByte(handle, COMMAND_BYTES);
        if (result < 0) {
            fprintf(stderr, "Failed to write to I2C bus\n");
            break;
        }

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        usleep(8000);  // Wait for measurement to complete

        uint8_t data[3];
        result = i2cReadI2CBlockData(handle, I2C_ADDR, data, 3);
        if (result != 3) {
            fprintf(stderr, "Failed to read from I2C bus\n");
            break;
        }

        if (crc8(data, 2) != data[2]) {
            fprintf(stderr, "CRC check failed\n");
            break;
        }

        int16_t raw = (data[0] << 8) | data[1];
        double pressure = raw / 60.0;

        fprintf(file, "%s,%f\n", timestamp, pressure);
        fflush(file);

        sleep(1);
    }

    fclose(file);
    i2cClose(handle);
    gpioTerminate();

    return 0;
}
