#define GPIO_PIN 4
#define SYNC_TICKS 56
#define TIMEOUT_TICKS 1000000 // 1 second in ticks

void sigint_handler(int sig) {
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    FILE *log_file = fopen("pressure_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    while (1) {
        int start_tick = gpioTick();
        gpioSetMode(GPIO_PIN, PI_INPUT);

        // Synchronization pulse
        gpioSetAlertFunc(GPIO_PIN, SYNC_TICKS, NULL);
        int sync_tick = gpioTick();
        int sync_diff = gpioTickDiff(sync_tick, start_tick);
        if (sync_diff < SYNC_TICKS - 10 || sync_diff > SYNC_TICKS + 10) {
            fprintf(stderr, "Synchronization error\n");
            continue;
        }

        // Status nibble
        gpioSetAlertFunc(GPIO_PIN, 1000000, NULL);
        int status_tick = gpioTick();
        int status_diff = gpioTickDiff(status_tick, sync_tick);
        if (status_diff < 12 || status_diff > 271) {
            fprintf(stderr, "Status error\n");
            continue;
        }

        // Data nibbles
        int data[3];
        for (int i = 0; i < 3; i++) {
            gpioSetAlertFunc(GPIO_PIN, 1000000, NULL);
            int data_tick = gpioTick();
            int data_diff = gpioTickDiff(data_tick, status_tick);
            if (data_diff < 12 || data_diff > 271) {
                fprintf(stderr, "Data error\n");
                continue;
            }
            data[i] = data_diff;
        }

        // Checksum nibble
        gpioSetAlertFunc(GPIO_PIN, 1000000, NULL);
        int checksum_tick = gpioTick();
        int checksum_diff = gpioTickDiff(checksum_tick, status_tick);
        if (checksum_diff < 12 || checksum_diff > 271) {
            fprintf(stderr, "Checksum error\n");
            continue;
        }

        // Validate checksum
        int checksum = (status_diff + data[0] + data[1] + data[2]) % 16;
        if (checksum != checksum_diff) {
            fprintf(stderr, "Checksum error\n");
            continue;
        }

        // Convert raw value to pressure
        int raw_value = (data[0] << 8) | data[1];
        float pressure = raw_value * 0.0001220703125 + 0.0; // Adjust these values based on your sensor

        // Log pressure reading
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
        fprintf(log_file, "%s, Pressure: %.2f Pa\n", buffer, pressure);
        fflush(log_file);
    }

    fclose(log_file);
    gpioTerminate();
    return 0;
