#define I2C_HANDLE 1
#define TMP117_ADDR 0x48
#define BUFFER_SIZE 100
#define SAMPLE_RATE 5 // in seconds

char buffer[BUFFER_SIZE];
int buffer_index = 0;

void signal_handler(int signum) {
    FILE *file = fopen("temperature_log.dat", "wb");
    if (file == NULL) {
        perror("Error opening file");
        exit(1);
    }

    fwrite(buffer, sizeof(char), buffer_index, file);
    fclose(file);

    gpioWrite(TMP117_ADDR, 0x00); // Send a stop condition
    gpioI2CWriteByte(I2C_HANDLE, TMP117_ADDR, 0x00);
    gpioTerminate();

    exit(0);
}

int main() {
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Error setting signal handler");
        return 1;
    }

    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("Error setting signal handler");
        return 1;
    }

    if (gpioInitialise() < 0) {
        perror("Error initializing pigpio");
        return 1;
    }

    int i2c_handle = gpioI2COpen(0, I2C_HANDLE);
    if (i2c_handle < 0) {
        perror("Error opening I2C handle");
        return 1;
    }

