        if (result < 0) {
            perror("Error writing to I2C device");
            continue;
        }

        gpioDelay(1000000); // Wait for conversion to complete

        result = gpioI2CReadByte(i2c_handle, TMP117_ADDR);
        if (result < 0) {
            perror("Error reading from I2C device");
            continue;
        }

        float temperature = (float)result * 0.0078125;
        printf("Temperature: %.2f°C\n", temperature);

        buffer[buffer_index++] = (char)temperature;
        if (buffer_index == BUFFER_SIZE) {
            FILE *file = fopen("temperature_log.dat", "wb");
            if (file == NULL) {
                perror("Error opening file");
                return 1;
            }

            fwrite(buffer, sizeof(char), BUFFER_SIZE, file);
            fclose(file);
            buffer_index = 0;
        }

        gpioDelay(SAMPLE_RATE * 1000000);
    }

    return 0;
}

