#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include "crc8.h"

#define SDA_GPIO 2
#define SCL_GPIO 3
#define SHT31_ADDR 0x44
#define MEASUREMENT_CMD 0x2C06

FILE *log_file;

void sig_handler(int signum) {
    fclose(log_file);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    if ((log_file = fopen("sht31d_data.log", "w")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    int i2c_handle = i2cOpen(1, SHT31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    while (1) {
        int retry_count = 0;
        while (retry_count < 3) {
            int result = i2cWriteByte(i2c_handle, MEASUREMENT_CMD);
            if (result >= 0) {
                time_sleep(15.0 / 1000.0);
                unsigned char data[6];
                result = i2cReadDevice(i2c_handle, data, 6);
                if (result >= 0) {
                    unsigned char crc_temp = crc8(data, 2, 0x31, 0xFF, 0x00);
                    unsigned char crc_humidity = crc8(data + 3, 2, 0x31, 0xFF, 0x00);
                    if (crc_temp == data[2] && crc_humidity == data[5]) {
                        float temperature = -45.0 + 175.0 * ((data[0] << 8) | data[1]) / 65535.0;
                        float humidity = 100.0 * ((data[3] << 8) | data[4]) / 65535.0;
                        time_t now = time(NULL);
                        struct tm *tm_info = localtime(&now);
                        char timestamp[20];
                        strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", tm_info);
                        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
                        fflush(log_file);
                        break;
                    }
                }
            }
            retry_count++;
        }
        if (retry_count == 3) {
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char timestamp[20];
            strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", tm_info);
            fprintf(log_file, "%s,error\n", timestamp);
            fflush(log_file);
        }
        time_sleep(5.0);
    }

    return 0;
}

