#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define TEMP_REG 0x00
#define GPIO_FAN 18
#define BUFFER_SIZE 60
#define HYSTERESIS 2.0

volatile sig_atomic_t stop;

void handle_signal(int signum) {
    stop = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open I2C bus
    int i2c = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Initialize circular buffer
    int buffer[BUFFER_SIZE] = {0};
    int buffer_index = 0;
    int buffer_sum = 0;

    // Initialize GPIO
    gpioSetMode(GPIO_FAN, PI_OUTPUT);

    while (!stop) {
        // Read temperature
        char temp_raw[2];
        if (i2cReadI2CBlockData(i2c, TEMP_REG, temp_raw, 2) < 0) {
            fprintf(stderr, "Failed to read temperature\n");
            continue;
        }

        // Convert to temperature
        int temp = ((temp_raw[0] << 8) | temp_raw[1]) >> 7;
        if (temp & 0x100) {
            temp |= 0xFE00;
        }
        float temp_c = temp * 0.5;

        // Add to buffer
        buffer_sum -= buffer[buffer_index];
        buffer[buffer_index] = temp_c;
        buffer_sum += temp_c;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        // Compute running average
        float avg = (float)buffer_sum / BUFFER_SIZE;

        // Control fan
        if (avg > 28.0 + HYSTERESIS) {
            gpioWrite(GPIO_FAN, 1);
        } else if (avg < 26.0 - HYSTERESIS) {
            gpioWrite(GPIO_FAN, 0);
        }

        // Wait for next cycle
        time_sleep(1);
    }

    // Cleanup
    gpioWrite(GPIO_FAN, 0);
    i2cClose(i2c);
    gpioTerminate();

    return 0;
}

