#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_HANDLE 1
#define I2C_ADDR 0x25
#define COMMAND 0x362F
#define SCALE_PRESSURE 60.0
#define SCALE_TEMPERATURE 200.0
#define CRC_POLYNOMIAL 0x31

void sigint_handler(int sig) {
    gpio_i2c_close(I2C_HANDLE);
    fclose(stdout);
    gpioTerminate();
    exit(0);
}

uint8_t crc8(uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if ((crc & 0x80) != 0) {
                crc = (uint8_t)((crc << 1) ^ CRC_POLYNOMIAL);
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    if (gpio_i2c_open(I2C_HANDLE, I2C_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    FILE *logfile = fopen("airflow.log", "w");
    if (logfile == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    while (1) {
        uint8_t command[2] = {COMMAND >> 8, COMMAND & 0xFF};
        gpio_i2c_write_device(I2C_HANDLE, command, 2);
        usleep(45000);

        uint8_t data[9];
        if (gpio_i2c_read_device(I2C_HANDLE, data, 9) != 9) {
            fprintf(stderr, "Failed to read from I2C device\n");
            continue;
        }

        if (crc8(data, 8) != data[8]) {
            fprintf(stderr, "CRC mismatch\n");
            continue;
        }

        int16_t raw_pressure = (data[0] << 8) | data[1];
        int16_t raw_temperature = (data[3] << 8) | data[4];
        double pressure = raw_pressure / SCALE_PRESSURE;
        double temperature = raw_temperature / SCALE_TEMPERATURE;

        time_t now = time(NULL);
        fprintf(logfile, "%ld,%f,%f\n", now, pressure, temperature);
        fflush(logfile);

        if (pressure > 5.0) {
            fprintf(stderr, "Warning: Pressure exceeds 5.0 Pa\n");
        }

        sleep(1);
    }

    return 0;
}

