#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <errno.h>

#define I2C_DEV "/dev/i2c-1"
#define I2C_ADDR 0x4A
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define HYSTERESIS 2

int i2c_fd, gpio_fd;
struct gpiod_chip *chip;
struct gpiod_line *line;

void cleanup(int signum) {
    gpiod_line_set_value(line, 0);
    gpiod_chip_close(chip);
    close(i2c_fd);
    exit(0);
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    if ((i2c_fd = open(I2C_DEV, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire bus access or talk to slave");
        return 1;
    }

    if (!(chip = gpiod_chip_open_by_name(GPIO_CHIP))) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    if (!(line = gpiod_chip_get_line(chip, GPIO_LINE))) {
        perror("Failed to get GPIO line");
        return 1;
    }

    if (gpiod_line_request_output(line, "temp_led", 0) < 0) {
        perror("Failed to set GPIO line as output");
        return 1;
    }

    while (1) {
        unsigned char buf[2];
        short temp;
        float celsius;

        if (read(i2c_fd, buf, 2) != 2) {
            perror("Failed to read from I2C device");
            return 1;
        }

        temp = (buf[0] << 8) | buf[1];
        celsius = (temp >> 4) * 0.0625;

        printf("Temperature: %.2f C\n", celsius);

        if (celsius > 28) {
            gpiod_line_set_value(line, 1);
        } else if (celsius < 27 - HYSTERESIS) {
            gpiod_line_set_value(line, 0);
        }

        sleep(1);
    }

    return 0;
}

