#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>

#define I2C_ADDR 0x44
#define I2C_DEV "/dev/i2c-1"
#define STS40_CMD_SINGLE_SHOT 0x2C, 0xE0
#define STS40_CRC8_POLYNOMIAL 0x31

int fd;

void cleanup(int signum) {
    close(fd);
    closelog();
    exit(0);
}

int main() {
    openlog("sts40_monitor", LOG_PID, LOG_USER);
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    if ((fd = open(I2C_DEV, O_RDWR)) < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %m");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address: %m");
        return 1;
    }

    while (1) {
        if (write(fd, (void*)&STS40_CMD_SINGLE_SHOT, sizeof(STS40_CMD_SINGLE_SHOT)) != sizeof(STS40_CMD_SINGLE_SHOT)) {
            syslog(LOG_ERR, "Failed to write to I2C device: %m");
            return 1;
        }

        usleep(10000); // wait for conversion

        unsigned char data[3];
        if (read(fd, data, sizeof(data)) != sizeof(data)) {
            syslog(LOG_ERR, "Failed to read from I2C device: %m");
            return 1;
        }

        // calculate CRC8
        unsigned char crc = 0;
        for (int i = 0; i < 2; i++) {
            crc ^= data[i];
            for (int j = 0; j < 8; j++) {
                if (crc & 0x80) {
                    crc = (crc << 1) ^ STS40_CRC8_POLYNOMIAL;
                } else {
                    crc <<= 1;
                }
            }
        }

        if (crc != data[2]) {
            syslog(LOG_ERR, "CRC mismatch");
            return 1;
        }

        // convert raw ticks to Celsius
        float temp = -45.0 + 175.0 * ((data[0] << 8) | data[1]) / 65535.0;

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%FT%T%z", timeinfo);

        FILE *logfile = fopen("temperature_log.txt", "a");
        if (logfile == NULL) {
            syslog(LOG_ERR, "Failed to open log file: %m");
            return 1;
        }

        fprintf(logfile, "%s,%.2f\n", timestamp, temp);
        fclose(logfile);

        syslog(LOG_INFO, "Temperature: %.2f C", temp);

        sleep(5);
    }

    return 0;
}

