#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x25
#define COMMAND 0x362F

void sigint_handler(int sig) {
    gpioTerminate();
    fclose(log_file);
    exit(0);
}

uint8_t crc8(uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if ((crc & 0x80) != 0) {
                crc = (uint8_t)((crc << 1) ^ 0x31);
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    signal(SIGINT, sigint_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    int handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    log_file = fopen("sdp810_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    while (1) {
        int result = i2cWriteWordData(handle, COMMAND, 0);
        if (result < 0) {
            fprintf(stderr, "Failed to write to I2C bus\n");
            return 1;
        }

        time_t now = time(NULL);
        sleep(1);

        uint8_t data[9];
        result = i2cReadDevice(handle, data, 9);
        if (result != 9) {
            fprintf(stderr, "Failed to read from I2C bus\n");
            return 1;
        }

        if (crc8(data, 2) != data[2] || crc8(data + 3, 2) != data[5] || crc8(data + 6, 2) != data[8]) {
            fprintf(stderr, "CRC failure\n");
            continue;
        }

        uint32_t raw_pressure = (data[0] << 8) | data[1];
        uint32_t raw_temp = (data[3] << 8) | data[4];
        uint32_t scale_factor = (data[6] << 8) | data[7];

        double pressure_Pa = raw_pressure * scale_factor / 1000.0;
        double temperature_C = -45.0 + 175.0 * raw_temp / 65535.0;

        fprintf(log_file, "%ld,%f,%f\n", now, pressure_Pa, temperature_C);
        fflush(log_file);
    }

    return 0;
}

