#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x63
#define WHO_AM_I_REG 0x08
#define WHO_AM_I_VAL 0x08
#define CALIBRATION_START_REG 0x05
#define CALIBRATION_END_REG 0x08
#define TRIGGER_MEASUREMENT_REG 0x00
#define READ_DATA_REG 0x00
#define MEASUREMENT_DELAY_MS 10

volatile sig_atomic_t stop;

void sigint_handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    int i2c = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    char who_am_i;
    if (i2cReadByteData(i2c, WHO_AM_I_REG) != WHO_AM_I_VAL) {
        fprintf(stderr, "Failed to verify sensor identity\n");
        return 1;
    }

    char calibration[4];
    if (i2cReadI2CBlockData(i2c, CALIBRATION_START_REG, calibration, 4) != 4) {
        fprintf(stderr, "Failed to read calibration coefficients\n");
        return 1;
    }

    FILE *file = fopen("environmental_data.txt", "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file\n");
        return 1;
    }

    while (!stop) {
        if (i2cWriteByteData(i2c, TRIGGER_MEASUREMENT_REG, 0) < 0) {
            fprintf(stderr, "Failed to trigger measurement\n");
            continue;
        }

        time_sleep(MEASUREMENT_DELAY_MS / 1000.0);

        char data[6];
        if (i2cReadI2CBlockData(i2c, READ_DATA_REG, data, 6) != 6) {
            fprintf(stderr, "Failed to read data\n");
            continue;
        }

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, 20, "%Y-%m-%dT%H:%M:%SZ", tm_info);

        float pressure = (data[0] << 8 | data[1]) / 20.0;
        float temperature = (data[3] << 8 | data[4]) / 100.0;

        fprintf(file, "%s, Pressure: %.2f hPa, Temperature: %.2f C\n", timestamp, pressure, temperature);
        fflush(file);

        printf("%s, Pressure: %.2f hPa, Temperature: %.2f C\n", timestamp, pressure, temperature);

        time_sleep(5);
    }

    fclose(file);
    i2cClose(i2c);
    gpioTerminate();

    return 0;
}

