#include <stdio.h>
#include <stdlib.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <unistd.h>
#include <gpiod.h>
#include <signal.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDR 0x63
#define GPIO_LINE 17

int fd;
struct gpiod_chip *chip;
struct gpiod_line *line;

void sigint_handler(int signum) {
    gpiod_line_release(line);
    close(fd);
    exit(0);
}

int main() {
    signal(SIGINT, sigint_handler);

    if ((fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire bus access or talk to slave");
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get line");
        return 1;
    }

    if (gpiod_line_request_output(line, "my-app", 0) < 0) {
        perror("Failed to set line as output");
        return 1;
    }

    while (1) {
        // Read from sensor
        char buf[6];
        if (read(fd, buf, 6) != 6) {
            perror("Failed to read from the i2c bus");
            return 1;
        }

        // Compute pressure and temperature
        int pressure = (buf[0] << 8) | buf[1];
        int temperature = (buf[3] << 8) | buf[4];

        printf("Pressure: %d Pa, Temperature: %d C\n", pressure, temperature);

        // Blink LED
        if (pressure < 95000) {
            gpiod_line_set_value(line, 1);
            usleep(500000);
            gpiod_line_set_value(line, 0);
            usleep(500000);
        } else {
            gpiod_line_set_value(line, 1);
            usleep(100000);
            gpiod_line_set_value(line, 0);
            usleep(100000);
        }

        usleep(1000000);
    }

    return 0;
}

