#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TMP102_ADDR 0x48
#define TMP102_TEMP_REG 0x00

volatile sig_atomic_t stop;

void sigint_handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", gpioErrorText(errno));
        return 1;
    }

    signal(SIGINT, sigint_handler);

    int handle = i2cOpen(1, TMP102_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C handle: %s\n", gpioErrorText(errno));
        gpioTerminate();
        return 1;
    }

    FILE *file = fopen("temperature_log.csv", "w");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file: %s\n", strerror(errno));
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    while (!stop) {
        char buf[2];
        buf[0] = TMP102_TEMP_REG;
        if (i2cWriteI2CBlockData(handle, TMP102_ADDR, buf, 1) < 0) {
            fprintf(stderr, "Failed to write to I2C: %s\n", gpioErrorText(errno));
            continue;
        }

        if (i2cReadI2CBlockData(handle, TMP102_ADDR, buf, 2) < 0) {
            fprintf(stderr, "Failed to read from I2C: %s\n", gpioErrorText(errno));
            continue;
        }

        uint16_t raw_temp = (buf[0] << 8) | buf[1];
        float temp = ((raw_temp >> 4) * 0.0625);

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%F %T", timeinfo);

        fprintf(file, "%s,%.2f\n", timestamp, temp);
        fflush(file);

        sleep(5);
    }

    fclose(file);
    i2cClose(handle);
    gpioTerminate();

    return 0;
}

