#define HUMID_REG 0x02
#define MEASUREMENT_CONFIG_BIT 0x80
#define CONFIG_DATA 0x00
#define MAX_RETRIES 5

volatile sig_atomic_t stop;

void sigint_handler(int signum) {
    stop = 1;
}

int main() {
    int i2cHandle;
    unsigned char data[2];
    unsigned int rawTemp, rawHumid;
    double temp, humid;
    int retries;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    i2cHandle = i2cOpen(1, HDC2010_ADDR, 0);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (!stop) {
        retries = 0;
        while (1) {
            if (i2cWriteByte(i2cHandle, MEASUREMENT_CONFIG_REG) < 0) {
                fprintf(stderr, "Failed to write to MEASUREMENT_CONFIG_REG\n");
                return 1;
            }

            gpioDelay(100000);  // Wait for measurement to complete

            if (i2cReadByteData(i2cHandle, MEASUREMENT_CONFIG_REG) & MEASUREMENT_CONFIG_BIT) {
                if (++retries > MAX_RETRIES) {
                    fprintf(stderr, "Failed to measure after %d retries\n", MAX_RETRIES);
                    return 1;
                }
                continue;
            }

            break;
        }

        if (i2cWriteByte(i2cHandle, TEMP_REG) < 0) {
            fprintf(stderr, "Failed to write to TEMP_REG\n");
            return 1;
        }

        if (i2cReadWordData(i2cHandle, TEMP_REG, data) < 0) {
            fprintf(stderr, "Failed to read from TEMP_REG\n");
            return 1;
        }

        rawTemp = (data[0] << 8) | data[1];
        temp = rawTemp / 65536.0 * 165.0 - 40.0;

        if (i2cWriteByte(i2cHandle, HUMID_REG) < 0) {
            fprintf(stderr, "Failed to write to HUMID_REG\n");
            return 1;
        }

        if (i2cReadWordData(i2cHandle, HUMID_REG, data) < 0) {
            fprintf(stderr, "Failed to read from HUMID_REG\n");
            return 1;
        }

        rawHumid = (data[0] << 8) | data[1];
        humid = rawHumid / 65536.0 * 100.0;

        printf("Temperature: %.2f°C, Humidity: %.2f%%\n", temp, humid);

        gpioDelay(5000000);  // Wait for 5 seconds
    }

    i2cClose(i2cHandle);
    gpioTerminate();

    return 0;
}

