#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_HANDLE 1
#define I2C_ADDR 0x25
#define COMMAND 0x362F

void sigint_handler(int sig) {
    gpioTerminate();
    exit(0);
}

char crc8(char *data, int len) {
    char crc = 0xFF;
    char polynomial = 0x31;
    int i, j;

    for (i = 0; i < len; i++) {
        crc ^= data[i];
        for (j = 0; j < 8; j++) {
            if ((crc & 0x80) != 0) {
                crc = (char)((crc << 1) ^ polynomial);
            } else {
                crc <<= 1;
            }
        }
    }

    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    int i2c = i2cOpen(I2C_HANDLE, I2C_ADDR);
    if (i2c < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    while (1) {
        char command[2] = {(char)(COMMAND >> 8), (char)(COMMAND & 0xFF)};
        if (i2cWriteDevice(i2c, command, 2) < 0) {
            fprintf(stderr, "Failed to write to I2C bus\n");
            break;
        }

        gpioDelay(100000);  // Wait for 45 ms

        char data[6];
        if (i2cReadDevice(i2c, data, 6) < 0) {
            fprintf(stderr, "Failed to read from I2C bus\n");
            break;
        }

        char crc = crc8(data, 4);
        if (crc != data[4]) {
            fprintf(stderr, "CRC check failed\n");
            continue;
        }

        unsigned short pressure = (data[0] << 8) | data[1];
        unsigned short temperature = (data[3] << 8) | data[4];

        printf("Pressure: %u, Temperature: %u\n", pressure, temperature);

        gpioDelay(500000);  // Wait for 500 ms
    }

    i2cClose(i2c);
    gpioTerminate();

    return 0;
}

