#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define AHT20_ADDR 0x38
#define RELAY_GPIO 17
#define RETRY_DELAY 10000 // in microseconds
#define POLL_INTERVAL 5000 // in milliseconds

int i2c_fd;
struct gpiod_chip *chip;
struct gpiod_line *line;

void cleanup(int signum) {
    gpiod_line_release(line);
    close(i2c_fd);
    exit(0);
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        perror("Failed to acquire bus access or talk to slave");
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    line = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (!line) {
        perror("Failed to get GPIO line");
        return 1;
    }

    gpiod_line_request_output(line, "relay", 0);

    while (1) {
        uint8_t cmd[] = {0xAC, 0x33, 0x00};
        if (write(i2c_fd, cmd, sizeof(cmd)) != sizeof(cmd)) {
            perror("Failed to write to I2C device");
            return 1;
        }

        usleep(80000); // wait 80 ms

        uint8_t data[6];
        if (read(i2c_fd, data, sizeof(data)) != sizeof(data)) {
            perror("Failed to read from I2C device");
            return 1;
        }

        if ((data[0] & 0x80) == 0 || (data[0] & 0x60) != 0) {
            fprintf(stderr, "Invalid sensor status byte: 0x%02x\n", data[0]);
            continue;
        }

        float humidity = ((data[1] << 16) | (data[2] << 8) | data[3]) * 100.0 / 0x100000000;
        printf("%ld: Humidity: %.2f%%\n", time(NULL), humidity);

        if (humidity > 60.0) {
            gpiod_line_set_value(line, 1);
        } else if (humidity < 55.0) {
            gpiod_line_set_value(line, 0);
        }

        usleep(POLL_INTERVAL * 1000);
    }

    return 0;
}

