#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>

#define I2C_DEV "/dev/i2c-1"
#define GPIO_CHIP "gpiochip4"
#define GPIO_LINE 17
#define I2C_ADDR_TMP117 0x48
#define I2C_ADDR_AHT20 0x38
#define TMP117_TEMP_REG 0x00
#define AHT20_INIT_CMD {0xBE, 0x08, 0x00}
#define AHT20_MEASURE_CMD {0xAC, 0x33, 0x00}
#define RETRY_COUNT 3
#define BACKOFF_TIME 10000 // in microseconds

int fd_i2c;
struct gpiod_chip *chip;
struct gpiod_line *line;

void cleanup(int signum) {
    close(fd_i2c);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    exit(0);
}

int i2c_read(int addr, int reg, int len, char *data) {
    int ret;
    for (int i = 0; i < RETRY_COUNT; i++) {
        char buf[2] = {reg, len};
        if (write(fd_i2c, buf, 2) != 2) {
            perror("Failed to write to the i2c bus");
            return -1;
        }
        usleep(BACKOFF_TIME);
        if ((ret = read(fd_i2c, data, len)) != len) {
            perror("Failed to read from the i2c bus");
            return -1;
        }
        if (data[0] & 0x80) {
            usleep(BACKOFF_TIME);
            continue;
        }
        return ret;
    }
    return -1;
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    if ((fd_i2c = open(I2C_DEV, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return 1;
    }

    if (ioctl(fd_i2c, I2C_SLAVE, I2C_ADDR_TMP117) < 0) {
        perror("Failed to acquire the i2c bus access");
        return 1;
    }

    if ((chip = gpiod_chip_open_by_name(GPIO_CHIP)) == NULL) {
        perror("Failed to open gpiochip");
        return 1;
    }

    if ((line = gpiod_chip_get_line(chip, GPIO_LINE)) == NULL) {
        perror("Failed to get gpio line");
        return 1;
    }

    if (gpiod_line_request_input(line, "motion_detect") < 0) {
        perror("Failed to request gpio line");
        return 1;
    }

    // Check sensor presence
    char data[3] = AHT20_INIT_CMD;
    if (i2c_write(I2C_ADDR_AHT20, data, 3) < 0) {
        fprintf(stderr, "AHT20 sensor not found\n");
    } else {
        fprintf(stderr, "AHT20 sensor found\n");
    }

    // Check sensor presence
    if (i2c_read(I2C_ADDR_TMP117, TMP117_TEMP_REG, 2, data) < 0) {
        fprintf(stderr, "TMP117 sensor not found\n");
    } else {
        fprintf(stderr, "TMP117 sensor found\n");
    }

    // Main loop
    while (1) {
        // Get temperature from TMP117
        if (i2c_read(I2C_ADDR_TMP117, TMP117_TEMP_REG, 2, data) < 0) {
            fprintf(stderr, "Failed to read temperature\n");
        } else {
            int16_t temp = (data[0] << 8) | data[1];
            float temp_c = temp * 0.0078125;
            printf("Temperature: %.2f C\n", temp_c);
        }

        // Get humidity and temperature from AHT20
        data[0] = AHT20_MEASURE_CMD[0];
        if (i2c_write(I2C_ADDR_AHT20, data, 1) < 0) {
            fprintf(stderr, "Failed to start measurement\n");
        } else {
            usleep(80000);  // Wait for measurement to complete
            if (i2c_read(I2C_ADDR_AHT20, 0, 7, data) < 0) {
                fprintf(stderr, "Failed to read measurement\n");
            } else {
                uint32_t raw_humidity = (data[1] << 16) | (data[2] << 8) | data[3];
                uint32_t raw_temp = (data[4] << 16) | (data[5] << 8) | data[6];
                float humidity = raw_humidity / 1048576.0 * 100.0;
                float temp_c = raw_temp / 1048576.0 * 200.0 - 50.0;
                printf("Humidity: %.2f %% Temperature: %.2f C\n", humidity, temp_c);
            }
        }

        // Check motion
        int value = gpiod_line_get_value(line);
        printf("Motion detected: %s\n", value ? "yes" : "no");

        sleep(1);
    }

    return 0;
}

