#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define RED_PIN 17
#define GREEN_PIN 22
#define BLUE_PIN 27

void handle_signal(int signum) {
    gpioWrite(RED_PIN, 0);
    gpioWrite(GREEN_PIN, 0);
    gpioWrite(BLUE_PIN, 0);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    while (1) {
        FILE* file = fopen("/proc/stat", "r");
        unsigned long total1, idle1, total2, idle2;
        unsigned long user, nice, system, idle, iowait, irq, softirq, steal;

        fscanf(file, "cpu %lu %lu %lu %lu %lu %lu %lu %lu %lu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &idle2);
        fclose(file);

        total1 = user + nice + system + idle + iowait + irq + softirq + steal;
        idle1 = idle + iowait;

        sleep(1);

        file = fopen("/proc/stat", "r");
        fscanf(file, "cpu %lu %lu %lu %lu %lu %lu %lu %lu %lu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &idle2);
        fclose(file);

        total2 = user + nice + system + idle + iowait + irq + softirq + steal;
        idle2 = idle + iowait;

        unsigned long totald = total2 - total1;
        unsigned long idled = idle2 - idle1;
        unsigned long cpu_load = (totald - idled) * 100 / totald;

        unsigned int red = 0, green = 0, blue = 0;

        if (cpu_load < 50) {
            green = 255;
        } else if (cpu_load < 100) {
            red = 255;
            green = 255;
        } else {
            red = 255;
        }

        gpioPWM(RED_PIN, red);
        gpioPWM(GREEN_PIN, green);
        gpioPWM(BLUE_PIN, blue);

        sleep(500);
    }

    return 0;
}

