#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SPI_MODE 0

#define GPIO_FAN 18
#define GPIO_TEMP 8

#define BUFFER_SIZE 20

typedef struct {
    time_t timestamp;
    int temperature;
    int pwm_duty;
} buffer_entry;

buffer_entry buffer[BUFFER_SIZE];
int buffer_index = 0;

void sigint_handler(int signum) {
    int i;

    gpioPWM(GPIO_FAN, 0);
    spiClose(SPI_CHANNEL);
    gpioTerminate();

    for (i = 0; i < buffer_index; i++) {
        printf("%ld, %d, %d\n", buffer[i].timestamp, buffer[i].temperature, buffer[i].pwm_duty);
    }

    exit(0);
}

int main() {
    int spiHandle, pwmDuty;
    char data[4];
    time_t timestamp;
    int temperature, i;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    spiHandle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spiHandle < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        return 1;
    }

    gpioSetMode(GPIO_FAN, PI_OUTPUT);
    gpioPWM(GPIO_FAN, 0);

    while (1) {
        if (spiXfer(spiHandle, data) < 0) {
            fprintf(stderr, "SPI transfer error\n");
            continue;
        }

        if ((data[3] & 0x01) != 0) {
            fprintf(stderr, "MAX31855 fault\n");
            continue;
        }

        temperature = ((data[0] << 4) | (data[1] >> 4)) * 0.25;

        if (temperature < 25) {
            pwmDuty = 0;
        } else if (temperature < 40) {
            pwmDuty = (temperature - 25) * 5.1;
        } else if (temperature < 60) {
            pwmDuty = (temperature - 40) * 3.5 + 50;
        } else {
            pwmDuty = 100;
        }

        gpioPWM(GPIO_FAN, pwmDuty * 1024 / 256);

        timestamp = time(NULL);

        buffer[buffer_index].timestamp = timestamp;
        buffer[buffer_index].temperature = temperature;
        buffer[buffer_index].pwm_duty = pwmDuty;

        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        sleep(1);
    }

    return 0;
}

