#include <pigpio.h>
#include <bmp180.h>

#define GPIO_PIN 2
#define I2C_BUS 1
#define I2C_ADDR 0x77

FILE *file;
bmp180_t bmp180;

void sigint_handler(int sig) {
    fclose(file);
    bmp180_delete(&bmp180);
    gpioTerminate();
    exit(0);
}

void alert_handler(int gpio, int level, uint32_t tick) {
    if (level == 0) {
        return;
    }

    int32_t temperature, pressure;
    bmp180_read(&bmp180, &pressure, &temperature);

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(file, "%s,%d,%d\n", timestamp, temperature, pressure);
    fflush(file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (bmp180_new(&bmp180, I2C_BUS, I2C_ADDR) < 0) {
        fprintf(stderr, "bmp180 initialization failed\n");
        return 1;
    }

    if ((file = fopen("altitude_log.txt", "w")) == NULL) {
        fprintf(stderr, "failed to open file\n");
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "failed to set GPIO mode\n");
        return 1;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "failed to set GPIO pull up/down\n");
        return 1;
    }

    if (gpioSetAlertFunc(GPIO_PIN, alert_handler) < 0) {
        fprintf(stderr, "failed to set GPIO alert function\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        sleep(1);
    }

    return 0;
}

