#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x77
#define TIMER_INTERVAL 50 // in ms
#define BUFFER_SIZE 600 // in 50ms intervals
#define GPIO_ALERT 24
#define PRESSURE_THRESHOLD 5 // in hPa

static volatile int running = 1;
static volatile int buffer_index = 0;
static volatile int buffer[BUFFER_SIZE];

void sigintHandler(int sig) {
    running = 0;
}

void alertFunc(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        fprintf(stderr, "Alert: Pressure deviates by more than %d hPa from the rolling average\n", PRESSURE_THRESHOLD);
    }
}

void timerFunc(int id, int level, uint32_t tick) {
    int pressure;
    int average;
    int i;

    // Read pressure
    if (i2cReadByteData(I2C_BUS, 0xF6) < 0) {
        fprintf(stderr, "Error reading pressure\n");
        return;
    }
    pressure = i2cReadByteData(I2C_BUS, 0xF6) << 8;
    if (i2cReadByteData(I2C_BUS, 0xF7) < 0) {
        fprintf(stderr, "Error reading pressure\n");
        return;
    }
    pressure |= i2cReadByteData(I2C_BUS, 0xF7);

    // Calculate rolling average
    average = 0;
    for (i = 0; i < BUFFER_SIZE; i++) {
        average += buffer[i];
    }
    average /= BUFFER_SIZE;

    // Check if pressure deviates by more than threshold from average
    if (abs(pressure - average) > PRESSURE_THRESHOLD) {
        gpioWrite(GPIO_ALERT, 1);
    } else {
        gpioWrite(GPIO_ALERT, 0);
    }

    // Add new pressure to buffer and remove oldest
    buffer[buffer_index++] = pressure;
    if (buffer_index >= BUFFER_SIZE) {
        buffer_index = 0;
    }
}

int main(int argc, char *argv[]) {
    int i2c;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    i2c = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Set up alert GPIO
    gpioSetMode(GPIO_ALERT, PI_OUTPUT);
    gpioWrite(GPIO_ALERT, 0);

    // Set up timer
    gpioSetTimerFuncEx(TIMER_INTERVAL, 0, timerFunc, NULL);

    // Set up signal handler for SIGINT
    signal(SIGINT, sigintHandler);

    // Main loop
    while (running) {
        sleep(1);
    }

    // Clean up
    gpioSetTimerFuncEx(TIMER_INTERVAL, 0, NULL, NULL);
    gpioWrite(GPIO_ALERT, 0);
    i2cClose(i2c);
    gpioTerminate();

    return 0;
}

