#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define GPIO_PIN 18
#define PWM_FREQ 25000
#define MIN_TEMP 40
#define MAX_TEMP 70
#define MIN_DUTY 0
#define MAX_DUTY 255

FILE *log_file;

void handle_sigint(int sig) {
    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
    fclose(log_file);
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    if ((log_file = fopen("fan_log.txt", "w")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(GPIO_PIN, PWM_FREQ);

    while (1) {
        FILE *temp_file;
        double temp;
        char line[256];

        if ((temp_file = fopen("/sys/class/thermal/thermal_zone0/temp", "r")) == NULL) {
            fprintf(stderr, "Failed to open temperature file\n");
            return 1;
        }

        if (fgets(line, sizeof(line), temp_file) == NULL) {
            fprintf(stderr, "Failed to read temperature\n");
            return 1;
        }

        fclose(temp_file);

        temp = atof(line) / 1000;

        if (temp < MIN_TEMP) temp = MIN_TEMP;
        if (temp > MAX_TEMP) temp = MAX_TEMP;

        int duty = MIN_DUTY + (temp - MIN_TEMP) * (MAX_DUTY - MIN_DUTY) / (MAX_TEMP - MIN_TEMP);

        gpioPWM(GPIO_PIN, duty);

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s, Temp: %.1f, Duty: %d\n", timestamp, temp, duty);
        fflush(log_file);

        sleep(5);
    }

    return 0;
}

