#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <jansson.h>

#define GPIO_HEATER 18
#define SPI_DEVICE "/dev/spidev0.0"
#define MAX31865_CONFIG 0xC1
#define MAX31865_RTD_MSB 0x01
#define MAX31865_RTD_LSB 0x02
#define MAX31865_FAULT_STATUS 0x07
#define R_REF 430.0
#define R_RTD_NOMINAL 100.0
#define T_CRITICAL 80.0

int spi_fd;
double Kp, Ki, Kd;

void handle_signal(int signum) {
    gpioHardwarePWM(GPIO_HEATER, 0, 0);
    close(spi_fd);
    pigpio_stop();
    exit(EXIT_FAILURE);
}

double read_temperature() {
    uint16_t rtd_code;
    char buffer[2];

    buffer[0] = MAX31865_RTD_MSB;
    buffer[1] = MAX31865_RTD_LSB;
    if (write(spi_fd, buffer, 2) != 2) {
        perror("Failed to write to SPI device");
        exit(EXIT_FAILURE);
    }
    if (read(spi_fd, buffer, 2) != 2) {
        perror("Failed to read from SPI device");
        exit(EXIT_FAILURE);
    }
    rtd_code = (buffer[0] << 8) | buffer[1];
    if (rtd_code & 0x1) {
        perror("MAX31865 fault detected");
        exit(EXIT_FAILURE);
    }
    return (rtd_code / 32768.0) * R_REF;
}

int main() {
    json_error_t error;
    json_t *config;
    double target_temp, temp, error_sum, last_error, duty_cycle;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return EXIT_FAILURE;
    }
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    config = json_load_file("config.json", 0, &error);
    if (!config) {
        fprintf(stderr, "Failed to load config file: %s\n", error.text);
        return EXIT_FAILURE;
    }
    target_temp = json_number_value(json_object_get(config, "target"));
    Kp = json_number_value(json_object_get(config, "Kp"));
    Ki = json_number_value(json_object_get(config, "Ki"));
    Kd = json_number_value(json_object_get(config, "Kd"));
    json_decref(config);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }
    if (ioctl(spi_fd, SPI_MODE_1, 500000) < 0) {
        perror("Failed to set SPI mode");
        return EXIT_FAILURE;
    }
    if (write(spi_fd, &MAX31865_CONFIG, 1) != 1) {
        perror("Failed to write to SPI device");
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_HEATER, PI_OUTPUT);
    error_sum = 0;
    last_error = 0;
    while (1) {
        temp = read_temperature();
        if (temp > T_CRITICAL) {
            gpioHardwarePWM(GPIO_HEATER, 0, 0);
            exit(EXIT_FAILURE);
        }
        duty_cycle = Kp * (target_temp - temp) + Ki * error_sum + Kd * (temp - last_error);
        if (duty_cycle < 0) duty_cycle = 0;
        if (duty_cycle > 1000) duty_cycle = 1000;
        gpioHardwarePWM(GPIO_HEATER, 1000, duty_cycle * 1000);
        error_sum += target_temp - temp;
        last_error = temp - target_temp;
        usleep(100000);
    }
    return EXIT_SUCCESS;
}

