void toggleLogging(int gpio, int level, uint32_t tick) {
    static uint32_t lastDebounce = 0;
    if ((tick - lastDebounce) > DEBOUNCE_TIME) {
        lastDebounce = tick;
        if (level == PI_LOW) {
            if (data.status == STATUS_OK) {
                bmp180GetPressure(&data, &calibration);
                fprintf(file, "%lu,%f\n", data.utcTime, data.pressure);
                gpioDelay(2000000); // 2 seconds delay
            }
        }
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (bmp180Open(I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to open BMP180 sensor\n");
        return 1;
    }

    if (bmp180GetCalibrationData(&calibration) < 0) {
        fprintf(stderr, "Failed to get BMP180 calibration data\n");
        return 1;
    }

    file = fopen(FILE_NAME, "w");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);
    gpioSetAlertFunc(GPIO_PIN, toggleLogging);

    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    while (1) {
        gpioDelay(1000000); // 1 second delay
    }

    return 0;
}

