#include <pigpio.h>
#include <curl/curl.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define DHT_PIN 4
#define DHT_TYPE 22
#define SERVER_URL "http://yourserver.com/api/humidity"

void post_data(float humidity, float temperature) {
    CURL *curl;
    CURLcode res;
    char post_data[100];

    sprintf(post_data, "{\"humidity\": %.2f, \"temperature\": %.2f}", humidity, temperature);

    curl_global_init(CURL_GLOBAL_DEFAULT);

    curl = curl_easy_init();
    if(curl) {
        curl_easy_setopt(curl, CURLOPT_URL, SERVER_URL);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, post_data);

        res = curl_easy_perform(curl);

        if(res != CURLE_OK)
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));

        curl_easy_cleanup(curl);
    }

    curl_global_cleanup();
}

void signal_handler(int signum) {
    gpioTerminate();
    exit(0);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    gpioSetMode(DHT_PIN, PI_INPUT);

    for(int retry = 0; retry < 3; retry++) {
        gpioWrite(DHT_PIN, PI_LOW);
        gpioDelay(1000);

        gpioSetMode(DHT_PIN, PI_OUTPUT);
        gpioDelay(20);
        gpioWrite(DHT_PIN, PI_HIGH);
        gpioDelay(40);
        gpioSetMode(DHT_PIN, PI_INPUT);

        gpioDelay(1);

        int data[41] = {0};
        for(int i = 0; i < 40; i++) {
            gpioDelay(50);
            data[i] = gpioRead(DHT_PIN);
        }

        int checksum = data[40];
        int calculated_checksum = data[0] + data[1] + data[2] + data[3] + data[4];

        if (checksum == calculated_checksum) {
            float humidity = data[0] * 256 + data[1];
            humidity /= 10;

            float temperature = (data[2] & 0x7F) * 256 + data[3];
            temperature /= 10;

            if (data[2] & 0x80)
                temperature *= -1;

            post_data(humidity, temperature);
            break;
        } else {
            fprintf(stderr, "Checksum error\n");
        }
    }

    gpioTerminate();
    return 0;
}

