#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define BMP180_ADDR 0x77
#define GPIO_PIN 4
#define OSS 3
#define DELAY 26

volatile sig_atomic_t stop;

void sigint_handler(int signum) {
    stop = 1;
}

void button_callback(int gpio, int level, uint32_t tick) {
    static uint32_t last_tick = 0;
    if (level == PI_LOW && tick - last_tick > 200000) {
        last_tick = tick;
        if (gpioRead(GPIO_PIN)) {
            printf("Logging enabled\n");
        } else {
            printf("Logging disabled\n");
        }
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);
    gpioSetISRFunc(GPIO_PIN, PI_FALLING_EDGE, 0, button_callback);

    int handle = i2cOpen(1, BMP180_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C handle: %d\n", handle);
        return 1;
    }

    // Read calibration coefficients
    uint16_t coefficients[11];
    for (int i = 0; i < 11; i++) {
        int result = i2cReadWordData(handle, 0xAA + i * 2);
        if (result < 0) {
            fprintf(stderr, "Failed to read calibration coefficient: %d\n", result);
            return 1;
        }
        coefficients[i] = (uint16_t)result;
    }

    // Validate coefficients
    if (coefficients[0] == 0xFFFF) {
        fprintf(stderr, "Invalid calibration coefficients\n");
        return 1;
    }

    // Main loop
    while (!stop) {
        if (gpioRead(GPIO_PIN)) {
            // Read pressure
            int result = i2cWriteByte(handle, 0xF4, 0x2E);
            if (result < 0) {
                fprintf(stderr, "Failed to start pressure measurement: %d\n", result);
                return 1;
            }
            gpioDelay(DELAY * 1000);
            result = i2cReadWordData(handle, 0xF6);
            if (result < 0) {
                fprintf(stderr, "Failed to read pressure: %d\n", result);
                return 1;
            }
            int pressure = (result & 0xFFF) >> (8 - OSS);
            // TODO: Implement BMP180 compensation algorithm
            printf("Pressure: %d hPa\n", pressure);
            FILE *file = fopen("pressure_log.txt", "a");
            if (file != NULL) {
                time_t now = time(NULL);
                fprintf(file, "%ld %d\n", now, pressure);
                fclose(file);
            }
        }
        gpioDelay(2000000);
    }

    i2cClose(handle);
    gpioTerminate();
    return 0;
}

