#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <max31855.h>

#define GPIO_HEATER 18
#define GPIO_SPI_CLK 11
#define GPIO_SPI_CS 8
#define GPIO_SPI_DO 9

#define Kp 1.0
#define Ki 0.1
#define Kd 0.01
#define target 50.0

void sigint_handler(int sig);
void update_heater(double temp, double dt);
double read_temp();

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (spiOpen(0, 500000) < 0) {
        fprintf(stderr, "Failed to open SPI\n");
        return 1;
    }

    if (gpioHardwarePWM(GPIO_HEATER, 1000, 0) < 0) {
        fprintf(stderr, "Failed to initialize heater\n");
        return 1;
    }

    while (1) {
        double temp = read_temp();
        if (temp < 0) {
            // Handle error
            continue;
        }

        // Calculate time difference
        static double last_time = 0;
        double dt = time(NULL) - last_time;
        last_time = time(NULL);

        update_heater(temp, dt);

        // Log data
        FILE *log_file = fopen("heater_log.txt", "a");
        if (log_file != NULL) {
            fprintf(log_file, "Temperature: %.2f, PWM: %d, PID: %.2f\n", temp, gpioGetPWMdutycycle(GPIO_HEATER), Kp * temp + Ki * temp * dt + Kd * (temp - last_temp) / dt);
            fclose(log_file);
        }

        sleep(1);
    }

    return 0;
}

void sigint_handler(int sig) {
    gpioHardwarePWM(GPIO_HEATER, 0, 0);
    spiClose(0);
    gpioTerminate();
    exit(0);
}

void update_heater(double temp, double dt) {
    static double last_temp = 0;
    double error = target - temp;
    double output = Kp * error + Ki * error * dt + Kd * (error - last_temp) / dt;
    if (output < 0) output = 0;
    if (output > 100) output = 100;
    gpioHardwarePWM(GPIO_HEATER, 1000, (int)(output * 10000));
    last_temp = temp;
}

double read_temp() {
    uint8_t data[4];
    if (spiXfer(0, data, 4) < 0) {
        fprintf(stderr, "Failed to read temperature\n");
        return -1;
    }

    // Parse data
    uint16_t raw_temp = (data[0] << 4) | (data[1] >> 4);
    uint16_t raw_ref = (data[2] << 4) | (data[3] >> 4);
    if ((raw_temp & 0x0001) || (raw_ref & 0x0001)) {
        fprintf(stderr, "Thermocouple fault\n");
        return -1;
    }

    // Convert to Celsius
    double temp = raw_temp * 0.0625;
    return temp;
}

