        // Log flow rates
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char time_str[20];
        strftime(time_str, 20, "%Y-%m-%d %H:%M:%S", tm_info);
        fprintf(file, "%s,%.2f,%.2f\n", time_str, flow1, flow2);
        fflush(file);

        // Sleep for 1 second
        time_sleep(1);
    }

