#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x39
#define FIFO_REG 0x60
#define GPIO_LINE 17
#define THRESHOLD 2000
#define LOG_FILE "adpd144ri_log.txt"

int i2c_fd, gpio_fd;
struct gpiod_chip *chip;
struct gpiod_line *line;
FILE *log_file;

void cleanup(int signum) {
    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2c_fd);
    exit(0);
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Open I2C bus
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return 1;
    }

    // Open GPIO chip
    if ((chip = gpiod_chip_open_by_name("gpiochip0")) == NULL) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Get GPIO line
    if ((line = gpiod_chip_get_line(chip, GPIO_LINE)) == NULL) {
        perror("Failed to get GPIO line");
        return 1;
    }

    // Open log file
    if ((log_file = fopen(LOG_FILE, "w")) == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    // Main loop
    while (1) {
        uint16_t ir_reading;
        time_t now = time(NULL);

        // Read IR data
        if (write(i2c_fd, &FIFO_REG, 1) != 1) {
            perror("Failed to write to I2C");
            return 1;
        }
        if (read(i2c_fd, &ir_reading, 2) != 2) {
            perror("Failed to read from I2C");
            return 1;
        }

        // Log reading
        fprintf(log_file, "%ld,%d\n", now, ir_reading);
        fflush(log_file);

        // Trigger LED if necessary
        if (ir_reading > THRESHOLD) {
            gpiod_line_set_value(line, 1);
        } else {
            gpiod_line_set_value(line, 0);
        }

        // Sleep for 100 ms
        usleep(100000);
    }

    return 0;
}

