#include <pigpio.h>
#include <pthread.h>
#include <signal.h>
#include <stdio.h>
#include <time.h>

#define GPIO_PIN 18
#define RPM_LOG_FILE "rpm_log.txt"

volatile sig_atomic_t stop;
pthread_mutex_t count_mutex;
unsigned long pulse_count;

void countPulse(int gpio, int level, uint32_t tick) {
    if (level == PI_ON) {
        pthread_mutex_lock(&count_mutex);
        pulse_count++;
        pthread_mutex_unlock(&count_mutex);
    }
}

void signalHandler(int signum) {
    stop = 1;
    gpioSetWatchdog(GPIO_PIN, 0);
    pthread_mutex_destroy(&count_mutex);
    fclose(fopen(RPM_LOG_FILE, "w"));
    gpioTerminate();
    exit(0);
}

int main() {
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    if (pthread_mutex_init(&count_mutex, NULL) != 0) {
        fprintf(stderr, "Failed to initialize mutex\n");
        return 1;
    }

    FILE *logFile = fopen(RPM_LOG_FILE, "a");
    if (logFile == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);
    gpioSetISRFunc(GPIO_PIN, EITHER_EDGE, 1000, countPulse);

    while (!stop) {
        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        pthread_mutex_lock(&count_mutex);
        double rpm = (double)pulse_count * 60 / 1;
        fprintf(logFile, "%s, %.2f RPM\n", timestamp, rpm);
        fflush(logFile);
        pulse_count = 0;
        pthread_mutex_unlock(&count_mutex);

        sleep(1);
    }

    fclose(logFile);
    pthread_mutex_destroy(&count_mutex);
    gpioTerminate();
    return 0;
}

