#define I2C_ADDR 0x39
#define PART_ID_REG 0x00
#define FIFO_DATA_REG 0x10
#define GPIO_LINE 17
#define IR_THRESHOLD 2000
#define DELAY_MS 100

int i2c_fd;
struct gpiod_chip *chip;
struct gpiod_line *line;
FILE *log_file;

void cleanup(int signum) {
    fclose(log_file);
    close(i2c_fd);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    exit(0);
}

