    gpiod_line_request_output(line, "adpd144ri", 0);

    while (1) {
        uint8_t part_id;
        uint16_t ir_data;

        if (read(i2c_fd, &part_id, 1) != 1 || part_id != 0x10) {
            perror("Failed to read PART_ID register");
            return 1;
        }

        if (read(i2c_fd, &ir_data, 2) != 2) {
            perror("Failed to read FIFO_DATA register");
            return 1;
        }

        time_t now = time(NULL);
        fprintf(log_file, "%ld,%d\n", now, ir_data);
        fflush(log_file);

        if (ir_data > IR_THRESHOLD) {
            gpiod_line_set_value(line, 1);
        } else {
            gpiod_line_set_value(line, 0);
        }

        usleep(DELAY_MS * 1000);
    }

    return 0;
}

