#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>

#define I2C_HANDLE 1
#define I2C_ADDR 0x36
#define COMMAND 0x3608
#define CRC_POLY 0x31
#define CRC_INIT 0xFF

void sigint_handler(int sig) {
    gpio_i2c_close(I2C_HANDLE);
    fflush(stdout);
    fclose(stdout);
    exit(0);
}

char crc8(char *data, int len) {
    char crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if ((crc & 0x80) != 0) {
                crc = (crc << 1) ^ CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    signal(SIGINT, sigint_handler);

    if (gpio_i2c_open(I2C_HANDLE, 1, 0) < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (gpio_i2c_write_byte(I2C_HANDLE, I2C_ADDR, COMMAND) < 0) {
        perror("Failed to write to I2C device");
        return 1;
    }

    FILE *log_file = fopen("flow_log.csv", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    while (1) {
        char buffer[3];
        if (gpio_i2c_read_i2c_block_data(I2C_HANDLE, I2C_ADDR, buffer, 3) < 0) {
            perror("Failed to read from I2C device");
            continue;
        }

        if (crc8(buffer, 2) != buffer[2]) {
            fprintf(stderr, "CRC check failed\n");
            continue;
        }

        short flow_raw = (buffer[0] << 8) | buffer[1];
        float flow_rate = (float)flow_raw / 1000.0;

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char time_str[20];
        strftime(time_str, 20, "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s,%f\n", time_str, flow_rate);
        fflush(log_file);

        usleep(1000000);
    }

    return 0;
}

