#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_NUMBER 17
#define GPIO_CONSUMER_NAME "ttp223_tamper"
#define TIMEOUT_SECONDS 5

struct gpiod_chip *chip;
struct gpiod_line *line;
struct timespec last_touch_time;

void cleanup(void) {
    gpiod_line_release(line);
    gpiod_chip_close(chip);
}

void signal_handler(int signum) {
    printf("Exiting on signal %d\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

int main(void) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        perror("Failed to open gpiochip");
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_NUMBER);
    if (line == NULL) {
        perror("Failed to get line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    int ret = gpiod_line_request_input(line, GPIO_CONSUMER_NAME);
    if (ret < 0) {
        perror("Failed to request line as input");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    clock_gettime(CLOCK_MONOTONIC, &last_touch_time);

    while (1) {
        usleep(100000); // sleep for 100 ms

        int value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("Failed to read line value");
            cleanup();
            exit(EXIT_FAILURE);
        }

        if (value == 1) {
            clock_gettime(CLOCK_MONOTONIC, &last_touch_time);
        } else {
            struct timespec current_time;
            clock_gettime(CLOCK_MONOTONIC, &current_time);

            long elapsed_seconds = current_time.tv_sec - last_touch_time.tv_sec;
            if (elapsed_seconds >= TIMEOUT_SECONDS) {
                printf("Intrusion detected\n");
                clock_gettime(CLOCK_MONOTONIC, &last_touch_time);
            }
        }
    }

    return 0;
}

