#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <stdio.h>

#define FLAME_SENSOR_PIN 4
#define FAN_PIN 18
#define PWM_FREQ 100
#define DEBOUNCE_TIME 50 // in ms

volatile sig_atomic_t stop;

void handler(int signum)
{
    stop = 1; // Set flag
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stime(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, handler);
    signal(SIGTERM, handler);

    // Set up GPIO pins
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(FAN_PIN, PI_OUTPUT);

    // Start PWM on fan pin
    gpioHardwarePWM(FAN_PIN, PWM_FREQ, 0);

    // Open log file
    FILE *logFile = fopen("flame_log.txt", "w");
    if (logFile == NULL)
    {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    time_t startTime, endTime;
    int flameDetected = 0;

    while (!stop)
    {
        // Debounce
        time_sleep(DEBOUNCE_TIME / 1000.0);

        // Read sensor
        int sensorValue = gpioRead(FLAME_SENSOR_PIN);
        if (sensorValue < 0)
        {
            fprintf(stderr, "Failed to read from flame sensor\n");
            return 1;
        }

        if (sensorValue == 0 && flameDetected)
        {
            // Flame ended
            endTime = time(NULL);
            fprintf(logFile, "%s: Flame ended\n", ctime(&endTime));
            flameDetected = 0;
            gpioHardwarePWM(FAN_PIN, 0, 0); // Turn off fan
        }
        else if (sensorValue == 1 && !flameDetected)
        {
            // Flame detected
            startTime = time(NULL);
            fprintf(logFile, "%s: Flame detected\n", ctime(&startTime));
            flameDetected = 1;
        }
    }

    // Cleanup
