#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0

#define TRIGGER_GPIO 23
#define DATA_READY_GPIO 24

#define HEATMAP_DATA_SIZE 32768

typedef struct {
    uint32_t magic_number;
    uint64_t timestamp;
    uint32_t start_frequency;
    uint32_t end_frequency;
    uint32_t chirps;
    uint32_t samples;
    uint32_t frame_period;
} config_t;

volatile sig_atomic_t stop;

void sig_handler(int signum) {
    stop = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open SPI
    int spi = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi < 0) {
        fprintf(stderr, "Failed to open SPI\n");
        return 1;
    }

    // Set up GPIO
    gpioSetMode(TRIGGER_GPIO, PI_OUTPUT);
    gpioSetMode(DATA_READY_GPIO, PI_INPUT);

    // Set up signal handler
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Write binary log file header
    FILE* file = fopen("log.bin", "wb");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file\n");
        return 1;
    }

    config_t config = {
        .magic_number = 0x52444144,
        .timestamp = time(NULL),
        .start_frequency = 770000000,
        .end_frequency = 790000000,
        .chirps = 64,
        .samples = 256,
        .frame_period = 100,
    };

    fwrite(&config, sizeof(config), 1, file);

    // Main loop
    uint32_t frame_number = 0;
    while (!stop) {
        // Trigger a frame
        gpioWrite(TRIGGER_GPIO, 1);
        time_sleep(0.001); // Wait for trigger to settle
        gpioWrite(TRIGGER_GPIO, 0);

        // Wait for data-ready interrupt
        while (!gpioRead(DATA_READY_GPIO)) {
            time_sleep(0.001);
        }

        // Read heatmap data
        uint8_t* heatmap_data = malloc(HEATMAP_DATA_SIZE);
        if (heatmap_data == NULL) {
            fprintf(stderr, "Failed to allocate memory\n");
            return 1;
        }

        spiXfer(spi, heatmap_data, HEATMAP_DATA_SIZE);

        // Log the frame
        fwrite(&frame_number, sizeof(frame_number), 1, file);
        fwrite(&config.timestamp, sizeof(config.timestamp), 1, file);
        fwrite(heatmap_data, HEATMAP_DATA_SIZE, 1, file);

        free(heatmap_data);

        frame_number++;
    }

    // Clean up
    fclose(file);
    spiClose(spi);
    gpioTerminate();

    return 0;
}

