#include <pigpio.h>
#include <stdio.h>
#include <signal.h>
#include <time.h>

#define OPT3001_ADDR 0x44
#define OPT3001_CONF 0x0F
#define OPT3001_RESULT 0x00

int handle;
FILE *file;

void sig_handler(int signum) {
    fclose(file);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    handle = i2cOpen(1, OPT3001_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C handle: %d\n", handle);
        return 1;
    }

    if (i2cWriteByteData(handle, OPT3001_CONF, 0xC0) < 0) {
        fprintf(stderr, "Failed to write to OPT3001\n");
        return 1;
    }

    file = fopen("light_data.txt", "w");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file\n");
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        char data[2];
        if (i2cReadI2CBlockData(handle, OPT3001_RESULT, data, 2) != 2) {
            fprintf(stderr, "Failed to read from OPT3001\n");
            continue;
        }

        int exponent = (data[0] >> 4) & 0x0F;
        int mantissa = ((data[0] & 0x0F) << 8) | data[1];
        float lux = 0.01 * pow(2, exponent) * mantissa;

        time_t now = time(NULL);
        struct tm *ptm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", ptm);

        fprintf(file, "%s,%f\n", timestamp, lux);
        fflush(file);

        gpioSleep(PI_TIME_RELATIVE, 0, 100000);
    }

    return 0;
}

