#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

volatile sig_atomic_t stop;

void intHandler(int dummy) {
    stop = 1;
}

int main() {
    signal(SIGINT, intHandler);

    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_request_config req_config;
    struct timespec ts;
    int val;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0\n");
        return 1;
    }

    line = gpiod_chip_get_line(chip, 17);
    if (line == NULL) {
        fprintf(stderr, "Failed to get line 17\n");
        gpiod_chip_close(chip);
        return 1;
    }

    gpiod_line_request_config_init(&req_config);
    req_config.consumer = "flame_detect";
    req_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    req_config.flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP;

    if (gpiod_line_request(line, &req_config) < 0) {
        fprintf(stderr, "Failed to request line\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    while (!stop) {
        clock_gettime(CLOCK_REALTIME, &ts);

        val = gpiod_line_get_value(line);
        if (val < 0) {
            fprintf(stderr, "Failed to get line value\n");
            break;
        }

        printf("%04d-%02d-%02d %02d:%02d:%02d: %s\n",
               ts.tv_year + 1900, ts.tv_mon + 1, ts.tv_mday,
               ts.tv_hour, ts.tv_min, ts.tv_sec,
               val == 0 ? "Flame Detected: YES" : "Flame Detected: NO");

        sleep(1);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

