#include <pigpio.h>
#include <stdio.h>
#include <signal.h>
#include <time.h>

#define GPIO_START 2
#define GPIO_END 9

volatile sig_atomic_t stop;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    for (int i = GPIO_START; i <= GPIO_END; i++) {
        if (gpioSetMode(i, PI_INPUT) < 0 || gpioSetPullUpDown(i, PI_PUD_DOWN) < 0) {
            fprintf(stderr, "Failed to configure GPIO %d\n", i);
            gpioTerminate();
            return 1;
        }
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!stop) {
        time_t now = time(NULL);
        printf("[%ld s]", now);

        for (int i = GPIO_START; i <= GPIO_END; i++) {
            int level = gpioRead(i);
            if (level < 0) {
                fprintf(stderr, "Failed to read GPIO %d\n", i);
                gpioTerminate();
                return 1;
            }
            printf(" CH%d=%d", i, level);
        }

        printf("\n");
        gpioDelay(100000); // 100 ms delay
    }

    gpioTerminate();
    return 0;
}

