#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define SLAVE_ADDR 0x60
#define HW_KEY 0x17
#define CHLIST 0x01
#define ALS_FORCE 0x06

void sigint_handler(int sig) {
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    int handle = i2cOpen(1, SLAVE_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    unsigned char part_id[2];
    if (i2cReadDevice(handle, part_id, 2) != 2) {
        fprintf(stderr, "Failed to read PART ID\n");
        return 1;
    }

    if (part_id[0] != 0x45) {
        fprintf(stderr, "Invalid PART ID: 0x%02X\n", part_id[0]);
        return 1;
    }

    if (i2cWriteByte(handle, HW_KEY) != 0) {
        fprintf(stderr, "Failed to write HW_KEY\n");
        return 1;
    }

    if (i2cWriteByte(handle, CHLIST) != 0) {
        fprintf(stderr, "Failed to write CHLIST\n");
        return 1;
    }

    if (i2cWriteByte(handle, ALS_FORCE) != 0) {
        fprintf(stderr, "Failed to write ALS_FORCE\n");
        return 1;
    }

    FILE *log_file = fopen("uv_als_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    while (1) {
        unsigned char uv_index[2];
        if (i2cReadDevice(handle, uv_index, 2) != 2) {
            fprintf(stderr, "Failed to read UV index\n");
            return 1;
        }

        unsigned char als_visible[2];
        if (i2cReadDevice(handle, als_visible, 2) != 2) {
            fprintf(stderr, "Failed to read Visible ALS\n");
            return 1;
        }

        time_t now = time(NULL);
        fprintf(log_file, "%ld,%d,%d\n", now, uv_index[0]*256+uv_index[1], als_visible[0]*256+als_visible[1]);
        fflush(log_file);

        sleep(1);
    }

    fclose(log_file);
    i2cClose(handle);
    gpioTerminate();

    return 0;
}

