#include <sys/ioctl.h>
#include <gpiod.h>
#include <signal.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDR1 0x36
#define I2C_ADDR2 0x37
#define GPIO_PIN 17
#define CRC_POLY 0x31
#define CRC_INIT 0xFF
#define SCALE_FACTOR 0.036
#define MEASUREMENT_DELAY 100
#define LOG_FILE "flow_log.txt"

int fd1, fd2;
struct gpiod_chip *chip;
struct gpiod_line *line;
FILE *log_file;

void cleanup(int signum) {
    gpiod_line_release(line);
    close(fd1);
    close(fd2);
    fclose(log_file);
    exit(0);
}

int crc8(unsigned char *data, int len) {
    unsigned char crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

void read_sensor(int fd, int addr) {
    unsigned char buffer[9];
    if (read(fd, buffer, 9) != 9) {
        perror("Failed to read from I2C device");
        return;
    }
    if (crc8(buffer, 6) != buffer[6]) {
        fprintf(stderr, "CRC failure on sensor %d\n", addr);
        return;
    }
    int flow = (buffer[0] << 8) | buffer[1];
    float ml_per_min = flow * SCALE_FACTOR;
    fprintf(log_file, "Sensor %d: %.2f ml/min\n", addr, ml_per_min);
    fflush(log_file);
    if (ml_per_min < 0.5) {
        gpiod_line_set_value(line, 1);
    } else {
        gpiod_line_set_value(line, 0);
    }
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    if ((fd1 = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return 1;
    }
    if (ioctl(fd1, I2C_SLAVE, I2C_ADDR1) < 0) {
        perror("Failed to acquire bus access");
        return 1;
    }
    if ((fd2 = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return 1;
    }
    if (ioctl(fd2, I2C_SLAVE, I2C_ADDR2) < 0) {
        perror("Failed to acquire bus access");
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        return 1;
    }
    gpiod_line_request_output(line, "flow_alarm", 0);

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    while (1) {
        write(fd1, "\x08", 1);
        usleep(MEASUREMENT_DELAY * 1000);
        read_sensor(fd1, I2C_ADDR1);

        write(fd2, "\x08", 1);
        usleep(MEASUREMENT_DELAY * 1000);
        read_sensor(fd2, I2C_ADDR2);

        sleep(1);
    }

    return 0;
}

