#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define BUFFER_SIZE 100

typedef struct {
    time_t timestamp;
    int reading;
} Entry;

Entry buffer[BUFFER_SIZE];
int buffer_index = 0;

void signal_handler(int signum) {
    printf("\n--- Buffer contents ---\n");
    for (int i = 0; i < buffer_index; i++) {
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&buffer[i].timestamp));
        printf("%s: %d\n", time_str, buffer[i].reading);
    }

    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    while (1) {
        time_t current_time = time(NULL);
        int reading = gpioRead(GPIO_PIN);

        if (reading == 0) {
            buffer[buffer_index].timestamp = current_time;
            buffer[buffer_index].reading = reading;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;

            printf("Obstacle detected at %s\n", ctime(&current_time));
        }

        time_sleep(0.05);
    }

    return 0;
}

