#include <wiringPi.h>
#include <time.h>
#include <signal.h>

#define SDA_PIN 2
#define SCL_PIN 3
#define I2C_ADDR 0x55
#define MODE_CONTROL_REG 0x1D
#define OPERATING_STATUS_REG 0x1B
#define X_ACCEL_REG 0x2A
#define Y_ACCEL_REG 0x2C
#define Z_ACCEL_REG 0x2E
#define SCALE_FACTOR 0.0009765625
#define TIMEOUT 1

int fd;
FILE *file;

void signal_handler(int signum) {
    fclose(file);
    close(fd);
    exit(0);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Failed to setup wiringPi\n");
        return 1;
    }

    pinMode(SDA_PIN, OUTPUT);
    pinMode(SCL_PIN, OUTPUT);

    fd = wiringPiI2CSetup(I2C_ADDR);
    if (fd == -1) {
        fprintf(stderr, "Failed to setup I2C\n");
        return 1;
    }

    if (wiringPiI2CWriteReg8(fd, MODE_CONTROL_REG, 0x10) == -1) {
        fprintf(stderr, "Failed to write to MODE_CONTROL_REG\n");
        return 1;
    }

    int start_time = time(NULL);
    while (1) {
        if (time(NULL) - start_time > TIMEOUT) {
            fprintf(stderr, "Sensor did not become active within 1 second\n");
            return 1;
        }

        if (wiringPiI2CReadReg8(fd, OPERATING_STATUS_REG) & 0x01) {
            break;
        }
    }

    file = fopen("fan_health.csv", "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file\n");
        return 1;
    }

    while (1) {
        int x_accel = wiringPiI2CReadReg16(fd, X_ACCEL_REG);
        int y_accel = wiringPiI2CReadReg16(fd, Y_ACCEL_REG);
        int z_accel = wiringPiI2CReadReg16(fd, Z_ACCEL_REG);

        if (x_accel == -1 || y_accel == -1 || z_accel == -1) {
            fprintf(stderr, "Failed to read acceleration registers\n");
            continue;
        }

        time_t now = time(NULL);
        struct tm *ptm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", ptm);

        fprintf(file, "%s,%f,%f,%f\n", timestamp, x_accel * SCALE_FACTOR, y_accel * SCALE_FACTOR, z_accel * SCALE_FACTOR);
        fflush(file);

        delay(500);
    }

    return 0;
}

