#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SDA_PIN 18
#define SCL_PIN 19
#define SENSOR_ADDR 0x0E
#define DEVICE_ID_REG 0x00
#define DEVICE_ID_VAL 0x8D
#define X_AXIS_REG 0x01
#define Y_AXIS_REG 0x03
#define Z_AXIS_REG 0x05
#define CONFIG_REG 0x02
#define CONFIG_VAL 0x40
#define SCALE_FACTOR 0.0001

FILE *file;

void sigint_handler(int sig) {
    fclose(file);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (gpioSetI2COptions(1, 1000000) < 0) {
        fprintf(stderr, "Failed to set I2C options\n");
        return 1;
    }

    if (gpioI2CWriteDevice(1, SENSOR_ADDR, &CONFIG_REG, 1) < 0) {
        fprintf(stderr, "Failed to write to sensor\n");
        return 1;
    }

    if (gpioI2CWriteDevice(1, SENSOR_ADDR, &CONFIG_VAL, 1) < 0) {
        fprintf(stderr, "Failed to write to sensor\n");
        return 1;
    }

    file = fopen("magnetic_log.csv", "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file\n");
        return 1;
    }

    fprintf(file, "Timestamp,X,Y,Z\n");
    fflush(file);

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (1) {
        char data[6];
        int ret;

        ret = gpioI2CReadDevice(1, SENSOR_ADDR, data, 6);
        if (ret < 0) {
            fprintf(stderr, "Failed to read from sensor\n");
            continue;
        }

        int16_t x = (data[1] << 8) | data[0];
        int16_t y = (data[3] << 8) | data[2];
        int16_t z = (data[5] << 8) | data[4];

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, 20, "%Y-%m-%dT%H:%M:%S", tm_info);

        fprintf(file, "%s,%.4f,%.4f,%.4f\n", timestamp, x * SCALE_FACTOR, y * SCALE_FACTOR, z * SCALE_FACTOR);
        fflush(file);

        gpioDelay(1000000);
    }

    return 0;
}

