#include <pigpio.h>
#include <stdio.h>
#include <time.h>
#include <signal.h>

#define GPIO_PIN 4
#define RPM_SCALE 60
#define SAMPLE_TIME 1

volatile sig_atomic_t stop;
volatile unsigned long pulseCount;
FILE *logFile;

void alertFunc(int gpio, int level, uint32_t tick)
{
    if (level == 1)
    {
        gpioSetAlertFunc(GPIO_PIN, NULL);
        unsigned long rpm = pulseCount * RPM_SCALE;
        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
        fprintf(logFile, "%s %lu\n", timestamp, rpm);
        fflush(logFile);
        printf("%s %lu\n", timestamp, rpm);
        pulseCount = 0;
        alarm(SAMPLE_TIME);
        gpioSetAlertFunc(GPIO_PIN, alertFunc);
    }
}

void termHandler(int signum)
{
    stop = 1;
    gpioSetAlertFunc(GPIO_PIN, NULL);
    fclose(logFile);
    gpioTerminate();
}

int main()
{
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    if ((logFile = fopen("rpm_log.txt", "w")) == NULL)
    {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, termHandler);
    signal(SIGTERM, termHandler);

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);
    gpioSetAlertFunc(GPIO_PIN, alertFunc);

    alarm(SAMPLE_TIME);

    while (!stop)
    {
        sleep(1);
    }

    return 0;
}

