#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <syslog.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_SENSOR 23
#define GPIO_LED 18

struct gpiod_chip *chip;
struct gpiod_line *sensor_line, *led_line;

void signal_handler(int signum) {
    syslog(LOG_INFO, "Shutting down...");
    gpiod_line_release(sensor_line);
    gpiod_line_release(led_line);
    closelog();
    exit(0);
}

int main() {
    openlog("ttp223b_led", LOG_PID, LOG_USER);
    syslog(LOG_INFO, "Starting up...");

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        return 1;
    }

    sensor_line = gpiod_chip_get_line(chip, GPIO_SENSOR);
    led_line = gpiod_chip_get_line(chip, GPIO_LED);

    if (!sensor_line || !led_line) {
        syslog(LOG_ERR, "Failed to get GPIO lines");
        return 1;
    }

    int ret = gpiod_line_request_input(sensor_line, "ttp223b_led");
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request input on sensor line");
        return 1;
