#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR1 4
#define SENSOR2 17
#define LED1 27
#define LED2 22
#define BUFFER_SIZE 100
#define DEBOUNCE_TIME 50 // in ms

typedef struct {
    int sensor;
    time_t timestamp;
    int state;
} log_entry;

log_entry log_buffer[BUFFER_SIZE];
int log_buffer_index = 0;
int overflow_count = 0;

void handle_signal(int signum) {
    // Turn off LEDs
    gpioWrite(LED1, 0);
    gpioWrite(LED2, 0);

    // Print log buffer contents
    printf("\nLog buffer contents:\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        printf("Sensor: %d, Timestamp: %ld, State: %d\n", log_buffer[i].sensor, log_buffer[i].timestamp, log_buffer[i].state);
    }

    // Print overflow count
    printf("Overflow count: %d\n", overflow_count);

    // Terminate GPIO
    gpioTerminate();

    // Exit program
    exit(0);
}

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(SENSOR1, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for sensor 1\n");
        return 1;
    }
    if (gpioSetMode(SENSOR2, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for sensor 2\n");
        return 1;
    }
    if (gpioSetMode(LED1, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for LED 1\n");
        return 1;
    }
    if (gpioSetMode(LED2, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for LED 2\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Main loop
    while (1) {
        // Read sensor states
        int state1 = gpioRead(SENSOR1);
        int state2 = gpioRead(SENSOR2);

        // Debounce
        time_sleep(DEBOUNCE_TIME / 1000.0);

        // Check if states have changed
        if (gpioRead(SENSOR1) != state1 || gpioRead(SENSOR2) != state2) {
            // Update LEDs
            gpioWrite(LED1, state1);
            gpioWrite(LED2, state2);

            // Log event
            log_buffer[log_buffer_index].sensor = state1 ? SENSOR1 : SENSOR2;
            log_buffer[log_buffer_index].timestamp = time(NULL);
            log_buffer[log_buffer_index].state = state1 ? 1 : 0;

            // Increment buffer index
            log_buffer_index = (log_buffer_index + 1) % BUFFER_SIZE;

            // Check for overflow
            if (log_buffer_index == 0) {
                overflow_count++;
            }
        }
    }

    return 0;
}

