#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SDA_GPIO 2
#define SCL_GPIO 3
#define SENSOR_ADDR 0x1D
#define CTRL1_REG 0x1F
#define ACC_START_REG 0x28
#define ACC_END_REG 0x2D
#define THRESHOLD 500
#define LED_GPIO 17
#define MAX_RETRIES 3

FILE *log_file;

void sigint_handler(int sig) {
    fclose(log_file);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    log_file = fopen("seismic_events.log", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    int i2c_handle = i2cOpen(1, SENSOR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        return 1;
    }

    char ctrl1;
    for (int i = 0; i < MAX_RETRIES; i++) {
        if (i2cReadByteData(i2c_handle, CTRL1_REG) < 0) {
            fprintf(stderr, "Failed to read CTRL1 register, retrying...\n");
            continue;
        }

        ctrl1 = (char)i2cReadByteData(i2c_handle, CTRL1_REG);
        break;
    }

    if ((ctrl1 & 0x01) != 0) {
        fprintf(stderr, "Failed to clear power-down bit\n");
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);

    while (1) {
        char acc_data[6];
        for (int i = 0; i < MAX_RETRIES; i++) {
            if (i2cReadI2CBlockData(i2c_handle, ACC_START_REG, acc_data, 6) < 0) {
                fprintf(stderr, "Failed to read acceleration data, retrying...\n");
                continue;
            }

            break;
        }

        int16_t x = (acc_data[1] << 8) | acc_data[0];
        int16_t y = (acc_data[3] << 8) | acc_data[2];
        int16_t z = (acc_data[5] << 8) | acc_data[4];

        double magnitude = sqrt(x * x + y * y + z * z);

        if (magnitude > THRESHOLD) {
            time_t now = time(NULL);
            struct tm *timeinfo = localtime(&now);
            char timestamp[20];
            strftime(timestamp, 20, "%Y-%m-%dT%H:%M:%S", timeinfo);
            fprintf(log_file, "%s, %.2f\n", timestamp, magnitude);
            fflush(log_file);

            gpioWrite(LED_GPIO, 1);
            time_sleep(1);
            gpioWrite(LED_GPIO, 0);
        }

        time_sleep(0.1);
    }

    return 0;
}

