#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <gpiod.h>

#define SENSOR_COUNT 5
#define GPIO_PINS {2, 3, 4, 17, 27}
#define DEBOUNCE_TIME 50 // in ms

volatile sig_atomic_t stop;
struct gpiod_chip *chip;
struct gpiod_line *lines[SENSOR_COUNT];

void signal_handler(int signum) {
    stop = 1;
}

char* get_timestamp() {
    time_t t = time(NULL);
    char* timestamp = asctime(gmtime(&t));
    timestamp[strlen(timestamp) - 1] = '\0'; // remove newline
    return timestamp;
}

int main() {
    openlog("flame_monitor", LOG_USER, LOG_DAEMON);
    syslog(LOG_INFO, "Starting flame monitor");

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip == NULL) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        closelog();
        return 1;
    }

    int GPIO_PINS[] = {2, 3, 4, 17, 27};
    for (int i = 0; i < SENSOR_COUNT; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_PINS[i]);
        if (lines[i] == NULL) {
            syslog(LOG_ERR, "Failed to get line %d", GPIO_PINS[i]);
            gpiod_chip_close(chip);
            closelog();
            return 1;
        }

        int ret = gpiod_line_request_input(lines[i], "flame_monitor");
        if (ret < 0) {
            syslog(LOG_ERR, "Failed to request line %d", GPIO_PINS[i]);
            gpiod_chip_close(chip);
            closelog();
            return 1;
        }
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!stop) {
        for (int i = 0; i < SENSOR_COUNT; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                syslog(LOG_ERR, "Failed to read line %d", GPIO_PINS[i]);
                continue;
            }

            if (val == 0) {
                usleep(DEBOUNCE_TIME * 1000);
                val = gpiod_line_get_value(lines[i]);
                if (val < 0) {
                    syslog(LOG_ERR, "Failed to read line %d", GPIO_PINS[i]);
                    continue;
                }

                if (val == 0) {
                    FILE *logfile = fopen("/var/log/flame_events.log", "a");
                    if (logfile == NULL) {
                        syslog(LOG_ERR, "Failed to open log file");
                        continue;
                    }

                    flock(fileno(logfile), LOCK_EX);
                    fprintf(logfile, "%s - Sensor ID: %d (GPIO %d) - Flame Detected\n", get_timestamp(), i, GPIO_PINS[i]);
                    fflush(logfile);
                    flock(fileno(logfile), LOCK_UN);
                    fclose(logfile);
                }
            }
        }

        usleep(1000000); // 1 second
    }

    for (int i = 0; i < SENSOR_COUNT; i++) {
        gpiod_line_release(lines[i]);
    }

    gpiod_chip_close(chip);
    closelog();
    return 0;
}

