    for (int i = 0; i < SENSOR_COUNT; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_PINS[i]);
        if (lines[i] == NULL) {
            syslog(LOG_ERR, "Failed to get line %d", GPIO_PINS[i]);
            gpiod_chip_close(chip);
            closelog();
            return 1;
        }

        int ret = gpiod_line_request_input(lines[i], "flame_monitor");
        if (ret < 0) {
            syslog(LOG_ERR, "Failed to request line %d", GPIO_PINS[i]);
            gpiod_chip_close(chip);
            closelog();
            return 1;
        }
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

