        for (int i = 0; i < SENSOR_COUNT; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                syslog(LOG_ERR, "Failed to read line %d", GPIO_PINS[i]);
                continue;
            }

            if (val == 0) {
