#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_ADDR 0x10
#define CONFIG_REG 0x00
#define ALS_REG 0x04
#define LED_PIN 18

FILE *log_file;

void sigint_handler(int sig) {
    gpioHardwarePWM(LED_PIN, 0, 0);
    gpioTerminate();
    fclose(log_file);
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    log_file = fopen("grow_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    int handle = i2cOpen(1, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    char config_data[] = {0x00, 0x00};
    if (i2cWriteDevice(handle, CONFIG_REG, config_data, 2) < 0) {
        fprintf(stderr, "Failed to write to sensor config register\n");
        return 1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);

    while (1) {
        char als_data[2] = {0, 0};
        if (i2cReadDevice(handle, ALS_REG, als_data, 2) < 0) {
            fprintf(stderr, "Failed to read from ALS register\n");
            return 1;
        }

        uint16_t raw_als = (als_data[0] << 8) | als_data[1];
        float lux = raw_als * 0.0576;

        int brightness;
        if (lux < 100) {
            brightness = 100;
        } else if (lux < 500) {
            brightness = 75;
        } else if (lux < 1000) {
            brightness = 50;
        } else {
            brightness = 25;
        }

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s, %.2f, %d, %d\n", timestamp, lux, raw_als, brightness);
        fflush(log_file);

        gpioHardwarePWM(LED_PIN, 1000, brightness * 100000);

        sleep(1);
    }

    return 0;
}

