#define GPIO_START 2
#define GPIO_END 9
#define LED_GPIO 17

volatile sig_atomic_t stop;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    for (int i = GPIO_START; i <= GPIO_END; i++) {
        gpioSetMode(i, PI_INPUT);
        gpioSetPullUpDown(i, PI_PUD_DOWN);
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    time_t last_touch[GPIO_END - GPIO_START + 1];
    for (int i = 0; i < GPIO_END - GPIO_START + 1; i++) {
        last_touch[i] = 0;
    }

    while (!stop) {
        for (int i = GPIO_START; i <= GPIO_END; i++) {
            if (gpioRead(i)) {
                time_t now = time(NULL);
                if (difftime(now, last_touch[i - GPIO_START]) > 0.05) {
                    last_touch[i - GPIO_START] = now;
                    FILE *file = fopen("touch_log.txt", "a");
                    if (file == NULL) {
                        fprintf(stderr, "Failed to open touch_log.txt for writing\n");
                        return 1;
                    }
                    char timestamp[20];
                    strftime(timestamp, sizeof(timestamp), "%F %T", localtime(&now));
                    fprintf(file, "%s - Channel %d Touched\n", timestamp, i);
                    fclose(file);
                    gpioWrite(LED_GPIO, 1);
                }
            }
        }
        gpioDelay(100000);  // 100ms delay
    }

    gpioWrite(LED_GPIO, 0);
    gpioTerminate();

    return 0;
