#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>

#define I2C_HANDLE 1
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define CONFIG_WORD 0xC810

void sigint_handler(int sig);
uint16_t byte_swap(uint16_t val);

int main() {
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to set SIGINT handler\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    int i2c = i2cOpen(I2C_HANDLE, OPT3001_ADDR, 0);
    if (i2c < 0) {
        fprintf(stderr, "Failed to open I2C handle: %d\n", i2c);
        return 1;
    }

    uint16_t config_word = byte_swap(CONFIG_WORD);
    if (i2cWriteWordData(i2c, CONFIG_REG, config_word) < 0) {
        fprintf(stderr, "Failed to write configuration word\n");
        return 1;
    }

    sleep(1);  // Wait for at least 100 ms

    FILE *file = fopen("light_data.txt", "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    while (1) {
        uint16_t raw_result;
        if (i2cReadWordData(i2c, RESULT_REG, &raw_result) < 0) {
            fprintf(stderr, "Failed to read result register\n");
            continue;
        }

        uint16_t result = byte_swap(raw_result);
        uint16_t exponent = (result >> 12) & 0x0F;
        uint16_t mantissa = result & 0x0FFF;
        float lux = mantissa * 0.01 * pow(2, exponent);

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%F %T", tm_info);

        printf("%s, %.2f\n", time_str, lux);
        fprintf(file, "%s, %.2f\n", time_str, lux);
        fflush(file);

        sleep(1);
    }

    fclose(file);
    i2cClose(i2c);
    gpioTerminate();
    return 0;
}

void sigint_handler(int sig) {
    fprintf(stderr, "SIGINT received, exiting...\n");
    exit(1);
}

uint16_t byte_swap(uint16_t val) {
    return (val << 8) | (val >> 8);
}

