    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    signal(SIGINT, signalHandler);

    if ((logFile = fopen("fire_events.log", "a")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(SENSOR_GPIO, PI_INPUT);
    gpioSetMode(ALERT_GPIO, PI_OUTPUT);

    while (1) {
        time_t now = time(NULL);
        int sensorValue = gpioRead(SENSOR_GPIO);

        if (sensorValue == PI_TIMEOUT) {
            fprintf(stderr, "Failed to read from sensor GPIO\n");
        } else {
            fprintf(logFile, "%s: Flame sensor value = %d\n", ctime(&now), sensorValue);
            fflush(logFile);

            if (sensorValue == 0) {
                gpioWrite(ALERT_GPIO, 1);
                time_sleep(1);
                gpioWrite(ALERT_GPIO, 0);
            }
        }

        time_sleep(POLL_INTERVAL / 1000.0);
    }

    return 0;
}
