#define DEBOUNCE_INTERVAL 50000 // microseconds
#define LOG_FILE "touch_log.txt"

struct gpiod_chip *chip;
struct gpiod_line *line;
FILE *file;

void cleanup(int signum) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (file) {
        fclose(file);
    }
    exit(signum);
}

int main(void) {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (gpiod_line_request_input(line, "touch_sensor") < 0) {
        fprintf(stderr, "Failed to request GPIO line as input\n");
        gpiod_chip_close(chip);
        return 1;
    }

    file = fopen(LOG_FILE, "a");
    if (!file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    struct timespec debounce_time = {0, DEBOUNCE_INTERVAL};
    int last_state = -1;
    while (1) {
        int state = gpiod_line_get_value(line);
        if (state != last_state) {
            last_state = state;
            char buffer[32];
            clock_gettime(CLOCK_REALTIME, &debounce_time);
            strftime(buffer, sizeof(buffer), "%F %T", localtime(&debounce_time.tv_sec));
            fprintf(file, "%s: %s\n", buffer, state ? "Touch Detected" : "Touch Released");
            fflush(file);
        }
        nanosleep(&debounce_time, NULL);
    }

    fclose(file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return 0;
}

