#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x08
#define COMMAND_SEQUENCE 0x3608

void sigint_handler(int sig) {
    gpioTerminate();
    exit(0);
}

char crc8(char *data, int len) {
    char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if ((crc & 0x80) != 0) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    signal(SIGINT, sigint_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    int handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C handle: %d\n", handle);
        return 1;
    }

    FILE *file = fopen("cooling_log.csv", "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file\n");
        return 1;
    }

    // Write header only if file is newly created
    if (ftell(file) == 0) {
        fprintf(file, "Timestamp,Flow Rate (ml/min),Status\n");
    }

    while (1) {
        char command[2] = {COMMAND_SEQUENCE >> 8, COMMAND_SEQUENCE & 0xFF};
        char data[3];

        if (i2cWriteI2CBlockData(handle, I2C_ADDR, command[0], 2, command) < 0) {
            fprintf(stderr, "Failed to write to I2C\n");
            return 1;
        }

        time_t timestamp = time(NULL);

        usleep(2000);

        if (i2cReadI2CBlockData(handle, I2C_ADDR, command[0], 3, data) < 0) {
            fprintf(stderr, "Failed to read from I2C\n");
            return 1;
        }

        char crc = crc8(data, 2);
        if (crc != data[2]) {
            fprintf(stderr, "CRC error\n");
            return 1;
        }

        int16_t raw_flow = (data[0] << 8) | data[1];
        float flow_rate = raw_flow / 90.0;

        char *status;
        if (flow_rate < 0.0 || flow_rate > 100.0) {
            status = "INVALID";
        } else {
            status = "OK";
        }

        fprintf(file, "%ld,%f,%s\n", timestamp, flow_rate, status);
        fflush(file);

        usleep(1000000);
    }

    fclose(file);
    i2cClose(handle);
    gpioTerminate();

    return 0;
}

