#define FLAME_SENSOR_LINE 17
#define BUZZER_LINE 18
#define POLL_INTERVAL 500
#define BUZZER_ACTIVATION_TIME 2000

struct gpiod_chip *chip;
struct gpiod_line *flame_sensor_line, *buzzer_line;
