        return 1;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_LINE);
    if (buzzer_line == NULL) {
        fprintf(stderr, "Failed to get line %d: %s\n", BUZZER_LINE, strerror(errno));
        return 1;
    }

    log_file = fopen("alert_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open alert_log.txt: %s\n", strerror(errno));
        return 1;
    }

    fprintf(log_file, "System started\n");

    ret = gpiod_line_request_input(flame_sensor_line, "flame_sensor");
    if (ret < 0) {
        fprintf(stderr, "Failed to request input for line %d: %s\n", FLAME_SENSOR_LINE, strerror(errno));
        return 1;
    }

    ret = gpiod_line_request_output(buzzer_line, "buzzer", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request output for line %d: %s\n", BUZZER_LINE, strerror(errno));
        return 1;
    }

    while (1) {
        int value = gpiod_line_get_value(flame_sensor_line);
        if (value < 0) {
            fprintf(stderr, "Failed to get value for line %d: %s\n", FLAME_SENSOR_LINE, strerror(errno));
            return 1;
        }

        if (value && !prev_value) {
            time_t now = time(NULL);
            fprintf(log_file, "Flame detected at %s", ctime(&now));
            fflush(log_file);

            ret = gpiod_line_set_value(buzzer_line, 1);
            if (ret < 0) {
                fprintf(stderr, "Failed to set value for line %d: %s\n", BUZZER_LINE, strerror(errno));
                return 1;
            }

            nanosleep(&poll_time, NULL);

            ret = gpiod_line_set_value(buzzer_line, 0);
            if (ret < 0) {
                fprintf(stderr, "Failed to set value for line %d: %s\n", BUZZER_LINE, strerror(errno));
                return 1;
            }
        }

        prev_value = value;
        nanosleep(&poll_time, NULL);
    }

    return 0;
}

