#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <stdio.h>

#define GPIO_INPUT 4
#define GPIO_OUTPUT 17
#define DEBOUNCE_TIME 200 // in ms

FILE *logFile;

void signalHandler(int signum) {
    fprintf(stderr, "Signal %d received, turning off LED and exiting...\n", signum);
    gpioWrite(GPIO_OUTPUT, PI_LOW);
    fclose(logFile);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    gpioSetMode(GPIO_INPUT, PI_INPUT);
    gpioSetMode(GPIO_OUTPUT, PI_OUTPUT);

    logFile = fopen("touch_log.txt", "w");
    if (logFile == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    int lastState = gpioRead(GPIO_INPUT);
    time_t lastDebounceTime = time(NULL);

    while (1) {
        int currentState = gpioRead(GPIO_INPUT);
        if (currentState != lastState && currentState == PI_HIGH && time(NULL) - lastDebounceTime > DEBOUNCE_TIME / 1000) {
            lastDebounceTime = time(NULL);
            gpioWrite(GPIO_OUTPUT, gpioRead(GPIO_OUTPUT) == PI_HIGH ? PI_LOW : PI_HIGH);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", gmtime(NULL));
            if (fprintf(logFile, "%s\n", timestamp) < 0) {
                fprintf(stderr, "Warning: Failed to write to log file\n");
            }
            fflush(logFile);
        }
        lastState = currentState;
        gpioDelay(10000); // delay for 10 ms
    }

    return 0;
}

