#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_ADDR 0x4A
#define PART_ID_REG 0x00
#define HW_REV_REG 0x01
#define LED_CURRENT_REG 0x02
#define AVG_REG 0x03
#define ENABLE_REG 0x04
#define HR_REG 0x2A

#define PART_ID 0x02
#define HW_REV 0x01

#define LED_CURRENT 0x3F
#define AVG 0x04
#define ENABLE 0x01

#define SAMPLES 5

FILE *file;

void sigint_handler(int sig) {
    fclose(file);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    file = fopen("heart_rate.csv", "w");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file\n");
        return 1;
    }

    int handle = i2cOpen(1, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    char part_id = i2cReadByteData(handle, PART_ID_REG);
    if (part_id != PART_ID) {
        fprintf(stderr, "Sensor not found or wrong\n");
        return 1;
    }

    char hw_rev = i2cReadByteData(handle, HW_REV_REG);
    if (hw_rev != HW_REV) {
        fprintf(stderr, "Sensor not found or wrong\n");
        return 1;
    }

    i2cWriteByteData(handle, LED_CURRENT_REG, LED_CURRENT);
    i2cWriteByteData(handle, AVG_REG, AVG);
    i2cWriteByteData(handle, ENABLE_REG, ENABLE);

    int samples[SAMPLES] = {0};
    int sum = 0;
    int index = 0;

    while (1) {
        int raw = i2cReadWordData(handle, HR_REG);
        if (raw < 0) {
            fprintf(stderr, "Failed to read from sensor\n");
            return 1;
        }

        int bpm = raw * 0.5;

        sum -= samples[index];
