#include <errno.h>
#include <signal.h>
#include <gpiod.h>

#define CHIP_NAME "gpiochip0"
#define TTP226_OUTPUTS {5, 6, 7, 8, 9, 10, 11, 12}
#define GPIO_OUTPUTS {17, 18, 19, 20, 21, 22, 23, 24}
#define NUM_OUTPUTS 8
#define NUM_INPUTS 8
#define DELAY 10000 // 10 ms
#define LOG_FILE "touch_log.txt"

struct gpiod_chip *chip;
struct gpiod_line **lines_in, **lines_out;
struct timespec delay = {0, DELAY * 1000}; // convert to nanoseconds
unsigned char counter = 0;

void cleanup(int signum) {
    for (int i = 0; i < NUM_OUTPUTS; i++) {
        gpiod_line_set_value(lines_out[i], 0);
        gpiod_line_release(lines_out[i]);
    }
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open chip: %s\n", strerror(errno));
        return 1;
    }

    lines_in = malloc(NUM_INPUTS * sizeof(struct gpiod_line *));
    lines_out = malloc(NUM_OUTPUTS * sizeof(struct gpiod_line *));
    for (int i = 0; i < NUM_INPUTS; i++) {
        lines_in[i] = gpiod_chip_get_line(chip, TTP226_OUTPUTS[i]);
        if (!lines_in[i]) {
            fprintf(stderr, "Failed to get line: %s\n", strerror(errno));
            return 1;
        }
    }
    for (int i = 0; i < NUM_OUTPUTS; i++) {
        lines_out[i] = gpiod_chip_get_line(chip, GPIO_OUTPUTS[i]);
        if (!lines_out[i]) {
            fprintf(stderr, "Failed to get line: %s\n", strerror(errno));
            return 1;
        }
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
    }

    while (1) {
        for (int i = 0; i < NUM_INPUTS; i++) {
            int value = gpiod_line_get_value(lines_in[i]);
            if (value < 0) {
                fprintf(stderr, "Failed to read line: %s\n", strerror(errno));
                continue;
            }
            if (value && !gpiod_line_get_value(lines_in[i - 1])) { // rising edge
                counter++;
                for (int j = 0; j < NUM_OUTPUTS; j++) {
                    int bit = (counter >> j) & 1;
                    int err = gpiod_line_set_value(lines_out[j], bit);
                    if (err < 0) {
                        fprintf(stderr, "Failed to write line: %s\n", strerror(errno));
                    }
                }
                time_t now = time(NULL);
                fprintf(log_file, "%s, Channel: %d, Counter: %d\n", ctime(&now), i + 1, counter);
                printf("Touch on channel %d | Counter: %d\n", i + 1, counter);
            }
        }
        nanosleep(&delay, NULL);
    }

    return 0;
}

