#include <stdio.h>
#include <time.h>

#define GPIO_MICROPHONE 4
#define GPIO_LED 17
#define SAMPLE_RATE_MICROS 125

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
