    signal(SIGINT, signal_handler);

    gpioSetMode(GPIO_MICROPHONE, PI_INPUT);
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    while (running) {
        if (gpioRead(GPIO_MICROPHONE) == PI_HIGH) {
            time_t now = time(NULL);
            printf("%ld\n", now);

            gpioWrite(GPIO_LED, PI_HIGH);
            gpioDelay(100000); // Delay for 100 ms
            gpioWrite(GPIO_LED, PI_LOW);
        }

        gpioDelay(SAMPLE_RATE_MICROS);
    }

    gpioTerminate();
    return 0;
}

