#include <stdio.h>
#include <stdlib.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>

#define I2C_DEV "/dev/i2c-1"
#define SENSOR_ADDR 0x49
#define REG_ALS_VIS_MSB 0x25
#define REG_ALS_VIS_LSB 0x24

int fd;

void cleanup(int signum) {
    printf("Closing I2C device...\n");
    close(fd);
    exit(0);
}

int main() {
    unsigned char buffer[2];
    int result;

    signal(SIGINT, cleanup);

    if ((fd = open(I2C_DEV, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to acquire bus access or talk to slave");
        return 1;
    }

    while (1) {
        buffer[0] = REG_ALS_VIS_MSB;
        result = write(fd, buffer, 1);
        if (result != 1) {
            perror("Failed to write to the i2c bus");
            return 1;
        }

        result = read(fd, buffer, 2);
        if (result != 2) {
            perror("Failed to read from the i2c bus");
            return 1;
        }

        usleep(100000); // sleep for 100ms

        printf("ALS Visible: 0x%02x%02x\n", buffer[1], buffer[0]);
    }

    return 0;
}

