#include <gpiod.h>

#define CHIPNAME "gpiochip0"
#define POLL_INTERVAL_MS 200

struct gpiod_chip *chip;
struct gpiod_line *lines[8];

void cleanup(int signum) {
    for (int i = 0; i < 8; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    chip = gpiod_chip_open_by_name(CHIPNAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open chip %s\n", CHIPNAME);
        return 1;
    }

    for (int i = 0; i < 8; i++) {
        lines[i] = gpiod_chip_get_line(chip, 5 + i);
        if (lines[i] == NULL) {
            fprintf(stderr, "Failed to request line %d\n", 5 + i);
            return 1;
        }
        if (gpiod_line_request_input(lines[i], "read-sensor") < 0) {
            fprintf(stderr, "Failed to set line %d as input\n", 5 + i);
            return 1;
        }
    }

    while (1) {
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        double timestamp = ts.tv_sec + ts.tv_nsec / 1e9;
        printf("[%.3fs] ", timestamp);
        for (int i = 0; i < 8; i++) {
            int value = gpiod_line_get_value(lines[i]);
            if (value < 0) {
                fprintf(stderr, "Failed to read line %d\n", 5 + i);
                return 1;
            }
            printf("CH%d=%d ", i + 1, value);
        }
        printf("\n");
        usleep(POLL_INTERVAL_MS * 1000);
    }

    return 0;
}

