#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <time.h>

#define RED_PIN 17
#define GREEN_PIN 18
#define BLUE_PIN 27

#define PWM_FREQ 1000
#define PWM_RANGE 255

void hsv_to_rgb(float h, float s, float v, float *r, float *g, float *b) {
    int i;
    float f, p, q, t;

    h = fmax(0.0, fmin(360.0, h));
    s = fmax(0.0, fmin(100.0, s));
    v = fmax(0.0, fmin(100.0, v));

    s /= 100;
    v /= 100;
    h /= 60;

    i = (int)floor(h);
    f = h - i;

    p = v * (1 - s);
    q = v * (1 - s * f);
    t = v * (1 - s * (1 - f));

    switch (i) {
        case 0:
            *r = v;
            *g = t;
            *b = p;
            break;
        case 1:
            *r = q;
            *g = v;
            *b = p;
            break;
        case 2:
            *r = p;
            *g = v;
            *b = t;
            break;
        case 3:
            *r = p;
            *g = q;
            *b = v;
            break;
        case 4:
            *r = t;
            *g = p;
            *b = v;
            break;
        default:
            *r = v;
            *g = p;
            *b = q;
            break;
    }

    *r *= 255;
    *g *= 255;
    *b *= 255;
}

void sigint_handler(int signum) {
    closelog();
    gpioTerminate();
    exit(0);
}

int main() {
    float r, g, b;
    float hue;
    int i;

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio library");
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    srand((unsigned int)time(NULL));

    while (1) {
        hue = (float)(rand() % 360);
        hsv_to_rgb(hue, 100, 100, &r, &g, &b);

        for (i = 0; i < PWM_RANGE; i++) {
            if (gpioPWM(RED_PIN, PWM_FREQ, (PWM_RANGE - i) * 1000) < 0) {
                syslog(LOG_ERR, "Failed to set PWM for red pin");
            }
            if (gpioPWM(GREEN_PIN, PWM_FREQ, (PWM_RANGE - i) * 1000) < 0) {
                syslog(LOG_ERR, "Failed to set PWM for green pin");
            }
            if (gpioPWM(BLUE_PIN, PWM_FREQ, (PWM_RANGE - i) * 1000) < 0) {
                syslog(LOG_ERR, "Failed to set PWM for blue pin");
            }
            time_sleep(0.1);
        }

        for (i = 0; i < PWM_RANGE; i++) {
