#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <bh1750.h>

#define LED_PIN 18
#define SENSOR_ADDR 0x23
#define RETRY_DELAY 1000000 // 1 second

void handle_sigint(int sig) {
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    int sensor = i2cOpen(1, SENSOR_ADDR, 0);
    if (sensor < 0) {
        fprintf(stderr, "Failed to open I2C sensor\n");
        return 1;
    }

    int result = i2cWriteByte(sensor, 0x10);
    if (result < 0) {
        fprintf(stderr, "Failed to write to I2C sensor\n");
        return 1;
    }

    while (1) {
        usleep(180000); // wait 180 ms

        char data[2];
        result = i2cReadDevice(sensor, data, 2);
        if (result < 0) {
            fprintf(stderr, "Failed to read from I2C sensor\n");
            return 1;
        }

        float lux = (data[0] << 8 | data[1]) / 1.2;
        printf("Light: %.2f lux\n", lux);

        // Map light levels to LED brightness
        float brightness = (log(lux + 1) / log(1000)) * 255;
        if (brightness < 0) brightness = 0;
        if (brightness > 255) brightness = 255;

        gpioPWM(LED_PIN, brightness);
    }

    i2cClose(sensor);
    gpioTerminate();

    return 0;
}

