#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <math.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>

#define GPIO_PIN 18
#define I2C_DEV "/dev/i2c-1"
#define VEML7700_ADDR 0x10
#define VEML7700_REG_CONF 0x00
#define VEML7700_REG_ALS 0x04
#define RETRY_DELAY 100000
#define GAMMA_CORRECTION 2.2
#define THRESHOLD 10000

int i2c_fd;
struct gpiod_chip *chip;
struct gpiod_line *line;

void cleanup(int signum) {
    gpiod_line_release(line);
    close(i2c_fd);
    exit(0);
}

int read_i2c(int addr, int reg) {
    int ret;
    for (int i = 0; i < 3; i++) {
        if (write(i2c_fd, &reg, 1) != 1) {
            perror("Failed to write to the i2c bus");
            return -1;
        }
        if (read(i2c_fd, &ret, 2) != 2) {
            perror("Failed to read from the i2c bus");
            usleep(RETRY_DELAY);
            continue;
        }
        return ret;
    }
    fprintf(stderr, "Failed to read from the sensor after 3 attempts\n");
    return -1;
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open the i2c bus");
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        perror("Failed to acquire bus access or talk to slave");
        return 1;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip");
        return 1;
    }
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get line");
        return 1;
    }
    if (gpiod_line_request_output(line, "ws2812b", 0) < 0) {
        perror("Failed to set line as output");
        return 1;
    }

    uint16_t conf = 0x0000;
    write(i2c_fd, &conf, 2);

    while (1) {
        int raw = read_i2c(VEML7700_ADDR, VEML7700_REG_ALS);
        if (raw < 0) continue;

        double lux = raw * 0.0288;
        int brightness = (int)(255 * pow(lux / 120000.0, GAMMA_CORRECTION));
        if (brightness > 255) brightness = 255;

        printf("Lux: %f, Brightness: %d\n", lux, brightness);

        for (int i = 0; i < brightness; i++) {
            gpiod_line_set_value(line, 1);
            gpiod_line_set_value(line, 0);
            usleep(12); // 800 kHz
        }

        usleep(200000); // 200 ms delay
    }

    return 0;
}

