#define GPIO_VAL "/sys/class/gpio/gpio17/value"
#define BUFFER_SIZE 60
#define DELAY 1000000

int i2c_fd, gpio_fd;
double buffer[BUFFER_SIZE];
int buffer_index = 0;

void cleanup(int signum) {
    write(gpio_fd, "0", 1);
    close(i2c_fd);
    close(gpio_fd);
    write(gpio_fd, "17", 2);
    exit(0);
}

double get_lux() {
    char data[2];
    if (read(i2c_fd, data, 2) != 2) {
        perror("Failed to read from I2C");
        return -1;
    }
    return (data[0] << 8 | data[1]) / 1.2;
}

double get_average() {
    double sum = 0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += buffer[i];
    }
    return sum / BUFFER_SIZE;
}

int main() {
    signal(SIGINT, cleanup);

    if ((i2c_fd = open(I2C_DEV, O_RDWR)) < 0) {
        perror("Failed to open I2C");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to select I2C address");
        return 1;
