    if (gpio_direction) {
        fprintf(gpio_direction, "out");
        fclose(gpio_direction);
    }

    while (1) {
        double lux = get_lux();
        if (lux >= 0) {
            buffer[buffer_index++] = lux;
            if (buffer_index == BUFFER_SIZE) {
                buffer_index = 0;
            }
            double avg = get_average();
            double freq = 0.5 + avg / 1000 * 4.5;
            if (freq < 0.5) {
                freq = 0.5;
            }
            if (freq > 5.0) {
                freq = 5.0;
            }
            usleep(DELAY / freq / 2);
            write(gpio_fd, "1", 1);
            usleep(DELAY / freq / 2);
            write(gpio_fd, "0", 1);
        }
        usleep(DELAY);
    }

