#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LED 17
#define GPIO_BUTTON 18

struct gpiod_chip *chip;
struct gpiod_line *led_line, *button_line;
struct gpiod_line_request_config req_config;

void signal_handler(int signum) {
    printf("Exiting...\n");
    gpiod_line_release(led_line);
    gpiod_line_release(button_line);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, GPIO_LED);
    if (!led_line) {
        perror("Failed to get LED line");
        return 1;
    }

    button_line = gpiod_chip_get_line(chip, GPIO_BUTTON);
    if (!button_line) {
        perror("Failed to get button line");
        return 1;
    }

    req_config.consumer = "blink_button";
    req_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    if (gpiod_line_request(led_line, &req_config, 0) < 0) {
        perror("Failed to request LED line");
        return 1;
    }

    req_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    req_config.flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP;
    if (gpiod_line_request(button_line, &req_config, 0) < 0) {
        perror("Failed to request button line");
        return 1;
    }

    while (1) {
        if (gpiod_line_set_value(led_line, 1) < 0) {
            perror("Failed to set LED line value");
            return 1;
        }
        usleep(1000000);

        if (gpiod_line_set_value(led_line, 0) < 0) {
            perror("Failed to set LED line value");
            return 1;
        }
        usleep(1000000);

        struct gpiod_line_event evt;
        if (gpiod_line_event_wait(button_line, NULL, 1000000000) > 0) {
            if (gpiod_line_event_read(button_line, &evt) < 0) {
                perror("Failed to read button event");
                return 1;
            }
            if (evt.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
                printf("Button pressed, stopping blinking...\n");
                break;
            }
        }
    }

    gpiod_line_release(led_line);
    gpiod_line_release(button_line);
    gpiod_chip_close(chip);

    return 0;
}

