#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define RED_GPIO 24
#define GREEN_GPIO 23
#define BLUE_GPIO 18

#define PWM_PERIOD 10000000 // 10 ms
#define PWM_DUTY_CYCLE_MAX 1000000 // 10% of 100 ms

struct gpiod_line *red_line, *green_line, *blue_line;
struct gpiod_chip *chip;

void cleanup(int signum) {
    gpiod_line_release(red_line);
    gpiod_line_release(green_line);
    gpiod_line_release(blue_line);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    signal(SIGINT, cleanup);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    red_line = gpiod_chip_get_line(chip, RED_GPIO);
    green_line = gpiod_chip_get_line(chip, GREEN_GPIO);
    blue_line = gpiod_chip_get_line(chip, BLUE_GPIO);

    if (!red_line || !green_line || !blue_line) {
        perror("Failed to get GPIO lines");
        return 1;
    }

    if (gpiod_line_request_output(red_line, "RGB LED", 0) < 0) {
        perror("Failed to request red line as output");
        return 1;
    }

    if (gpiod_line_request_output(green_line, "RGB LED", 0) < 0) {
        perror("Failed to request green line as output");
        return 1;
    }

    if (gpiod_line_request_output(blue_line, "RGB LED", 0) < 0) {
        perror("Failed to request blue line as output");
        return 1;
    }

    srand(time(NULL));

    while (1) {
        int red_duty_cycle = rand() % PWM_DUTY_CYCLE_MAX;
        int green_duty_cycle = rand() % PWM_DUTY_CYCLE_MAX;
        int blue_duty_cycle = rand() % PWM_DUTY_CYCLE_MAX;

        for (int i = 0; i < red_duty_cycle; i++) {
            gpiod_line_set_value(red_line, 1);
            clock_nanosleep(CLOCK_MONOTONIC, 0, &(struct timespec){0, PWM_PERIOD / red_duty_cycle}, NULL);
            gpiod_line_set_value(red_line, 0);
            clock_nanosleep(CLOCK_MONOTONIC, 0, &(struct timespec){0, PWM_PERIOD / red_duty_cycle}, NULL);
        }

        for (int i = 0; i < green_duty_cycle; i++) {
            gpiod_line_set_value(green_line, 1);
            clock_nanosleep(CLOCK_MONOTONIC, 0, &(struct timespec){0, PWM_PERIOD / green_duty_cycle}, NULL);
            gpiod_line_set_value(green_line, 0);
            clock_nanosleep(CLOCK_MONOTONIC, 0, &(struct timespec){0, PWM_PERIOD / green_duty_cycle}, NULL);
        }

