#define I2C_ADDR 0x19
#define I2C_BUS 1
#define GPIO_OUTPUT 17
#define GRAVITY 9.80665
#define DEFAULT_THRESHOLD 2.0

int i2cHandle;

void sigint_handler(int sig) {
    gpioTerminate();
    i2cClose(i2cHandle);
    exit(0);
}

double getAcceleration() {
    unsigned char buffer[6];
    i2cReadDevice(i2cHandle, buffer, 6);
    int x = (buffer[1] << 8) | buffer[0];
    int y = (buffer[3] << 8) | buffer[2];
    int z = (buffer[5] << 8) | buffer[4];
    return sqrt(x*x + y*y + z*z) / 16384.0 * GRAVITY;
}

int main(int argc, char *argv[]) {
    double threshold = DEFAULT_THRESHOLD;
    if (argc > 1) {
        threshold = atof(argv[1]);
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
