    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    char config[2] = {0x27, 0x00};
    i2cWriteDevice(i2cHandle, config, 2);

    gpioSetMode(GPIO_OUTPUT, PI_OUTPUT);

    while (1) {
        double accel = getAcceleration();
        if (accel > threshold) {
            gpioWrite(GPIO_OUTPUT, 1);
            sleep(50);
