#define I2C_HANDLE 1
#define I2C_ADDR 0x39
#define MODE_REG 0x0D
#define ALS_LSB_REG 0x64
#define ALS_MSB_REG 0x65
#define RED_REG 0x66
#define GREEN_REG 0x68
#define BLUE_REG 0x6A
#define PWM_GPIO 18

int i2cHandle;
FILE *csvFile;

void signalHandler(int signum) {
    gpioWrite(PWM_GPIO, 0);
    gpioTerminate();
    i2cClose(i2cHandle);
    fclose(csvFile);
    exit(signum);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    i2cHandle = i2cOpen(I2C_HANDLE, I2C_ADDR, 0);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        return 1;
    }

    if (i2cWriteByteData(i2cHandle, MODE_REG, 0x01) < 0) {
        fprintf(stderr, "Failed to write to MODE_REG\n");
        return 1;
    }

    csvFile = fopen("color_log.csv", "w");
