#define I2C_ADDR 0x1F
#define WHO_AM_I 0x0D
#define CTRL_REG1 0x2A
#define XYZ_DATA_CFG 0x0E
#define OUT_X_MSB 0x01
#define WHO_AM_I_VAL 0xC7

volatile sig_atomic_t stop;

void sigint_handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    int handle = i2cOpen(1, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        return 1;
    }

    char who_am_i;
    if (i2cReadByteData(handle, WHO_AM_I) != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I register does not match expected value\n");
        return 1;
    }

    i2cWriteByteData(handle, CTRL_REG1, 0x00); // Place into standby
    i2cWriteByteData(handle, XYZ_DATA_CFG, 0x00); // Configure for ±2g mode
    i2cWriteByteData(handle, CTRL_REG1, 0x01); // Activate in active mode

    while (!stop) {
        char data[6];
        i2cReadI2CBlockData(handle, OUT_X_MSB, data, 6);

        int16_t x = (data[0] << 8) | data[1];
        int16_t y = (data[2] << 8) | data[3];
        int16_t z = (data[4] << 8) | data[5];

        double x_g = (double)x / 4096 * 9.81;
        double y_g = (double)y / 4096 * 9.81;
        double z_g = (double)z / 4096 * 9.81;

        double magnitude = sqrt(x_g * x_g + y_g * y_g + z_g * z_g);

        if (magnitude > 19.62) {
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char timestamp[20];
            strftime(timestamp, 20, "%F %T", tm_info);

            FILE *file = fopen("impact_log.txt", "a");
            fprintf(file, "%s,%.3f,%.3f,%.3f,%.3f\n", timestamp, x_g, y_g, z_g, magnitude);
            fclose(file);
        }

        gpioDelay(500000); // Delay for 50 ms
    }

    i2cClose(handle);
    gpioTerminate();

    return 0;
}

