#include <stdio.h>
#include <stdlib.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <unistd.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <time.h>
#include <signal.h>

#define I2C_ADDR 0x69
#define I2C_BUS 1
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define WHO_AM_I 0x0F
#define SENSITIVITY 0.00875
#define MAX_RATE 50.0

int fd;

void sig_handler(int signum) {
    close(fd);
    remove("gyro_log.txt");
    exit(0);
}

int main() {
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    if ((fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire bus access or talk to slave");
        return 1;
    }

    if (wiringPiI2CWriteReg8(fd, CTRL_REG1, 0x0F) < 0) {
        perror("Failed to write to CTRL_REG1");
        return 1;
    }

    if (wiringPiI2CWriteReg8(fd, CTRL_REG4, 0x00) < 0) {
        perror("Failed to write to CTRL_REG4");
        return 1;
    }

    if (wiringPiI2CWriteReg8(fd, CTRL_REG1, 0x0F) < 0) {
        perror("Failed to restart CTRL_REG1");
        return 1;
    }

    if (wiringPiI2CReadReg8(fd, WHO_AM_I) != 0xD3) {
        fprintf(stderr, "Sensor not found\n");
        return 1;
    }

    FILE *log_file = fopen("gyro_log.txt", "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    for (int i = 0; i < 100; i++) {
        short x = wiringPiI2CReadReg16(fd, OUT_X_L);
        short y = wiringPiI2CReadReg16(fd, OUT_X_L + 2);
        short z = wiringPiI2CReadReg16(fd, OUT_X_L + 4);

        double x_dps = x * SENSITIVITY;
        double y_dps = y * SENSITIVITY;
        double z_dps = z * SENSITIVITY;

        time_t now = time(NULL);
        struct tm *ptm = localtime(&now);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", ptm);

        fprintf(log_file, "%s,%f,%f,%f\n", timestamp, x_dps, y_dps, z_dps);

        if (x_dps > MAX_RATE || y_dps > MAX_RATE || z_dps > MAX_RATE) {
            fprintf(stderr, "Warning: Axis exceeding maximum rate\n");
            fprintf(log_file, "ALERT: Axis exceeding maximum rate\n");
        }

        usleep(50000);
    }

    fclose(log_file);
    close(fd);
    return 0;
}

