#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69
#define DATA_REG 0x01
#define CTRL_REG 0x00
#define SAMPLE_INTERVAL 10000 // in microseconds

FILE *log_file;

void sigint_handler(int sig) {
    fclose(log_file);
    gpioTerminate();
    exit(0);
}

int main() {
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        perror("Unable to catch SIGINT");
        exit(1);
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Unable to initialize pigpio\n");
        return 1;
    }

    log_file = fopen("audio_log.dat", "w");
    if (log_file == NULL) {
        perror("Unable to open log file");
        return 1;
    }

    int sensor1_handle = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    int sensor2_handle = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);

    if (sensor1_handle < 0 || sensor2_handle < 0) {
        fprintf(stderr, "Unable to open I2C handles\n");
        return 1;
    }

    char ctrl_data = 0x80;
    i2cWriteByte(sensor1_handle, CTRL_REG, ctrl_data);
    i2cWriteByte(sensor2_handle, CTRL_REG, ctrl_data);

    while (1) {
        struct timespec timestamp;
        clock_gettime(CLOCK_REALTIME, &timestamp);

        int sensor1_data = i2cReadWord(sensor1_handle, DATA_REG);
        int sensor2_data = i2cReadWord(sensor2_handle, DATA_REG);

        if (sensor1_data >= 0 && sensor2_data >= 0) {
            int tdoa = sensor2_data - sensor1_data;
            fprintf(log_file, "%d,%d,%d,%d,%d\n", timestamp.tv_sec, timestamp.tv_nsec, sensor1_data, sensor2_data, tdoa);
        }

        gpioDelay(SAMPLE_INTERVAL);
    }

    return 0;
}

