                perror("Failed to read from SPI device");
                return 1;
            }

            uint16_t val = (rx[0] << 8) | rx[1];
            float scale = (reg == 0x04 || reg == 0x06 || reg == 0x08) ? 0.02 : 0.00025;
            float reading = val * scale;

