#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <math.h>

#define ADXL345_ADDR 0x53
#define POWER_CTL 0x2D
#define DATAX0 0x32
#define DEVICE_ID 0x00
#define GPIOPIN 17
#define SCALE_FACTOR 256.0
#define THRESHOLD 2.5
#define SAMPLE_RATE 100 // in ms

void write_i2c(int handle, char reg, char val) {
    char buf[2] = {reg, val};
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        perror("Failed to write to I2C device");
        exit(1);
    }
}

char read_i2c(int handle, char reg) {
    char val;
    if (i2cWriteDevice(handle, &reg, 1) != 1) {
        perror("Failed to write to I2C device");
        exit(1);
    }
    if (i2cReadDevice(handle, &val, 1) != 1) {
        perror("Failed to read from I2C device");
        exit(1);
    }
    return val;
}

int main() {
    if (gpioInitialise() < 0) {
        perror("Failed to initialize GPIO");
        return 1;
    }

    int handle = i2cOpen(1, ADXL345_ADDR, 0);
    if (handle < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (read_i2c(handle, DEVICE_ID) != 0xE5) {
        perror("Failed to verify device ID");
        return 1;
    }

    write_i2c(handle, POWER_CTL, 0x08);

    FILE *log_file = fopen("impact_log.txt", "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    gpioSetMode(GPIOPIN, PI_OUTPUT);

    while (1) {
        int x = read_i2c(handle, DATAX0);
        int y = read_i2c(handle, DATAX0 + 1);
        int z = read_i2c(handle, DATAX0 + 2);

        double magnitude = sqrt(x * x + y * y + z * z) / SCALE_FACTOR;

        if (magnitude > THRESHOLD) {
            gpioWrite(GPIOPIN, 1);
            time_t now = time(NULL);
            fprintf(log_file, "%s: Magnitude: %f, X: %d, Y: %d, Z: %d\n", ctime(&now), magnitude, x, y, z);
            fflush(log_file);
            time_sleep(500);
            gpioWrite(GPIOPIN, 0);
        }

        time_sleep(SAMPLE_RATE);
    }

    fclose(log_file);
    i2cClose(handle);
    gpioTerminate();

    return 0;
}

