            time_t now = time(NULL);
            fprintf(log_file, "%s: Magnitude: %f, X: %d, Y: %d, Z: %d\n", ctime(&now), magnitude, x, y, z);
            fflush(log_file);
            time_sleep(500);
            gpioWrite(GPIOPIN, 0);
        }

        time_sleep(SAMPLE_RATE);
    }

    fclose(log_file);
    i2cClose(handle);
    gpioTerminate();

    return 0;
}
