int i2c_fd, gpio_fd;
struct gpiod_chip *chip;
struct gpiod_line *line;

void cleanup(int signum) {
    close(i2c_fd);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Open I2C device
    if ((i2c_fd = open(I2C_DEV, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return 1;
    }

    // Open GPIO chip
    if ((chip = gpiod_chip_open_by_name("gpiochip0")) == NULL) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (gpiod_line_request_output(line, "accelerometer_led", 0) < 0) {
        perror("Failed to request GPIO line");
        return 1;
    }

    // Verify sensor identity
    char who_am_i;
    if (read(i2c_fd, &who_am_i, 1) != 1 || who_am_i != 0x1A) {
        perror("Failed to verify sensor identity");
        return 1;
    }

    // Main loop
    while (1) {
        // Read acceleration data
        char data[6];
        if (read(i2c_fd, data, 6) != 6) {
            perror("Failed to read acceleration data");
            return 1;
        }

        // Compute magnitude
        int x = (data[0] << 8) | data[1];
        int y = (data[2] << 8) | data[3];
        int z = (data[4] << 8) | data[5];
        int magnitude = sqrt(x * x + y * y + z * z);

        // Check threshold
        if (magnitude > THRESHOLD) {
            // Turn LED on
            gpiod_line_set_value(line, 1);

            // Append timestamped entry to 'impact_log.txt'
            FILE *log_file = fopen("impact_log.txt", "a");
            time_t now = time(NULL);
            fprintf(log_file, "%s: Impact detected\n", ctime(&now));
            fclose(log_file);

            // Wait for 500 ms
            usleep(500000);

            // Turn LED off
            gpiod_line_set_value(line, 0);
        }

        // Wait for 100 ms
        usleep(100000);
    }

    return 0;
}

