#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <stdio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS (8 | 0x40) // CPOL=1, CPHA=1

#define WHO_AM_I_REG 0x00
#define WHO_AM_I_VAL 0x3F5A

#define X_GYRO_OUT_REG 0x14

#define SCALE 0.0305

FILE *log_file;

void sigint_handler(int sig) {
    fclose(log_file);
    gpioSPI(SPI_CHANNEL, 0, 0, 0);
    gpioTerminate();
    exit(0);
}

int main() {
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        perror("Unable to catch SIGINT");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    int spi_handle = gpioSPI(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS, 16);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel: %s\n", gpioErrorText(spi_handle));
        return 1;
    }

    log_file = fopen("gyro_log.csv", "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }
    fprintf(log_file, "Timestamp,Angular Rate\n");

    unsigned char who_am_i_reg = WHO_AM_I_REG | 0x80;
    unsigned char who_am_i_val;
    if (gpioSPIXfer(spi_handle, &who_am_i_reg, 1, &who_am_i_val, 1) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register: %s\n", gpioErrorText(spi_handle));
        return 1;
    }
    if (who_am_i_val != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I register value mismatch: 0x%04X\n", who_am_i_val);
        return 1;
    }

    while (1) {
        unsigned char x_gyro_out_reg = X_GYRO_OUT_REG | 0x80;
        short x_gyro_out_val;
        if (gpioSPIXfer(spi_handle, &x_gyro_out_reg, 1, (unsigned char*)&x_gyro_out_val, 2) < 0) {
            fprintf(stderr, "Failed to read X_GYRO_OUT register: %s\n", gpioErrorText(spi_handle));
            return 1;
        }

        double angular_rate = (double)x_gyro_out_val * SCALE;
        time_t now = time(NULL);
        fprintf(log_file, "%ld,%f\n", now, angular_rate);
        fflush(log_file);

        gpioDelay(10000000); // 10 ms delay
    }

    return 0;
}

