#include <pigpio.h>
#include <stdio.h>
#include <signal.h>
#include <time.h>

#define I2C_ADDR 0x69
#define WHO_AM_I 0x0F
#define CTRL_REG1 0x0F
#define CTRL_REG4 0x00
#define OUT_X_L 0x28
#define SENSITIVITY 8.75

int i2cHandle;
FILE *file;

void signalHandler(int signum) {
    fclose(file);
    gpioTerminate();
    exit(0);
}

void initializeSensor() {
    int retryCount = 0;
    while (retryCount < 3) {
        i2cHandle = i2cOpen(1, I2C_ADDR, 0);
        if (i2cHandle >= 0) {
            break;
        }
        retryCount++;
    }
    if (i2cHandle < 0) {
        perror("Failed to initialize sensor");
        exit(1);
    }

    char whoAmI;
    i2cReadByteData(i2cHandle, WHO_AM_I, &whoAmI);
    if (whoAmI != 0xD3) {
        perror("Sensor not found");
        exit(1);
    }

    i2cWriteByteData(i2cHandle, CTRL_REG1, 0x0F);
    i2cWriteByteData(i2cHandle, CTRL_REG4, 0x00);
}

void logGyroData() {
    char data[6];
    i2cReadI2CBlockData(i2cHandle, OUT_X_L, data, 6);

    int16_t x = (data[1] << 8) | data[0];
    int16_t y = (data[3] << 8) | data[2];
    int16_t z = (data[5] << 8) | data[4];

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    fprintf(file, "%ld,%f,%f,%f\n", ts.tv_nsec, x / SENSITIVITY, y / SENSITIVITY, z / SENSITIVITY);
    fflush(file);
}

int main() {
    signal(SIGINT, signalHandler);

    if (gpioInitialise() < 0) {
        perror("Failed to initialize GPIO");
        return 1;
    }

    file = fopen("gyro_log.csv", "w");
    if (file == NULL) {
        perror("Failed to open file");
        return 1;
    }
    fprintf(file, "Timestamp,X,Y,Z\n");

    initializeSensor();

    while (1) {
        logGyroData();
        gpioDelay(10000000); // delay for 10 ms
    }

    return 0;
}

