    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    log_file = fopen("flame_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    while (!stop) {
        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        int level = gpioRead(GPIO_PIN);
        if (level == PI_BAD_GPIO) {
            fprintf(log_file, "%s - Error reading sensor\n", timestamp);
            fflush(log_file);
        } else {
            fprintf(log_file, "%s - Flame detected: %s\n", timestamp, level ? "YES" : "NO");
            fflush(log_file);

            if (level == 0) {
                printf("FLAME DETECTED!\n");
            }
        }

        gpioDelay(500000);  // 500ms delay
    }

    fclose(log_file);
    gpioTerminate();
    return 0;
}

