#include <stdio.h>
#include <stdlib.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define I2C_DEV "/dev/i2c-1"
#define I2C_ADDR 0x53
#define REG_START 0x28
#define REG_END 0x2D

int fd;
FILE *file;

void handle_sigint(int sig) {
    fclose(file);
    close(fd);
    exit(0);
}

int main() {
    signal(SIGINT, handle_sigint);

    if ((fd = open(I2C_DEV, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire bus access or talk to slave");
        return 1;
    }

    if ((file = fopen("vibration_log.csv", "w")) == NULL) {
        perror("Failed to open the CSV file");
        return 1;
    }

    fprintf(file, "Timestamp,X,Y,Z\n");

    while (1) {
        char buf[6];
        int i;

        for (i = REG_START; i <= REG_END; i++) {
            if (write(fd, &i, 1) != 1) {
                perror("Failed to write to the i2c bus");
                return 1;
            }

            if (read(fd, buf + (i - REG_START), 1) != 1) {
                perror("Failed to read from the i2c bus");
                return 1;
            }
        }

        int16_t x = (buf[1] << 8) | buf[0];
        int16_t y = (buf[3] << 8) | buf[2];
        int16_t z = (buf[5] << 8) | buf[4];

