    if ((file = fopen("vibration_log.csv", "w")) == NULL) {
        perror("Failed to open the CSV file");
        return 1;
    }

    fprintf(file, "Timestamp,X,Y,Z\n");

    while (1) {
        char buf[6];
        int i;

        for (i = REG_START; i <= REG_END; i++) {
            if (write(fd, &i, 1) != 1) {
                perror("Failed to write to the i2c bus");
                return 1;
            }

            if (read(fd, buf + (i - REG_START), 1) != 1) {
                perror("Failed to read from the i2c bus");
                return 1;
            }
        }

        int16_t x = (buf[1] << 8) | buf[0];
        int16_t y = (buf[3] << 8) | buf[2];
        int16_t z = (buf[5] << 8) | buf[4];

        time_t now = time(NULL);
        struct tm *tm_info = gmtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%FT%TZ", tm_info);

        fprintf(file, "%s,%d,%d,%d\n", timestamp, x, y, z);
        fflush(file);

        usleep(100000);
    }

    return 0;
}
