#include <math.h>
#include <time.h>

#define I2C_ADDR 0x1D
#define I2C_BUS "/dev/i2c-1"
#define WHO_AM_I 0x0D
#define CTRL_REG1 0x2A
#define OUT_X_MSB 0x01
#define OUT_Y_MSB 0x03
#define OUT_Z_MSB 0x05
#define DEG_TO_RAD (M_PI / 180.0)

int fd;
FILE *log_file;

void cleanup(int signum) {
    fclose(log_file);
    close(fd);
    exit(0);
}

int main() {
    int ret;
    char buf[2];
    short x, y, z;
    double angle;

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    if ((fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire bus access or talk to slave");
        return 1;
    }

    buf[0] = WHO_AM_I;
    if ((ret = write(fd, buf, 1)) != 1) {
        perror("Failed to write to the i2c bus");
        return 1;
    }

    if ((ret = read(fd, buf, 1)) != 1 || buf[0] != 0x2A) {
        fprintf(stderr, "Failed to verify sensor identity\n");
        return 1;
    }

    buf[0] = CTRL_REG1;
    buf[1] = 0x00;  // Standby mode
    if ((ret = write(fd, buf, 2)) != 2) {
        perror("Failed to write to the i2c bus");
        return 1;
    }

    buf[0] = CTRL_REG1;
    buf[1] = 0x10;  // Active mode, 100 Hz data rate
    if ((ret = write(fd, buf, 2)) != 2) {
        perror("Failed to write to the i2c bus");
        return 1;
    }

    log_file = fopen("fall_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    while (1) {
        buf[0] = OUT_X_MSB;
        if ((ret = write(fd, buf, 1)) != 1) {
            perror("Failed to write to the i2c bus");
            continue;
        }

        if ((ret = read(fd, buf, 6)) != 6) {
            perror("Failed to read from the i2c bus");
            continue;
        }

        x = (buf[1] << 8) | buf[0];
        y = (buf[3] << 8) | buf[2];
        z = (buf[5] << 8) | buf[4];

        angle = atan2(x, sqrt(y*y + z*z)) * 180.0 / M_PI;

        if (fabs(angle) > 45.0) {
            time_t now = time(NULL);
            fprintf(log_file, "%ld %d %d %d\n", now, x, y, z);
            fflush(log_file);
        }

        usleep(10000);
    }

    return 0;
}

