#include <pigpio.h>
#include <stdio.h>
#include <signal.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_CLOCK_SPEED 1000000
#define SPI_MODE 0

#define ADXL354_RESET 0x52
#define ADXL354_POWER_CTL 0x2D
#define ADXL354_STATUS 0x04
#define ADXL354_PARTID 0x01

#define ADXL354_RUN_BIT 0x01
#define ADXL354_STABLE_BIT 0x02

#define ADXL354_XDATA 0x08
#define ADXL354_YDATA 0x0B
#define ADXL354_ZDATA 0x0E

#define ADXL354_READ_BIT 0x80
#define ADXL354_MULTI_BYTE_BIT 0x40

#define SENSOR_PRESENT_ID 0x1D

#define LOG_FILENAME "vibration_log.txt"

int spiHandle;
FILE *logFile;

void exitHandler(int signum) {
    gpioSPI(spiHandle, 0, 0, 0);
    fclose(logFile);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    spiHandle = spiOpen(SPI_CHANNEL, SPI_CLOCK_SPEED, SPI_MODE);
    if (spiHandle < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        return 1;
    }

    logFile = fopen(LOG_FILENAME, "w");
    if (logFile == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    signal(SIGINT, exitHandler);
    signal(SIGTERM, exitHandler);

    // Reset the sensor
    spiWriteByte(spiHandle, ADXL354_RESET);
    gpioDelay(1000000);  // Wait 1 ms

    // Set the measurement mode
    char powerCtl = spiReadByte(spiHandle, ADXL354_POWER_CTL);
    powerCtl &= ~ADXL354_RUN_BIT;
    spiWriteByte(spiHandle, ADXL354_POWER_CTL, powerCtl);

    while (1) {
        char status = spiReadByte(spiHandle, ADXL354_STATUS);
        if ((status & ADXL354_STABLE_BIT) != 0) {
            powerCtl |= ADXL354_RUN_BIT;
            spiWriteByte(spiHandle, ADXL354_POWER_CTL, powerCtl);
        }

        char partId = spiReadByte(spiHandle, ADXL354_PARTID);
        if (partId != SENSOR_PRESENT_ID) {
            fprintf(stderr, "Sensor not present\n");
            return 1;
        }

        char xData = spiReadByte(spiHandle, ADXL354_XDATA | ADXL354_READ_BIT | ADXL354_MULTI_BYTE_BIT);
        char yData = spiReadByte(spiHandle, ADXL354_YDATA | ADXL354_READ_BIT | ADXL354_MULTI_BYTE_BIT);
        char zData = spiReadByte(spiHandle, ADXL354_ZDATA | ADXL354_READ_BIT | ADXL354_MULTI_BYTE_BIT);

        time_t now = time(NULL);
        fprintf(logFile, "%ld, %d, %d, %d\n", now, xData, yData, zData);
        fflush(logFile);

        gpioDelay(100000000);  // Wait 100 ms
    }

    return 0;
}

