#include <signal.h>
#include <gpiod.h>
#include <time.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE1 17
#define GPIO_LINE2 27

struct gpiod_chip *chip;
struct gpiod_line *line1, *line2;
struct gpiod_line_request_config config;

void cleanup(int signum) {
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    signal(SIGINT, cleanup);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Open chip failed");
        return -1;
    }

    line1 = gpiod_chip_get_line(chip, GPIO_LINE1);
    line2 = gpiod_chip_get_line(chip, GPIO_LINE2);
    if (!line1 || !line2) {
        perror("Get line failed");
        return -1;
    }

    config.consumer = "KY-032 Obstacle Sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    if (gpiod_line_request(line1, &config, 0) || gpiod_line_request(line2, &config, 0)) {
        perror("Request line failed");
        return -1;
    }

    while (1) {
        struct timespec ts = {0, 100*1000*1000};
        int values[2];
        if (gpiod_line_bulk_get_values(line1, 2, values) || gpiod_line_bulk_get_values(line2, 2, values+1)) {
            perror("Bulk read failed");
            return -1;
        }

        time_t t = time(NULL);
        printf("%s: Sensor 1: %s, Sensor 2: %s\n", ctime(&t), values[0] ? "Clear" : "Obstacle", values[1] ? "Clear" : "Obstacle");

        nanosleep(&ts, NULL);
    }

    return 0;
}

