#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <spidev.h>

#define SPI_DEV "/dev/spidev0.0"
#define CS_GPIO 8
#define MSC_CTRL_REG 0x24
#define X_OUT_REG 0x04
#define Y_OUT_REG 0x06
#define Z_OUT_REG 0x08
#define SCALE_FACTOR 0.02
#define READ_DELAY 100

struct gpiod_chip *chip;
struct gpiod_line *line;
int spi_fd;

void cleanup(int signum) {
    gpiod_line_release(line);
    close(spi_fd);
    exit(0);
}

int main() {
    struct spi_ioc_transfer spi[3];
    int i, ret;
    short data[3];

    signal(SIGINT, cleanup);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    line = gpiod_chip_get_line(chip, CS_GPIO);
    if (!line) {
        perror("Failed to get GPIO line");
        return 1;
    }

    ret = gpiod_line_request_output(line, "ADIS16266", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        return 1;
    }

    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Configure SPI settings here...

    while (1) {
        gpiod_line_set_value(line, 0);

        // Write to MSC_CTRL register...

        gpiod_line_set_value(line, 1);

        usleep(READ_DELAY * 1000);

        gpiod_line_set_value(line, 0);

        // Read X, Y, and Z registers...

        for (i = 0; i < 3; i++) {
            // Fill in SPI transfer structs...

            ret = ioctl(spi_fd, SPI_IOC_MESSAGE(3), spi);
            if (ret < 0) {
                perror("Failed to read SPI data");
                return 1;
            }

            data[i] = (spi[i].rx_buf[1] << 8) | spi[i].rx_buf[0];
        }

        printf("X: %f, Y: %f, Z: %f\n", data[0] * SCALE_FACTOR, data[1] * SCALE_FACTOR, data[2] * SCALE_FACTOR);
    }

    return 0;
}

