#define FXOS8700_CTRL_REG2 0x2B
#define FXOS8700_M_CTRL_REG1 0x5B
#define FXOS8700_M_CTRL_REG2 0x5C
#define FXOS8700_OUT_X_MSB 0x01

int i2cHandle;

void sigint_handler(int sig) {
    gpioTerminate();
    exit(0);
}

void setup_fxos8700() {
    // Check WHO_AM_I register
    char who_am_i;
    if (i2cReadByteData(i2cHandle, FXOS8700_WHO_AM_I) != FXOS8700_WHO_AM_I_VAL) {
        printf("FXOS8700 not found\n");
        exit(1);
    }

    // Initialize accelerometer and magnetometer in hybrid mode
    i2cWriteByteData(i2cHandle, FXOS8700_CTRL_REG1, 0x1F); // Accelerometer active, 100Hz
    i2cWriteByteData(i2cHandle, FXOS8700_CTRL_REG2, 0x00); // No self-test, no reset, no sleep
    i2cWriteByteData(i2cHandle, FXOS8700_M_CTRL_REG1, 0x1F); // Magnetometer active, 100Hz
    i2cWriteByteData(i2cHandle, FXOS8700_M_CTRL_REG2, 0x00); // No self-test, no reset, no sleep
}

