#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <signal.h>
#include <time.h>

#define ADXL345_I2C_ADDR 0x53
#define ADXL345_DEVICE "/dev/i2c-1"
#define ADXL345_XDATA 0x32
#define ADXL345_YDATA 0x34
#define ADXL345_ZDATA 0x36

int fd;

void cleanup(int signum) {
    close(fd);
    exit(0);
}

int main() {
    int x, y, z;
    double angle;
    char buffer[256];
    FILE *log_file;
    struct sigaction action;
    action.sa_handler = cleanup;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);

    if ((fd = open(ADXL345_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open i2c device");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, ADXL345_I2C_ADDR) < 0) {
        perror("Failed to acquire bus access or talk to slave");
        return 1;
    }

    log_file = fopen("/var/log/tilt_events.log", "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    while (1) {
        if (read(fd, &x, 1) != 1) {
            perror("Failed to read from the i2c bus");
            return 1;
        }
        if (read(fd, &y, 1) != 1) {
            perror("Failed to read from the i2c bus");
            return 1;
        }
        if (read(fd, &z, 1) != 1) {
            perror("Failed to read from the i2c bus");
            return 1;
        }

        angle = atan2(y, x) * 180.0 / M_PI;
        if (fabs(angle) > 30.0) {
            time_t now = time(NULL);
            struct tm *timeinfo = localtime(&now);
            strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
            fprintf(log_file, "%s: Tilt event detected at angle %.2f degrees\n", buffer, angle);
            fflush(log_file);
        }

        usleep(100000);
    }

    fclose(log_file);
    close(fd);
    return 0;
}

