#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define WINDOW_SIZE 5000 // 5 seconds at 1ms intervals

volatile sig_atomic_t stop;

void alarmHandler(int signum) {
    stop = 1;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return 1;
    }

    int threshold = atoi(argv[1]);
    if (threshold <= 0) {
        fprintf(stderr, "Invalid threshold: %s\n", argv[1]);
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);

    signal(SIGINT, alarmHandler);
    signal(SIGTERM, alarmHandler);

    while (!stop) {
        int highReadings = 0;
        for (int i = 0; i < WINDOW_SIZE; i++) {
            if (gpioRead(GPIO_PIN) == PI_HIGH) {
                highReadings++;
            }
            gpioDelay(1000); // 1ms delay
        }

        time_t now = time(NULL);
        if (highReadings > threshold) {
            printf("%s: ALERT - High readings: %d\n", ctime(&now), highReadings);
        } else {
            printf("%s: Normal - High readings: %d\n", ctime(&now), highReadings);
        }

        gpioDelay(1000000); // 1 second delay
    }

    gpioTerminate();
    return 0;
}

