#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO17 17
#define GPIO27 27
#define SECURITY_CODE_LEN 6
#define MAX_BUFFER 100

volatile sig_atomic_t stop;
struct gpiod_chip *chip;
struct gpiod_line *line17, *line27;
FILE *log_file;

void signal_handler(int signum) {
    stop = 1;
}

void unlock_door(struct gpiod_line *line) {
    gpiod_line_set_value(line, 1);
    sleep(5);
    gpiod_line_set_value(line, 0);
}

int main() {
    char buffer[MAX_BUFFER];
    char security_code[SECURITY_CODE_LEN + 1];
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    srand((time_t)ts.tv_nsec);
    int i;
    for (i = 0; i < SECURITY_CODE_LEN; i++) {
        security_code[i] = (rand() % 10) + '0';
    }
    security_code[i] = '\0';
    printf("Security code: %s\n", security_code);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0\n");
        return 1;
    }

    line17 = gpiod_chip_get_line(chip, GPIO17);
    line27 = gpiod_chip_get_line(chip, GPIO27);
    if (!line17 || !line27) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        return 1;
    }

    if (gpiod_line_request_output(line17, "door_access", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO17 as output\n");
        return 1;
    }

    if (gpiod_line_request_output(line27, "door_access", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO27 as output\n");
        return 1;
    }

    log_file = fopen("access_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open access_log.txt\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!stop) {
        printf("Enter security code: ");
        fgets(buffer, MAX_BUFFER, stdin);
        if (strncmp(buffer, security_code, SECURITY_CODE_LEN) == 0) {
            unlock_door(line17);
            fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d,%s",
                    ts.tv_sec / 86400 + 1970, (ts.tv_sec % 86400) / 86400 + 1,
                    (ts.tv_sec % 86400 % 3600) / 3600, (ts.tv_sec % 86400 % 3600 % 60) / 60,
                    ts.tv_sec % 86400 % 3600 % 60 % 60, security_code);
            for (i = 0; i < SECURITY_CODE_LEN; i++) {
                security_code[i] = (rand() % 10) + '0';
            }
            security_code[i] = '\0';
            printf("Security code: %s\n", security_code);
        } else {
            printf("Access denied\n");
        }
    }

    gpiod_line_release(line17);
    gpiod_line_release(line27);
    gpiod_chip_close(chip);
    fclose(log_file);
    return 0;
}

