        fgets(buffer, MAX_BUFFER, stdin);
        if (strncmp(buffer, security_code, SECURITY_CODE_LEN) == 0) {
            unlock_door(line17);
            fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d,%s",
