#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pigpio.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <signal.h>

#define I2C_ADDR 0x5A
#define I2C_BUS 1
#define PWM_GPIO 18
#define SECRET_KEY "MySecretKey"
#define SAMPLE_RATE 50 // 20 ms
#define PLAY_TIME 5000 // 5 seconds

int i2cHandle;

void stop(int signum) {
    gpioWrite(PWM_GPIO, 0);
    gpioTerminate();
    close(i2cHandle);
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, stop);
    signal(SIGTERM, stop);

    i2cHandle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Initialize MPR121
    // Soft reset
    i2cWriteByte(i2cHandle, 0x2B, 0x6B);
    // Electrode configuration
    i2cWriteByte(i2cHandle, 0x2A, 0x80);

    gpioSetMode(PWM_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_GPIO, 1000);

    int serverSocket = socket(AF_INET, SOCK_STREAM, 0);
    if (serverSocket < 0) {
        fprintf(stderr, "Failed to create socket\n");
        return 1;
    }

    struct sockaddr_in serverAddress;
    serverAddress.sin_family = AF_INET;
    serverAddress.sin_addr.s_addr = INADDR_ANY;
    serverAddress.sin_port = htons(12345);

    if (bind(serverSocket, (struct sockaddr*)&serverAddress, sizeof(serverAddress)) < 0) {
        fprintf(stderr, "Failed to bind socket\n");
        return 1;
    }

    if (listen(serverSocket, 1) < 0) {
        fprintf(stderr, "Failed to listen on socket\n");
        return 1;
    }

    while (1) {
        int clientSocket = accept(serverSocket, NULL, NULL);
        if (clientSocket < 0) {
            fprintf(stderr, "Failed to accept client\n");
            return 1;
        }

        char buffer[1024];
        int bytesRead = read(clientSocket, buffer, sizeof(buffer) - 1);
        if (bytesRead < 0) {
            fprintf(stderr, "Failed to read from client\n");
            return 1;
        }

        if (strncmp(buffer, "MOTION_DETECTED:", 15) == 0 && strcmp(buffer + 15, SECRET_KEY) == 0) {
            FILE* logFile = fopen("frequency_log.txt", "w");
            if (logFile == NULL) {
                fprintf(stderr, "Failed to open log file\n");
                return 1;
            }

            for (int i = 0; i < PLAY_TIME / SAMPLE_RATE; i++) {
                usleep(SAMPLE_RATE * 1000);

                int touchData = i2cReadByte(i2cHandle, 0x03);
                int frequency = 220 + (touchData / 255.0) * (880 - 220);

                gpioPWM(PWM_GPIO, frequency);

                fprintf(logFile, "%d\n", frequency);
            }

            fclose(logFile);
        }

        close(clientSocket);
    }

    return 0;
}

