#include <stdio.h>
#include <stdlib.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <unistd.h>
#include <math.h>
#include <signal.h>
#include <gpiod.h>

#define I2C_DEV "/dev/i2c-1"
#define I2C_ADDR 0x1E
#define CTRL_REG1_M 0x20
#define OUT_X_L_M 0x08
#define PWM_CHIP "gpiochip0"
#define PWM_LINE 17

int i2c_fd;
struct gpiod_chip *chip;
struct gpiod_line *line;

void cleanup(int signum) {
    gpiod_line_release(line);
    close(i2c_fd);
    exit(0);
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire bus access or talk to slave");
        return 1;
    }

    chip = gpiod_chip_open_by_name(PWM_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    line = gpiod_chip_get_line(chip, PWM_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        return 1;
    }

    if (gpiod_line_request_output(line, "lsm303dlhc", 0) < 0) {
        perror("Failed to set GPIO line as output");
        return 1;
    }

    char buf[2] = {CTRL_REG1_M, 0x18};
    if (write(i2c_fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        return 1;
    }

    while (1) {
        buf[0] = OUT_X_L_M;
        if (write(i2c_fd, buf, 1) != 1) {
            perror("Failed to write to I2C device");
            return 1;
        }

        if (read(i2c_fd, buf, 6) != 6) {
            perror("Failed to read from I2C device");
            return 1;
        }

        int x = (buf[1] << 8) | buf[0];
        int y = (buf[3] << 8) | buf[2];
        int z = (buf[5] << 8) | buf[4];

        double magnitude = sqrt(x * x + y * y + z * z);
        int brightness = (int)(magnitude * 100.0);

        if (gpiod_line_set_value(line, brightness) < 0) {
            perror("Failed to set GPIO line value");
            return 1;
        }

        usleep(100000);
    }

    return 0;
}

