#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define HMC5883L_ADDR 0x1E
#define HMC5883L_CONFIG_A 0x70
#define HMC5883L_CONFIG_B 0x20
#define HMC5883L_MODE 0x00
#define SAMPLE_WINDOW 100
#define SAMPLE_RATE 500

volatile sig_atomic_t stop;

void sig_handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    int i2cHandle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C handle: %d\n", i2cHandle);
        return 1;
    }

    char config[2] = {HMC5883L_CONFIG_A, HMC5883L_CONFIG_B};
    if (i2cWriteDevice(i2cHandle, config, 2) < 0) {
        fprintf(stderr, "Failed to write to device\n");
        return 1;
    }

    if (i2cWriteByte(i2cHandle, HMC5883L_MODE) < 0) {
        fprintf(stderr, "Failed to write to device\n");
        return 1;
    }

    int16_t x, y, z;
    int32_t x_sum = 0, y_sum = 0, z_sum = 0;
    int samples = 0;

    while (!stop) {
        if (i2cReadDevice(i2cHandle, (char*)&x, 2) < 0) {
            fprintf(stderr, "Failed to read from device\n");
            break;
        }
        if (i2cReadDevice(i2cHandle, (char*)&y, 2) < 0) {
            fprintf(stderr, "Failed to read from device\n");
            break;
        }
        if (i2cReadDevice(i2cHandle, (char*)&z, 2) < 0) {
            fprintf(stderr, "Failed to read from device\n");
            break;
        }

        x_sum += x;
        y_sum += y;
        z_sum += z;
        samples++;

        if (samples >= SAMPLE_WINDOW) {
            printf("X: %d, Y: %d, Z: %d\n", x_sum / samples, y_sum / samples, z_sum / samples);
            x_sum = y_sum = z_sum = 0;
            samples = 0;
        }

        gpioDelay(1000000 / SAMPLE_RATE);
    }

    i2cClose(i2cHandle);
    gpioTerminate();

    return 0;
}

