    if (i2cWriteDevice(i2cHandle, config, 2) < 0) {
        fprintf(stderr, "Failed to write to device\n");
        return 1;
    }

    if (i2cWriteByte(i2cHandle, HMC5883L_MODE) < 0) {
        fprintf(stderr, "Failed to write to device\n");
        return 1;
    }

    int16_t x, y, z;
    int32_t x_sum = 0, y_sum = 0, z_sum = 0;
    int samples = 0;

    while (!stop) {
        if (i2cReadDevice(i2cHandle, (char*)&x, 2) < 0) {
            fprintf(stderr, "Failed to read from device\n");
            break;
        }
        if (i2cReadDevice(i2cHandle, (char*)&y, 2) < 0) {
            fprintf(stderr, "Failed to read from device\n");
            break;
        }
        if (i2cReadDevice(i2cHandle, (char*)&z, 2) < 0) {
            fprintf(stderr, "Failed to read from device\n");
            break;
        }

        x_sum += x;
        y_sum += y;
        z_sum += z;
        samples++;

        if (samples >= SAMPLE_WINDOW) {
            printf("X: %d, Y: %d, Z: %d\n", x_sum / samples, y_sum / samples, z_sum / samples);
            x_sum = y_sum = z_sum = 0;
            samples = 0;
        }

        gpioDelay(1000000 / SAMPLE_RATE);
    }

    i2cClose(i2cHandle);
    gpioTerminate();

    return 0;
}
