        perror("Failed to write to CTRL_REG1");
        return 1;
    }

    if (i2c_smbus_write_byte_data(fd, 0x23, 0x00) < 0) {
        perror("Failed to write to CTRL_REG4");
        return 1;
    }

    if (i2c_smbus_write_byte_data(fd, 0x30, 0x2A) < 0) {
        perror("Failed to write to INT1_CFG");
        return 1;
    }

    if (i2c_smbus_write_byte_data(fd, 0x33, 0x7D) < 0) {
        perror("Failed to write to INT1_THS");
        return 1;
