        buffer[buffer_head].x = x;
        buffer[buffer_head].y = y;
        buffer[buffer_head].z = z;

        buffer_head = (buffer_head + 1) % BUFFER_SIZE;
        if (buffer_head == buffer_tail) {
            buffer_tail = (buffer_tail + 1) % BUFFER_SIZE;
        }

        if (gpiod_line_event_wait(line, NULL) > 0) {
            gpiod_line_event_read(line);
            for (int i = 0; i < 10; i++) {
                int index = (buffer_tail - i - 1 + BUFFER_SIZE) % BUFFER_SIZE;
                printf("(%d, %d, %d) ", buffer[index].x, buffer[index].y, buffer[index].z);
            }
            printf("\n");
        }

        usleep(10000);
    }

    return 0;
}

