#define GPIO_CHIP "gpiochip0"
#define GPIO_PIR 4
#define GPIO_RELAY 17
#define MOTION_TIMEOUT 10000 // 10 seconds

struct gpiod_chip *chip;
struct gpiod_line *pir_line, *relay_line;

void cleanup(int signum) {
    syslog(LOG_INFO, "Shutting down...");
    gpiod_line_release(pir_line);
    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);
    closelog();
    exit(0);
}

int main() {
    openlog("pir_relay", LOG_PID, LOG_USER);
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        return 1;
    }

    pir_line = gpiod_chip_get_line(chip, GPIO_PIR);
    if (!pir_line) {
        syslog(LOG_ERR, "Failed to get PIR line");
        return 1;
    }

    relay_line = gpiod_chip_get_line(chip, GPIO_RELAY);
    if (!relay_line) {
        syslog(LOG_ERR, "Failed to get RELAY line");
        return 1;
    }

    if (gpiod_line_request_input(pir_line, "pir") < 0) {
        syslog(LOG_ERR, "Failed to request PIR line as input");
        return 1;
    }

    if (gpiod_line_request_output(relay_line, "relay", 0) < 0) {
        syslog(LOG_ERR, "Failed to request RELAY line as output");
        return 1;
    }

    int motion_start = 0;
    int motion_timeout = 0;
    while (1) {
        if (gpiod_line_get_value(pir_line) == 1) {
            if (!motion_start) {
                motion_start = gpiod_get_time_ns(NULL);
                syslog(LOG_INFO, "Motion detected");
            }

            if (gpiod_get_time_ns(NULL) - motion_start > MOTION_TIMEOUT) {
                if (!motion_timeout) {
                    motion_timeout = 1;
                    syslog(LOG_WARNING, "Motion timeout, triggering failsafe");
                    gpiod_line_set_value(relay_line, 0);
                }
            } else {
                if (motion_timeout) {
                    motion_timeout = 0;
                    syslog(LOG_INFO, "Motion resumed");
                }

                gpiod_line_set_value(relay_line, 1);
                usleep(1000000); // 1 second
                gpiod_line_set_value(relay_line, 0);
                usleep(500000); // 500 ms
            }
        } else {
            if (motion_start) {
                motion_start = 0;
                syslog(LOG_INFO, "Motion stopped");
            }

            if (motion_timeout) {
                motion_timeout = 0;
                syslog(LOG_INFO, "Failsafe deactivated");
            }
        }
    }

    return 0;
}

