#define I2C_DEV "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define BUFFER_SIZE 1024

int i2c_fd;
char buffer[BUFFER_SIZE];

void handle_signal(int signum) {
    // Cleanup resources
    close(i2c_fd);
    exit(0);
}

void read_acceleration() {
    // Read acceleration data from MPU6050
    int res = read(i2c_fd, buffer, 6);
    if (res != 6) {
        perror("Failed to read from MPU6050");
        return;
    }

    // Process and log data
    int16_t accel_x = (buffer[0] << 8) | buffer[1];
    int16_t accel_y = (buffer[2] << 8) | buffer[3];
    int16_t accel_z = (buffer[4] << 8) | buffer[5];

    // Scale raw values to g
    float g_x = accel_x / 16384.0;
    float g_y = accel_y / 16384.0;
    float g_z = accel_z / 16384.0;

    // Log data to sysfs interface
    // ...
}

int main() {
    // Open I2C device
    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return 1;
    }

    // Wake up MPU6050 and set accelerometer range
    // ...

    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Set up timer
    struct sigevent sev;
    sev.sigev_notify = SIGEV_SIGNAL;
    sev.sigev_signo = SIGALRM;
    timer_t timer_id;
    if (timer_create(CLOCK_REALTIME, &sev, &timer_id) == -1) {
        perror("Failed to create timer");
        return 1;
    }

    struct itimerspec its;
    its.it_value.tv_sec = 0;
    its.it_value.tv_nsec = 100000000;  // 100 Hz
    its.it_interval = its.it_value;
    if (timer_settime(timer_id, 0, &its, NULL) == -1) {
        perror("Failed to set timer");
        return 1;
    }

    // Main loop
    while (1) {
        sleep(1);  // Sleep until next timer signal
        read_acceleration();
    }

    return 0;
}

