#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <stdio.h>

#define SENSOR_PIN 17
#define RELAY_PIN 27
#define DEBOUNCE_TIME 500 // 500 ms

volatile sig_atomic_t stop;

void alarmHandler(int signum) {
    stop = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Set sensor pin as input
    gpioSetMode(SENSOR_PIN, PI_INPUT);

    // Set relay pin as output
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Setup signal handling
    signal(SIGINT, alarmHandler);
    signal(SIGTERM, alarmHandler);

    // Initialize last activation time
    time_t lastActivation = 0;

    while (!stop) {
        // Read sensor pin
        int sensorValue = gpioRead(SENSOR_PIN);

        // Check if sound is detected and debounce mechanism is passed
        if (sensorValue && (time(NULL) - lastActivation) * 1000 > DEBOUNCE_TIME) {
            // Activate relay
            gpioWrite(RELAY_PIN, 1);

            // Log activation time
            time_t currentTime = time(NULL);
            struct tm *timeInfo = localtime(&currentTime);
            FILE *file = fopen("alarm_log.txt", "a");
            if (file != NULL) {
                fprintf(file, "%d-%02d-%02d %02d:%02d:%02d - Alarm activated\n",
                        timeInfo->tm_year + 1900, timeInfo->tm_mon + 1, timeInfo->tm_mday,
                        timeInfo->tm_hour, timeInfo->tm_min, timeInfo->tm_sec);
                fclose(file);
            }

            // Wait for 3 seconds
            gpioDelay(3000000); // 3 seconds

            // Deactivate relay
            gpioWrite(RELAY_PIN, 0);

            // Update last activation time
            lastActivation = time(NULL);
        }

        // Wait for 100 ms
        gpioDelay(100000); // 100 ms
    }

    // Deinitialize pigpio library
    gpioTerminate();

    return 0;
}

