#include <string.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 9600
#define UART_TX_PIN 14
#define UART_RX_PIN 15
#define READ_COMMAND {0xFF,0x01,0x86,0x00,0x00,0x00,0x00,0x00,0x79}
#define READ_TIMEOUT 1000
#define CHECKSUM_OFFSET 7
#define CO2_OFFSET 2
#define CO2_LENGTH 2
#define LOG_FILE "co2_log.json"
#define ERROR_LOG "co2_error.log"

void handle_sigint(int sig) {
    // Cleanup and exit
    gpioSerialClose(UART_DEVICE);
    fclose(fopen(LOG_FILE, "w"));
    fclose(fopen(ERROR_LOG, "w"));
    exit(0);
}

int main() {
    // Setup signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open UART
    int uart = gpioSerialOpen(UART_DEVICE, BAUD_RATE);
    if (uart < 0) {
        fprintf(stderr, "Failed to open UART: %s\n", gpioSerialErrorMessage(uart));
        return 1;
    }

    // Write read command
    if (gpioSerialWrite(uart, READ_COMMAND, sizeof(READ_COMMAND)) < 0) {
        fprintf(stderr, "Failed to write to UART: %s\n", gpioSerialErrorMessage(uart));
        return 1;
    }

    // Wait for response
    gpioDelay(1000000); // 1 second delay

    // Read response
    char response[9];
    int bytes_read = gpioSerialRead(uart, response, sizeof(response));
    if (bytes_read < 0) {
        fprintf(stderr, "Failed to read from UART: %s\n", gpioSerialErrorMessage(uart));
        return 1;
    }

    // Validate checksum
    int checksum = 0;
    for (int i = 0; i < CHECKSUM_OFFSET; i++) {
        checksum += response[i];
    }
    checksum = ~checksum + 1;
    if (checksum != response[CHECKSUM_OFFSET]) {
        fprintf(stderr, "Checksum mismatch\n");
        return 1;
    }

    // Extract CO2 concentration
    int co2 = (response[CO2_OFFSET] << 8) | response[CO2_OFFSET + 1];

    // Log CO2 concentration
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);
    FILE *log_file = fopen(LOG_FILE, "a");
    fprintf(log_file, "{\"timestamp\":\"%s\",\"ppm\":%d,\"error\":false}\n", timestamp, co2);
    fflush(log_file);
    fclose(log_file);

    // Cleanup
    gpioSerialClose(uart);
    gpioTerminate();

    return 0;
}

