#include <pigpio.h>
#include <i2c-dev.h>
#include <unistd.h>
#include <signal.h>
#include <stdio.h>

#define I2C_ADDR 0x1E
#define BUFFER_SIZE 100
#define TARGET_HEADING 90.0
#define DEVIATION_THRESHOLD 10.0

int i2cHandle;
double buffer[BUFFER_SIZE];
int bufferIndex = 0;

void signalHandler(int signum) {
    gpioWrite(17, 0);
    gpioTerminate();
    i2cClose(i2cHandle);
    exit(0);
}

double getHeading() {
    uint8_t data[6];
    i2cReadI2CBlockData(i2cHandle, I2C_ADDR, 0x03, data, 6);
    int x = (data[0] << 8) | data[1];
    int y = (data[2] << 8) | data[3];
    double heading = atan2(y, x) * 180 / M_PI;
    if(heading < 0) heading += 360;
    return heading;
}

void updateGPIO(double heading) {
    double target = TARGET_HEADING;
    if(target > 360) target -= 360;
    double deviation = fabs(heading - target);
    if(deviation > 180) deviation = 360 - deviation;
    if(deviation > DEVIATION_THRESHOLD) {
        gpioWrite(17, 1);
    } else {
        gpioWrite(17, 0);
    }
}

int main() {
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    if(gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    i2cHandle = i2cOpen(1, I2C_ADDR, 0);
    if(i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        return 1;
    }

    if(gpioSetMode(17, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        return 1;
    }

    uint8_t config_a = 0x70;
    uint8_t config_b = 0x20;
    uint8_t mode = 0x00;
    i2cWriteByteData(i2cHandle, 0x00, config_a);
    i2cWriteByteData(i2cHandle, 0x01, config_b);
    i2cWriteByteData(i2cHandle, 0x02, mode);

    while(1) {
        double heading = getHeading();
        buffer[bufferIndex] = heading;
        bufferIndex = (bufferIndex + 1) % BUFFER_SIZE;
        updateGPIO(heading);
        usleep(100000);
    }

    return 0;
}

