#include <sys/ioctl.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>

#define I2C_ADDR 0x23
#define I2C_BUS "/dev/i2c-1"
#define RED_RELAY 17
#define GREEN_RELAY 27
#define BLUE_RELAY 22

int i2c_fd;
struct gpiod_chip *chip;
struct gpiod_line *red, *green, *blue;

void cleanup(int signum) {
    gpiod_line_release(red);
    gpiod_line_release(green);
    gpiod_line_release(blue);
    gpiod_chip_close(chip);
    close(i2c_fd);
    printf("Exiting...\n");
    exit(0);
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    red = gpiod_chip_get_line(chip, RED_RELAY);
    green = gpiod_chip_get_line(chip, GREEN_RELAY);
    blue = gpiod_chip_get_line(chip, BLUE_RELAY);

    if (!red || !green || !blue) {
        perror("Failed to get GPIO lines");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return 1;
    }

    // Configure BH1750 for continuous high-resolution mode
    char config[] = {0x10, 0x00};
    if (write(i2c_fd, config, 2) != 2) {
        perror("Failed to write to I2C bus");
        return 1;
    }

    while (1) {
        usleep(120000);  // Wait at least 120 ms for the first conversion

        char data[2];
        if (read(i2c_fd, data, 2) != 2) {
            perror("Failed to read from I2C bus");
            return 1;
        }

        float lux = (data[0] * 256 + data[1]) / 1.2;

        if (lux < 50) {
            gpiod_line_set_value(red, 1);
            gpiod_line_set_value(green, 0);
            gpiod_line_set_value(blue, 0);
        } else if (lux < 150) {
            gpiod_line_set_value(red, 0);
            gpiod_line_set_value(green, 1);
            gpiod_line_set_value(blue, 0);
        } else if (lux < 300) {
            gpiod_line_set_value(red, 0);
            gpiod_line_set_value(green, 0);
            gpiod_line_set_value(blue, 1);
        } else {
            gpiod_line_set_value(red, 1);
            gpiod_line_set_value(green, 1);
            gpiod_line_set_value(blue, 1);
        }

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", tm_info);

        FILE *log_file = fopen("lighting_log.txt", "a");
        if (log_file) {
            fprintf(log_file, "%s, Lux: %.2f, Red: %d, Green: %d, Blue: %d\n",
                    timestamp, lux,
                    gpiod_line_get_value(red),
                    gpiod_line_get_value(green),
                    gpiod_line_get_value(blue));
            fclose(log_file);
        } else {
            perror("Failed to open log file");
        }
    }

    return 0;
}

