        gpioDelay(STEP_DELAY);
        gpioWrite(IN1, 1);
        gpioDelay(STEP_DELAY);
        gpioWrite(IN1, 0);
        gpioDelay(STEP_DELAY);
    }
    lock_state = false;
    printf("Unlocked\n");
}

