#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN_1 4
#define GPIO_PIN_2 17
#define GPIO_PIN_3 27
#define GPIO_PIN_4 22

#define PWM_FREQ 100
#define PWM_RANGE 100

typedef struct {
    int hour;
    int minute;
    int second;
    int relay;
    int state;
} schedule_entry;

void cleanup(int signum);
int read_schedule(const char *filename, schedule_entry *entries);
void handle_schedule(schedule_entry *entries, int num_entries);

int main(int argc, char *argv[])
{
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise GPIO\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN_1, PI_OUTPUT);
    gpioSetMode(GPIO_PIN_2, PI_OUTPUT);
    gpioSetMode(GPIO_PIN_3, PI_OUTPUT);
    gpioSetMode(GPIO_PIN_4, PI_OUTPUT);

    schedule_entry entries[24];
    int num_entries = read_schedule("lighting_schedule.txt", entries);

    if (num_entries < 0) {
        fprintf(stderr, "Failed to read schedule\n");
        return 1;
    }

    handle_schedule(entries, num_entries);

    return 0;
}

void cleanup(int signum)
{
    gpioTerminate();
    exit(0);
}

int read_schedule(const char *filename, schedule_entry *entries)
{
    FILE *file = fopen(filename, "r");

    if (file == NULL) {
        return -1;
    }

    char line[100];
    int i = 0;

    while (fgets(line, sizeof(line), file)) {
        if (sscanf(line, "%d:%d:%d,%d,%d", &entries[i].hour, &entries[i].minute, &entries[i].second, &entries[i].relay, &entries[i].state) != 5) {
            continue;
        }

        i++;
    }

    fclose(file);

    return i;
}

void handle_schedule(schedule_entry *entries, int num_entries)
{
    time_t now;
    struct tm *timeinfo;

    while (1) {
        time(&now);
        timeinfo = localtime(&now);

        for (int i = 0; i < num_entries; i++) {
            if (entries[i].hour == timeinfo->tm_hour && entries[i].minute == timeinfo->tm_min && entries[i].second == timeinfo->tm_sec) {
                int pin = GPIO_PIN_1 + entries[i].relay;
                int state = entries[i].state;

                gpioWrite(pin, state);

                for (int duty = 0; duty <= PWM_RANGE; duty++) {
                    gpioPWM(pin, PWM_FREQ, duty);
                    time_sleep(1);
                }

                for (int duty = PWM_RANGE; duty >= 0; duty--) {
                    gpioPWM(pin, PWM_FREQ, duty);
                    time_sleep(1);
                }
            }
        }

        time_sleep(1);
    }
}

