#define MIN_DISTANCE 2
#define MAX_DISTANCE 30
#define MIN_FREQUENCY 200
#define MAX_FREQUENCY 2000

#define SPEED_OF_SOUND 34300 // in cm/s
#define DELAY_BETWEEN_MEASUREMENTS 600000 // in microseconds

void sigint_handler(int sig) {
    gpioWrite(BUZZER, 0);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    gpioSetMode(TRIG, PI_OUTPUT);
    gpioSetMode(ECHO, PI_INPUT);
    gpioSetMode(BUZZER, PI_OUTPUT);

    while (1) {
        gpioWrite(TRIG, 1);
        gpioDelay(10); // 10 microsecond trigger pulse
        gpioWrite(TRIG, 0);

        unsigned int start_tick, end_tick;
        while (gpioRead(ECHO) == 0) {
            if (gpioRead(ECHO) == 1) {
                start_tick = gpioTick();
                break;
            }
        }

        while (gpioRead(ECHO) == 1) {
            if (gpioRead(ECHO) == 0) {
                end_tick = gpioTick();
                break;
            }
        }

        if (start_tick == 0 || end_tick == 0) {
            fprintf(stderr, "Failed to read from HC-SR04\n");
            continue;
        }

        unsigned int pulse_width = end_tick - start_tick;
        double distance = (pulse_width / 1000000.0) * (SPEED_OF_SOUND / 2); // convert to cm

        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
            continue;
        }

        double frequency = MIN_FREQUENCY + ((distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE)) * (MAX_FREQUENCY - MIN_FREQUENCY);
        gpioHardwarePWM(BUZZER, frequency, 500000); // 500000 is the duty cycle, which is 50%

        gpioDelay(DELAY_BETWEEN_MEASUREMENTS);
    }

    return 0;
}
```

This program will continuously measure the distance from the HC-SR04 sensor and set the frequency of the PWM signal on the buzzer accordingly. The frequency is linearly mapped from 200 Hz to 2000 Hz based on the measured distance. If the measured distance is outside the range 2 cm to 30 cm, an error message will be printed to stderr. If the HC-SR04 fails to read, an error message will be printed to stderr.

The program will exit gracefully when it receives a SIGINT signal (usually from pressing Ctrl+C). It will turn off the buzzer and terminate the pigpio library before exiting.

Please note that this program assumes that the HC-SR04 sensor is connected to the Raspberry Pi Zero W and the buzzer is connected to GPIO18. You may need to adjust the pin numbers according to your setup.

Also, this program uses the gpioHardwarePWM function, which is available only on the Raspberry Pi Zero W and Raspberry Pi 3. If you are using a different Raspberry Pi model, you will need to use gpioPWM function instead.

