    while (true) {
        for (int i = 0; i < 10; i++) {
            gpioHardwarePWM(gpio, 5000, 1000000); // play note
            gpioDelay(1000000); // delay between notes
            gpioHardwarePWM(gpio, 5000, 0); // stop note
