#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_LINE_NUM "17"
#define GPIO_CHIP_NAME "gpiochip0"
#define EVENT_POLL_TIMEOUT 1000
#define WINDOW_SIZE 5

volatile sig_atomic_t stop;
struct gpiod_line *line;
struct gpiod_chip *chip;
FILE *log_file;

void signal_handler(int signum) {
    stop = 1;
}

int main(int argc, char *argv[]) {
    int poll_timeout = EVENT_POLL_TIMEOUT;
    if (argc > 1) {
        poll_timeout = atoi(argv[1]);
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    line = gpiod_chip_get_line(chip, atoi(GPIO_LINE_NUM));
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        return 1;
    }

    int ret = gpiod_line_request_input(line, "vibration_sensor");
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line as input\n");
        return 1;
    }

    log_file = fopen("vibration_events.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    struct gpiod_line_event_request req;
    req.consumer = "vibration_sensor";
    req.flags = 0;
    req.num_lines = 1;
    req.lines = &line;
    req.timeout_ms = poll_timeout;

    int event_count = 0;
    int high_count = 0;
    while (!stop) {
        struct gpiod_line_event_batch *events = gpiod_line_event_request_batch(line, &req);
        if (!events) {
            fprintf(stderr, "Failed to get GPIO events\n");
            return 1;
        }

        for (size_t i = 0; i < events->num_lines; i++) {
            struct gpiod_line_event evt = events->events[i];
            time_t now = time(NULL);
            char *timestamp = ctime(&now);
            timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

            fprintf(log_file, "%s,%d\n", timestamp, evt.event_type == GPIOD_LINE_EVENT_RISING_EDGE);
            fflush(log_file);

            if (evt.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
                event_count++;
                high_count++;
            } else {
                high_count--;
            }

            if (event_count > WINDOW_SIZE) {
                if (high_count >= 3) {
                    printf("EARTHQUAKE ALERT at %s\n", timestamp);
                }
                event_count--;
            }
        }

        gpiod_line_event_batch_free(events);
    }

    gpiod_line_release(line);
    fclose(log_file);
    gpiod_chip_close(chip);

    return 0;
}

