#define I2C_DEV "/dev/i2c-1"
#define I2C_ADDR 0x1E
#define REG_CRA_REG_M 0x00
#define REG_MR_REG_M 0x02
#define REG_OUT_X_H 0x03
#define REG_OUT_Y_H 0x05
#define REG_OUT_Z_H 0x07

int fd;

void cleanup(int signum) {
    close(fd);
    remove("mag_log.csv");
    exit(0);
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    if ((fd = open(I2C_DEV, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire bus access or talk to slave");
        return 1;
    }

    char buf[2] = {0};
    buf[0] = REG_CRA_REG_M;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write to the i2c bus");
        return 1;
    }

    buf[0] = 0x14;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write to the i2c bus");
        return 1;
    }

    buf[0] = REG_MR_REG_M;
    buf[1] = 0x00;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to the i2c bus");
        return 1;
