#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <stdio.h>
#include <unistd.h>
#include <jansson.h>

#define GPIO_TTP223 4
#define GPIO_RELAY 17
#define DEBOUNCE_TIME 200 // in ms

volatile sig_atomic_t signal_received = 0;

void signal_handler(int sig) {
    signal_received = 1;
}

void touch_callback(int gpio, int level, uint32_t tick) {
    static uint32_t last_touch_time = 0;
    uint32_t current_time = gpioTick();

    if ((current_time - last_touch_time) > (DEBOUNCE_TIME * 1000)) {
        gpioWrite(GPIO_RELAY, level == PI_LOW ? PI_HIGH : PI_LOW);

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%FT%TZ", tm_info);

        json_t *root = json_object();
        json_object_set_new(root, "timestamp", json_string(timestamp));
        json_object_set_new(root, "relay_state", json_string(level == PI_LOW ? "OFF" : "ON"));

        FILE *file = fopen("relay_log.json", "a");
        if (file) {
            fprintf(file, "%s\n", json_dumps(root, 0));
            fclose(file);
        }

        json_decref(root);

        last_touch_time = current_time;
    }
}

int main() {
    signal(SIGINT, signal_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    gpioSetMode(GPIO_TTP223, PI_INPUT);
    gpioSetPullUpDown(GPIO_TTP223, PI_PUD_DOWN);
    gpioSetISRFunc(GPIO_TTP223, EITHER_EDGE, 50, touch_callback);

    while (!signal_received) {
        sleep(1);
    }

    gpioWrite(GPIO_RELAY, PI_LOW);

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%FT%TZ", tm_info);

    json_t *root = json_object();
    json_object_set_new(root, "timestamp", json_string(timestamp));
    json_object_set_new(root, "relay_state", json_string("OFF"));

    FILE *file = fopen("relay_log.json", "a");
    if (file) {
        fprintf(file, "%s\n", json_dumps(root, 0));
        fclose(file);
    }

    json_decref(root);

    gpioTerminate();

    return 0;
}

