#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_PIN_17 17
#define GPIO_PIN_23 23
#define GPIO_PIN_24 24
#define GPIO_PIN_25 25
#define TIME_INTERVAL 10
#define RELAY_ACTIVE 0
#define RELAY_INACTIVE 1

struct gpiod_chip *chip;
struct gpiod_line *lines[4];
FILE *log_file;

void activate_relay(int pin, int moisture_level) {
    struct timespec ts = {5, 0};
    if (gpiod_line_set_value(lines[pin], RELAY_ACTIVE) < 0) {
        perror("Failed to activate relay");
    } else {
        fprintf(log_file, "[%s] Activated relay %d with moisture level %d\n",
                time_iso8601(), pin, moisture_level);
        fflush(log_file);
    }
    nanosleep(&ts, NULL);
    if (gpiod_line_set_value(lines[pin], RELAY_INACTIVE) < 0) {
        perror("Failed to deactivate relay");
    } else {
        fprintf(log_file, "[%s] Deactivated relay %d\n", time_iso8601(), pin);
        fflush(log_file);
    }
}

void signal_handler(int signum) {
    for (int i = 0; i < 4; i++) {
        gpiod_line_set_value(lines[i], RELAY_INACTIVE);
    }
    fclose(log_file);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_file = fopen("irrigation_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    for (int i = 0; i < 4; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_PIN_17 + i);
        if (lines[i] == NULL) {
            perror("Failed to get GPIO line");
            return 1;
        }
        if (gpiod_line_request_output(lines[i], "irrigation_system", 1) < 0) {
            perror("Failed to request GPIO line as output");
            return 1;
        }
    }

    srand(time(NULL));
    while (1) {
        int moisture_level = rand() % 101;
        for (int i = 0; i < 4; i++) {
            if (moisture_level < 30) {
                activate_relay(i, moisture_level);
            }
        }
        sleep(TIME_INTERVAL);
    }

    return 0;
}

