    stop = 1;
    gpioServo(VALVE_SERVO, 0);
    gpioServo(NOZZLE_SERVO, 0);
    gpioTerminate();
    exit(0);
}

int main() {
    int moisture_values[] = {20, 40, 60, 80, 100};
    int num_values = sizeof(moisture_values) / sizeof(int);
    int i, j;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gpioSetMode(VALVE_SERVO, PI_OUTPUT);
    gpioSetMode(NOZZLE_SERVO, PI_OUTPUT);

    while (!stop) {
        for (i = 0; i < num_values && !stop; i++) {
            int value = moisture_values[i];

            if (value < 50) {
                // Open the valve and start watering
                for (j = 0; j < 5 && !stop; j++) {
                    int angle = 45 * j;
                    int pulsewidth = 500 + angle * 10;
                    if (gpioServo(VALVE_SERVO, pulsewidth) < 0) {
                        fprintf(stderr, "Failed to open valve\n");
                        break;
                    }
                    if (gpioServo(NOZZLE_SERVO, pulsewidth) < 0) {
                        fprintf(stderr, "Failed to position nozzle\n");
                        break;
                    }
                    sleep(2);
                }
                // Hold for 5 seconds
                sleep(5);

                // Close the valve
                if (gpioServo(VALVE_SERVO, 500) < 0) {
                    fprintf(stderr, "Failed to close valve\n");
                }
            } else {
                // Skip watering
                sleep(5);
            }
        }
    }

    gpioTerminate();
    return 0;
}

