#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define SPEED_OF_SOUND 34300 // in cm/s
#define MIN_GUARD_TIME 600000 // in microseconds

struct gpiod_chip *chip;
struct gpiod_line *trigger_line, *echo_line;
FILE *log_file;

void cleanup(int signum) {
    fclose(log_file);
    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip == NULL) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (trigger_line == NULL) {
        perror("Failed to get trigger line");
        return 1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (echo_line == NULL) {
        perror("Failed to get echo line");
        return 1;
    }

    if (gpiod_line_request_output(trigger_line, "trigger", 0) < 0) {
        perror("Failed to request trigger line as output");
        return 1;
    }

    if (gpiod_line_request_input(echo_line, "echo") < 0) {
        perror("Failed to request echo line as input");
        return 1;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        gpiod_line_set_value(trigger_line, 1);
        usleep(10);
        gpiod_line_set_value(trigger_line, 0);

        struct timespec start, end;
        clock_gettime(CLOCK_MONOTONIC, &start);

        while (gpiod_line_get_value(echo_line) == 0) {
            if (clock_gettime(CLOCK_MONOTONIC, &end) < 0) {
                perror("Failed to get echo line value");
                return 1;
            }

            if ((end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000 > 50000) {
                fprintf(log_file, "-1\n");
                fflush(log_file);
                goto next_iteration;
            }
        }

        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpiod_line_get_value(echo_line) == 1) {
            if (clock_gettime(CLOCK_MONOTONIC, &end) < 0) {
                perror("Failed to get echo line value");
                return 1;
            }

            if ((end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000 > 50000) {
                fprintf(log_file, "-1\n");
                fflush(log_file);
                goto next_iteration;
            }
        }

        int duration_us = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
        int distance_cm = duration_us / 2 * SPEED_OF_SOUND;

        fprintf(log_file, "%d\n", distance_cm);
        fflush(log_file);

    next_iteration:
        usleep(MIN_GUARD_TIME);
    }

    return 0;
}

