#include <stdio.h>
#include <stdint.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_HANDLE 1
#define VL53L1X_ADDR 0x29
#define GPIO_RELAY 18
#define POLL_INTERVAL 100 // in ms

void sigint_handler(int sig);
int init_vl53l1x(int i2c_handle);
int read_vl53l1x(int i2c_handle);

int main() {
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to set SIGINT handler\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    int i2c_handle = i2cOpen(1, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C handle: %d\n", i2c_handle);
        return 1;
    }

    if (init_vl53l1x(i2c_handle) < 0) {
        fprintf(stderr, "Failed to initialise VL53L1X\n");
        return 1;
    }

    while (1) {
        int distance = read_vl53l1x(i2c_handle);
        if (distance < 0) {
            fprintf(stderr, "Failed to read from VL53L1X\n");
            return 1;
        }

        printf("Distance: %d cm\n", distance);

        if (distance <= 50) {
            gpioWrite(GPIO_RELAY, 1);
        } else {
            gpioWrite(GPIO_RELAY, 0);
        }

        gpioDelay(1000000); // delay for 1 second
    }

    return 0;
}

void sigint_handler(int sig) {
    i2cClose(I2C_HANDLE);
    gpioWrite(GPIO_RELAY, 0);
    gpioTerminate();
    exit(0);
}

int init_vl53l1x(int i2c_handle) {
    uint8_t soft_reset[] = {0x00, 0x00};
    if (i2cWriteDevice(i2c_handle, soft_reset, 2) < 0) {
        return -1;
    }

    uint8_t ranging_mode[] = {0x00, 0x80, 0x01};
    if (i2cWriteDevice(i2c_handle, ranging_mode, 3) < 0) {
        return -1;
    }

    return 0;
}

int read_vl53l1x(int i2c_handle) {
    uint8_t interrupt_status[2];
    if (i2cReadDevice(i2c_handle, interrupt_status, 2) < 0) {
        return -1;
    }

    if ((interrupt_status[0] & 0x01) == 0) {
        return -1;
    }

    uint8_t distance_msb, distance_lsb;
    if (i2cReadDevice(i2c_handle, &distance_msb, 1) < 0 || i2cReadDevice(i2c_handle, &distance_lsb, 1) < 0) {
        return -1;
    }

    return (distance_msb << 8) | distance_lsb;
}

