#include <wiringPiI2C.h>
#include <wiringPi.h>
#include <stdio.h>
#include <signal.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47

int fd;

void sig_handler(int signum) {
    printf("Exiting...\n");
    close(fd);
    exit(0);
}

int main() {
    int res;
    float gyro_x, gyro_y, gyro_z;

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    if (wiringPiSetup() == -1) {
        printf("Failed to setup wiringPi\n");
        return 1;
    }

    fd = wiringPiI2CSetup(MPU6050_ADDR);
    if (fd == -1) {
        printf("Failed to setup I2C communication\n");
        return 1;
    }

    // Wake up the sensor
    res = wiringPiI2CWriteReg8(fd, PWR_MGMT_1, 0);
    if (res == -1) {
        printf("Failed to wake up the sensor\n");
        return 1;
    }

    // Set the gyroscope full-scale range to ±250 dps
    res = wiringPiI2CWriteReg8(fd, GYRO_CONFIG, 0x18);
    if (res == -1) {
        printf("Failed to set the gyroscope full-scale range\n");
        return 1;
    }

    while (1) {
        // Read the gyroscope data
        int16_t raw_gyro_x = wiringPiI2CReadReg16(fd, GYRO_XOUT_H);
        int16_t raw_gyro_y = wiringPiI2CReadReg16(fd, GYRO_YOUT_H);
        int16_t raw_gyro_z = wiringPiI2CReadReg16(fd, GYRO_ZOUT_H);

        if (raw_gyro_x == -1 || raw_gyro_y == -1 || raw_gyro_z == -1) {
            printf("Failed to read the gyroscope data\n");
            return 1;
        }

        // Convert the raw values to degrees/second
