    gpioTerminate();
    exit(0);
}

void log_event(char* message) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    FILE *file = fopen("smart_lighting.log", "a");
    if (file == NULL) {
        printf("Failed to open log file\n");
        return;
    }

    fprintf(file, "[%s] %s\n", timestamp, message);
    fclose(file);
}

int main() {
    if (gpioInitialise() < 0) {
        printf("Failed to initialize GPIO\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gpioSetMode(GPIO_PIN_17, PI_OUTPUT);
    gpioSetMode(GPIO_PIN_18, PI_OUTPUT);
    gpioSetMode(GPIO_PIN_27, PI_OUTPUT);
    gpioSetMode(GPIO_PIN_22, PI_OUTPUT);

    if (gpioSetPWMfrequency(GPIO_PIN_17, PWM_FREQ) < 0) {
        printf("Failed to set PWM frequency for GPIO 17\n");
        return 1;
    }

    if (gpioSetPWMfrequency(GPIO_PIN_18, PWM_FREQ) < 0) {
        printf("Failed to set PWM frequency for GPIO 18\n");
        return 1;
    }

    if (gpioSetPWMfrequency(GPIO_PIN_27, PWM_FREQ) < 0) {
        printf("Failed to set PWM frequency for GPIO 27\n");
        return 1;
    }

    if (gpioSetPWMfrequency(GPIO_PIN_22, PWM_FREQ) < 0) {
        printf("Failed to set PWM frequency for GPIO 22\n");
        return 1;
    }

    for (int duty = 0; duty < PWM_RANGE; duty++) {
        gpioPWM(GPIO_PIN_17, duty);
        gpioPWM(GPIO_PIN_18, duty);
        gpioPWM(GPIO_PIN_27, duty);
        gpioPWM(GPIO_PIN_22, duty);

        char message[50];
        sprintf(message, "Duty cycle set to %d", duty);
        log_event(message);

        time_sleep(1);
    }

    gpioTerminate();
    return 0;
}

