#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>

#define I2C_ADDR 0x68
#define I2C_BUS 1
#define GYRO_XOUT_H 0x43
#define PWR_MGMT_1 0x6B
#define SMPLRT_DIV 0x19
#define GYRO_CONFIG 0x1B
#define WHO_AM_I 0x75
#define GPIO17 17

int i2cHandle;

void sig_handler(int signum) {
    gpioWrite(GPIO17, PI_LOW);
    gpioTerminate();
    i2cClose(i2cHandle);
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise GPIO\n");
        return 1;
    }

    gpioSetMode(GPIO17, PI_OUTPUT);

    i2cHandle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    char whoAmI;
    i2cReadByteData(i2cHandle, WHO_AM_I, &whoAmI);
    if (whoAmI != I2C_ADDR) {
        fprintf(stderr, "WHO_AM_I register does not match I2C address\n");
        return 1;
    }

    i2cWriteByteData(i2cHandle, PWR_MGMT_1, 0x00);
    i2cWriteByteData(i2cHandle, SMPLRT_DIV, 0x07);
    i2cWriteByteData(i2cHandle, GYRO_CONFIG, 0x00);

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        char data[6];
        i2cReadDevice(i2cHandle, data, 6);

        int16_t gyroX = (data[0] << 8) | data[1];
        int16_t gyroY = (data[2] << 8) | data[3];
        int16_t gyroZ = (data[4] << 8) | data[5];

        float gyroX_deg_s = gyroX / 131.0;
        float gyroY_deg_s = gyroY / 131.0;
        float gyroZ_deg_s = gyroZ / 131.0;

        if (abs(gyroX_deg_s) > 250.0 || abs(gyroY_deg_s) > 250.0 || abs(gyroZ_deg_s) > 250.0) {
            gpioWrite(GPIO17, PI_HIGH);
        } else {
            gpioWrite(GPIO17, PI_LOW);
        }

        usleep(50000);
    }

    return 0;
}

