#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>

#define SPI_DEV "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 8
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define REG_START 0x43
#define REG_END 0x48
#define RATE_SCALE 131.0

struct gpiod_chip *chip;
struct gpiod_line *line;
int spi_fd;

void cleanup(int signum) {
    close(spi_fd);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    remove("gyro_log.txt");
    exit(0);
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Open SPI device
    if ((spi_fd = open(SPI_DEV, O_RDWR)) < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Configure SPI
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS) < 0) {
        perror("Failed to set SPI bits per word");
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        return 1;
    }

    // Open GPIO chip
    if ((chip = gpiod_chip_open_by_name(GPIO_CHIP)) == NULL) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Get GPIO line
    if ((line = gpiod_chip_get_line(chip, GPIO_LINE)) == NULL) {
        perror("Failed to get GPIO line");
        return 1;
    }

    // Set line as output
    if (gpiod_line_request_output(line, "mpu9250", 0) < 0) {
        perror("Failed to set GPIO line as output");
        return 1;
    }

    // Open log file
    FILE *log_file = fopen("gyro_log.txt", "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    while (1) {
        // Assert chip select
        gpiod_line_set_value(line, 0);

        // Read gyroscope data
        uint8_t tx[2] = {REG_START, 0};
        uint8_t rx[6] = {0};
        struct spi_ioc_transfer tr = {
            .tx_buf = (unsigned long)tx,
            .rx_buf = (unsigned long)rx,
            .len = 2,
            .delay_usecs = 0,
            .speed_hz = SPI_SPEED,
            .bits_per_word = SPI_BITS,
        };
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
            perror("Failed to read from SPI device");
            return 1;
        }

        // Deassert chip select
        gpiod_line_set_value(line, 1);

        // Convert raw values to degrees per second
        int16_t x_raw = (rx[1] << 8) | rx[0];
        int16_t y_raw = (rx[3] << 8) | rx[2];
        int16_t z_raw = (rx[5] << 8) | rx[4];
