#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <time.h>
#include <signal.h>

#define MPU_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F
#define LED_PIN 21

int i2cHandle;

void sigint_handler(int sig) {
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    i2cClose(i2cHandle);
    exit(0);
}

int main() {
    signal(SIGINT, sigint_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise GPIO\n");
        return 1;
    }

    i2cHandle = i2cOpen(1, MPU_ADDR, 0);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        return 1;
    }

    char buf[1];
    buf[0] = 0x00;
    if (i2cWriteByteData(i2cHandle, PWR_MGMT_1, buf[0]) < 0) {
        fprintf(stderr, "Failed to write to PWR_MGMT_1\n");
        return 1;
    }

    buf[0] = 0x00;
    if (i2cWriteByteData(i2cHandle, ACCEL_CONFIG, buf[0]) < 0) {
        fprintf(stderr, "Failed to write to ACCEL_CONFIG\n");
        return 1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);

    while (1) {
        char data[6];
        if (i2cReadI2CBlockData(i2cHandle, ACCEL_XOUT_H, data, 6) < 0) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            continue;
        }

        short x = (data[0] << 8) | data[1];
        short y = (data[2] << 8) | data[3];
        short z = (data[4] << 8) | data[5];

        double roll = atan2(y, z) * 180 / M_PI;
        double pitch = atan2(-x, sqrt(y*y + z*z)) * 180 / M_PI;

        printf("Roll: %f, Pitch: %f\n", roll, pitch);

        if (fabs(roll) > 45 || fabs(pitch) > 45) {
            gpioWrite(LED_PIN, 1);
        } else {
            gpioWrite(LED_PIN, 0);
        }

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", tm_info);

        FILE *log_file = fopen("tilt_log.txt", "a");
        if (log_file != NULL) {
            fprintf(log_file, "%s,%f,%f\n", timestamp, roll, pitch);
            fclose(log_file);
        }

        time_sleep(0.1);
    }

    return 0;
}

