#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>

#define I2C_DEV "/dev/i2c-1"
#define I2C_ADDR 0x5A
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define RETRY_COUNT 3
#define DELAY_MS 10
#define LOG_FILE "biometric_log.txt"

int i2c_fd;
struct gpiod_chip *chip;
struct gpiod_line *line;
FILE *log_file;

void cleanup(int signum) {
    fclose(log_file);
    close(i2c_fd);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    exit(0);
}

int i2c_read(int addr, int reg, int retry) {
    int ret;
    char buf[2];

    buf[0] = reg;
    ret = write(i2c_fd, buf, 1);
    if (ret != 1) {
        if (retry > 0) {
            usleep(DELAY_MS * 1000);
            return i2c_read(addr, reg, retry - 1);
        } else {
            perror("Failed to write to I2C device");
            exit(1);
        }
    }

    ret = read(i2c_fd, buf, 2);
    if (ret != 2) {
        if (retry > 0) {
            usleep(DELAY_MS * 1000);
            return i2c_read(addr, reg, retry - 1);
        } else {
            perror("Failed to read from I2C device");
            exit(1);
        }
    }

    return (buf[0] << 8) | buf[1];
}

int main() {
    int i;
    char buf[50];
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(1);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire bus access or talk to slave");
        exit(1);
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(1);
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        exit(1);
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(1);
    }

    while (1) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

        i = i2c_read(I2C_ADDR, 0x20, RETRY_COUNT);
        fprintf(log_file, "%s,AmbientLight:%04X,", timestamp, i);

        i = i2c_read(I2C_ADDR, 0x22, RETRY_COUNT);
        fprintf(log_file, "Proximity:%04X\n", i);
        fflush(log_file);

        if (i > 100) {
            gpiod_line_set_value(line, 1);
        } else {
            gpiod_line_set_value(line, 0);
        }

        sleep(0.1);
    }

    return 0;
}

