#include <pigpio.h>
#include <stdio.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define GYRO_X_ADDR 0x02
#define GYRO_Y_ADDR 0x04
#define READ_BIT 0x80
#define SENSITIVITY 200
#define DELAY_MS 10
#define MAX_RETRIES 3

FILE *file;

void sigint_handler(int sig) {
    fflush(file);
    fclose(file);
    gpioSPI(SPI_CHANNEL, 0);
    gpioTerminate();
    exit(0);
}

int16_t read_register(uint8_t addr, int retries) {
    uint8_t tx[3] = {addr | READ_BIT, 0x00};
    uint8_t rx[3] = {0x00, 0x00, 0x00};
    int result = gpioSPI(SPI_CHANNEL, 3, tx, rx);
    if (result < 0 && retries > 0) {
        return read_register(addr, retries - 1);
    } else if (result < 0) {
        return 0;
    } else {
        return (rx[1] << 8) | rx[2];
    }
}

int main() {
    signal(SIGINT, sigint_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    if (gpioSPI(SPI_CHANNEL, SPI_FLAGS, SPI_SPEED) < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        return 1;
    }

    file = fopen("gyro_data.csv", "w");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file\n");
        return 1;
    }

    while (1) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        int64_t timestamp = ts.tv_sec * 1000000 + ts.tv_nsec / 1000;

        int16_t x_rate = read_register(GYRO_X_ADDR, MAX_RETRIES);
        int16_t y_rate = read_register(GYRO_Y_ADDR, MAX_RETRIES);

        fprintf(file, "%lld,%d,%d\n", timestamp, x_rate, y_rate);
        fflush(file);

        gpioDelay(DELAY_MS * 1000);
    }

    return 0;
}

