#include <pigpio.h>
#include <concurrentqueue.h>
#include <signal.h>
#include <time.h>
#include <stdlib.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_DELAY 1

#define GYRO_ADDR_RATE_XL 0x02
#define GYRO_ADDR_RATE_XH 0x03

#define GYRO_SENSITIVITY 200.0
#define THRESHOLD 20.0

#define GPIO_LED 17

moodycamel::ConcurrentQueue<double> queue;

volatile bool running = true;

void sig_handler(int signum) {
    running = false;
}

void readGyro() {
    char data[2];
    while (running) {
        gpioSPIXfer(SPI_CHANNEL, 0x80 | GYRO_ADDR_RATE_XL, data, 2);
        int16_t rate = (data[0] << 8) | data[1];
        double rate_deg_s = rate / GYRO_SENSITIVITY;

        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);

        queue.enqueue(ts.tv_sec + ts.tv_nsec / 1e9);
        queue.enqueue(rate_deg_s);

        if (fabs(rate_deg_s) > THRESHOLD) {
            gpioWrite(GPIO_LED, 1);
        } else {
            gpioWrite(GPIO_LED, 0);
        }

        gpioDelay(1);
    }
}

int main() {
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    if (gpioInitialise() < 0) {
        return 1;
    }

    if (gpioSPIBegin(SPI_CHANNEL, SPI_SPEED, SPI_DELAY) < 0) {
        gpioTerminate();
        return 1;
    }

    gpioSetMode(8, PI_OUTPUT);
    gpioSetMode(11, PI_OUTPUT);
    gpioSetMode(10, PI_OUTPUT);
    gpioSetMode(9, PI_INPUT);

    gpioSetMode(GPIO_LED, PI_OUTPUT);

    readGyro();

    gpioSPIDone(SPI_CHANNEL);
    gpioTerminate();

    return 0;
}

