#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN1 17
#define GPIO_PIN2 18
#define GPIO_PIN3 27

#define PWM_FREQ 100
#define PWM_RANGE 255

int fade_duration;

void sigint_handler(int sig) {
    printf("Exiting...\n");
    gpioPWM(GPIO_PIN1, 0);
    gpioPWM(GPIO_PIN2, 0);
    gpioPWM(GPIO_PIN3, 0);
    gpioTerminate();
    exit(0);
}

int main(int argc, char *argv[]) {
    if (argc != 2 || atoi(argv[1]) < 1 || atoi(argv[1]) > 3600) {
        printf("Usage: %s <duration in seconds> (1-3600)\n", argv[0]);
        return 1;
    }

    fade_duration = atoi(argv[1]);

    if (gpioInitialise() < 0) {
        printf("Failed to initialise pigpio library\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    gpioSetMode(GPIO_PIN1, PI_OUTPUT);
    gpioSetMode(GPIO_PIN2, PI_OUTPUT);
    gpioSetMode(GPIO_PIN3, PI_OUTPUT);

    printf("Starting smart sunset simulator with fade duration of %d seconds\n", fade_duration);

    for (int i = 0; i <= PWM_RANGE; i++) {
        gpioPWM(GPIO_PIN1, i);
        gpioDelay(fade_duration * 1000000 / PWM_FREQ);
    }

    for (int i = 0; i <= PWM_RANGE; i++) {
        gpioPWM(GPIO_PIN2, i);
        gpioDelay(fade_duration * 1000000 / PWM_FREQ);
    }

    for (int i = 0; i <= PWM_RANGE; i++) {
        gpioPWM(GPIO_PIN3, i);
        gpioDelay(fade_duration * 1000000 / PWM_FREQ);
    }

    printf("Smart sunset simulator completed\n");

    gpioPWM(GPIO_PIN1, 0);
    gpioPWM(GPIO_PIN2, 0);
    gpioPWM(GPIO_PIN3, 0);

    gpioTerminate();

    return 0;
}

