#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define RED_RELAY 17
#define YELLOW_RELAY 22
#define GREEN_RELAY 23
#define BLUE_RELAY 24

struct gpiod_chip *chip;
struct gpiod_line *red_line, *yellow_line, *green_line, *blue_line;

void cleanup(int signum) {
    gpiod_line_release(red_line);
    gpiod_line_release(yellow_line);
    gpiod_line_release(green_line);
    gpiod_line_release(blue_line);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Open chip failed");
        return 1;
    }

    red_line = gpiod_chip_get_line(chip, RED_RELAY);
    yellow_line = gpiod_chip_get_line(chip, YELLOW_RELAY);
    green_line = gpiod_chip_get_line(chip, GREEN_RELAY);
    blue_line = gpiod_chip_get_line(chip, BLUE_RELAY);

    if (!red_line || !yellow_line || !green_line || !blue_line) {
        perror("Get line failed");
        return 1;
    }

    int request_r = gpiod_line_request_output(red_line, "red_relay", 0);
    int request_y = gpiod_line_request_output(yellow_line, "yellow_relay", 0);
    int request_g = gpiod_line_request_output(green_line, "green_relay", 0);
    int request_b = gpiod_line_request_output(blue_line, "blue_relay", 0);

    if (request_r < 0 || request_y < 0 || request_g < 0 || request_b < 0) {
        perror("Request line as output failed");
        return 1;
    }

    while (1) {
        printf("Red light on\n");
        gpiod_line_set_value(red_line, 0);
        sleep(10);

        printf("Yellow light on\n");
        gpiod_line_set_value(yellow_line, 0);
        sleep(2);

        printf("Green light on\n");
        gpiod_line_set_value(green_line, 0);
        sleep(10);

        printf("Yellow light on\n");
        gpiod_line_set_value(yellow_line, 0);
        sleep(3);

        printf("All lights off\n");
        gpiod_line_set_value(red_line, 1);
        gpiod_line_set_value(yellow_line, 1);
        gpiod_line_set_value(green_line, 1);
        gpiod_line_set_value(blue_line, 1);
    }

    return 0;
}

