    if (!red_line || !yellow_line || !green_line || !blue_line) {
        perror("Get line failed");
        return 1;
    }

    int request_r = gpiod_line_request_output(red_line, "red_relay", 0);
    int request_y = gpiod_line_request_output(yellow_line, "yellow_relay", 0);
    int request_g = gpiod_line_request_output(green_line, "green_relay", 0);
    int request_b = gpiod_line_request_output(blue_line, "blue_relay", 0);

    if (request_r < 0 || request_y < 0 || request_g < 0 || request_b < 0) {
        perror("Request line as output failed");
        return 1;
    }

    while (1) {
        printf("Red light on\n");
        gpiod_line_set_value(red_line, 0);
        sleep(10);

        printf("Yellow light on\n");
        gpiod_line_set_value(yellow_line, 0);
        sleep(2);

        printf("Green light on\n");
        gpiod_line_set_value(green_line, 0);
        sleep(10);

        printf("Yellow light on\n");
        gpiod_line_set_value(yellow_line, 0);
        sleep(3);

        printf("All lights off\n");
        gpiod_line_set_value(red_line, 1);
        gpiod_line_set_value(yellow_line, 1);
        gpiod_line_set_value(green_line, 1);
        gpiod_line_set_value(blue_line, 1);
    }

    return 0;
}
```

This program will cycle through the states red (10 seconds), red+yellow (2 seconds), green (10 seconds), and yellow (3 seconds). It will print each state transition to stdout. The program will run indefinitely until interrupted by a SIGINT or SIGTERM signal.

Please note that you need to replace "/dev/gpiochip0" with the actual path to your GPIO chip. You can find the path by running the command `ls /dev/gpiochip*`.

