#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>

#define GPIO_OUTPUT 17
#define I2C_BUS 1
#define I2C_ADDR 0x5A

FILE *log_file;

void signal_handler(int signum) {
    fclose(log_file);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_OUTPUT, PI_OUTPUT);

    // Open I2C device
    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }

    // Configure MPR121
    unsigned char config[] = {0x80, 0x63, 0x5E, 0x00, 0x5D, 0x01, 0x41, 0x0A, 0x42, 0x08, 0x5B, 0x21, 0x5C, 0x0D, 0x5E, 0x0D};
    for (int i = 0; i < sizeof(config); i += 2) {
        if (i2cWriteI2CBlockData(i2c_handle, config[i], &config[i+1], 1) < 0) {
            fprintf(stderr, "Failed to write to I2C device\n");
            return 1;
        }
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen("touch_relay.log", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Read touch status
        unsigned char touch_status[2];
        if (i2cReadI2CBlockData(i2c_handle, 0x00, touch_status, 2) < 0) {
            fprintf(stderr, "Failed to read from I2C device\n");
            return 1;
        }

        // Log touch status
        time_t now = time(NULL);
        fprintf(log_file, "%s: Touch status: 0x%02X%02X\n", ctime(&now), touch_status[1], touch_status[0]);
        fflush(log_file);

        // Toggle GPIO17 if electrode 0 is touched
        if (touch_status[0] & 0x01) {
            gpioWrite(GPIO_OUTPUT, !gpioRead(GPIO_OUTPUT));
        }

        // Sleep for 10 ms
        time_sleep(0.01);
    }

    return 0;
}

