#define FLAME_SENSOR_GPIO 17
#define BUZZER_GPIO 18
#define LED_GPIO 23
#define DEBOUNCE_TIME 50000 // 50 ms

struct gpiod_chip *chip;
struct gpiod_line *flame_sensor, *buzzer, *led;
FILE *log_file;

void cleanup(int signum) {
    gpiod_line_release(flame_sensor);
    gpiod_line_release(buzzer);
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    fclose(log_file);
    exit(0);
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    flame_sensor = gpiod_chip_get_line(chip, FLAME_SENSOR_GPIO);
    buzzer = gpiod_chip_get_line(chip, BUZZER_GPIO);
    led = gpiod_chip_get_line(chip, LED_GPIO);

    if (!flame_sensor || !buzzer || !led) {
        perror("Failed to get GPIO line");
        return 1;
    }

    if (gpiod_line_request_input(flame_sensor, "flame_sensor") < 0) {
        perror("Failed to request input for flame sensor");
        return 1;
    }

    if (gpiod_line_request_output(buzzer, "buzzer", 0) < 0) {
        perror("Failed to request output for buzzer");
        return 1;
    }

    if (gpiod_line_request_output(led, "led", 0) < 0) {
        perror("Failed to request output for LED");
        return 1;
    }

    log_file = fopen("flame_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    int last_flame_state = 0;
    int flame_detected_count = 0;

    while (1) {
        int current_flame_state = gpiod_line_get_value(flame_sensor);

        if (current_flame_state != last_flame_state) {
            last_flame_state = current_flame_state;
            flame_detected_count = 0;
        } else if (current_flame_state == 0) {
            gpiod_line_set_value(buzzer, 0);
            gpiod_line_set_value(led, 0);
            fprintf(log_file, "%ld: Flame Cleared\n", time(NULL));
            fflush(log_file);
        } else if (++flame_detected_count == 3) {
            gpiod_line_set_value(buzzer, 1);
            gpiod_line_set_value(led, 1);
            fprintf(log_file, "%ld: Flame Detected\n", time(NULL));
            fflush(log_file);
            usleep(DEBOUNCE_TIME);
        }

        usleep(DEBOUNCE_TIME);
    }

    return 0;
}

