        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_SOL2);
        return 3;
    }

    signal(SIGINT, sigint_handler);

    FILE *log_file = fopen("dispense_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 4;
    }

    while (1) {
        time_t now = time(NULL);
        fprintf(log_file, "%ld,%d,%d,%d\n", now, GPIO_SOL1, GPIO_SOL2, DISPENSE_TIME/2);
        gpioWrite(GPIO_SOL1, 1);
        gpioDelay(DISPENSE_TIME/2);
        fprintf(log_file, "%ld,%d,%d,%d\n", time(NULL), GPIO_SOL1, GPIO_SOL2, DISPENSE_TIME/2);
