#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23
#define ENA 24
#define ENB 25

#define Kp 1.0
#define Ki 0.01
#define Kd 0.1

FILE *log_file;

void handle_sigint(int sig) {
    gpioWrite(MOTOR_A_FORWARD, 0);
    gpioWrite(MOTOR_A_BACKWARD, 0);
    gpioWrite(MOTOR_B_FORWARD, 0);
    gpioWrite(MOTOR_B_BACKWARD, 0);
    fclose(log_file);
    gpioTerminate();
    exit(0);
}

double get_distance() {
    return ((double)rand()/(RAND_MAX)) * 400.0 + 2.0;
}

double get_tilt_error() {
    return ((double)rand()/(RAND_MAX) * 20.0) - 10.0;
}

void control_motors(double tilt_error, double distance) {
    static double integral = 0.0;
    static double last_error = 0.0;
    double dt = 0.05;
    double error_derivative = (tilt_error - last_error) / dt;
    integral += tilt_error * dt;
    last_error = tilt_error;

    double motor_a_speed = Kp * tilt_error + Ki * integral + Kd * error_derivative;
    double motor_b_speed = Kp * tilt_error + Ki * integral + Kd * error_derivative;

    if (distance < 20.0) {
        motor_a_speed = -motor_a_speed / 2;
        motor_b_speed = -motor_b_speed / 2;
    }

    if (motor_a_speed > 255.0) motor_a_speed = 255.0;
    if (motor_a_speed < -255.0) motor_a_speed = -255.0;
    if (motor_b_speed > 255.0) motor_b_speed = 255.0;
    if (motor_b_speed < -255.0) motor_b_speed = -255.0;

    gpioPWM(MOTOR_A_FORWARD, abs(motor_a_speed));
    gpioPWM(MOTOR_A_BACKWARD, abs(motor_a_speed));
    gpioPWM(MOTOR_B_FORWARD, abs(motor_b_speed));
    gpioPWM(MOTOR_B_BACKWARD, abs(motor_b_speed));

    if (motor_a_speed > 0) {
        gpioWrite(MOTOR_A_BACKWARD, 0);
    } else {
        gpioWrite(MOTOR_A_FORWARD, 0);
    }

    if (motor_b_speed > 0) {
        gpioWrite(MOTOR_B_BACKWARD, 0);
    } else {
        gpioWrite(MOTOR_B_FORWARD, 0);
    }

    time_t rawtime;
    struct tm * timeinfo;
    time (&rawtime);
    timeinfo = localtime (&rawtime);
    fprintf(log_file, "%s, %f, %f, %f, %f\n", asctime(timeinfo), tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    log_file = fopen("balance_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "log file open failed\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(ENA, PI_OUTPUT);
    gpioSetMode(ENB, PI_OUTPUT);

    gpioWrite(ENA, 1);
    gpioWrite(ENB, 1);

    srand(time(NULL));

    while (1) {
        double tilt_error = get_tilt_error();
        double distance = get_distance();
        control_motors(tilt_error, distance);
        gpioDelay(50000);
    }

    return 0;
}

