#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>
#include <alsa/asoundlib.h>

#define ALSA_AVAILABLE 1
#define SAMPLE_RATE 8000
#define CHANNELS 1
#define PERIOD_SIZE 1024
#define GPIO_RED 17
#define GPIO_GREEN 18
#define GPIO_BLUE 27

snd_pcm_t *handle;

void sig_handler(int signum) {
    snd_pcm_close(handle);
    gpioTerminate();
    exit(0);
}

int main(int argc, char *argv[]) {
    float sensitivity = 1.0;
    if (argc > 1) {
        sensitivity = atof(argv[1]);
        if (sensitivity <= 0) {
            fprintf(stderr, "Invalid sensitivity argument\n");
            return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    gpioSetMode(GPIO_RED, PI_OUTPUT);
    gpioSetMode(GPIO_GREEN, PI_OUTPUT);
    gpioSetMode(GPIO_BLUE, PI_OUTPUT);

    if (ALSA_AVAILABLE) {
        if (snd_pcm_open(&handle, "default", SND_PCM_STREAM_CAPTURE, 0) < 0) {
            fprintf(stderr, "Failed to open ALSA device\n");
            return 1;
        }

        snd_pcm_set_params(handle, SND_PCM_FORMAT_S16_LE, SND_PCM_ACCESS_RW_INTERLEAVED, CHANNELS, SAMPLE_RATE, 1, PERIOD_SIZE);
        snd_pcm_prepare(handle);
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        short samples[PERIOD_SIZE];
        int err;
        if (ALSA_AVAILABLE) {
            err = snd_pcm_readi(handle, samples, PERIOD_SIZE);
            if (err == -EPIPE) {
                snd_pcm_prepare(handle);
            } else if (err == -ESTRPIPE) {
                snd_pcm_resume(handle);
            } else if (err < 0) {
                fprintf(stderr, "ALSA read error: %s\n", snd_strerror(err));
                return 1;
            }
        } else {
            // Simulate audio input
            for (int i = 0; i < PERIOD_SIZE; i++) {
                samples[i] = sin(2 * M_PI * i / SAMPLE_RATE) * 32767;
            }
        }

        float rms = 0;
        for (int i = 0; i < PERIOD_SIZE; i++) {
            rms += samples[i] * samples[i];
        }
        rms = sqrt(rms / PERIOD_SIZE);

        int pwm = rms * sensitivity;
        gpioPWM(GPIO_RED, pwm);
        gpioPWM(GPIO_GREEN, pwm);
        gpioPWM(GPIO_BLUE, pwm);

        printf("RMS: %f, PWM: %d\n", rms, pwm);

        gpioDelay(10000000);  // 10 ms delay
    }

    return 0;
}

