#include <pigpio.h>
#include <stdio.h>
#include <signal.h>
#include <time.h>

#define I2C_ADDR 0x29
#define I2C_BUS 1

int i2cHandle = -1;
FILE *file;

void signalHandler(int signum) {
    if (i2cHandle >= 0) {
        i2cClose(i2cHandle);
    }
    if (file != NULL) {
        fclose(file);
    }
    gpioTerminate();
    exit(signum);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    i2cHandle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    file = fopen("color_data.csv", "w");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file\n");
        return 1;
    }

    // Power-on and RGBC enable
    char data[2] = {0x80, 0x03};
    if (i2cWriteDevice(i2cHandle, data, 2) < 0) {
        fprintf(stderr, "Failed to write to I2C bus\n");
        return 1;
    }

    // Set integration time
    data[0] = 0x81;
    data[1] = 0xD5;
    if (i2cWriteDevice(i2cHandle, data, 2) < 0) {
        fprintf(stderr, "Failed to write to I2C bus\n");
        return 1;
    }

    while (1) {
        gpioDelay(500000);  // Delay for 500 ms

        char buffer[6];
        buffer[0] = 0x14;
        if (i2cWriteDevice(i2cHandle, buffer, 1) < 0) {
            fprintf(stderr, "Failed to write to I2C bus\n");
            continue;
        }

        if (i2cReadDevice(i2cHandle, buffer, 6) < 0) {
            fprintf(stderr, "Failed to read from I2C bus\n");
            continue;
        }

        time_t now = time(NULL);
        fprintf(file, "%ld,%d,%d,%d,%d\n", now, buffer[1], buffer[2], buffer[3], buffer[4]);
        fflush(file);
    }

    return 0;
}

