#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_PINS {17, 27, 22, 23}
#define SUNRISE_DURATION 3600
#define DAYTIME_DURATION 21600
#define SUNSET_DURATION 3600
#define NIGHTTIME_DURATION 50400

struct gpiod_chip *chip;
struct gpiod_line *lines[4];

void cleanup(int signum) {
    for (int i = 0; i < 4; i++) {
        gpiod_line_set_value(lines[i], 1);
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    int pins[] = GPIO_PINS;
    for (int i = 0; i < 4; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            perror("Failed to get GPIO line");
            return 1;
        }
        if (gpiod_line_request_output(lines[i], "my-consumer", 0) < 0) {
            perror("Failed to request GPIO line as output");
            return 1;
        }
    }

    while (1) {
        // Sunrise phase
        for (int i = 0; i < SUNRISE_DURATION; i++) {
            for (int j = 0; j < 4; j++) {
                gpiod_line_set_value(lines[j], i % 2);
                sleep(1);
            }
        }

        // Daytime phase
        for (int i = 0; i < DAYTIME_DURATION; i++) {
            for (int j = 0; j < 4; j++) {
                gpiod_line_set_value(lines[j], 0);
                sleep(1);
            }
        }

        // Sunset phase
        for (int i = 0; i < SUNSET_DURATION; i++) {
            for (int j = 0; j < 4; j++) {
                gpiod_line_set_value(lines[j], i % 2);
                sleep(1);
            }
        }

        // Nighttime phase
        for (int i = 0; i < NIGHTTIME_DURATION; i++) {
            for (int j = 0; j < 4; j++) {
                gpiod_line_set_value(lines[j], 1);
                sleep(1);
            }
        }
    }

    return 0;
}

