    for (int i = 0; i < 4; i++) {
        gpioSetMode(relays[i], PI_OUTPUT);
    }

    FILE* log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    srand(time(NULL));
    while (1) {
        for (int i = 0; i < 4; i++) {
            int reading = rand() % 101;
            int state = (reading < 30) ? 0 : 1;
            gpioWrite(relays[i], state);
            time_t now = time(NULL);
            fprintf(log_file, "Time: %s, Sensor %d: %d, Relay %d: %d\n", ctime(&now), i+1, reading, i+1, state);
            fflush(log_file);
