    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    int handle = i2cOpen(1, ADXL345_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C handle: %d\n", handle);
        return 1;
    }

    char data_format = 0x0B;
    i2cWriteByteData(handle, DATA_FORMAT, data_format);

    char power_ctl = 0x08;
    i2cWriteByteData(handle, POWER_CTL, power_ctl);

    signal(SIGINT, sigint_handler);

    while (1) {
        char data[6];
        i2cReadI2CBlockData(handle, DATAX0, data, 6);

        int16_t x = (data[1] << 8) | data[0];
        int16_t y = (data[3] << 8) | data[2];
        int16_t z = (data[5] << 8) | data[4];

        float x_g = x / 256.0;
        float y_g = y / 256.0;
        float z_g = z / 256.0;

        if (abs(x_g) < 0.2 && abs(y_g) < 0.2 && abs(z_g) < 0.2) {
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char timestamp[20];
