#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pthread.h>

#define TRIG 4
#define ECHO 18
#define MAX_DISTANCE 23200
#define MAX_TIMEOUT 100000000

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
FILE *file;
volatile unsigned int startTick = 0;
volatile unsigned int endTick = 0;

void startPulse(void) {
    pthread_mutex_lock(&mutex);
    gpioTrigger(TRIG, 1, 10);
    startTick = gpioTick();
    pthread_mutex_unlock(&mutex);
}

void endPulse(void) {
    pthread_mutex_lock(&mutex);
    endTick = gpioTick();
    pthread_mutex_unlock(&mutex);
}

void measureDistance(void) {
    unsigned int distanceTicks;
    unsigned long long timestamp_ns;
    double distance_cm;

    pthread_mutex_lock(&mutex);
    distanceTicks = endTick - startTick;
    pthread_mutex_unlock(&mutex);

    if (distanceTicks < MAX_TIMEOUT) {
        distance_cm = (double)distanceTicks * 101.0 / 1000000.0;
        timestamp_ns = gpioTick() * 1000;

        if (distance_cm <= MAX_DISTANCE) {
            pthread_mutex_lock(&mutex);
            fprintf(file, "%llu,%.2f\n", timestamp_ns, distance_cm);
            fflush(file);
            pthread_mutex_unlock(&mutex);
        }
    }
}

void sigintHandler(int sig) {
    fclose(file);
    gpioTerminate();
    pthread_mutex_destroy(&mutex);
    exit(0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    file = fopen("distance_log.txt", "w");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigintHandler);

    gpioSetMode(TRIG, PI_OUTPUT);
    gpioSetMode(ECHO, PI_INPUT);

    gpioSetAlertFunc(ECHO, startPulse);
    gpioSetAlertFunc(ECHO, endPulse);
    gpioSetAlertFunc(ECHO, measureDistance);

    while (1) {
        sleep(1);
    }

    return 0;
}

