#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>

#define LIS3DH_ADDR 0x18
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D

int i2cHandle;
float threshold = 2.0;

void sigint_handler(int sig) {
    gpioWrite(18, 0);
    gpioTerminate();
    i2cClose(i2cHandle);
    exit(0);
}

int main(int argc, char *argv[]) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    i2cHandle = i2cOpen(1, LIS3DH_ADDR, 0);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);

    i2cWriteByteData(i2cHandle, CTRL_REG1, 0x57);
    i2cWriteByteData(i2cHandle, CTRL_REG4, 0x88);

    while (1) {
        char data[6];
        i2cReadI2CBlockData(i2cHandle, OUT_X_L, data, 6);

        int16_t x = (data[1] << 8) | data[0];
        int16_t y = (data[3] << 8) | data[2];
        int16_t z = (data[5] << 8) | data[4];

        float gx = x * 0.0009765625;
        float gy = y * 0.0009765625;
        float gz = z * 0.0009765625;

        if (fabs(gx) > threshold || fabs(gy) > threshold || fabs(gz) > threshold) {
            FILE *logFile = fopen("/var/log/high_acceleration.log", "a");
            if (logFile != NULL) {
                time_t now = time(NULL);
                fprintf(logFile, "%ld: %.2f %.2f %.2f\n", now, gx, gy, gz);
                fclose(logFile);
            }
            system("sudo shutdown -h now");
        }

        sleep(0.1);
    }

    return 0;
}

