#define RIGHT_PIN 27
#define ALERT_PIN 22

#define BUFFER_SIZE 5
#define ALERT_THRESHOLD 5

struct gpiod_chip *chip;
struct gpiod_line *left, *center, *right, *alert;
int buffer[BUFFER_SIZE];
int buffer_index = 0;
int alert_count = 0;

void handle_signal(int signum) {
    gpiod_line_release(left);
    gpiod_line_release(center);
    gpiod_line_release(right);
    gpiod_line_release(alert);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    left = gpiod_chip_get_line(chip, LEFT_PIN);
    center = gpiod_chip_get_line(chip, CENTER_PIN);
    right = gpiod_chip_get_line(chip, RIGHT_PIN);
    alert = gpiod_chip_get_line(chip, ALERT_PIN);

    if (!left || !center || !right || !alert) {
        perror("Failed to get GPIO line");
        return 1;
    }

    while (1) {
        int left_val = gpiod_line_get_value(left);
        int center_val = gpiod_line_get_value(center);
        int right_val = gpiod_line_get_value(right);

        buffer[buffer_index++ % BUFFER_SIZE] = center_val;

        if (center_val == 0) {
            alert_count = 0;
        } else {
            alert_count++;
