        if (alert_count >= ALERT_THRESHOLD) {
            gpiod_line_set_value(alert, 1);
            usleep(2000000);
            gpiod_line_set_value(alert, 0);
            alert_count = 0;
        }

        printf("Left: %d, Center: %d, Right: %d\n", left_val, center_val, right_val);

        // Implement your line-following logic here

        usleep(10000);
    }

    return 0;
