#include <pigpio.h>
#include <stdio.h>
#include <time.h>
#include <signal.h>

#define I2C_HANDLE 1
#define I2C_ADDR 0x30
#define RELAY_GPIO 17
#define THRESHOLD 500 // in mT
#define POLL_INTERVAL 100 // in ms
#define POLL_ATTEMPTS 50

void sigint_handler(int sig) {
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
    i2cClose(I2C_HANDLE);
    printf("Exiting...\n");
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    int i2c_handle = i2cOpen(1, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        return 1;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    while (1) {
        // Start conversion
        if (i2cWriteByte(i2c_handle, 0xC1) < 0) {
            fprintf(stderr, "Failed to write to I2C\n");
            gpioWrite(RELAY_GPIO, 0);
            continue;
        }

        // Poll until conversion is done
        int poll_count = 0;
        while (poll_count < POLL_ATTEMPTS) {
            char status;
            if (i2cReadByteData(i2c_handle, 0xC1) < 0) {
                fprintf(stderr, "Failed to read from I2C\n");
                gpioWrite(RELAY_GPIO, 0);
                continue;
            }

            if (status == 0)
                break;

            gpioDelay(1000); // Delay for 1000 ticks of 1ms
            poll_count++;
        }

        if (poll_count == POLL_ATTEMPTS) {
            fprintf(stderr, "Timeout error\n");
            continue;
        }

        // Read field strength
        char msb, lsb;
        if (i2cReadByteData(i2c_handle, 0xC0) < 0) {
            fprintf(stderr, "Failed to read from I2C\n");
            gpioWrite(RELAY_GPIO, 0);
            continue;
        }

        int field_raw = (msb << 8) | lsb;
        int field_mT_x100 = field_raw * 25 / 1000;

        // Log field reading
        time_t now = time(NULL);
        struct tm *ptm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", ptm);
        printf("%s, Field: %d mT\n", timestamp, field_mT_x100);

        // Trigger relay if field strength exceeds threshold
        if (field_mT_x100 > THRESHOLD) {
            gpioWrite(RELAY_GPIO, 1);
            printf("%s, Relay activated\n", timestamp);
        } else {
            gpioWrite(RELAY_GPIO, 0);
            printf("%s, Relay deactivated\n", timestamp);
        }

        gpioDelay(POLL_INTERVAL * 1000); // Delay for POLL_INTERVAL ms
    }

    return 0;
}

