        }

        if (poll_count == POLL_ATTEMPTS) {
            fprintf(stderr, "Timeout error\n");
            continue;
        }

        // Read field strength
        char msb, lsb;
        if (i2cReadByteData(i2c_handle, 0xC0) < 0) {
            fprintf(stderr, "Failed to read from I2C\n");
            gpioWrite(RELAY_GPIO, 0);
            continue;
        }

        int field_raw = (msb << 8) | lsb;
        int field_mT_x100 = field_raw * 25 / 1000;

        // Log field reading
        time_t now = time(NULL);
        struct tm *ptm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", ptm);
        printf("%s, Field: %d mT\n", timestamp, field_mT_x100);

        // Trigger relay if field strength exceeds threshold
        if (field_mT_x100 > THRESHOLD) {
            gpioWrite(RELAY_GPIO, 1);
            printf("%s, Relay activated\n", timestamp);
        } else {
            gpioWrite(RELAY_GPIO, 0);
            printf("%s, Relay deactivated\n", timestamp);
        }

        gpioDelay(POLL_INTERVAL * 1000); // Delay for POLL_INTERVAL ms
    }

    return 0;
}
```

This program uses the pigpio library to interact with the GPIO and I2C buses. It starts by initializing the GPIO and I2C buses, then enters a loop where it starts a conversion, polls until the conversion is done, reads the field strength, logs the field reading, and triggers the relay if the field strength exceeds the threshold. The loop then waits for the specified interval before repeating.

The program also includes error checking for all I2C and GPIO operations, and logs any errors that occur. If the program is terminated with Ctrl+C, it will close the I2C handle, deactivate the relay, terminate pigpio, and log the shutdown.

Please note that this program assumes that the Si7210 is connected to the I2C bus with the default address and that the relay is connected to GPIO 17. You may need to adjust the I2C address, relay GPIO, threshold, poll interval, and poll attempts according to your specific setup.

