    signal(SIGTERM, sigint_handler);

    if ((log_file = fopen("relay_log.txt", "w")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        fprintf(stderr, "Failed to create socket\n");
        return 1;
    }

    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        fprintf(stderr, "Failed to set socket options\n");
        return 1;
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        fprintf(stderr, "Failed to bind socket\n");
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        fprintf(stderr, "Failed to listen on socket\n");
        return 1;
    }

    if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
        fprintf(stderr, "Failed to accept connection\n");
        return 1;
    }

    while (1) {
        if (read(new_socket, buffer, 1024) < 0) {
            fprintf(stderr, "Failed to read from socket\n");
            return 1;
        }

        if (strncasecmp(buffer, "ON", 2) == 0) {
            gpioWrite(GPIO_PIN, 1);
            fprintf(log_file, "%ld: Relay ON\n", time(NULL));
        } else if (strncasecmp(buffer, "OFF", 3) == 0) {
            gpioWrite(GPIO_PIN, 0);
            fprintf(log_file, "%ld: Relay OFF\n", time(NULL));
        } else {
            fprintf(log_file, "%ld: Invalid command\n", time(NULL));
        }

        memset(buffer, 0, 1024);
    }

    return 0;
}

