#include <pigpio.h>
#include <stdio.h>
#include <signal.h>
#include <unistd.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09
#define GPIO_OUTPUT 18

volatile sig_atomic_t stop;

void sig_handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    int sensor1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    int sensor2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);

    if (sensor1 < 0 || sensor2 < 0) {
        fprintf(stderr, "Failed to open I2C handles\n");
        return 1;
    }

    if (i2cWriteByte(sensor1, 0x36) || i2cWriteByte(sensor2, 0x36)) {
        fprintf(stderr, "Failed to start measurements\n");
        return 1;
    }

    if (gpioSetMode(GPIO_OUTPUT, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        return 1;
    }

    gpioWrite(GPIO_OUTPUT, 0);

    FILE* logfile = fopen("flow_log.txt", "a");
    if (logfile == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    while (!stop) {
        usleep(100000);  // 100 ms

        char buffer[3];
        if (i2cReadI2CBlockData(sensor1, buffer, 3) != 3 ||
            i2cReadI2CBlockData(sensor2, buffer, 3) != 3) {
            fprintf(stderr, "Failed to read from sensors\n");
            continue;
        }

        int16_t value1 = (buffer[0] << 8) | buffer[1];
        int16_t value2 = (buffer[0] << 8) | buffer[1];

        // TODO: Implement CRC-8 validation

        double flow1 = value1 / 1500.0;
        double flow2 = value2 / 1500.0;

        if (flow1 < 5.0 && flow2 < 5.0) {
            gpioWrite(GPIO_OUTPUT, 1);
        } else {
            gpioWrite(GPIO_OUTPUT, 0);
        }

        fprintf(logfile, "%ld, %f, %f\n", time(NULL), flow1, flow2);
        fflush(logfile);
    }

    fclose(logfile);

    gpioWrite(GPIO_OUTPUT, 0);

    if (sensor1 >= 0) i2cClose(sensor1);
    if (sensor2 >= 0) i2cClose(sensor2);

    gpioTerminate();

    printf("Shutdown complete\n");

    return 0;
}

