void signal_handler(int signum) {
    stop = 1;
}

int main() {
    openlog("rain_window", LOG_USER, LOG_PID);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO library");
        closelog();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gpioSetMode(RAIN_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(RAIN_SENSOR_GPIO, PI_PUD_UP);

    gpioSetMode(MOTOR_ENA_GPIO, PI_OUTPUT);
    gpioSetMode(MOTOR_IN1_GPIO, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_GPIO, PI_OUTPUT);

    int last_state = gpioRead(RAIN_SENSOR_GPIO);
    int dry_count = 0;

    while (!stop) {
        gpioDelay(200000); // 200 ms

        int current_state = gpioRead(RAIN_SENSOR_GPIO);

        if (current_state == 0 && last_state == 1) { // Rising edge
            syslog(LOG_INFO, "Rain detected, starting motor");

            if (gpioWrite(MOTOR_ENA_GPIO, 1) < 0) {
                syslog(LOG_WARNING, "Failed to set ENA");
            }
            if (gpioWrite(MOTOR_IN1_GPIO, 1) < 0) {
                syslog(LOG_WARNING, "Failed to set IN1");
            }
            if (gpioWrite(MOTOR_IN2_GPIO, 0) < 0) {
                syslog(LOG_WARNING, "Failed to set IN2");
            }

            gpioDelay(5000000); // 5 seconds

            syslog(LOG_INFO, "Stopping motor");

            if (gpioWrite(MOTOR_ENA_GPIO, 0) < 0) {
                syslog(LOG_WARNING, "Failed to reset ENA");
            }
            if (gpioWrite(MOTOR_IN1_GPIO, 0) < 0) {
                syslog(LOG_WARNING, "Failed to reset IN1");
            }
            if (gpioWrite(MOTOR_IN2_GPIO, 0) < 0) {
                syslog(LOG_WARNING, "Failed to reset IN2");
            }

            dry_count = 0;
        } else if (current_state == 1) {
            dry_count++;
            if (dry_count >= 3) {
                syslog(LOG_INFO, "Dry for 3 consecutive polls, stopping motor");

                if (gpioWrite(MOTOR_ENA_GPIO, 0) < 0) {
                    syslog(LOG_WARNING, "Failed to reset ENA");
                }
                if (gpioWrite(MOTOR_IN1_GPIO, 0) < 0) {
                    syslog(LOG_WARNING, "Failed to reset IN1");
                }
                if (gpioWrite(MOTOR_IN2_GPIO, 0) < 0) {
                    syslog(LOG_WARNING, "Failed to reset IN2");
                }

                dry_count = 0;
            }
        }

        last_state = current_state;
    }

    closelog();
    gpioTerminate();

    return 0;
}

