#include <pigpio.h>
#include <signal.h>
#include <stdio.h>
#include <unistd.h>

#define SERVO_GPIO 18
#define BUTTON1_GPIO 21
#define BUTTON2_GPIO 22
#define DEBOUNCE_DELAY 200000 // 200ms

void sigint_handler(int sig) {
    printf("Shutting down...\n");
    gpioServo(SERVO_GPIO, 0);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        printf("Failed to initialize GPIO\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    gpioSetMode(BUTTON1_GPIO, PI_INPUT);
    gpioSetMode(BUTTON2_GPIO, PI_INPUT);
    gpioSetPullUpDown(BUTTON1_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(BUTTON2_GPIO, PI_PUD_UP);

    gpioSetMode(SERVO_GPIO, PI_OUTPUT);

    int button1_state, button2_state;
    int last_button1_state = 0, last_button2_state = 0;

    while (1) {
        button1_state = gpioRead(BUTTON1_GPIO);
        button2_state = gpioRead(BUTTON2_GPIO);

        if (button1_state != last_button1_state) {
            usleep(DEBOUNCE_DELAY);
            button1_state = gpioRead(BUTTON1_GPIO);
            if (button1_state != last_button1_state) {
                if (button1_state == 0) {
                    printf("Locking...\n");
                    gpioServo(SERVO_GPIO, 2000);
                }
                last_button1_state = button1_state;
            }
        }

        if (button2_state != last_button2_state) {
            usleep(DEBOUNCE_DELAY);
            button2_state = gpioRead(BUTTON2_GPIO);
            if (button2_state != last_button2_state) {
                if (button2_state == 0) {
                    printf("Unlocking...\n");
                    gpioServo(SERVO_GPIO, 1000);
                }
                last_button2_state = button2_state;
            }
        }

        usleep(10000); // 10ms delay
    }

    return 0;
}

