#define MPR121_ADDR 0x5A
#define GPIO_RELAY 17
#define DEBOUNCE_TIME 200 // in ms

void sigint_handler(int sig) {
    gpioWrite(GPIO_RELAY, PI_OFF);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    gpioSetSignalFunc(SIGINT, sigint_handler);
    gpioSetSignalFunc(SIGTERM, sigint_handler);

    mpr121_t mpr121 = mpr121_init(1, MPR121_ADDR);
    if (mpr121 == NULL) {
        fprintf(stderr, "Failed to initialize MPR121\n");
        return 1;
    }

    gpioSetMode(GPIO_RELAY, PI_OUTPUT);
    gpioWrite(GPIO_RELAY, PI_OFF);

    mpr121_soft_reset(mpr121);
    mpr121_set_baseline_filtering(mpr121, MHD, NHD, NCL, FDL);
    mpr121_set_debounce(mpr121, 0x5B, 0x00); // set debounce time
    mpr121_set_ffi_sfi_cdt(mpr121, 0x2C, 0x00); // set FFI/SFI/CDT
    mpr121_set_auto_config(mpr121, 0x7B, 0x00); // set auto-config
    mpr121_enable_electrodes(mpr121, 0x5E, 0x0C); // enable electrodes

    unsigned long start_time = 0;
    while (1) {
        uint16_t touch_status = mpr121_get_touch_status(mpr121, 0x00);
        if (touch_status & 0x01) { // electrode 0 is touched
            if (start_time == 0 || gpioTick() - start_time >= DEBOUNCE_TIME) {
                gpioWrite(GPIO_RELAY, gpioRead(GPIO_RELAY) == PI_OFF ? PI_ON : PI_OFF);
                start_time = gpioTick();
            }
        } else {
            start_time = 0;
        }
    }

    mpr121_free(mpr121);
    gpioTerminate();

    return 0;
}

