#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_ADDR 0x23
#define I2C_BUS 1
#define RELAY_PIN 23
#define SLEEP_TIME 2

FILE *log_file;

void signal_handler(int signum) {
    fclose(log_file);
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_file = fopen("grow_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    int i2c = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    while (1) {
        int result = i2cWriteByte(i2c, 0x20);
        if (result < 0) {
            fprintf(stderr, "Failed to write to I2C bus\n");
            return 1;
        }

        sleep(120 / 1000);

        unsigned char data[2];
        result = i2cReadDevice(i2c, data, 2);
        if (result < 0) {
            fprintf(stderr, "Failed to read from I2C bus\n");
            return 1;
        }

        unsigned int raw = (data[0] << 8) | data[1];
        float lux = raw / 1.2;

        time_t now = time(NULL);
        fprintf(log_file, "%ld, %f\n", now, lux);
        fflush(log_file);

        if (lux < 150) {
            gpioWrite(RELAY_PIN, 1);
        } else {
            gpioWrite(RELAY_PIN, 0);
        }

        sleep(SLEEP_TIME);
    }

    return 0;
}

