#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <gpiod.h>

#define DOUT_GPIO 23
#define SCK_GPIO 24
#define LOCK_GPIO 25
#define HX711_CLK_DELAY 1000
#define TARE_READINGS 10
#define READINGS_PER_MEASUREMENT 5
#define MEASUREMENT_DELAY 500

volatile sig_atomic_t stop;

void signal_handler(int signum) {
    stop = 1;
}

int hx711_read(struct gpiod_chip *chip, struct gpiod_line *sck, struct gpiod_line *dout) {
    int i, j, data = 0;

    for (i = 0; i < 24; i++) {
        gpiod_line_set_value(sck, 1);
        usleep(HX711_CLK_DELAY);
        gpiod_line_set_value(sck, 0);
        if (gpiod_line_get_value(dout) == 1) {
            data |= (1 << (23 - i));
        }
        usleep(HX711_CLK_DELAY);
    }

    for (j = 0; j < 3; j++) {
        gpiod_line_set_value(sck, 1);
        usleep(HX711_CLK_DELAY);
        gpiod_line_set_value(sck, 0);
        usleep(HX711_CLK_DELAY);
    }

    return data;
}

int main(int argc, char *argv[]) {
    struct gpiod_chip *chip;
    struct gpiod_line *dout, *sck, *lock;
    int i, weight, tare_offset = 0, scale = 100, duration = 1000;

    openlog("hx711_load_cell", LOG_PID, LOG_USER);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        return 1;
    }

    dout = gpiod_chip_get_line(chip, DOUT_GPIO);
    if (!dout) {
        syslog(LOG_ERR, "Failed to get DOUT line");
        return 1;
    }

    sck = gpiod_chip_get_line(chip, SCK_GPIO);
    if (!sck) {
        syslog(LOG_ERR, "Failed to get SCK line");
        return 1;
    }

    lock = gpiod_chip_get_line(chip, LOCK_GPIO);
    if (!lock) {
        syslog(LOG_ERR, "Failed to get LOCK line");
        return 1;
    }

    gpiod_line_request_output(dout, "HX711", 0);
    gpiod_line_request_output(sck, "HX711", 0);
    gpiod_line_request_output(lock, "Solenoid", 0);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    for (i = 0; i < TARE_READINGS; i++) {
        tare_offset += hx711_read(chip, sck, dout);
    }
    tare_offset /= TARE_READINGS;

    while (!stop) {
        int total_weight = 0;
        for (i = 0; i < READINGS_PER_MEASUREMENT; i++) {
            total_weight += hx711_read(chip, sck, dout);
        }
        weight = (total_weight - tare_offset) / scale;

        if (weight > duration) {
            gpiod_line_set_value(lock, 1);
            usleep(200000);
            gpiod_line_set_value(lock, 0);
        }

        syslog(LOG_INFO, "Weight: %d grams", weight);
        usleep(MEASUREMENT_DELAY);
    }

    gpiod_line_release(dout);
    gpiod_line_release(sck);
    gpiod_line_release(lock);
    closelog();

    return 0;
}

