#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <mosquitto.h>

#define GPIO_PIN 17
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_TOPIC "home/lights/control"

static void on_connect(struct mosquitto *mosq, void *obj, int rc) {
    if(rc){
        syslog(LOG_ERR, "Connect error: %s\n", mosquitto_connack_string(rc));
    } else {
        syslog(LOG_USER, "Connected to the MQTT broker\n");
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    }
}

static void on_message(struct mosquitto *mosq, void *obj, const struct mosquitto_message *msg) {
    if(msg->payloadlen){
        if(strcmp((char*)msg->payload, "ON") == 0){
            gpioWrite(GPIO_PIN, 1);
            syslog(LOG_USER, "Received ON command\n");
        } else if(strcmp((char*)msg->payload, "OFF") == 0){
            gpioWrite(GPIO_PIN, 0);
            syslog(LOG_USER, "Received OFF command\n");
        } else {
            syslog(LOG_ERR, "Invalid payload: %s\n", (char*)msg->payload);
        }
    } else {
        syslog(LOG_ERR, "Empty payload\n");
    }
}

static void on_disconnect(struct mosquitto *mosq, void *obj, int rc) {
    syslog(LOG_USER, "Disconnected from the MQTT broker\n");
}

static void on_error(struct mosquitto *mosq, void *obj, int err) {
    syslog(LOG_ERR, "MQTT error: %s\n", mosquitto_strerror(err));
}

int main(int argc, char *argv[]) {
    openlog("mqtt_relay", LOG_PID, LOG_USER);

    mosquitto_lib_init();
    struct mosquitto *mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if(mosq){
        mosquitto_connect_callback_set(mosq, on_connect);
        mosquitto_message_callback_set(mosq, on_message);
        mosquitto_disconnect_callback_set(mosq, on_disconnect);
        mosquitto_error_callback_set(mosq, on_error);

        if(mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60)){
            syslog(LOG_ERR, "Failed to connect to the MQTT broker\n");
            return 1;
        }

        if(gpioInitialise() < 0){
            syslog(LOG_ERR, "Failed to initialize pigpio\n");
            return 1;
        }

        gpioSetMode(GPIO_PIN, PI_OUTPUT);
        gpioWrite(GPIO_PIN, 0);

        while(1){
            int rc = mosquitto_loop(mosq, -1, 1);
            if(rc){
                syslog(LOG_ERR, "Mosquitto loop error: %s\n", mosquitto_strerror(rc));
                break;
            }
        }

        gpioWrite(GPIO_PIN, 0);
        gpioTerminate();
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
    } else {
        syslog(LOG_ERR, "Failed to create mosquitto client\n");
        return 1;
    }

    closelog();
    return 0;
}

