#include <pigpio.h>

#define SENSOR_ADDR 0x23
#define RELAY_PIN 17
#define I2C_BUS 1
#define LUX_THRESHOLD_DUSK 50
#define LUX_THRESHOLD_DAWN 200
#define POLL_INTERVAL_MS 5000
#define SENSOR_CMD_HR 0x21

FILE *log_file;

void sigint_handler(int sig) {
    fclose(log_file);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    log_file = fopen("chicken_coop_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    int sensor_handle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
    if (sensor_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        return 1;
    }

    while (1) {
        char buf[2];
        buf[0] = SENSOR_CMD_HR;
        i2cWriteI2CBlockData(sensor_handle, SENSOR_ADDR, buf, 1);
        time_sleep(0.18);
        i2cReadI2CBlockData(sensor_handle, SENSOR_ADDR, buf, 2);

        int lux = (buf[0] << 8) | buf[1];
