void sigint_handler(int signum) {
    stop = 1;
}

void log_state(int state) {
    time_t now = time(NULL);
    struct tm *ptm = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", ptm);
    printf("%s: Relay is %s\n", timestamp, state ? "ON" : "OFF");
}

