    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (gpioSetMode(TOUCH_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", TOUCH_PIN);
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_PIN);
        return 1;
    }

    int last_touch_state = LOW;
    int relay_state = LOW;
    gpioWrite(RELAY_PIN, relay_state);
    log_state(relay_state);

    while (!stop) {
        int touch_state = gpioRead(TOUCH_PIN);
        if (touch_state != last_touch_state) {
            gpioDelay(1000000); // 1 sec delay
            touch_state = gpioRead(TOUCH_PIN);
            if (touch_state == HIGH) {
                relay_state = !relay_state;
                gpioWrite(RELAY_PIN, relay_state);
                log_state(relay_state);
            }
        }
        last_touch_state = touch_state;
        gpioDelay(1000000); // 10 ms delay
    }

    gpioWrite(RELAY_PIN, LOW);
    gpioTerminate();
    printf("Exiting...\n");

    return 0;
}

