#include <stdio.h>

#define FLOW_SENSOR_PIN 17
#define VALVE_PIN 27
#define SAMPLE_TIME 1000 // in milliseconds

volatile unsigned int pulses = 0;
pthread_mutex_t pulses_mutex;
FILE *log_file;

void handle_pulse(int gpio, int level, uint32_t tick) {
    pthread_mutex_lock(&pulses_mutex);
    pulses++;
    pthread_mutex_unlock(&pulses_mutex);
}

void *monitor_flow(void *arg) {
    while (1) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

        pthread_mutex_lock(&pulses_mutex);
        double lpm = (pulses / 450.0) * 60.0;
        pulses = 0;
        pthread_mutex_unlock(&pulses_mutex);

        fprintf(log_file, "%s, LPM: %.2f\n", time_str, lpm);
        fflush(log_file);

        if (lpm > 5.0) {
            gpioWrite(VALVE_PIN, PI_LOW);
            fprintf(log_file, "%s, Valve closed\n", time_str);
            fflush(log_file);
        } else if (lpm < 4.5) {
            gpioWrite(VALVE_PIN, PI_HIGH);
            fprintf(log_file, "%s, Valve opened\n", time_str);
            fflush(log_file);
        }

        sleep(SAMPLE_TIME / 1000);
    }

    return NULL;
}

void handle_signal(int signum) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s, Received signal %d\n", time_str, signum);
    fflush(log_file);

    gpioWrite(VALVE_PIN, PI_HIGH);
    fclose(log_file);
    pthread_mutex_destroy(&pulses_mutex);
    gpioTerminate();

    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set flow sensor pin mode\n");
        return 1;
    }

    if (gpioSetMode(VALVE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set valve pin mode\n");
        return 1;
    }

    if (pthread_mutex_init(&pulses_mutex, NULL) != 0) {
        fprintf(stderr, "Failed to initialize mutex\n");
        return 1;
    }

    if ((log_file = fopen("water_flow.log", "w")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 1000, handle_pulse, NULL) < 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        return 1;
    }

    pthread_t monitor_thread;
    if (pthread_create(&monitor_thread, NULL, monitor_flow, NULL) != 0) {
        fprintf(stderr, "Failed to create monitor thread\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        sleep(1);
    }

    return 0;
}

