#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <json-c/json.h>

#define DATA_PIN 23
#define SCK_PIN 24
#define SERVO_PIN 18
#define TIMEOUT 1000

double calibration_factor;
char server_ip[20] = "127.0.0.1";
int server_port = 12345;

void signal_handler(int signum) {
    gpioTerminate();
    exit(0);
}

double read_load_cell() {
    int i, data, clock;
    double val = 0;

    gpioSetMode(DATA_PIN, PI_INPUT);
    gpioSetMode(SCK_PIN, PI_OUTPUT);

    gpioWrite(SCK_PIN, 0);
    gpioDelay(1);

    for (i = 0; i < 24; i++) {
        gpioWrite(SCK_PIN, 1);
        gpioDelay(1);
        data = gpioRead(DATA_PIN);
        val = val << 1 | data;
        gpioWrite(SCK_PIN, 0);
        gpioDelay(1);
    }

    gpioWrite(SCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(SCK_PIN, 0);
    gpioDelay(1);

    return val / calibration_factor;
}

void control_servo(double weight) {
    double pulse_width = (weight - 1000) / 10;
    gpioServo(SERVO_PIN, pulse_width);
}

int main() {
    FILE *config_file = fopen("config.ini", "r");
    if (config_file) {
        fscanf(config_file, "calibration_factor=%lf\n", &calibration_factor);
        fscanf(config_file, "server_ip=%s\n", server_ip);
        fscanf(config_file, "server_port=%d\n", &server_port);
        fclose(config_file);
    } else {
        calibration_factor = 1.0;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket < 0) {
        perror("Failed to create socket");
        return 1;
    }

    struct sockaddr_in server_address;
    server_address.sin_family = AF_INET;
    server_address.sin_port = htons(server_port);
    server_address.sin_addr.s_addr = inet_addr(server_ip);

    if (bind(server_socket, (struct sockaddr *)&server_address, sizeof(server_address)) < 0) {
        perror("Failed to bind socket");
        return 1;
    }

    listen(server_socket, 5);

    while (1) {
        int client_socket = accept(server_socket, NULL, NULL);
        if (client_socket < 0) {
            perror("Failed to accept client");
            return 1;
        }

        double target_weight;
        read(client_socket, &target_weight, sizeof(target_weight));

        control_servo(target_weight);
        sleep(1);

        double actual_weight = read_load_cell();

        FILE *log_file = fopen("dispensing_log.json", "a");
        if (log_file) {
            time_t now = time(NULL);
            struct tm *ptm = localtime(&now);
            char timestamp[32];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", ptm);

            struct json_object *log_entry = json_object_new_object();
            json_object_object_add_new(log_entry, "timestamp", json_object_new_string(timestamp));
            json_object_object_add_new(log_entry, "target_weight", json_object_new_double(target_weight));
            json_object_object_add_new(log_entry, "actual_weight", json_object_new_double(actual_weight));

            char *log_entry_string = json_object_to_json_string(log_entry);
            fprintf(log_file, "%s\n", log_entry_string);
            fclose(log_file);

            json_object_put(log_entry);
        }

        write(client_socket, &actual_weight, sizeof(actual_weight));
        close(client_socket);
    }

    return 0;
}

