    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int last_touch_state = gpioRead(TOUCH_PIN);
    int last_relay_state = LOW;
    time_t last_change_time = time(NULL);

    while (!stop) {
        int touch_state = gpioRead(TOUCH_PIN);
        if (touch_state != last_touch_state) {
            time_t current_time = time(NULL);
            if (current_time - last_change_time >= debounce_time / 1000.0) {
                last_touch_state = touch_state;
