#include <signal.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define FREQUENCY 50

volatile sig_atomic_t stop;

void sigint_handler(int signum) {
    stop = 1;
}

int main() {
    int angle = 90;
    int pulse_width;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (!stop) {
        char c = getchar();
        if (c == '+') {
            angle += 10;
            if (angle > 180) angle = 180;
        } else if (c == '-') {
            angle -= 10;
            if (angle < 0) angle = 0;
        } else if (c == 'q') {
            stop = 1;
        }

        pulse_width = (angle / 180.0) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) + MIN_PULSE_WIDTH;
        if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
            fprintf(stderr, "Invalid pulse width: %d\n", pulse_width);
            return 1;
        }

        gpioServo(SERVO_PIN, pulse_width);
        printf("Current angle: %d\n", angle);
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();

    return 0;
}

