#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_LINE 17
#define GPIO_CHIP "gpiochip0"
#define DEBOUNCE_TIME 2000000 // 2 ms
#define SAMPLE_RATE 5 // 5 seconds

struct gpiod_chip *chip;
struct gpiod_line *line;
struct timespec last_pulse;
int pulse_count = 0;
int running = 1;
FILE *log_file;

void handle_signal(int signum) {
    running = 0;
}

int main(void) {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        return 1;
    }

    int ret = gpiod_line_request_input_flags(line, "hall-effect-sensor", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line as input\n");
        return 1;
    }

    log_file = fopen("motor_rpm.log", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    clock_gettime(CLOCK_MONOTONIC, &last_pulse);

    while (running) {
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);

        if ((now.tv_nsec - last_pulse.tv_nsec) < DEBOUNCE_TIME) {
            continue;
        }

        ret = gpiod_line_event_wait(line, NULL, NULL, DEBOUNCE_TIME);
        if (ret < 0) {
            fprintf(stderr, "Failed to wait for GPIO event\n");
            return 1;
        }

        clock_gettime(CLOCK_MONOTONIC, &last_pulse);

        pulse_count++;

        if ((now.tv_sec - last_pulse.tv_sec) >= SAMPLE_RATE) {
            double rpm = (pulse_count / 5.0) * 60.0;
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", gmtime(&now.tv_sec));
            fprintf(log_file, "%s,%.2f\n", timestamp, rpm);
            fflush(log_file);
            printf("RPM: %.2f\n", rpm);
            pulse_count = 0;
            clock_gettime(CLOCK_MONOTONIC, &last_pulse);
        }
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(log_file);

    return 0;
}

