#include <pigpio.h>
#include <signal.h>
#include <stdio.h>
#include <unistd.h>

#define TOUCH_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_TIME 500000 // 500ms

volatile sig_atomic_t stop;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gpioSetMode(TOUCH_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    gpioWrite(RELAY_PIN, PI_LOW);

    unsigned long last_touch_time = 0;
    unsigned long touch_duration = 0;

    while (!stop) {
        if (gpioRead(TOUCH_PIN) == PI_BAD_GPIO) {
            fprintf(stderr, "Failed to read from GPIO %d\n", TOUCH_PIN);
            break;
        }

        if (gpioTickDiff(last_touch_time, gpioTick()) > DEBOUNCE_TIME) {
            gpioWrite(RELAY_PIN, gpioRead(RELAY_PIN) == PI_LOW ? PI_HIGH : PI_LOW);
            last_touch_time = gpioTick();
        }

        if (gpioRead(TOUCH_PIN) == PI_HIGH) {
            touch_duration = gpioTickDiff(last_touch_time, gpioTick());
            if (touch_duration > 10000000) { // 10 seconds
                gpioWrite(RELAY_PIN, PI_LOW);
                last_touch_time = gpioTick();
            }
        }

        usleep(50000); // 50 ms
    }

    gpioWrite(RELAY_PIN, PI_LOW);
    gpioTerminate();

    return 0;
}

