#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_VALVE 23
#define GPIO_FLOW 24
#define GPIO_PWM 18
#define PULSES_PER_LITER 450
#define Kp 1.0
#define UPDATE_INTERVAL 100 // in ms

FILE *log_file;
volatile unsigned long pulse_count = 0;
double target_flow_rate;

void sigint_handler(int sig) {
    gpioWrite(GPIO_VALVE, 0);
    gpioPWM(GPIO_PWM, 0);
    gpioWrite(GPIO_VALVE, 0);
    fclose(log_file);
    gpioTerminate();
    exit(0);
}

void flow_sensor_isr(int gpio, int level, uint32_t tick) {
    pulse_count++;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s -t target_flow_rate\n", argv[0]);
        return 1;
    }

    target_flow_rate = atof(argv[1]);
    if (target_flow_rate <= 0) {
        fprintf(stderr, "Invalid target flow rate: %f\n", target_flow_rate);
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(GPIO_VALVE, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d mode\n", GPIO_VALVE);
        return 1;
    }

    if (gpioSetMode(GPIO_FLOW, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d mode\n", GPIO_FLOW);
        return 1;
    }

    if (gpioSetMode(GPIO_PWM, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d mode\n", GPIO_PWM);
        return 1;
    }

    if (gpioSetISRFunc(GPIO_FLOW, EITHER_EDGE, 1000, &flow_sensor_isr) < 0) {
        fprintf(stderr, "Failed to register ISR\n");
        return 1;
    }

    log_file = fopen("flow_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    gpioWrite(GPIO_VALVE, 1);

    while (1) {
        double current_flow_rate = pulse_count / (UPDATE_INTERVAL / 1000.0);
        pulse_count = 0;

        double error = target_flow_rate - current_flow_rate;
        double duty_cycle = Kp * error;

        if (duty_cycle < 0) duty_cycle = 0;
        else if (duty_cycle > 255) duty_cycle = 255;

        gpioPWM(GPIO_PWM, (uint32_t)duty_cycle);

        time_t timestamp = time(NULL);
        fprintf(log_file, "%ld,%f,%f\n", timestamp, current_flow_rate, duty_cycle);
        fflush(log_file);

        gpioDelay(1000000); // delay for 1 second
    }

    return 0;
}

