#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5A
#define GPIO_RELAY 17

void sigint_handler(int sig) {
    gpioWrite(GPIO_RELAY, PI_LOW);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    int i2c = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Soft reset
    i2cWriteByte(i2c, 0x2B, 0x40);
    time_sleep(0.01);

    // Configure filtering
    i2cWriteByte(i2c, 0x2A, 0xFF);
    time_sleep(0.01);

    // Set touch and release thresholds
    for (int i = 0; i < 12; i++) {
        i2cWriteByte(i2c, 0x04 + i, 0x00);
        i2cWriteByte(i2c, 0x14 + i, 0x00);
    }
    time_sleep(0.01);

    // Enable run mode
    i2cWriteByte(i2c, 0x2B, 0x00);
    time_sleep(0.01);

    gpioSetMode(GPIO_RELAY, PI_OUTPUT);

    FILE *log_file = fopen("relay_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    while (1) {
        for (int i = 0; i < 12; i++) {
            char status = i2cReadByteData(i2c, 0x00 + i);
            if (status & 0x01) {
                gpioWrite(GPIO_RELAY, PI_HIGH);
                fprintf(log_file, "%ld: Relay activated\n", time(NULL));
                fflush(log_file);
                break;
            }
        }

        if (gpioRead(GPIO_RELAY) == PI_LOW) {
            gpioWrite(GPIO_RELAY, PI_LOW);
            fprintf(log_file, "%ld: Relay deactivated\n", time(NULL));
            fflush(log_file);
        }

        time_sleep(0.05);
    }

    fclose(log_file);
    i2cClose(i2c);
    gpioTerminate();

    return 0;
}

