    // Initialize the MPR121
    if (mpr121_init(handle) < 0) {
        fprintf(stderr, "Failed to initialize MPR121\n");
        return 1;
    }

    // Set touch and release thresholds
    if (mpr121_set_thresholds(handle, 0x10, 0x0A) < 0) {
        fprintf(stderr, "Failed to set thresholds\n");
        return 1;
    }

    // Set filter/charge time and electrode current
    if (mpr121_set_config(handle, 0x20, 0x01) < 0) {
        fprintf(stderr, "Failed to set config\n");
        return 1;
    }

    // Enter run mode with ELE_EN=1
    if (mpr121_run(handle) < 0) {
        fprintf(stderr, "Failed to enter run mode\n");
        return 1;
    }

    // Set up the relay pin as output
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Handle SIGINT and SIGTERM
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!stop) {
        // Read the touch status registers
        uint16_t touch_status = mpr121_get_touch_status(handle);
        if (touch_status < 0) {
            fprintf(stderr, "Failed to get touch status\n");
            return 1;
        }

        // If any electrode is touched, toggle the relay
        if (touch_status > 0) {
            gpioWrite(RELAY_PIN, !gpioRead(RELAY_PIN));
            printf("Electrode touched: 0x%04X\n", touch_status);
        }

        // Wait for 100 ms
        gpioDelay(100000000);
    }

    // Close the I2C bus
    i2cClose(handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}
