#define GPIO_PIN_1 17
#define GPIO_PIN_2 27
#define MIN_DUTY 0
#define MAX_DUTY 255
#define MIN_DELAY 50000
#define MAX_DELAY 200000

volatile sig_atomic_t shutdown = 0;

void sigint_handler(int signum) {
    shutdown = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    srand(time(NULL));

    if (gpioSetMode(GPIO_PIN_1, PI_OUTPUT) != 0 || gpioSetMode(GPIO_PIN_2, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        return 1;
    }

    while (!shutdown) {
        int steps = rand() % 11 + 5;

        for (int i = 0; i < steps && !shutdown; i++) {
            int duty1 = rand() % (MAX_DUTY - MIN_DUTY + 1) + MIN_DUTY;
            int duty2 = rand() % (MAX_DUTY - MIN_DUTY + 1) + MIN_DUTY;
            int delay = rand() % (MAX_DELAY - MIN_DELAY + 1) + MIN_DELAY;

            if (gpioPWM(GPIO_PIN_1, duty1) != 0 || gpioPWM(GPIO_PIN_2, duty2) != 0) {
                fprintf(stderr, "Failed to set PWM\n");
                return 1;
            }

            gpioDelay(1);

            if (gpioPWM(GPIO_PIN_1, 0) != 0 || gpioPWM(GPIO_PIN_2, 0) != 0) {
                fprintf(stderr, "Failed to clear PWM\n");
                return 1;
            }

            gpioDelay(delay);
        }
    }

    gpioTerminate();

    return 0;
}

