#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>

#define DATA_PIN 4
#define CLOCK_PIN 17
#define SOLENOID_PIN 27
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "weight_log.txt"
#define SAMPLE_COUNT 100
#define SAMPLE_INTERVAL 500
#define THRESHOLD 10.0

double scale_factor = 1.0;
double offset = 0.0;

void cleanup(int signum) {
    gpioTerminate();
    fclose(fopen(LOG_FILE, "a"));
    exit(0);
}

double read_hx711() {
    int value = 0;
    gpioSetMode(DATA_PIN, PI_INPUT);
    gpioSetMode(CLOCK_PIN, PI_OUTPUT);
    gpioWrite(CLOCK_PIN, 0);
    for (int i = 0; i < 24; i++) {
        gpioWrite(CLOCK_PIN, 1);
        gpioDelay(1);
        gpioWrite(CLOCK_PIN, 0);
        value = (value << 1) | gpioRead(DATA_PIN);
    }
    gpioSetMode(DATA_PIN, PI_INPUT);
    return (double)value * scale_factor + offset;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    FILE *file = fopen(CALIBRATION_FILE, "r");
    if (file) {
        fscanf(file, "%lf %lf", &scale_factor, &offset);
        fclose(file);
    }

    double sum = 0.0;
    for (int i = 0; i < SAMPLE_COUNT; i++) {
        sum += read_hx711();
        gpioDelay(SAMPLE_INTERVAL * 1000);
    }
    offset = sum / SAMPLE_COUNT;

    file = fopen(CALIBRATION_FILE, "w");
    fprintf(file, "%lf %lf", scale_factor, offset);
    fclose(file);

    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);
    signal(SIGINT, cleanup);

    while (1) {
        double weight = read_hx711();
        time_t now = time(NULL);
        fprintf(fopen(LOG_FILE, "a"), "%ld %lf\n", now, weight);
        if (weight > THRESHOLD) {
            gpioWrite(SOLENOID_PIN, 1);
        } else {
            gpioWrite(SOLENOID_PIN, 0);
        }
        gpioDelay(SAMPLE_INTERVAL * 1000);
    }

    return 0;
}

