#include <syslog.h>

#define SENSOR_PIN 4
#define MOTOR_IN1 17
#define MOTOR_IN2 18
#define MOTOR_PWM 27

#define DEBOUNCE_COUNT 3
#define DEBOUNCE_INTERVAL 50

#define PWM_FREQ 1000
#define PWM_DUTYCYCLE 150

#define MOTOR_RUN_TIME 5

void stop(int signum) {
    gpioWrite(MOTOR_IN1, 0);
    gpioWrite(MOTOR_IN2, 0);
    gpioPWM(MOTOR_PWM, 0);
    closelog();
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    openlog("window_control", LOG_PID, LOG_USER);

    if (gpioSetMode(SENSOR_PIN, PI_INPUT) < 0) {
        syslog(LOG_ERR, "Failed to set sensor pin mode\n");
        return 1;
    }

    if (gpioSetMode(MOTOR_IN1, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set motor IN1 pin mode\n");
        return 1;
    }

    if (gpioSetMode(MOTOR_IN2, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set motor IN2 pin mode\n");
        return 1;
    }

    if (gpioSetMode(MOTOR_PWM, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set motor PWM pin mode\n");
        return 1;
    }

    signal(SIGINT, stop);
    signal(SIGTERM, stop);

    while (1) {
        int i, low_count = 0;
        for (i = 0; i < DEBOUNCE_COUNT; i++) {
            if (gpioRead(SENSOR_PIN) == LOW) {
                low_count++;
            }
            gpioDelay(DEBOUNCE_INTERVAL * 1000);
        }

        if (low_count >= DEBOUNCE_COUNT) {
            syslog(LOG_INFO, "Rain detected\n");
            gpioWrite(MOTOR_IN1, 1);
            gpioWrite(MOTOR_IN2, 0);
            gpioPWM(MOTOR_PWM, PWM_DUTYCYCLE);
            gpioDelay(MOTOR_RUN_TIME * 1000 * 1000);
            gpioWrite(MOTOR_IN1, 0);
            gpioWrite(MOTOR_IN2, 0);
            gpioPWM(MOTOR_PWM, 0);
            syslog(LOG_INFO, "Window closed\n");
        } else {
            syslog(LOG_INFO, "No rain detected\n");
        }

        gpioDelay(60 * 1000 * 1000);
    }

    return 0;
}

