#include <pigpio.h>
#include <stdio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#define DT_PIN 23
#define SCK_PIN 24
#define LOCK_PIN 17
#define THRESHOLD 100 // in grams
#define SLEEP_TIME 1 // in seconds

void signal_handler(int signum) {
    gpioTerminate();
    exit(0);
}

int read_load_cell() {
    int data = 0;
    gpioSetMode(DT_PIN, PI_INPUT);
    gpioSetMode(SCK_PIN, PI_OUTPUT);

    gpioWrite(SCK_PIN, 0);
    usleep(1);

    for(int i=0; i<24; i++) {
        gpioWrite(SCK_PIN, 1);
        usleep(1);
        data = data << 1;
        if(gpioRead(DT_PIN)) data++;
        gpioWrite(SCK_PIN, 0);
        usleep(1);
    }

    gpioSetMode(DT_PIN, PI_INPUT);
    return data;
}

void log_event() {
    time_t now = time(NULL);
    struct tm *ptm = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", ptm);

    FILE *file = fopen("stock_events.txt", "a");
    if (file == NULL) {
        perror("Error opening file");
        return;
    }

    fprintf(file, "%s: Ingredient stock level low\n", timestamp);
    fclose(file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gpioSetMode(LOCK_PIN, PI_OUTPUT);

    while(1) {
        int weight = read_load_cell();
        if(weight < THRESHOLD) {
            gpioWrite(LOCK_PIN, 1);
            usleep(5000000); // 5 seconds
            gpioWrite(LOCK_PIN, 0);
            log_event();
        }
        sleep(SLEEP_TIME);
    }

    return 0;
}

