    struct tm *ptm = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", ptm);

    FILE *file = fopen("stock_events.txt", "a");
    if (file == NULL) {
        perror("Error opening file");
        return;
    }

    fprintf(file, "%s: Ingredient stock level low\n", timestamp);
    fclose(file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gpioSetMode(LOCK_PIN, PI_OUTPUT);

    while(1) {
        int weight = read_load_cell();
        if(weight < THRESHOLD) {
            gpioWrite(LOCK_PIN, 1);
            usleep(5000000); // 5 seconds
            gpioWrite(LOCK_PIN, 0);
            log_event();
        }
        sleep(SLEEP_TIME);
    }

    return 0;
}
