#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_SENSOR 16
#define GPIO_RELAY 20

struct gpiod_chip *chip;
struct gpiod_line *sensor_line, *relay_line;

void cleanup(int signum) {
    gpiod_line_release(sensor_line);
    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open chip");
        return 1;
    }

    sensor_line = gpiod_chip_get_line(chip, GPIO_SENSOR);
    if (!sensor_line) {
        fprintf(stderr, "Failed to get line for sensor\n");
        return 1;
    }

    relay_line = gpiod_chip_get_line(chip, GPIO_RELAY);
    if (!relay_line) {
        fprintf(stderr, "Failed to get line for relay\n");
        return 1;
    }

    struct gpiod_line_request_config config = {
        .consumer = "ir_obstacle_avoidance",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
    };

    if (gpiod_line_request(sensor_line, &config, 0) < 0) {
        perror("Failed to request line for sensor");
        return 1;
    }

    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    if (gpiod_line_request(relay_line, &config, 0) < 0) {
        perror("Failed to request line for relay");
        return 1;
    }

    FILE *log_file = fopen("relay_events.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    int sensor_value, relay_value = 0;
    while (1) {
        sensor_value = gpiod_line_get_value(sensor_line);
        if (sensor_value < 0) {
            perror("Failed to read sensor value");
            return 1;
        }

        if (sensor_value == 0) {
            relay_value = !relay_value;
            gpiod_line_set_value(relay_line, relay_value);

            time_t now = time(NULL);
            struct tm *timeinfo = localtime(&now);
            char timestamp[32];
            strftime(timestamp, sizeof(timestamp), "%FT%T%z", timeinfo);

            if (fprintf(log_file, "%s, Relay state: %d\n", timestamp, relay_value) < 0) {
                perror("Failed to write to log file");
                return 1;
            }
            fflush(log_file);
        }
    }

    return 0;
}

