#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_NUM 18
#define CONFIG_FILE "watering.conf"

volatile sig_atomic_t interrupt_flag = 0;
struct gpiod_chip *chip;
struct gpiod_line *line;

void signal_handler(int signum) {
    interrupt_flag = 1;
}

int main() {
    int duration;
    FILE *file;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Request GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE_NUM);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set line as output with default value 0
    int ret = gpiod_line_request_output(line, "watering_system", 0);
    if (ret < 0) {
        perror("Failed to set GPIO line as output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Read duration from config file
    file = fopen(CONFIG_FILE, "r");
    if (!file) {
        perror("Failed to open config file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (fscanf(file, "duration=%d", &duration) != 1 || duration < 1 || duration > 3600) {
        fprintf(stderr, "Invalid duration in config file\n");
        fclose(file);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    fclose(file);

    printf("Watering duration: %d seconds\n", duration);

    // Activate the valve
    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        perror("Failed to set GPIO line value");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("Valve: ON\n");

    // Wait for the configured duration
    while (duration > 0 && !interrupt_flag) {
        sleep(1);
        duration--;
    }

    // Deactivate the valve
    ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        perror("Failed to set GPIO line value");
    }

    printf("Valve: OFF\n");

    // Release the GPIO line
    gpiod_line_release(line);

    // Close the GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

