#include <time.h>
#include <stdio.h>
#include <signal.h>

#define LEFT_MOTOR_PIN 22
#define RIGHT_MOTOR_PIN 23
#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27

#define BASE_SPEED 150
#define MAX_SPEED 255

FILE *log_file;

void stop_motors(void) {
    gpioPWM(LEFT_MOTOR_PIN, 0);
    gpioPWM(RIGHT_MOTOR_PIN, 0);
}

void control_loop(void) {
    int left_sensor, middle_sensor, right_sensor;
    int left_speed, right_speed;
    char timestamp[20];

    while (1) {
        left_sensor = gpioRead(LEFT_SENSOR_PIN);
        middle_sensor = gpioRead(MIDDLE_SENSOR_PIN);
        right_sensor = gpioRead(RIGHT_SENSOR_PIN);

        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", gmtime(&now));

        fprintf(log_file, "%s,%d,%d,%d,", timestamp, left_sensor, middle_sensor, right_sensor);

        if (middle_sensor == 0) {
            left_speed = BASE_SPEED;
            right_speed = BASE_SPEED;
        } else if (left_sensor == 0) {
            left_speed = BASE_SPEED / 2;
            right_speed = BASE_SPEED;
        } else if (right_sensor == 0) {
            left_speed = BASE_SPEED;
            right_speed = BASE_SPEED / 2;
        } else {
            stop_motors();
            fprintf(log_file, "0,0\n");
            continue;
        }

        gpioPWM(LEFT_MOTOR_PIN, left_speed);
        gpioPWM(RIGHT_MOTOR_PIN, right_speed);

        fprintf(log_file, "%d,%d\n", left_speed, right_speed);

        time_sleep(0.01);
    }
}

void sigint_handler(int sig) {
    stop_motors();
    fclose(log_file);
    gpioTerminate();
    exit(0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    log_file = fopen("trace_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);

    gpioSetMode(LEFT_MOTOR_PIN, PI_OUTPUT);
    gpioSetMode(RIGHT_MOTOR_PIN, PI_OUTPUT);
    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);

    control_loop();

    return 0;
}

