#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_ADDR 0x23
#define RELAY_PIN 23
#define LUX_THRESHOLD 150
#define MEASUREMENT_DELAY 180

void sigint_handler(int sig) {
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    signal(SIGINT, sigint_handler);

    int handle = i2cOpen(1, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    FILE *log_file = fopen("grow_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    while (1) {
        char cmd = 0x10;
        i2cWriteByte(handle, cmd);
        gpioDelay(1000000); // delay for 1 second

        char data[2];
        int count = i2cReadDevice(handle, data, 2);
        if (count != 2) {
            time_t now = time(NULL);
            fprintf(log_file, "%ld: Error reading from sensor\n", now);
            fflush(log_file);
            continue;
        }

        unsigned int lux = (data[0] << 8) | data[1];
        time_t now = time(NULL);
        fprintf(log_file, "%ld: Lux reading: %u\n", now, lux);
        fflush(log_file);

        if (lux < LUX_THRESHOLD) {
            gpioWrite(RELAY_PIN, 1);
        } else {
            gpioWrite(RELAY_PIN, 0);
        }

        gpioDelay(MEASUREMENT_DELAY * 1000); // delay in microseconds
    }

    return 0;
}

