#include <pigpio.h>
#include <signal.h>
#include <stdio.h>

#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22
#define DEBOUNCE_DELAY 100 // in milliseconds

void sigint_handler(int sig) {
    printf("Exiting...\n");
    gpioTerminate();
    exit(0);
}

void move_servo(int position) {
    gpioServo(SERVO_PIN, position);
}

int main() {
    if (gpioInitialise() < 0) {
        printf("Failed to initialize pigpio library\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);

    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    while (1) {
        if (gpioRead(LOCK_BUTTON_PIN) == 0) {
            gpioDelay(1000000); // 1 second delay
            if (gpioRead(LOCK_BUTTON_PIN) == 0) {
                printf("Lock button pressed\n");
                move_servo(1000); // move servo to locked position
            }
        }

        if (gpioRead(UNLOCK_BUTTON_PIN) == 0) {
            gpioDelay(1000000); // 1 second delay
            if (gpioRead(UNLOCK_BUTTON_PIN) == 0) {
                printf("Unlock button pressed\n");
                move_servo(2000); // move servo to unlocked position
            }
        }
    }

    return 0;
}

