#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO17 "gpiochip0"
#define GPIO27 "gpiochip0"
#define MOTOR1 "gpio17"
#define MOTOR2 "gpio27"

struct gpiod_line *motor1, *motor2;
struct gpiod_chip *chip;

void stop(int signum) {
    gpiod_line_release(motor1);
    gpiod_line_release(motor2);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    signal(SIGINT, stop);
    signal(SIGTERM, stop);

    chip = gpiod_chip_open_by_name(GPIO17);
    if (!chip) {
        perror("Open chip failed");
        return 1;
    }

    motor1 = gpiod_chip_get_line(chip, atoi(MOTOR1));
    if (!motor1) {
        perror("Get line failed");
        return 1;
    }

    if (gpiod_line_request_output(motor1, "motor1", 0) < 0) {
        perror("Request line as output failed");
        return 1;
    }

    motor2 = gpiod_chip_get_line(chip, atoi(MOTOR2));
    if (!motor2) {
        perror("Get line failed");
        return 1;
    }

    if (gpiod_line_request_output(motor2, "motor2", 0) < 0) {
        perror("Request line as output failed");
        return 1;
    }

    while (1) {
        if (gpiod_line_set_value(motor1, 1) < 0) {
            perror("Set line value failed");
            return 1;
        }
        usleep(200000);

        if (gpiod_line_set_value(motor1, 0) < 0) {
            perror("Set line value failed");
            return 1;
        }
        usleep(300000);
    }

    return 0;
}

