#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <zmq.h>

#define GPIO_LINE_SENSOR 17
#define GPIO_LINE_LED 27
#define GPIO_CHIP_NAME "gpiochip0"
#define ZMQ_TOPIC "SOUND_ALERTS"
#define ZMQ_ADDR "tcp://*:5555"

struct gpiod_line *gpio_line_sensor, *gpio_line_led;
struct gpiod_chip *gpio_chip;
void *zmq_context;
void *zmq_publisher;

void cleanup(int signum) {
    gpiod_line_release(gpio_line_sensor);
    gpiod_line_release(gpio_line_led);
    gpiod_chip_close(gpio_chip);
    zmq_close(zmq_publisher);
    zmq_ctx_destroy(zmq_context);
    exit(0);
}

int main(int argc, char *argv[]) {
    if (argc != 2 || (strcmp(argv[1], "sound_sensor") != 0 && strcmp(argv[1], "alarm_node") != 0)) {
        printf("Usage: %s [sound_sensor|alarm_node]\n", argv[0]);
        return 1;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    gpio_line_sensor = gpiod_chip_get_line(gpio_chip, GPIO_LINE_SENSOR);
    gpio_line_led = gpiod_chip_get_line(gpio_chip, GPIO_LINE_LED);

    if (!gpio_line_sensor || !gpio_line_led) {
        perror("Failed to get GPIO lines");
        return 1;
    }

    if (gpiod_line_request_input(gpio_line_sensor, "sound_sensor") < 0) {
        perror("Failed to request GPIO line for input");
        return 1;
    }

    if (gpiod_line_request_output(gpio_line_led, "alarm_led", 0) < 0) {
        perror("Failed to request GPIO line for output");
        return 1;
    }

    zmq_context = zmq_ctx_new();
    if (!zmq_context) {
        perror("Failed to create ZeroMQ context");
        return 1;
    }

    zmq_publisher = zmq_socket(zmq_context, ZMQ_PUB);
    if (zmq_bind(zmq_publisher, ZMQ_ADDR) < 0) {
        perror("Failed to bind ZeroMQ socket");
        return 1;
    }

    if (strcmp(argv[1], "sound_sensor") == 0) {
        while (1) {
            int value = gpiod_line_get_value(gpio_line_sensor);
            if (value == 0) {
                zmq_msg_t msg;
                zmq_msg_init_size(&msg, strlen(ZMQ_TOPIC));
                memcpy(zmq_msg_data(&msg), ZMQ_TOPIC, strlen(ZMQ_TOPIC));
                zmq_send(zmq_publisher, &msg, ZMQ_SNDMORE);
                zmq_msg_close(&msg);
                zmq_msg_init_size(&msg, 0);
                zmq_send(zmq_publisher, &msg, 0);
            }
            usleep(10000);
        }
    } else if (strcmp(argv[1], "alarm_node") == 0) {
        while (1) {
            zmq_msg_t msg;
            zmq_msg_init(&msg);
            if (zmq_recv(zmq_publisher, &msg, 0) > 0) {
                gpiod_line_set_value(gpio_line_led, 1);
                usleep(1000000);
                gpiod_line_set_value(gpio_line_led, 0);
            }
            zmq_msg_close(&msg);
        }
    }

    return 0;
}

