#define I2C_DEV "/dev/i2c-1"
#define UDP_ADDR "239.255.255.250"
#define UDP_PORT 5005
#define NUM_SENSORS 4
#define ADDR_BASE 0x23

int running = 1;
int fd;
int sock;
struct sockaddr_in addr;
char buffer[100];

void handle_signal(int signum) {
    running = 0;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        perror("Failed to create UDP socket");
        return 1;
    }

    addr.sin_family = AF_INET;
    addr.sin_port = htons(UDP_PORT);
    addr.sin_addr.s_addr = inet_addr(UDP_ADDR);

    while (running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int addr = ADDR_BASE + i;
            if (ioctl(fd, I2C_SLAVE, addr) < 0) {
                sprintf(buffer, "%d,NaN;", i+1);
            } else {
                char data[2] = {0x20, 0x00};
                if (write(fd, data, 2) != 2) {
                    sprintf(buffer, "%d,NaN;", i+1);
                } else {
                    usleep(180000);
                    if (read(fd, data, 2) != 2) {
                        sprintf(buffer, "%d,NaN;", i+1);
                    } else {
                        float lux = ((data[0] << 8) | data[1]) / 1.2;
                        sprintf(buffer, "%d,%f;", i+1, lux);
                    }
                }
            }
            sendto(sock, buffer, strlen(buffer), 0, (struct sockaddr*)&addr, sizeof(addr));
        }
        sleep(1);
    }

    close(sock);
    close(fd);
    return 0;
}

