#include <unistd.h>
#include <string.h>
#include <gpiod.h>
#include <signal.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDR 0x28
#define MAX_RETRIES 3
#define RETRY_DELAY 100000 // microseconds

int i2c_fd;
FILE *log_file;

void handle_sigint(int sig) {
    fflush(log_file);
    close(i2c_fd);
    exit(0);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret, raw, flow;
    char buf[2];

    signal(SIGINT, handle_sigint);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    line = gpiod_chip_get_line(chip, 4); // Assuming I2C1 is on GPIO4
    if (!line) {
        perror("Failed to get GPIO line");
        return 1;
    }

    ret = gpiod_line_request_output(line, "i2c-gpio", 0);
    if (ret < 0) {
        perror("Failed to set GPIO line as output");
        return 1;
    }

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return 1;
    }

    log_file = fopen("airflow_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    while (1) {
        for (int i = 0; i < MAX_RETRIES; i++) {
            if (write(i2c_fd, buf, 0) < 0) {
                perror("Failed to write to I2C device");
                return 1;
            }

            if (read(i2c_fd, buf, 2) == 2) {
                raw = (buf[0] << 8) | buf[1];
                flow = (raw - 3277) * 0.1;
                time_t now = time(NULL);
                fprintf(log_file, "%ld: %d\n", now, flow);
                break;
            }

            usleep(RETRY_DELAY);
        }
    }

    return 0;
}

