#include <time.h>

#define I2C_ADDR 0x37
#define REG_ADDR 0x28
#define SCALE_FACTOR 0.000244
#define MAX_RETRIES 3
#define BACKOFF_TIME 10

int i2c_fd;
FILE *csv_file, *error_file;

void handle_signal(int signum) {
    fclose(csv_file);
    fclose(error_file);
    close(i2c_fd);
    exit(0);
}

int main(int argc, char *argv[]) {
    int i2c_addr = I2C_ADDR;
    int interval = 1;
    char *filename = "seismic_data.csv";

    // Parse command-line options
    int opt;
    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_addr = strtol(optarg, NULL, 0);
                break;
            case 'i':
                interval = atoi(optarg);
                break;
            case 'f':
                filename = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_addr] [-i interval] [-f filename]\n", argv[0]);
                exit(1);
        }
    }

    // Open I2C device
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        exit(1);
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, i2c_addr) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(1);
    }

    // Open CSV file
    if ((csv_file = fopen(filename, "w")) == NULL) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        exit(1);
    }

    // Open error log file
    if ((error_file = fopen("seismic_error.log", "w")) == NULL) {
        perror("Failed to open error log file");
        fclose(csv_file);
        close(i2c_fd);
        exit(1);
    }

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        char buf[6];
        int retries = 0;

        // Read from sensor
        while (retries < MAX_RETRIES) {
            if (read(i2c_fd, buf, 6) != 6) {
                perror("Failed to read from sensor");
                retries++;
                usleep(BACKOFF_TIME * 1000);
            } else {
                break;
            }
        }

        if (retries == MAX_RETRIES) {
            time_t now = time(NULL);
            fprintf(error_file, "%ld: Failed to read from sensor\n", now);
            continue;
        }

        // Convert to g and log
        time_t now = time(NULL);
        int16_t x = (buf[1] << 8) | buf[0];
        int16_t y = (buf[3] << 8) | buf[2];
        int16_t z = (buf[5] << 8) | buf[4];
