#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <errno.h>
#include <sys/select.h>
#include <signal.h>
#include <time.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define TIMEOUT 2

int uart_fd;

void handle_signal(int signum) {
    printf("Exiting...\n");
    close(uart_fd);
    exit(0);
}

int main() {
    struct termios options;
    fd_set readfds;
    char buffer[256];
    char *line;
    int ret;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (uart_fd == -1) {
        perror("Failed to open UART device");
        return 1;
    }

    tcgetattr(uart_fd, &options);
    cfsetispeed(&options, BAUD_RATE);
    cfsetospeed(&options, BAUD_RATE);
    options.c_cflag |= (CLOCAL | CREAD);
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;
    options.c_cc[VMIN] = 0;
    options.c_cc[VTIME] = 5;

    tcsetattr(uart_fd, TCSANOW, &options);

    while (1) {
        FD_ZERO(&readfds);
        FD_SET(uart_fd, &readfds);

        ret = select(uart_fd + 1, &readfds, NULL, NULL, NULL);
        if (ret == -1) {
            perror("Select error");
            return 1;
        } else if (ret) {
            ret = read(uart_fd, buffer, sizeof(buffer) - 1);
            if (ret == -1) {
                perror("Read error");
                return 1;
            }
            buffer[ret] = '\0';

            line = strtok(buffer, "\n");
            while (line != NULL) {
                char timestamp[20], range[10];
                if (sscanf(line, "%[^,],%s", timestamp, range) == 2) {
                    printf("Timestamp: %s, Range: %s meters\n", timestamp, range);
                }
                line = strtok(NULL, "\n");
            }
        }
    }

    return 0;
}

