#include <pigpio.h>
#include <serialport.h>

#define LEFT_GPIO 4
#define MIDDLE_GPIO 17
#define RIGHT_GPIO 27

#define SERIAL_PORT "/dev/ttyAMA0"
#define BAUD_RATE SP_BAUD_115200

static SerialPort serial;

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        gpioTerminate();
        SerialPort_close(serial);
        SerialPort_free(serial);
        exit(0);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(LEFT_GPIO, PI_INPUT);
    gpioSetMode(MIDDLE_GPIO, PI_INPUT);
    gpioSetMode(RIGHT_GPIO, PI_INPUT);

    gpioSetPullUpDown(LEFT_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(MIDDLE_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(RIGHT_GPIO, PI_PUD_UP);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (SerialPort_open(&serial, SERIAL_PORT) != SP_OK) {
        fprintf(stderr, "Failed to open serial port\n");
        return 1;
    }

    if (SerialPort_setBaudRate(serial, BAUD_RATE) != SP_OK) {
        fprintf(stderr, "Failed to set baud rate\n");
        return 1;
    }

    if (SerialPort_setDataBits(serial, SP_DATABITS_8) != SP_OK) {
        fprintf(stderr, "Failed to set data bits\n");
        return 1;
    }

    if (SerialPort_setParity(serial, SP_PARITY_NONE) != SP_OK) {
        fprintf(stderr, "Failed to set parity\n");
        return 1;
    }

    if (SerialPort_setStopBits(serial, SP_STOPBITS_1) != SP_OK) {
        fprintf(stderr, "Failed to set stop bits\n");
        return 1;
    }

    while (1) {
        int left = gpioRead(LEFT_GPIO);
        int middle = gpioRead(MIDDLE_GPIO);
        int right = gpioRead(RIGHT_GPIO);

        if (left == -1 || middle == -1 || right == -1) {
            fprintf(stderr, "gpioRead failed\n");
            continue;
        }

        printf("%ld,%d,%d,%d\n", time(NULL), left, middle, right);

        if (left == 0 && middle == 0 && right == 0) {
            char* message = "EMERGENCY STOP!\n";
            if (SerialPort_write(serial, message, strlen(message)) != SP_OK) {
                fprintf(stderr, "Failed to write to serial port\n");
            }
        }

        sleep(100);
    }

    return 0;
}

